-- ============================================================
-- Qazax4a (1/3): Günə-özəl push bildirişlərinin Qazax (kk) tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL Qazax1.sql (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4'::uuid, 'Жаңғақ пен бадам жейтін уақыт 🥜', 'Тіскебасарға чипсы емес, жаңғақ таңдаңыз. Омега-3 Сізге де, болашақ бөпеңізге де қажет.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'Өзіңізге уақыт бөліңіз 💆‍♀️', 'Стресс гормондарын қуамыз! Бүгін өзіңізге ұнайтын фильмді көріңіз немесе жылы душ қабылдаңыз.'),
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3', 'Ең кішкентай бастама 🫧', 'Әзірге көзге көрінбейді. Болашақ бөпеңіз әзірше бір ғана жасуша, бірақ оның жоспары үлкен!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'Ғажайып сәт келді ме? ✨', 'Ұрықтану әдетте осы күндері жүреді. Сіз сезбесеңіз де, ғажайып үдеріс басталып кетті.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'Ақуыз бомбасы 🍳', 'Таңғы асыңызда жұмыртқа бар ма? Жасушалардың жаңаруы үшін ақуыз өте маңызды. Асыңыз дәмді болсын!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'Серуенге шығамыз ба? 👟', 'Таза ауа көңіл күйіңізді көтереді. Жаттығулар бөліміндегі жеңіл жаяу жүру бағдарламасын қарап көріңіз.'),
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d', 'Жаңа саяхат басталады! 🚀', 'Денеңіз ғажайып бір кереметті қабылдауға дайындалып жатыр. Сіз бұған дайынсыз ба?'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'Дәрумендерді ұмыттыңыз ба? 💊', 'Фолий қышқылы қазір Сіздің ең жақын досыңыз. Болашақ бөпеңіздің денсаулығының берік негізін қалау үшін Тамақтану бөліміне кіріп көріңіз!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'Бүгін өзіңізді қалай сезініп жүрсіз? 🌈', 'Жаңа кезең басталғанда эмоцияларыңыз өзгеруі мүмкін. Бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, өз жағдайыңызды бақылаңыз.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'Әзірге микроскопиялық деңгейде 🔬', 'Үлкен хикаялар кішкентай бөлшектерден басталады. Қазір болашақ бөпеңіз тек ой түрінде ғана, бірақ оның мүмкіндігі шексіз!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'Детокс уақыты келді! 🚫', 'Темекі, алкогольді ішімдіктер немесе шамадан тыс кофеин? Олармен қоштасатын кез келді. Дені сау ана = Сәтті бастама.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'Су құтысы жаныңызда ма? 💧', 'Ағзаңызға жеткілікті су ішу қазір екі есе маңызды. Күнделікті су мөлшерін ішуді ұмытпаңыз.'),
  ('1466cb19-fd27-4f75-a79c-d709e1623239', 'Көкнәр дәніндей 🌱', 'Бөпе жатырда өз орнын алып жатыр. Өлшемі кішкентай болса да, жүрегі қалыптаса бастады.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'ДНҚ жиынтығы дайын! 🧬', 'Бөпенің көзінің түсі, шашы және жынысы генетикалық кодта әлдеқашан белгіленген. Сіздіңше, ол кімге ұқсайды?'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'Жидек думаны 🍓', 'Таңқурай ма, әлде құлпынай ма? Антиоксиданттарға бай бұл жидектер иммунитетіңізді нығайтады.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'Тыныш төңкеріс жүріп жатыр 🤫', 'Ұрықтанған жұмыртқа жасушасы жатырдың қабырғасына бекініп жатыр. Сіз сезбесеңіз де, таңғажайып үдеріс жүріп жатыр.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'Сүйектерге қажетті кальций 🥛', 'Сүт, айран әлде ірімшік? Бөпенің болашақ қаңқасы үшін бүгін міндетті түрде сүт өнімдерін жеңіз.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'Әлсіздік сезіп жүрсіз бе? Оның себебі бар 🥱', 'Прогестерон гормонының деңгейі жоғарылап жатыр. Төсек тартып тұрса, қарсылық білдірмей, демалып алыңыз!'),
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be', 'Болашақты жоспарлаңыз 💭', 'Жүктілік альбомына алғашқы ''бастапқы'' фотоңызды жүктегіңіз келмей ме?'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'Іргетасын қалаймыз 🏗️', 'Ағзаңыз жаңа бір ғажайыпқа дайындалып жатыр, етеккір аяқталуға жақын. Болашақ бөпенің денсаулығы мықты болуы үшін фолий қышқылының (B9) жеткілікті қоры қажет. Тамақтану бөліміндегі құнарлы мәзірді қарап шықтыңыз ба? 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'Ұйқы қандай тәтті 😴', 'Күш-қуат жинау керек. Ұйқысыз түндер басталмай тұрып, күніне кемінде 8 сағат ұйықтауға тырысыңыз.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'Жасыл күшті іске қосыңыз! 🥦', 'Саумалдық пен брокколи жай ғана көкөніс емес, табиғи дәрумендер қоймасы. Бүгін мәзіріңізге міндетті түрде жасыл тағам қосыңыз.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'Дәрігеріңізді таңдадыңыз ба? 👩‍⚕️', 'Сенім артатын маманды қазірден бастап іздеңіз. Дәрігерлер мен клиникалар бөліміндегі пікірлерді қарап, таңдауыңызды нақтылай аласыз.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'Ағзаңыз белгі беріп жатыр ма? 🌡️', 'Овуляция кезеңі жақындап келеді. Дене қызуыңызды бақылаңыз, дәл осы күндері жүкті болу ықтималдығы ең жоғары!'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'Дәруменді ұмытып кеттіңіз бе? 😬', 'Фолий қышқылы — менің болашақ омыртқамның негізі! Дәрі-дәрмек еске салғышын тексеріңізші, бүгінгі мөлшерін қабылдадыңыз ба? ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'Қанды бөлініс қалыпты ма? 🩸', 'Қорықпаңыз, бұл имплантациялық қан кету болуы мүмкін. Күмәніңіз болса, Дәрігерлер бөлімін қараңыз.'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'Темір ханымсыз ба? 🥩', 'Қан көлеміңіз арта түседі. Қызыл ет немесе жасымық жеп, анемияға жол бермеңіз.'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'Толқынысқа толы күту... 🧘‍♀️', 'Етеккір уақыты жақындап қалды. Күйзелісті азайту үшін Ақ шуылдар бөлімін тыңдаңыз.'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'Күнтізбені тексердіңіз бе? 🗓️', 'Етеккіріңіз кешіксе, тест жасайтын уақыт келген шығар? Қуанышты жаңалықты бізбен бөлісіңіз!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'Күнжіт дәніндей! 🌱', 'Енді ол ресми түрде эмбрион деп аталады. Ол жылдам өсіп келеді, ал Сіз өзгеріп жатырсыз.'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'Жүрегіңіз айни ма? 🤢', 'Таңертең қиналасыз ба? Зімбір шайы немесе лимон қосылған су көмектесуі мүмкін. Асқазаныңызды аш қалдырмаңыз.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'Маңызды құрылыс жүріп жатыр! 🚧', 'Ми мен омыртқа жотасы қалыптасып жатыр. Фолий қышқылын қабылдауды жалғастырыңыз!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'Таңертең жүрегіңіз айни ма? 🤢', 'Төсектен тұрмай тұрып, тұзды крекер жеңіз. Қандағы қант деңгейін тұрақты ұстау үшін аз-аздан тамақтаныңыз.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'Тық-тық... Естіп тұрсыз ба? 💓', 'Жүрегім соға бастады! Осы кішкентай мотордың үнін естуге асықсыз ба? Күнтізбеге алғашқы УДЗ уақытын белгілеп қойыңыз! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'Ресми растаудың уақыты келді! ✅', 'Әлі бармаған болсаңыз, дәрігердің қабылдауына жазылыңыз. Дәрігерлер бөлімінен өзіңізге лайықты маманды табыңыз.'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'Жүректің алғашқы соғысы 💓', 'Сіз естімесеңіз де, кішкентай жүрек жұмысын бастап кетті. Ол минутына 100-ден астам рет соғады!'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'Зімбір шайы көмекке келеді! 🍵', 'Жүрек айнуы басылмай жүр ме? Зімбір асқазанды тыныштандырады. Тамақтану бөлімінде рецепттер бар.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'Шаршау шегіне жетті ме? 😴', 'Денеңіз энергия өндіретін зауыттай жұмыс істеп жатыр. Түсте аздап көз шырымын алу — Сіздің ана ретіндегі құқығыңыз!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'Тәтті бұршақтай 🟢', 'Шамамен 6 mm. Қолдары мен аяқтары кішкентай бүршік тәрізді қалыптаса бастайды. Кішкентай жүзгіш!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'Жарыс көлігіндей! 🏎️', 'Жүрегі минутына 100-160 рет соғады. Сіздікінен екі есе жылдам! Бұл дыбыс Сізге музыкадай естіледі.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'Қандағы қант төмендемесін! 📉', 'Асқазан бос болғанда жүрек айнуы күшейеді. Сөмкеңізде әрдайым крекер немесе кептірілген жеміс алып жүріңіз.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'Дәретхана марафоны ма? 🚻', 'Дәретханаға жиі бару — қалыпты жағдай. Бүйректеріңіз қарқындырақ жұмыс істеп жатыр. Бірақ суды азайтпаңыз, керісінше көбірек ішіңіз!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'Лимон қосылған судың кереметі 🍋', 'Жүрек айнуын азайтып, ағзаны тазартады. Судың жеткіліксіздігі бас ауруын тудыруы мүмкін.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'Қуатыңыз таусылып бара ма? 🔋', 'Күш-қуатыңыз тез таусылуы мүмкін. Түсте аздап мызғып алу Сізге жақсы әсер етеді.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'Маған бассейн керек! 🏊‍♀️', 'Анашым, мен жүзетін суды (қағанақ суын) Сіз түзесіз. Су трекеріне кіріңіз. Бір стақан су іштіңіз бе? ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'Эмоциялар каруселі 🎢', 'Бірде күліп, артынша жылау... Гормондар Сізді есіңізден адастырған жоқ, олар жай ғана өз жұмысын істеп жатыр.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'Иістерге сезімталсыз ба? 👃', 'Ұнатпайтын тағамдарды өзіңізді қинап жемеңіз. Балама нұсқаларды «Тамақтану» бөлімінен қараңыз.'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'Ми дамып жатыр! 🧠', 'Жүйке түтігі жабылып жатыр. Фолий қышқылын қабылдауды тоқтатпаңыз, болашақ данышпанның іргетасы қалануда!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'Жүрегіңіз айнып жүр ме? Кешіріңіз! 🥺', 'Гормондар сауық құрып жатыр, оған кінәлі — менмін. Сізді қинап жүрмін бе? Тұзды крекер жеп көрейік пе? 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'Бет әлпеті қалыптасып жатыр 👀', 'Көзі, мұрны мен құлағы қалыптасып келеді. Әзірге олар қара нүктелерге ұқсайды, бірақ бет пішіні біртіндеп айқындала бастады.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'B6 дәрумені қандай тағамдарда бар? 🍌', 'Банан, авокадо немесе тауық еті... Бұл дәрумен жүрек айнуын жеңілдетуі мүмкін.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'Жасырын би кеші! 💃', 'Сіз әлі сезбесеңіз де, бөпе қазірдің өзінде қимылдап жүр. Оның алғашқы қозғалыстары әзірге жай ғана жыбырлағандай болады.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'Тұздалған қияр ма, әлде шоколад па? 🥒', 'Ерекше тағамдарға құмарту — қалыпты жағдай. Бірақ қант мөлшеріне назар аударыңыз! Пайдалы балама тағамдарды таңдауға болады.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'Шалбарыңыз тар болып жүр ме? 👖', 'Салмақ бақылағышына бастапқы салмағыңызды енгіздіңіз бе? 📈'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'Кофеинді азайттыңыз ба? ☕', 'Күніне 1 кеседен артық ішуге болмайды. Кофеинсіз шай немесе шөп шайын ішіп көріңіз.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'Мен билеп жүрмін! 🕺', 'Қолдары мен аяқтары бүгіледі. Ол Сіздің құрсағыңызда акробатикалық қимылдар жасап жатыр, бірақ Сіз оны әлі сезбейсіз.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'Көкөніс сорпасы? 🥣', 'Асқазаныңыз ауыр тағамдарды қабылдамаса, жеңіл сорпа ішіңіз. Әрі дәрумен, әрі сұйықтық!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'Қимыл-қозғалыс кезінде 🧘‍♀️', 'Қимылдағыңыз келе ме? Жаттығулар бөлімінде Сізге лайық не бар екенін қарап көрейік пе?'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'Әкесін де қатыстырыңыз 🗣️', 'Бұл тек Сіздің хикаяңыз емес. Алғашқы УДЗ суретін бірге қарап, болашақ жоспарларыңызды талқылаңыздар.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'Тістерім қышымайды... әзірге! 😬', 'Сүт, йогурт, ірімшік... Бүгінгі ас мәзіріңізде осылар бар ма? 🥛'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'Жасөспірім сияқтысыз ба? 😳', 'Бетіңізге безеу шығуы мүмкін. Бұл — гормондардың әсері! Теріңізді таза ұстаңыз, дәрі қолданбаңыз.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'Алғашқы фотомызды түсірдіңіз бе? 🤰', 'Галереяға өсіп келе жатқан ішіңіздің алғашқы фотосын жүктеңіз! ✨'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'Іш қату мазалай ма? 🚽', 'Мол су мен талшыққа бай тағамдар — Сіздің достарыңыз. Киви мен кептірілген өрік көп көмектесуі мүмкін.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'Сізді қысып жатырмын ба? Кешіріңіз!', 'Салмағыңыз артпаса да, мен үйімді кеңейтіп жатырмын. Келіңіз, тар шалбарды шешіп, ыңғайлырақ киім киейік. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'Тұздалған тағам ба, әлде шоколад па? 🍫', 'Тамақтану бөлімін қарап, бүгін мәзірде қандай пайдалы тағам бар екенін біліңіз! 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'Дәм сезу басталады 👅', 'Тілінде дәм сезу бүртіктері қалыптасып келеді. Сіз жеген тағамдардың дәмін ол да сезеді.'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'Еттің иісіне шыдай алмай жүрсіз бе? 🥩', 'Ақуыз қажет! Ет жей алмасаңыз, оны жасымық, ноқат немесе жаңғақпен алмастырыңыз.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'Бюстгальтеріңіз тар болып жүр ме? 👙', 'Кеудеңіз үлкейіп, сезімтал бола түседі. Ыңғайлы, спорттық үлгідегі, сымсыз іш киімге ауысатын кез келді.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'Ағзаңызға су қажет! 💧', 'Сусыздану бас ауруын тудыруы мүмкін. Су трекеріне кіріп, бір стақан су ішіңіз! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'Ол енді адам бейнесіне ұқсайды! 👶', 'Ал жүзіңіздегі әйгілі жүктілік шуағы ше? ✨ Осы сұлулықты Галереяда мәңгілікке сақтап қойыңыз!'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'С дәруменінің қуаты 🍊', 'Апельсин, киви немесе бұрыш... Иммунитетіңізді болаттай берік ұстаңыз, ауыруға болмайды!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'Бүйректері жұмыс істей бастады! 🚽', 'Сену қиын, бірақ ол қазірдің өзінде кіші дәретке шығады. Амниотикалық сұйықтықты жұтып, қайта бөліп шығарады. Айналым басталды!'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'Кальций жеткілікті болсын 🥛', 'Тіс бүршіктері қалыптасып жатыр. Сүзбе, ірімшік немесе айран... Бұлар оның болашақтағы әдемі күлкісі үшін қажет!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'Басыңыз ауырып тұр ма? 🤕', 'Дәрі ішуге асықпаңыз. Қараңғы бөлмеде демалу, салқын компресс немесе массаж жақсырақ көмектесуі мүмкін.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'Қан айналымыңыз күшейіп жатыр! 🌊', 'Қан тамырларыңыздағы қан мөлшері артып, жүрегіңіз жылдамырақ жұмыс істейді. Ағзаны салқындату үшін су өте маңызды. Басыңыз айналмас үшін су ішуді ұмытпаңыз! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'Құрылыс жұмыстары жүріп жатыр! 🏗️', 'Бөпеге кальций қажет! Тамақтану бөлімінен сүт өнімдері туралы ақпаратты қараңыз. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'Балық күні! 🐟', 'Құрамында сынабы жоқ балықты таңдаңыз. Мидың дамуы үшін Омега-3 өте маңызды.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'Созылу белгілеріне жол жоқ! 🧴', 'Ішіңіз әлі білінбесе де, теріңізді ылғалдандырыңыз. Бадам немесе кокос майы қышуды да басады.'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'Сырды ашатын уақыт келді ме? 📢', '1-ші триместр аяқталуға жақын. Қауіп азайды. Қуанышты жаңалықты достарыңызбен бөлісуге дайынсыз ба?'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'Қаңқа қатайып келеді! 🦴', 'Жұмсақ шеміршектер сүйекке айналып жатыр. Кальций қорыңызды толықтырыңыз, бөпеңіздің сүйектері мықты болсын!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'Сіз мұхит жасап жатырсыз! 🌊', 'Амниотикалық сұйықтық жаңарып отырады. Бөпеңіз таза бассейнде жүзуі үшін суды молынан ішуді ұмытпаңыз.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'Ішіңіз қышып жүр ме? 🌵', 'Тері созылған сайын қышудың пайда болуы қалыпты. Бадам майын немесе арнайы крем жағып, жайсыздықты басыңыз.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'Қуатыңыз қайта оралып жатыр ма? 🔋', 'Бүгін өзіңізді қалай сезініп жүрсіз? Симптомдар күнделігіне жазып қойыңыз! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'Мен Сізді Ана деймін... 🥺', 'Дауыс желбезектерім қалыптасып жатыр. Қазір үнсізбін, бірақ Сізге алғаш рет үн қататын күнімді елестетесіз бе? Мен елестетемін...'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'Грейпфруттай болды! 🍊', 'Беліңіз жуандауы мүмкін. Сандар өзгерді ме? Салмақ трекеріне жазып қойыңыз! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'Қосарланған тест тапсыратын уақыт па? 🗓️', '11-14 апта аралығы маңызды. Даун синдромы қаупін тексеру үшін дәрігеріңізбен кеңесіңіз.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'Қарныңыз ашты ма, әлде шөлдедіңіз бе? 🤔', 'Ми кейде бұл сезімдерді шатастырады. Алдымен бір стақан су ішіңіз. Әлі де аш болсаңыз, тамақтанатын уақыт келді деген сөз.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'Гимнастика уақыты! 🤸', 'Бөпеңіз қолдарын жұдырық етіп түйіп, аузын аша бастады. Сіз сезбесеңіз де, іште нағыз олимпиада өтіп жатыр!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'Ақылды бөпе келе жатыр! 🧠', 'Йод мидың дамуы үшін өте маңызды. Мәзіріңізде йодталған тұз, балық немесе сүт өнімдері бар ма?'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'Мен созылып жатырмын! 🤸', 'Сіз де қимылсыз қалмаңыз, Анашым. Жаттығулар бөліміндегі жеңіл йога қимылдарын қарап көрейік пе?'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'Грек жаңғағы мен орман жаңғағының күші 🐿️', 'Мидың дамуы үшін Омега-3 маңызды. Сөмкеңізде жаңғақ қоспасын алып жүріңіз: ол әрі тоқ ұстайды, әрі бөпеңіздің зияткерлік дамуына көмектеседі.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'Алтын кезең басталды! ✨', 'Құттықтаймыз! Сіз 2-ші триместрге қадам бастыңыз. Қуатыңыз артып, қауіп азаяды. Енді жүктіліктің қызығын көретін уақыт келді.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'Қуат беретін ас қажет 💥', 'Бөпеңіз тез өсіп келеді. Қызыл ет, жұмыртқа немесе бұршақ тұқымдастар... Темір мен ақуыз қорын толықтыруды ұмытпаңыз.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'Көлемі лимондай! 🍋', 'Шамамен 7-8 см. Ол енді басын бұрып, қабағын түйе алады. Бет қимылдары дамып келеді!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'Киім шкафыңызды қарап шығыңыз 👗', 'Түймелеріңіз жабылмай жүр ме? Тар шалбарларды жинап қойыңыз. Кең, ыңғайлы әрі табиғи матадан тігілген киімдерге ауысыңыз.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'Қыз ба, әлде ұл ма? 🩷💙', 'Жыныс мүшелері толық қалыптасып келеді. УДЗ-ден көру қиын болса да, оның кім екені әлдеқашан белгілі! Сіздіңше, қыз ба, әлде ұл ма?'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'Талшыққа бай тағам — нағыз қаһарман 🌾', 'Ас қорытуды жақсарту үшін сұлы, көкөністер мен жемістерге басымдық беріңіз. Тамақтану бөлімінде дәмді салаттар бар.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'Салмақ көтеріп жүрсіз бе? 🏋️‍♀️', 'Бөпе май қабатын жинап, қаңқасы қатайып келеді. Салмағымыз тез артып жатыр!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'Қоректік заттар ағыны жеделдеді!', 'Сіз бүгін қандай пайдалы тағам жедіңіз? Тамақтану тізімін қарап шығыңыз! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'Бөбеңіз бас бармағын сорып жатыр! 👍', 'Ультрадыбыстық зерттеу кезінде оның бас бармағын сорып жатқанын көре аласыз. Бұл — туғаннан кейін қажет болатын ему рефлексіне дайындық.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'Жүзгенді ұнатасыз ба? 🏊‍♀️', 'Ол суда өмір сүріп жатыр. Қағанақ суы таза әрі жеткілікті болуы үшін Сіз де күні бойы мол су ішуіңіз керек.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'Даусыңызды шығарыңыз! 🗣️', 'Бөпе қазірдің өзінде Сіздің даусыңыз бен жүрек соғысыңызды анық естиді. Оған бесік жырын айта бастаңыз, бұл оны тыныштандырады. 🎶'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'Бүгін SPA күні ме? ✨', 'Бөпенің терісі суда бүріспеуі үшін арнайы крем тәрізді қабатпен қапталған. Ал Сіз ше? Бүгін өзіңізге уақыт бөліңіз! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'Жарықты көрдім! 💡', 'Қабақтары жабық болса да, ол жарықты сезеді. Ішіңізге қолшам түсірсеңіз, бетін бұрып әкетуі мүмкін.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'Іш қатудан сақтаныңыз 🏃‍♀️', 'Дәрінің орнына көбірек су ішіп, кептірілген қара өрік пен киви жеңіз.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'Кілт қайда? 🔑', 'Ұмытшақтық — қалыпты жағдай. Миыңыз қазір әлдеқайда маңызды іспен айналысып жатыр: адам жаратуда! Істер тізімін жүргізе бастаңыз.'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'Аяғыңыз құрыса ма? 🦵', 'Бұл магний мен кальцийдің жетіспеуінен болуы мүмкін. Банан, бадам немесе йогурт жеңіз. Көбірек су ішуді де ұмытпаңыз!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'Бір алмұрттай! 🍐', 'Бойы ұзарып, денесі тіктеліп келеді. Енді басын толық тік ұстай алады. Ол өсіп келеді, ал Сіз құлпыра түсудесіз!'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'Сіз — Темір ханымсыз! 🦸‍♀️', 'Басыңыз айналмауы үшін қызыл ет немесе жасымық жеңіз. Тамақтану бөлімінде рецепттер бар.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'Көлемі алмадай 🍎', 'Шалбарыңыздың түймесін ағытып қойсаңыз болады, еркін отырыңыз! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'Қызыл иегіңіз қана ма? 😬', 'Гормондар қызыл иекті сезімтал етеді. Жұмсақ тіс щеткасын қолданып, аузыңызды тұзды сумен шайыңыз.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'Сізді естіп тұрмын, Анашым! 👂', 'Құлақ сүйектері қатайып келеді. Бөпе енді даусыңыздың ырғағын, күлкіңізді және жүрек соғысыңызды таниды.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'Бөпенің қаңқасы қатайып келеді🦴', 'Кальций қорыңыз азаймауы үшін сүт, йогурт тұтыныңыз немесе бадам жеңіз.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'Сол жақ қырыңызбен ұйықтаңыз 🛌', 'Шалқаңыздан жату қан айналымын қиындатуы мүмкін. Сол жақ қырыңызбен жату Сізге де, бөпеге де оттегінің көбірек жетуіне көмектеседі.'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'Ішіңіз тартылып тұр ма? 😣', 'Кенет қимыл жасамаңыз. Жылы душ немесе жеңіл массаж ауырсынуды азайтуы мүмкін.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'Саусақ іздері дайын! 🖐️', 'Әлемде ешкімде қайталанбайтын бірегей өрнектер қалыптасып үлгерді. Ол қазірдің өзінде жеке тұлға. Керемет емес пе?'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'Қарныңыз жиі аша ма? 😋', 'Тәбетіңіздің артуы жақсы, бірақ екі адам үшін тамақтану керек деген — аңыз. Сапалы калория көздерін таңдаңыз: жаңғақ, жеміс-жидек, көкөніс.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'Мұрныңыз бітеліп қалды ма? 🤧', 'Сіз ауырып қалған жоқсыз, бұл — жүктілік риниті. Тұзды су спрейін қолданып, бөлме ауасын ылғалдандырыңыз.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'Жылдам жеткізу! 🚚', 'Қарным ашқанда, Сізді түрткілей бастауым мүмкін. Тамақтану бөлімінде бүгінге қандай пайдалы ас бар екен? 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'Май қабаты қалыптасуда 🧸', 'Бөпе денесін жылы ұстау үшін май жинай бастайды.'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'Іш қату қоймай жүр ме? 🚽', 'Талшыққа бай тағамдар мен мол су — ең жақсы ем. Қимылсыз қалмаңыз, күнделікті серуен ішектің жұмысын жақсартады.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'Сүйектері қатайып келеді! 🦴', 'Резеңкедей жұмсақ шеміршектер сүйекке айналып жатыр. Кальций қорын толықтырыңыз, бөпенің қаңқасы болаттай берік болсын!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'Бас айналуға жол жоқ! 🛑', 'Қан көлемі артқан сайын темірге деген қажеттілік те көбейеді. Саумалдық, қарақұмық немесе қызыл ет... Мәзіріңізге міндетті түрде қосыңыз!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'Ішіңізде дискотека ма? 💃', 'Іште сальто жасауды үйреніп жүрмін! Сездіңіз бе?'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'Біртүрлі түстер көріп жүрсіз бе? 😴', 'Гормондар түндеріңізді киноға айналдыруы мүмкін. Қорықпаңыз, бұл қалыпты жағдай. Түстеріңізді Көңіл күй күнделігіне жазып қойыңыз!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'Табиғи крем жағылып жатыр! 🧴', 'Терісі әжімденбеуі үшін ол верникс деп аталатын ақ, ірімшік тәрізді затпен қапталады. Бұл — табиғаттың өз қорғаныш кремі!'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'Бір банандаймын! 🍌', 'Шамамен 18-20 sm. Енді мені басымнан аяғыма дейін өлшейді. Бойым өсіп, денем қалыптасып келеді.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'Тсс, мен ұйықтап жатырмын 😴', 'Анашым, менің де ұйқы режимім бар. Сіз жүргенде тербеліп ұйықтаймын, ал жатқанда оянып алып, дискотека жасаймын! Кешіріңіз 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'Жолдың жартысы артта қалды! 🏁', 'Құттықтаймыз! 20 апта артта қалды. Сіз жүктіліктің бел ортасына жеттіңіз. Сіз кереметсіз, мұны атап өту керек!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'Жүктелуде... 50% ⏳', 'Құттықтаймын! Жолдың жартысын артта қалдырдық. Осы тарихи күнді атап өту үшін Галереяға бір әдемі фото қосайық! ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'Әкем мені сезе ме?', 'Қолыңызды ішіңізге қойса, бәлкім, мен де оған сәлем берермін.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'Түрлі-түсті түстер көріп жүрсіз бе?', 'Жүктілік кезінде көретін түстеріңіз кино сияқты болады, солай емес пе? Мен де сол түстеріңізде бармын ба? 😴'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'Темірдің досы кім? 🍊', 'Темір қабылдап жүрсеңіз, оны міндетті түрде C дәруменімен бірге ішіңіз. Сонда темір ағзаға жақсырақ сіңеді.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'Беліңіз ауыра ма? 👠', 'Биік өкшелі аяқкиімді шкафқа қоя тұрыңыз, енді жайлылықты таңдаңыз! Ортопедиялық аяқкиім киіңіз.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'Бүйіріңіз тартып ауыра ма? ⚡', 'Кенеттен шаншып ауыруы мүмкін, қорықпаңыз, мен жай ғана үйімді кеңейтіп жатырмын! Жаттығулар бөліміндегі жеңілдететін қимылдарды жасап көріңіз. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'Төлқұжаты дайын! 🛂', 'Саусақ іздері толық қалыптасты. Әлемде ешкімде жоқ қайталанбас өрнектер енді онда да бар. Бірегей жан дүниеге келгелі жатыр!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'Судың дәмі жоқ па? 💧', 'Ішу қиын болса, қияр, қарбыз немесе жалбыз қосылған суды байқап көріңіз. Сусыздану бас ауруын тудырады.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'Анашым, мен Сізді естіп тұрмын! 👂', 'Даусыңыз маған бесік жырындай естіледі. Ал жүрегіңіздің соғысы — ең әдемі ырғақ. Менімен көбірек сөйлесіңізші, Сізді танығым келеді.'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'Мырыш: Құпия қаһарман 🛡️', 'Жасушаларым жылдам бөлініп жатыр. Маған құрылыс материалы қажет! Мәзіріңізде қызыл ет, ірімшік немесе жаңғақ бар ма?'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'Мангоның көлеміндей болдым! 🥭', 'Шамамен 15 см. Терім әлі жұқа, бірақ май қабатым қалыптасып келеді. Қазір толықтау көрінемін, Анашым!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'Сездіңіз бе? Тептім! ⚽', 'Анашым, мен ояумын! Сол жеңіл жыбыр — менің Сізге «Сәлем!» дегенім. Қолыңызды ішіңізге қойыңызшы, мүмкін, тағы бір тебермін?'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'Ұл ма, әлде қыз ба? 💙💗', 'Жынысымды білуге болатын УДЗ уақыты жақындап қалды. Толқып жүрсіз бе?'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'Алғашқы ойыншығым бар!', 'Кіндік бауымды ұстап ойнаймын, кейде қысып та қоямын. Саусақтарым ұстауды үйреніп келеді.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'Маңызды кездесудің уақыты келді! 🗓️', '18-22 апта — ең егжей-тегжейлі УДЗ жасайтын уақыт. Саусақтарымды, жүрегімді — бәрін мұқият тексереді. Дәрігерге жазылдыңыз ба?'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'Маған темір керек 🏗️', 'Мен қызыл қан жасушаларын түзіп жатырмын. Маған көмектесіңіз: сиыр етін, саумалдық немесе жасымық жеңіз.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'Аяғыңыз ісіп жүр ме? 👠', 'Ісіну басталуы мүмкін. Жұмыста да, үйде де мүмкіндігінше аяғыңызды жоғары көтеріңіз. Ыңғайлы аяқ киім таңдаңыз!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'Ық... Ық... 🤭', 'Ішіңіз ырғақты түрде бүлкілдей ме? Қорықпаңыз, Анашым, бұл жай ғана ықылық! Мен көкетті жаттықтырып жатырмын.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'Дәмдерді ажыратады! 👅', 'Қағанақ суының дәмі Сіздің жеген тағамдарыңызға қарай өзгереді. Ащы бұрыш жедіңіз бе? Бөпе оны сезеді!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'Көздерім билеп жүр...', 'Қабақтарым жұмулы болса да, мен түс көріп жатырмын. Түсімде не бар деп ойлайсыз?'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'Қыжыл мазалай ма? 🔥', 'Жатыр асқазанды қысып тұр. Аз-аздан, бірақ жиі тамақтаныңыз. Тамақтан кейін бірден жатпаңыз, тік отырыңыз.'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'Толғақ па, әлде жаттығу ма? 🤔', 'Ішіңіз қатайып жатыр ма? Бұл жалған толғақ болуы мүмкін. Жатыр босануға дайындалып жатыр. Ауыртпаса, бұл қалыпты жағдай.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'Тұзды тағамнан бас тартыңыз 🧂', 'Аяқтарыңыз ісінсе, тұзды азайтыңыз. Суды көп ішу және ақжелкен көмектесуі мүмкін. Сақинаңыз саусағыңызды қысып тұрған жоқ па?'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'Кішкентай фабрика іске қосылды! 🏭', 'Енді қан жасушаларын бауырым емес, сүйек кемігім өндіреді. Маған көмектесу үшін Тамақтану бөлімінде темірге бай қандай тағамдар бар?'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'Тсс, мен ұйықтап жатырмын... 🤫', 'Анашым, мен неге қозғалмай жатырмын? Өйткені тәуліктің көп бөлігін ұйқымен өткіземін. Мен ұйықтағанда, Сіз де демалыңыз.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'Жасырын жаттығу уақыты! 🧘‍♀️', 'Кегель жаттығуларын ұмытпаңыз. Отырған жеріңізде жамбас түбі бұлшықеттерін қысып, қайта босатыңыз. Бұл босану кезінде қажет болады!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'Алғашқы тыныс алу жаттығулары! 🫁', 'Өкпемде сурфактант түзіліп жатыр. Бұл зат дүниеге келгенде алғашқы демімді алуға көмектеседі. Жаттығып жатырмын!'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'Өзіңізге күтім жасайтын күн 💅', 'Жүктілік кезінде пигментті дақтар пайда болса, күн сәулесінен қорғаныңыз. Бүгін бетіңізге маска жасап көрсеңіз қалай?'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'Бет-жүзін зерттеп жүр! 👶', 'Қолдарымен бетіне, мұрнына, тіпті кіндік бауына да тиеді. Сипап сезу қабілеті дамып келеді. Ол өзін танып жатыр!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'Тұздалған қияр мен балмұздақ? 🥒🍦', 'Ерекше тағам үйлесімдерін жегіңіз келе ме? Бұл — денеңіздің сигналдары. Дегенмен қант пен тұзды мөлшермен тұтынуға тырысыңыз.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'Көлемі кокос жаңғағындай! 🥥', 'Шамамен 28 см. Салмағы жарты келіден асты! Енді ол бұрынғыдан да қаттырақ тебеді.'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'Музыка қоямыз ба? 🎶', 'Анашым, сырттағы дыбыстарды естіп тұрмын! Сіздің сүйікті әндеріңіз маған да ұнайды. Бірге билейміз бе?'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'Кіндігіңіз сыртқа шығып кетті ме? 🔘', 'Ішіңіз үлкейген сайын кіндігіңіз де томпайып шығады. Қорықпаңыз, босанғаннан кейін қалпына келеді!'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'Ол не дыбыс еді, Анашым? 🔊', 'Кенет шыққан қатты дыбыстан шошып кетемін. Сіз тыныш болсаңыз, мен де тынышпын. Маған бесік жырын айтып бересіз бе?'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'Бесігім — өзіңіз... 💤', 'Сіз жүргенде мен тербеліп, ұйықтап қаламын. Ал тоқтағаныңызда оянып кетемін! Мені ұйықтату үшін баяу серуендеуді жалғастырайық па? 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'Тәтті су іштіңіз бе? 🥤', 'Гестациялық диабетке арналған тест өте маңызды. Менің де, Сіздің де денсаулығыңыз үшін міндетті түрде тексеруден өтіңіз.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'Ішіңізде сызық пайда болды ма? ➖', 'Linea Nigra — гормондардың әсері. Уайымдамаңыз, босанғаннан кейін жоғалады. Сіз қандай күйде болсаңыз да сұлусыз!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'Өмір сүру мүмкіндігім артты! 🌟', '24 аптаға толдым! Медициналық тұрғыдан енді өмір сүруге қабілетті деп есептелемін. Бұл — өте маңызды кезең, Анашым.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'Қыжыл мазалай ма? 🔥', 'Бұл менің шашым өсіп жатқандықтан емес, жатыр асқазанды қысып тұрғандықтан болады. Тамақтан кейін бірден жатпаңыз, тік отырыңыз.'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'Анашым, мен зерігіп кеттім! 🤸', 'Сіз тыныш жатқанда, мен оянамын. Ішіңізді сипап көріңізші, бәлкім, кішкентай ғана тебумен жауап берермін?'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'Қауындай болдым! 🍈', 'Шамамен 600 грамммын. Енді маған орын сәл тар болып барады. Тебуім күшейе түсуі мүмкін, кешіріңіз! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'Аяқ киіміңіз қысып жүр ме? 👟', 'Аяғыңыздың өлшемі ұлғаюы мүмкін. Қазір сәннен гөрі жайлылық маңызды. Кең спорттық аяқ киімге ауысыңыз!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'Шашымның түсі қалыптасып жатыр! 🎨', 'Генетикалық лотерея басталды. Ақшыл, қара әлде жирен боламын ба? Шашымның пигменті қалыптасып жатыр. Сіздіңше, кімге ұқсаймын?'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'Ісінуден шаршадыңыз ба? 🎈', 'Бір қызығы, су ішу ісінуді азайтады. Қияр, қарбыз сияқты суы мол тағамдар да көмектесуі мүмкін. Тұзды шектеңіз.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'Мен қызғылт түске еніп келемін...', 'Терім енді шыныдай мөлдір емес! Қылтамырларым қанға толып, түсім қызғылттанып келеді. Қан айналымыңыз жақсы болуы үшін Су трекеріндегі суыңызды ішуді ұмытпаңыз! 🥤'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'Ой! Мына дыбыс не еді? 😳', 'Есік тарс жабылғанда селк ете қалдым. Есту қабілетім өте жақсы, Анашым. Баяу музыка қосыңызшы, бірге демалайық.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'Мұрным ашылды! 👃', 'Мұрын жолдарым бітеліп еді, енді ашылды. Тыныс алуға жаттығып жүрмін.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'Ас қорыту баяулады ма? 🐌', 'Прогестерон ішектің жұмысын баяулатады. Кептірілген өрік, қара өрік және кебек қосылған нан Сізге көмектесуі мүмкін.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'Жастықтан қамал жасаңыз! 🏰', 'Жайлы ұйықтай алмай жүрсіз бе? Аяқтарыңыздың арасына және ішіңіздің астына жастық қойыңыз. Қосымша тірек міндетті түрде қажет!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'Мен йога шеберімін! 🦶', 'Сенуіңіз қиын шығар, бірақ аяғымның башпайын ұстап, аузыма сала аламын! Мен өте икемдімін. Ал Сізге еңкейгенде қиын ба?'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'Көзімді аштым! 👀', 'Анашым, сенуіңіз қиын шығар, бірақ мен қабағымды көтердім. Айналам қараңғы болса да, көру қабілетім қалыптасып келеді. Сізді көретін күн жақын!'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'Әкемді естіп тұрмын ба? 🗣️', 'Ер адамның дауысы жуан болғандықтан, мен оны жақсырақ естимін. Әкеммен сөйлесіңізші, маған ертегі оқып берсін.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'Сіз менің қорғанымсыз!', 'Иммундық жүйем қалыптасып келеді, сізден маған антиденелер өтеді. Мені аурулардан қорғап жүрсіз, Анашым. ❤️'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'Балтырыңыз құрыса ма? 🦶', 'Түнде балтырыңыз құрыса ма? Магний жетіспейді. Банан, бадам немесе йогурт... Бұлшықеттерге босаңсу қажет.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'Көзімді аштым! 👀', 'Қараңғы болса да, қабақтарымды енді аша аламын. Кірпіктерімді қағып қоямын. Әлемді көретін күнім жақын!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'Жарық түсіп тұр, Анашым! ☀️', 'Көзімді жыпылықтатып жатырмын! Егер ішіңізге күн сәулесі түссе, мен оның жарығын көремін. Әлем қандай түсті?'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'Крем жағатын уақыт келді 🧴', 'Ішіңіз тез өсіп, теріңіз созылып жатыр. Қышудың алдын алу үшін күн сайын ылғалдандырғыш крем жағыңыз.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'Алғашқы вакцина — Сізден 🛡️', 'Сізден оған антиденелер өтеді. Олар бөпеңізді туғаннан кейінгі алғашқы айларда қорғайды.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'Тұзды қияр ма? Жоқ! 🚫', 'Аяғыңыз ісінсе, тұзды барынша азайтыңыз. Тұздалған тағам дәмді болғанымен, ісінуге әкеледі. Лимон қосылған су ішіңіз.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'Бұл әлем тым шулы... 🔊', 'Құлағымның сезімтал болғаны сонша, тіпті сырттағы көліктердің дабылын да естимін. Аздап тыныштықта болайықшы? Маған Ақ шуылдардан жаңбырдың дыбысын қосып беріңізші, бірге мызғып алайық. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'Мен ырғақ ұстап жүрмін 🥁', 'Жүрегім бірқалыпты соғып тұр, тыныс алуға жаттығып жүрмін. Кейде ықылықтаймын.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'Мәреге жақындап қалдыңыз! 🏁', '2-триместрдің соңғы күндері. 3-кезең басталмай тұрып, қанып ұйықтап алыңыз!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', '3-триместрге қош келдіңіз! 🏁', 'Соңғы кезең басталды! Енді денеңіз ауырлай түседі, бірақ мәре сызығы көрініп тұр. Сабыр сақтаңыз, Анашым!'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'Асқазаныңыз өртеніп жатқандай ма? 🔥', 'Жатыр асқазанды жоғары қарай қысады. Сүт ішу немесе бір уыс шикі бадам жеу қыжылды басуы мүмкін.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'Бір шоқ брокколидеймін 🥦', 'Май қабатым қалыңдап, қолдарым мен аяқтарым томпая бастады.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'Ұя дайындаймыз ба? 🐣', 'Менің кереуетім, кішкентай киімдерім... Тізімді әкеммен бірге Ортақ сатып алу бөлімінде дайындаңыздар! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'Қан тобыңыз теріс пе? 🩸', 'Резус-факторы теріс аналар үшін маңызды апта. Иммуноглобулин екпесі қажет болуы мүмкін. Дәрігеріңізбен кеңесіңіз!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'Кірпіктерім ұзарып қалды! 👁️', 'Көзімді ашып-жұмамын. Жарық пен қараңғылықты ажырата аламын. Ішіңізге шам түсірсеңіз, бетімді бұрып әкетемін. Байқап көргіңіз келе ме?'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'Балық, балық, балық! 🐟', 'Қазір миымның ең жылдам дамып жатқан кезеңі. Маған Омега-3 қажет. Аптасына 2 рет балық жейсіз бе?'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'Мен осындамын, Анашым! 👋', 'Кейде тыныш жатамын, ал кейде билеймін. Тебуімді санап жүрсіз бе? Бәрі жақсы, тек маған орын тарылып барады.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'Аяқтарыңызда тамырлар торланып көріне ме? 🕸️', 'Варикозды тамырлар пайда болуы мүмкін. Ұзақ уақыт тік тұрып қалмаңыз. Кешке аяқтарыңызды қабырғаға көтеріп жатыңыз.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'Қан өндіретін фабрика іске қосылды 🩸', 'Осы уақытқа дейін қан жасушаларын бауыр өндірсе, енді оларды сүйек кемігі өндіреді. Бұл — өз бетінше өмір сүруге дайындық!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'Темір мен C витаминінің үйлесімі 🥩🍊', 'Анемия қаупін азайту үшін ет жегенде апельсин шырынын ішіңіз. C витамині темірдің сіңуін 2 есе арттырады.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'Үлкен орамжапырақтаймын 🥬', 'Терім тегістеліп, бетім томпайып келеді. Сізді көруге асықпын!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'Тыныс алу қиындады ма? 😮‍💨', 'Мен жоғары көтерілген сайын көкетті қысып барамын. Терең тыныс алуға тырысыңыз, Анашым. Аз қалды, жақында мен төмен түсемін.'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'Сөмкеңізді ойластырдыңыз ба? 👜', 'Әлі ерте емес! Перзентханаға арналған сөмке тізімін қарап шығыңыз. Жетіспейтін заттарды қазірден дайындап қою күйзелісті азайтады.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'Бір құпия айтайын ба? 🤫', 'Сіз ұйықтап жатқанда, даусыңызды елестетіп, мен де ұйқыға кетемін. Түсімде кімді көремін деп ойлайсыз? Әрине, Сізді! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'Бұл шоколад па? 🍫', 'Ммм, дәмі маған дейін жетті! Енді күш-қуатым тасып тұр. Келіңіз, билейік, Анашым! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'Мен асқабақтай болып қалдым! 🎃', 'Беттерім сонша томпайып келеді, мені тістеп алғыңыз келетін шығар! Мұнда орын тар, бірақ Сізге жақын болған қандай жақсы.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'Мен басымды төмен қаратып жатырмын! 🙃', 'Өмірге төңкеріліп қарау қызық екен! Босануға дайындалып жатырмын, Анашым. Осы қалыпта Сізге одан да жақынмын.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'Ішіңіз қатайып жатыр ма? 🤰', 'Қорықпаңыз, періштем! Бұл жай ғана жаттығу. Біз бір команда болып, сол маңызды күнге дайындалып жатырмыз!'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'Мінезім қандай болады? ✨', 'Қырсық па, әлде сезімтал ма? Туатын күнім бойынша жұлдыз белгісі мен туралы не дейді? Сіздің жұлдыз белгіңізбен үйлесемін бе? Келіңіз, Жұлдыз жорамалын қарайық! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'Қабырғаларыңыз ауыра ма? 🥊', 'Кешіріңіз, Анашым, орным тар. Аяқтарымды созғанда, қабырғаларыңызға тиіп кетемін. Тік отыру жеңілдетуі мүмкін.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'Тебулерімді санап жүрсіз бе? 🦶', 'Қазірдің өзінде қимыл-қозғалыс тәртібім қалыптасып келеді. Тебу санағышына кіріп, менің белсенділігімді бақылаңыз. Бәрі дұрыс па?'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'Миым қатпарланып жатыр! 🧠', 'Бұрын тегіс еді, ал қазір қатпарлар мен сайлар пайда болып жатыр. Бұл миллиардтаған нейронның іске қосылғанын білдіреді. Данышпан келе жатыр!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'Рефлюкс Сізді шаршатты ма? 🔥', 'Асқазан қышқылы тамағыңызға көтеріле ме? Тамақтан кейін сағыз шайнау немесе жылы сүт ішу көмектесуі мүмкін.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'Көлемім асқабақтай! 🎃', 'Шамамен 39-40 sm. Салмағым 1.2 kq болды! Сізге ауыр болып жүрмін бе? Кешіріңіз, Анашым, бірақ мен салмақ қосуым керек.'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'Сізге таза ауа керек 🌿', 'Бүгін үйден шығып, жайлы әрі ауасы таза жерде шай ішеміз бе? Анаға қолайлы орындарды қарап көріңіз!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'Сол бір үлкен күн... ✨', 'Асықпай-ақ қояйық, бірақ сөмкемізді біртіндеп жинай бастайық. Перзентхана сөмкесінің тізімінде не бар екенін көрейік пе?'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'Тсс... Мен ұйықтап жатырмын 😴', 'Миымның тез дамып жатқаны сонша, уақытымның көбін ұйқымен өткіземін. Сіз де демалыңыз, Анашым.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'Маған қандай ат қоясыз? 👶', 'Әлі шешпеген болсаңыз, әкеммен бірге Бөпе есімдерінің тізімін қарап шығыңыздар. Маған қайсысы көбірек жарасады?'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'Бөлмем, төсегім, кішкентай заттарым... 🐣', 'Бізге қажет нәрсенің бәрін алдыңыз ба? Ұсынылатын өнімдерді қарап көріңіз, бәлкім, бірдеңе ұмыт қалған шығар.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'Жатыр бұлшықеттері босануға дайындалып жатыр.', 'Қорықпаңыз, бұл жай ғана жаттығу. Егер ауырсыну жиілесе, Толғақ өлшегішпен аралығын тексеріңіз!'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'Әкемнің даусы естілді! 🧔', 'Оның дауысын естігенде жүрегім одан сайын қатты соғады. Оған менің де осында екенімді, сәлем жолдап жатқанымды айтыңызшы! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'Сүйектерімді нығайтыңызшы! 💪', 'Маған кальций керек, Анашым. Бір стақан сүт немесе айран ішсеңіз, екеуіміз де өте күшті боламыз! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'Тық-тық! Онда кім бар? ✊', 'Тебулерім кейде жаныңызды ауыртып жібере ме? Кешіріңіз 🥺 Мен тек Сізге қол тигізгім келеді.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'Деміңіз тарылып жүр ме? 😮‍💨', 'Мен сәл жоғары көтеріліп, өкпеңізді қысып тұрмын. Кешіріңіз, Анашым, жақында төмен түсемін де, Сіз еркін тыныстайсыз! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'Иісіңізді сеземін...', 'Мені құшағыңызға алатын сәтті ойлап жүрсіз бе? Мен күн сайын сол сәтті армандап өсіп келемін, Анашым! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'Үйім тарылып барады... 🏠', 'Қимылдарым жұдырық пен шынтақ соққыларына айналып барады. Бәрі дұрыс па? Келіңіз, бірге Тебу санағышын тексерейік!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'Маникюрім дайын!', 'Сенбейсіз, тырнақтарым саусақ ұшына дейін жетіп қалды.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'Дәрігерге бару жиілейді! 🩺', 'Босанатын перзентхана мен дәрігерді таңдадыңыз ба? Дәрігерлер мен клиникалар тізімін қарап шығыңыз! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'Бірде күліп, бірде жылап жүрсіз бе?', 'Гормондар тағы да өз дегенін істеп жүр. Босанудан қорқу мен бөпеңізбен қауышу қуанышы қатар сезіледі. Ішіңіздегіні Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'Сізден маған ерекше күш беріліп жатыр! 🛡️', 'Ауырмаңызшы, Анашым! Сіздің иммунитетіңіз менің алғашқы қорғаным болады. Біз — жеңілмейтін командамыз! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'Тағы да ұйқыңыз қашты ма? 🥺', 'Ал мен болсам, пырылдап ұйықтап жатырмын. Көзіңізді жұмып, мені елестетіңізші... Бәлкім, түсімізде кездесерміз? 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'Сүйектерім тастай қатайып келеді! 🦴', 'Бірақ ол үшін Сіздің ағзаңыздағы қорды алып жатырмын... Кешіріңізші! 🙈 Бір стақан сүт ішсеңіз, татуласамыз ба? 🥛'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'Әлгі әнді тағы бір айтып беріңізші! 🎶', 'Даусыңыз маған сондай тыныштық сыйлайды... Сіз ән айтқанда, мен ішіңізде билеймін, сезесіз бе? 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'Қабырғалар қысып барады! 🏠', 'Маған орын тым тар болып кетті, Анашым. Аяғымды созсам, қабырғаңызға тиеді... Ауыртып қойсам, сүйіп жазып жіберейін бе? 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'Киімдерімді үтіктеп қойдыңыз ба? 👗', 'Олардың иісі қазірдің өзінде мұрныма келіп тұрғандай. Мені сол киімдермен көруге асығып жүргеніңізді білемін! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'Хауызымның суы азайып қалыпты... 💧', 'Мен таза әрі мол суда жүзгенді жақсы көремін. Мен үшін бір стақан су ішесіз бе? 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'Жолды тексеріп жатырмын! 🔦', 'Басымды төмен қаратып, шығар есікке қарап жатырмын. Сіз тек терең тыныс алыңыз, бәрі керемет болады!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'Мынау кімнің жылы қолы? 🖐️', 'Әкем бе? Оның жанасуын сезгенде тынышталып қаламын. Оған мен де қолымды созғанымды айтыңызшы, алақан түйістірейік! ✋'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'Менің бөлмем дайын ба? 🧸', 'Бесігіме қарап, қиялға беріліп жүрсіз бе? Оның ішіне қойған ойыншықты құшақтауға асықпын! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'Төмен түсіп келемін, сезіп тұрсыз ба? ⬇️', 'Жамбас сүйектеріңіздің арасына орналасып келемін. Енді тыныс алуыңыз жеңілдейді, бірақ дәретханаға жиі баратын боласыз! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'Иммунитетім нығайып келеді 🛡️', 'Сізден маған берілетін антиденелер мені микробтар әлеміне дайындап жатыр. Сүтіңіз де мені қорғайды, Анашым!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'Менің алғашқы киімім қайда? 👕', 'Перзентханаға арналған сөмкені жинадыңыз ба? Маған кигізетін кішкентай комбинезонды аялай сипаңызшы...'),
  ('deba1190-6096-4dec-88eb-70e669fb3ccb', 'Сізді көргім келеді! 👀', 'Көздерім ашық, бірақ мұнда қараңғы. Жүзіңіз бен күлкіңізді көретін күнге дейінгі уақытты санап жүрмін. Аз қалды! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'Терім тегістеліп келеді! 🧖‍♀️', 'Денемдегі түктер түсіп, май қабатым қалыңдап келеді. Сіздің нәзік жанасуыңызға дайындалып жатырмын, Анашым. Үлбіреген жұмсақ боламын! ☁️'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'Көздерімді бақырайтып аштым! 👀', 'Қараңғы болса да, бәрін бақылап жатырмын. Сізге ұқсаймын ба, әлде әкеме ме екен? Екеуіңіз бәстесіп қойдыңыздар ма? 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'Тсс... Мен ұйықтап жатырмын! 😴', 'Миымның қарқынды дамып жатқаны сонша, маған көп ұйқы керек. Сіз де менімен бірге ұйықтап алыңызшы, Анашым? 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'Үйге өзгеріс енгізіп жүрсіз бе? 🌪️', 'Барлық жерді тазалап, шкафтарды реттегіңіз келіп жүр... Бұл — ұя салу инстинкті! Бірақ өзіңізді шаршатпаңыз, маған жақсылап демалған ана керек.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'Мұнда тым тар болып кетті! 🏠', 'Бұрылғым келеді, бірақ орын жоқ. Шынтағымды шығарсам, ішіңіз қисайып көрінеді. Қарап күлесіз! 😄')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8'::uuid, 'Маған пайдалы май керек! 🥑', 'Авокадо, жаңғақ немесе зәйтүн майы... Мені томпақ бөпе ету өз қолыңызда!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'Жүрегіңіздің үні маған бесік жырындай... 💓', 'Басым төмен қарап жатыр, сондықтан құлағым жүрегіңізге жақынырақ. Осы ырғақ — мені тыныштандыратын жалғыз әуен.'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'Мен күш жинап жатырмын! ⚡', 'Көп қимылдамай жүрмін бе? Қорықпаңыз. Қазір маған ұйқы қажет. Маңызды күнге күш жинап жатырмын. Сіз де демалыңыз! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'Шынтағымды сездіңіз бе? 💪', 'Кешіріңіз, Анашым! Керілгім келеді, бірақ орын жоқ. Ішіңіз бұдыр-бұдыр болып көрінгенде, маған күлесіз бе? 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'Пингвин сияқты жүрсіз бе? 🤭', 'Мен төмен түскендіктен, жүрісіңіз өзгерді. Бірақ қандай күйде, қалай жүрсеңіз де, Сіз әлемдегі ең сұлу анасыз! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'Ық... Ық... 😲', 'Тағы да ықылық атып жатырмын! Көкетімді жаттықтырып жүрмін. Ішіңіз ырғақты түрде селкілдесе, біліңіз — ол мен!'),
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800', 'Дәрігермен кездестік пе? 👩‍⚕️', 'Сол суық гель ішіңізге тигенде, мен қытықтанамын! 🙈 Бірақ жүрегімнің соғуын есту Сізге тыныштық сыйлайтынын білемін.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'Біз бір командамыз! 🤝', 'Толғақ басталғанда қорықпаңыз. Терең тыныс алыңыз. Біз бірге бәрін еңсереміз, уәде беремін!'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'Сөмкелер есік алдында тұр ма? 🎒', 'Кез келген сәтте «Тосынсый!» деуім мүмкін. Маған кигізетін алғашқы бас киімді сөмкеге салдыңыз ба? Тоңғым келмейді. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'Мәреге аз қалды! 🏆', '37-апта аяқталып келеді! Енді ерте мерзімді кезеңдеміз. Яғни бүгін дүниеге келсем де, өкпем тыныс алуға дайын!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'Түсімде Сізді көрдім... 💤', 'Даусыңыз, иісіңіз, жылуыңыз... Оянып, Сізді шынымен құшақтайтын сәтті асыға күтіп жүрмін, Анашым!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'Ішіңіз қатайып кетті ме? 🤰', 'Бұл жай ғана дайындық па, әлде мен келе жатырмын ба? Күмәндансаңыз, Толғақ өлшегішін ашыңыз. Ол нақты айтып береді: ауруханаға бару керек пе, әлде төсекке жату керек пе?'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'Мен әлі осындамын! 👋', 'Маған орын өте тар, сондықтан аз қимылдаймын. Бірақ алаңдасаңыз, Тебу есептегішіне кіріңіз. Келіңіз, бірге санайық! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'Шұлықтарымды салдыңыз ба? 🧦', 'Тоңғым келмейді, Анашым! Аурухана сөмкесінің тізімін соңғы рет тексеріңіз. Менің алғашқы комбинезоным сонда ма? 🥰'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'Тебуім азайды ма? 🦶', 'Маған орын тар болып қалды, Анашым! Бірақ қимылдарымды сезуіңіз керек. Күмәніңіз болса, тәтті бірдеңе жеп, Тебуді санау бөліміне кіріңіз.'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'Құжаттар дайын ба? 📄', 'Жеке куәлік, талдау нәтижелері... Сөмкеңізді соңғы рет тексеріп шығыңыз. Перзентхана сөмкесінің тізімінде бәрін белгілеп қойдыңыз ба? ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'Көзіңізді жұмыңыз... 😌', 'Босанудан қорықпаңыз. Мені алғаш рет құшағыңызға алатын сәтті ғана елестетіңіз. Менің иісім бар ауырсынуды ұмыттырады.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'Жатыр мойны 🗝️', 'Жасырын жұмыс жүріп жатыр! Жатыр мойны жұмсарып, жұқарып, ашыла бастайды. Сіз сезбесеңіз де, денеңіз маған жол ашып жатыр.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'Бүгін дәл сол күн бе? 🗓️', '40 апта аяқталды! Күнтізбеде бүгінгі күн белгіленген. Келе берейін бе, әлде тағы біраз еркелейін бе? Кез келген сәтте тосынсый жасай аламын! Дайын болыңыз! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'Мен кешіккен жоқпын! 👑', 'Жұлдыздар сахнаға ең соңында шығады ғой, Анашым! Тағы біраз еркелейін, сосын келемін. Сабыр сақтаңыз! 😌'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'Ұйықтай алмай жүрсіз бе? 🥺', 'Көзіңізге ұйқы келмей жүр ме? Келіңіз, мен дүниеге келгенде маған тыңдататын дыбыстарды қазірден бірге тыңдайық. Ақ шу бөлімі екеуімізді де тыныштандырады. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'Сөмкемді жинап, есік алдында күтіп отырмын! 🚪', '38 апта! Енді дүниеге келуге ресми түрде дайынмын. Өкпем де, миым да, бүкіл ағзам толық жетілді.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'Суыңыз кетсе, не істейсіз? 💦', 'Дүрбелеңге салынбаңыз! Блог бөліміндегі Босанудың негізгі 3 белгісі мақаласын оқыңыз.'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'Төмен қарай жылжып келемін... ⬇️', 'Жамбас сүйектеріңізге қысым түсіріп жатқанымды білемін. Бірақ бұл — Сізбен қауышудың жалғыз жолы. Менің төзімді Анашым! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'Ұйқысыз түндер ме? 🥱', 'Босану жақындаған сайын ұйықтап кету қиындай түсуі мүмкін. Бұл — ағзаңыздың Сізді бөпелі өмір ырғағына дайындауы.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'Жүрегім қалай соғып тұр? 💓', 'Мені сағынғанда қолыңызды ішіңізге қойыңыз. Жүрегіміз бірге соғады. Бәрі жақсы, тек кездесетін күнімізді күтіп жүрміз. 🗓️'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'Тық-тық, бұл мен! ✊', 'Ішіңіз оқтын-оқтын ауыра ма? Уақыт жоғалтпай, Толғақ өлшегіш түймесін басыңыз. Егер толғақ аралығы қысқарып жатса, демек көптен күткен күн — бүгін! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'Уыз келді ме? ✨', 'Емшектен сарғыш сұйықтық бөлінуі мүмкін. Бұл — бөпеңіздің алғашқы қорғаны. Блогтардан емізу туралы оқыңыз. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'Жалған ба, әлде шынайы ма? 🤔', 'Ішіңіз бір қатайып, бір босап жатыр ма? Егер толғақ тұрақты болмаса, бұл жалған толғақ. Нақты білу үшін Толғақ өлшегішті ашып, тексеріп көріңіз!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'Шырышты тығын түсті ме? 🩸', 'Қою бөлінді шықса, бұл жатыр мойны ашыла бастағанын білдіреді. Қорықпаңыз, бұл — босануға дайындалу керектігін білдіретін белгі.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'Шалп! Бұл ненің дыбысы? 💦', 'Қағанақ суы кетсе, үрейленбеңіз. Терең тыныс алып, дәрігеріңізге хабарлаңыз. Мен келе жатырмын! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'Стресті қуатын кез келді! 😮‍💨', 'Уайымдап жүрсіз бе? Жаттығулар бөліміндегі босану кезінде тыныс алу тәсілдерін қазірден үйреніңіз. Олар толғақ кезінде Сізге өте қажет болады.'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'Табиғи жолмен көмектесейік 🍍', 'Құрма мен ананас жатыр мойнын жұмсартады дейді. Тамақтану бөлімін ашып, бүгінгі мәзіріңізге оларды қосыңыз. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'Жүрек соғысы... ❤️', '40 аптадан асқанда плацентаның жағдайын тексеру үшін КТГ (NST) тексеруінен өту маңызды. Бәрі дұрыс екеніне көз жеткізіңіз.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'Баспалдақпен көтерілейік пе? 🪜', 'Маған жол көрсетші! Баспалдақпен көтерілу немесе отырып-тұру жаттығуы менің төмен түсуіме көмектесуі мүмкін. Жаттығулар бөлімін қараңыз.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'Мұнда ауа райы керемет 🌡️', 'Жылы, қараңғы әрі жайлы... Шыққым келмейді десем, маған ренжімейсіз ғой? 🥺 Қалжыңдап тұрмын, келе жатырмын!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'Жүрегім қалай соғып тұр? 💓', 'Дәрігерде NST тексеруінен өтіп жатырмыз ба? Сол дүрс-дүрс еткен дыбысты естігенде, көңіліңіз бірден жайланады ғой...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'Құрма жеп жүрсіз бе? 🌴', 'Табиғи босану үшін осындай дәмді тәсілді қолданып көрген жөн!'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'Мен салмақ қосып жатырмын ғой! ⚖️', 'Мұнда болған әр күнімде аздап томпая түсіп жатырмын. Бетім сүйкімді бола түсті, бірақ Сізге қиындап барады. Кешіріңіз! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'Сөмкеге тіскебасар салдыңыз ба? 🍫', 'Босанғаннан кейін қатты қарныңыз ашады! Перзентхана сөмкесіне өзіңіз жақсы көретін печенье немесе шоколад салып қойыңыз.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'Плацента қартая ма? 🍂', 'Дәрігер қағанақ суының мөлшерін тексеріп жүр ме? Маған әлі де оттегі жеткілікті келіп тұрса, демек мәселе жоқ. Бұл — бірге өткізетін соңғы күндеріміз ғана.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'Түнде толғақ басталды ма? 🌙', 'Ұйқыдан оятқан сол ауырсыну... Бұл нағыз толғақ па? Уақыт жоғалтпай, Толғақ өлшегішін қосыңыз. Бәлкім, дәл осы түн — СОЛ ТҮН шығар! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'Шығу туралы бұйрық келді ме? 📢', 'Дәрігер толғақты жасанды түрде қоздыруды ұсынып отыр ма? Қорықпаңыз. Ең бастысы — менің аман-есен құшағыңызға келуім. Қай жолмен келгенім маңызды емес!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'Жүктілік кезіндегі соңғы суретіңіз... 📸', 'Осы ішіңізге соңғы рет қараңыз. Ертең-ақ құшағыңызда болуым мүмкін. Осындай ғажайып денеңізді мақтан тұтыңыз, Анашым!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('7797557a-9277-450c-98b3-b0fa58923513'::uuid, 'Кешкі шомылудан кейін ұйықтайтын уақыт! 🛁', 'Бөпеңіздің тыныш ұйықтауы үшін түнгі ұйқы алдында шомылдыру өте пайдалы.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'Күнделікті жөргек санын бақылап жүрсіз бе? 🧷', 'Бөпеңіздің жеткілікті тамақтанғанын көрсететін ең жақсы белгі — жөргектері. Жөргекті ауыстырған сайын Anacan қолданбасында белгілеуді ұмытпаңыз!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'Ұйқы режимін талдайық. ⏱️', 'Бөпеңіз ұйықтағанда ұйқы таймерін қосып, оның күнделікті ұйқы нормасын қаншалықты сақтайтынын графиктен көріңіз.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'Аналарға арналған дәмді әрі пайдалы таңдау! 🍲', 'Қуатыңызды арттыратын «Пайдалы рецепттер» бөлімін қарап шығып, өзіңізге қамқорлық жасаңыз.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'Бөпеңіз тез өсіп келеді! ⚖', '️ Апта сайынғы салмағын Даму трекеріне енгізіп, оның қалыпты өсу динамикасын қолданба арқылы бақылаңыз.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'Сұрағыңыз бар ма? 🤖', 'Тіпті түнде де Anacan AI Сізбен бірге! Мазалаған сұрақтарыңызды қойып, дереу қолдау алыңыз.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'Бөпеңізбен бірге алғашқы серуендер! 🌳', 'Күн райы жақсы болса, далаға шығыңыз. Бөпеңіздің күн сайын таза ауада болуы өте маңызды әрі пайдалы.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'Осы сәтті мәңгілік естелікке айналдырыңыз! 📸', 'Бүгінгі сүйкімді сәттерді Бөпе альбомына жүктеп, болашақта қарап, жымиып еске алатын естеліктер жасаңыз.'),
  ('1af46170-3a5b-41ea-bb18-ce899698f996', 'Алғашқы күніңіз құтты болсын! 🥳', 'Бөпеңіздің ұйқысы мен тамақтану тәртібін бақылау үшін Anacan қолданбасындағы таймерді пайдалана бастаңыз.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'Бөпеңіз ұйықтағанда, Сіз де демалыңыз! 😴', 'Бүгін өзіңізді қалай сезінгеніңізді Көңіл күй күнделігіне жазуды ұмытпаңыз.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'Уыз сүті — алғашқы екпе! 🤱', 'Тамақтану мөлшерін қолданбадағы Тамақтануды бақылау құралы арқылы оңай тіркеңіз.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', 'Сүтім аз деп мұңаймаңыз! 🥛', 'Бөпеңіздің асқазаны әлі шиедей ғана. Күнделікті тамақтану статистикасын қолданбадан бақылай аласыз.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'Өзіңізге уақыт бөліңіз. 💆‍♀', '️ Жатыр бұлшықеттеріңіз қалпына келіп жатыр. Бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'Бөпеңіздің терісіндегі ақ қабат оны қорғайды. 👶 Уайымдамаңыз.', 'Жөргегін ауыстырған сайын Anacan-да белгілеп, көрсеткіштердің қалыпты екенін тексеруді ұмытпаңыз!'),
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c', 'Бөпеңіздің ему рефлексі өте күшті! 🍼', 'Әр емізу уақытын таймермен бақылап, оның жеткілікті тойғанына көз жеткізіңіз.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'Еш себепсіз көңіліңіз босай ма? 😢', 'Бұл — мүлде табиғи жағдай! Сезімдеріңізді Anacan AI-мен немесе Қауымдастығымызда бөлісіп, қолдау ала аласыз.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'Бөпеңізді ұйықтату қиын болып жүр ме? 🎶', 'Қолданбамыздағы Ақ шу құралын қосыңыз — бөпеңіз ана құрсағындағыдай терең ұйқыға кетсін.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'Кіндік қалдығы құрғақ әрі таза болуы керек. ⏱️', 'Кіндік қалдығы суланса, оны міндетті түрде құрғатып, дәрігер тағайындаған антисептикалық ерітіндіні күн сайын қолдану қажет.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'Аналардың дәруменге бай тағамдармен тамақтануы өте маңызды! 🥗', 'Пайдалы тағам рецептері бөліміне кіріп, күш-қуатыңызды қалпына келтіріңіз.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'Ол Сізді иісіңіз бен даусыңыздан таниды! 👃', 'Сондықтан Сіз бөлмеден шығып кеткенде, бөпеңіз мазасызданып, өзін қауіпсіз сезінбеуі мүмкін.'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', '«Қолға үйреніп қалады» деген аңызға сенбеңіз! 🤗', 'Бөпеңізді жиі құшақтаңыз. Бұл араларыңыздағы байланысты нығайтып қана қоймай, сүтіңіздің көбеюіне де көмектеседі.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'Күн мен түн ауысып кетті ме? 🛌', 'Ұйқы режимі мен күнделікті нормаларды қолданбадан бақылаңыз, бөпеңіз ұйықтағанда, Сіз де көз шырымын алыңыз.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'Жоспарлы тексерулер басталады. 💉', 'Бөпеңіздің бойы мен салмағын Даму трекеріне енгізіп, жеке даму кестесін жасаңыз!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'Аралықтарды ұмытпау үшін таймер осында. 🍼', 'Жөргек ауыстыру мен тамақтандыру уақытын Anacan көмегімен оңай реттеңіз.'),
  ('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c', 'Суперана болуға міндетті емессіз! 🦸‍♀', '️ Көмек сұраудан қысылмаңыз. Шабыт алу үшін Блогтар бөліміндегі мақалаларды оқыңыз.'),
  ('ded576fe-d3fa-4078-9b83-36eaf5b495d5', 'Дамуын қадам сайын бақылаңыз. 📏', 'Бас шеңбері, бойы мен салмағы туралы деректерді Салмақ трекеріне енгізуді ұмытып кеттіңіз бе? Қазір белгілеңіз.'),
  ('0240c7db-30e2-4d5b-86a4-0b27f230557c', 'Әкесінің құшағы 🫂', 'Алғашқы аптаның шаршауы әбден қажытты. Бүгін кешке әкесі бөпені кеудесіне жатқызып ұйықтатсын әрі Ақ шуды қоссын. Ал Сіз жылы душ қабылдап, есікті жауып, небәрі 15 минутқа су астында бәрін ұмытыңыз. Сіздің қолыңыздан келеді.'),
  ('7449500c-dd2f-4529-a9a7-67ddeee4fe31', 'Tummy time (етпетінен жату) уақыты! 🐢', 'Ояу кезінде оны 1-2 минут етпетінен жатқызып, бұлшықеттерін нығайтыңыз.'),
  ('74dae015-c762-4d96-ad34-7d706065ef5f', 'Құттықтаймыз, ана атанғаныңызға 1 апта болды! 🥳', 'Құттықтаймыз, ана атанғаныңызға 1 апта болды! 🥳 Бөпенің фотосессиясы бөлімін пайдаланып, осы ерекше күнге естелік сурет жасаңыз.'),
  ('7c7a5fbe-09ea-4f4c-a054-883ad490f939', 'Алғашқы аптаның көрсеткіштерін қарайық па? 📊', 'Anacan қолданбасынан ұйқы, жөргек ауыстыру және тамақтандыру бойынша апталық статистикаңызды тексергіңіз келе ме?'),
  ('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c', 'Дененің қалпына келуі 🩹', 'Денеңіз әлі де қалпына келіп жатыр, тігістеріңіз де ауыруы мүмкін. Өзіңізден мінсіз болуды талап етпеңіз.'),
  ('d83a6f20-2dc5-45c9-9550-38fedec5c042', 'Ішек микрофлорасы қалыптасып жатыр! 🦠', 'Іші желденіп, мазасыздана бастаса, Anacan қолданбасындағы Ақ шу бөлімінің ырғақтары оны тыныштандыруға көмектеседі.'),
  ('3258a482-400c-485d-af7c-ccb221416732', 'Түнде ояну Сізді шаршатып жүр ме? 😴', 'Көңіл күй күнделігіне бүгінгі сезімдеріңізді жазып қойыңыз, Anacan AI Сізге пайдалы кеңестер берсін.'),
  ('80a2cd79-a6d6-4c87-b540-c42931228485', 'Бөпеңіздің асқазаны үлкейіп келеді. 🍒', 'Тамақтануды бақылау құралы арқылы оның қанша жегенін тіркеп, күнделікті нормасын тексеріңіз.'),
  ('cdd7b6ae-f340-479e-9d33-221c6775ebb3', 'Бөпеңізді қатты құндақтамаңыз, еркін қимылдасын! 🚫', 'Пайдалы ақпарат пен заманауи тәсілдер туралы көбірек білу үшін блогтарымызды оқыңыз.'),
  ('1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'Сүтіңіз енді құнарлы жетілген сүтке айналып келеді. 🥛', 'Емізу таймерін қосып, бөпеңіздің бүгін қанша емгенін дәл өлшеңіз!'),
  ('9a18572b-e386-4df8-ba20-b5eb78b8f99f', 'Алғашқы 10 күн қалай өтті? 📸', 'Ұйқысыздық, қорқыныш, кейде көз жасы және алапат махаббат сезімі... Алғашқы 10 күнді, яғни ең қиын бастау кезеңін артта қалдырдыңыз! Сіз кереметсіз.'),
  ('ffd7ff0c-bf80-4552-8a28-8d30f0674b07', 'Бүгін кем дегенде 15 минутты тек өзіңізге арнаңыз. 🛁', 'Жылы душ қабылдап, қолданбадағы пайдалы рецепттермен өзіңізді қуантыңыз.'),
  ('092f30cd-002d-4c4e-a83e-0b13c38cc743', 'Бөпеңіздің көруі айқындала түсуде! 👀', 'Ол енді Сіздің жүзіңізді жақсырақ ажыратады. Осы жағымды сәттерден туған сезімдеріңізді Көңіл күй күнделігіне жазыңыз.'),
  ('20684bd3-d3fb-479e-89f1-9adf84e485af', 'Тамақтану тәртібі қалай жүріп жатыр? 🤱', 'Қолданбадағы таймерді қосып, тамақтану нормасын Тамақтануды бақылау құралы арқылы оңай қадағалаңыз.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'Ұйқы мен тамақтану арасындағы тепе-теңдік. 📚', 'Блогтар бөліміндегі жаңа туған нәрестелердің дамуы туралы ең соңғы мақаламызды оқыдыңыз ба?'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'Құттықтаймыз, бөпеңізге 2 апта толды! 🎈', 'Осы шағын мерекені атап өту үшін «Бөпенің фотосессиясы» бөліміндегі қызықты идеяларды пайдаланыңыз.'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'Кейде тамақтандыру ұзаққа созылуы мүмкін. 🍼', 'Таймерді пайдаланып, үдерісті талдаңыз. Ең бастысы — өзіңізге де, бөпеңізге де жайлы болуы.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'Өзіңізді қалай сезініп жүрсіз? 🧘‍♀', '️ Ана болу әрі керемет, әрі шаршатады. Көңіл күй күнделігіне кіріп, бүгінгі көңіл күйіңізді бағалаңыз.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'Бөпеге күтім жасау үшін тағы не қажет? 🧴', 'Басқа аналар қолданып көріп, ұнатқан өнімдерді «Ұсынылатын өнімдер» бөлімінен табыңыз.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'Жөргек ауыстыру қалыпты әдетке айналды! 👶', 'Күнделікті зәр мен нәжіс шығуын жөргек трекеріне белгілеп, бөпеңіздің денсаулығын бақылаңыз.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'Ана да демалуы керек! 🛋', '️ Бөпеңіздің ұйқы режимін таймермен белгілеп қойсаңыз, енді демалу кезегі Сізде. Өзіңізге шай құйып, тынығыңыз.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'Іш кебу мазалап жүр ме? 🌪️', 'Алаңдамаңыз. Бөпеңіздің ішін ақырын уқалап, көңілін басқаға аудару үшін Ақ шуды қосыңыз.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'Күнделікті есебіңіз дайын! 📊', 'Anacan қолданбасына кіріп, бүгінгі ұйқы, тамақтану және жөргек ауыстыру кестелерінің талдауын қараңыз.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'Өсу кезеңін бақылап отырамыз! 📏', 'Келесі ай жақындап қалды. Қолданбадағы Даму трекері бөліміне кіріп, деректерді жаңартқаныңызға көз жеткізіңіз.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'Бірге болғандарыңызға 20 күн толды! 🥰', 'Сіз керемет анасыз! Бөпе фотосессиясы құралымен осы күнді әдемі естелікке айналдырыңыз.'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'Бүгін тек жағымды эмоциялар! ✨', 'Көңіл күй күнделігін ашып, бөпеңіздің Сізді ең қатты күлдірген сәтін жазып қойыңыз. Anacan AI Сізді тыңдайды!'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'Даму секірісі кезеңі! 📈', 'Бөпеңіз жиі ашығуы мүмкін. Таймер арқылы тамақтануын бақылап, үдерісті қадағалаңыз.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'Кешкі мазасыздық күшейді ме? 🎶', 'Бұған іш кебуі немесе шаршау себеп болуы мүмкін. Оны Ақ шу бөліміндегі табиғат дыбыстарымен тыныштандырыңыз.'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'Тура 3 апта! 🎉', 'Бөпеңіздің осы шағын мерейтойын атап өту үшін Бөпе фотосессиясы бөлімін пайдаланып, сүйкімді бір сәтті мәңгілік естелікке айналдырыңыз.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'Өзіңізді де ұмытпаңыз! 🥗', 'Сіздің денсаулығыңыз — бөпеңіздің денсаулығы. Әйелдерге арналған пайдалы рецептілерден күш-қуатыңызды қалпына келтіретін тіскебасарды таңдаңыз.'),
  ('713d2aac-0316-483d-9c46-781631bb7e21', 'Сіз керемет анасыз! ✨', 'Бірге болғандарыңызға 30 күн толды. Бөпе альбомына алғашқы күн мен бүгінгі күннің айырмашылығын көрсететін коллаж қосыңыз.'),
  ('ef07a5ff-817b-4b0a-ad2a-706e799bad22', 'Жаңа ай, жаңа белес. 📊', 'Айлық тамақтану, ұйқы және жөргек статистикасын қарап, бөпеңіздің күн тәртібін қаншалықты жақсы қалыптастырғаныңызды көріңіз!'),
  ('282baeb2-eb26-44cb-9eff-2eb2d88677a2', 'Күннің шаршауын басыңыз. 🛁', 'Өзіңізге уақыт бөліп, бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, демалыңыз.'),
  ('5366cee2-8491-4a45-8d5c-88d78aa6eee0', 'Міне, 2-ші айға да қадам бастық! 🎊', 'Бөпеңіздің дамуын қолдау үшін онымен күні бойы сөйлесіңіз.'),
  ('c5b12eaa-4012-417b-bf89-d5bd9d26aee9', 'Тамақтану тәртібі өзгеруі мүмкін. 🍼', 'Бөпеңіздің тәбетін бақылау үшін Anacan таймерін қосып, күнделікті мөлшерін тексеріңіз.'),
  ('24927359-7877-4f99-9dea-0460583a0880', 'Күнделікті жөргек санын бақылап жүрміз. 🧷', 'Бөпеңіздің жеткілікті тамақтанып жүргеніне көз жеткізу үшін Anacan-да әр жөргек ауыстыруды белгілей беріңіз.'),
  ('77d01c80-0ffb-4089-a192-db04bf909aa1', 'Ұйықтауы қиындап жүр ме? 🌙', 'Ақ шу ішінен мұхит толқындарының дыбысын таңдаңыз. Бөпеңіз тәтті ұйқыға кеткенде, Сіз де демалыңыз.'),
  ('afe3841b-76da-4cfe-9cf7-b2077153f607', 'Алғашқы «а-гу» дыбыстары естіле бастады! 🗣️', 'Тілінің дамуын қолдау үшін бөпеңіз шығарған дыбыстарды қайталап, онымен сөйлесіңіз.'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'Уақыт тапқан сайын оқып, жаңа нәрселер үйреніңіз. 📚', 'Жаңа туған нәрестенің дамуы мен күтімі туралы ең пайдалы мақалалар Сізді Блогтар бөлімінде күтеді.'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'Бірінші айдағы тексеру жақындап қалды. ⚖️', 'Бөпеңіздің осы уақытқа дейінгі салмағы мен бойының өсуін Дамуды бақылау бөліміне енгізгеніңізге көз жеткізіңіз.'),
  ('eabf6802-121e-4850-8036-ab2dbabaf84e', 'Сезімдеріңізбен бөлісуден тартынбаңыз. 📝', 'Шаршадыңыз ба, әлде бақыттысыз ба? Қандай күйде болсаңыз да, бүгінгі эмоцияларыңызды Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('2b4adff1-6ebf-471c-9dc4-e4e39cc16323', 'Зейіні артып келеді! 👀', 'Бөпеңіз енді қара-ақ түсті контрастарды жақсырақ ажыратады.  Ішімен жатқызған кезде дамытуға арналған карточкаларды пайдалануды ұмытпаңыз.'),
  ('5e1b47e3-2994-433f-a7c8-b1e6a121de30', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Таймер арқылы оң немесе сол емшекпен емізгеніңізді белгілеп қойыңыз, ал Тамақтануды бақылау құралы бәрін есте сақтасын!'),
  ('8152dc55-7f72-41b2-bb12-02cf7745f75a', 'Әкелерді де үдеріске тартамыз! 👨‍🍼', 'Серіктес режимі арқылы әкелер де бөпенің дамуынан хабардар бола алады.'),
  ('77ad5a07-cc0a-4fb4-b323-d177412300b1', 'Апталық статистикаңыз дайын! 📊', 'Соңғы күндері ұйқы мен тамақтану нормаларын қаншалықты сақтағаныңызды талдау үшін қолданбаға кіріңіз.'),
  ('8fac7e6d-3d63-4646-99a7-c927a088e849', 'Таза ауа тәбетті ашады! 🌳', 'Бөпеңізді күн сайын таза ауаға алып шығуға тырысыңыз. Бұл Сізге де, бөпеңізге де өте пайдалы.'),
  ('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124', 'Сүтіңіздің сапасын арттырыңыз. 🍲', 'Пайдалы әрі дәмді тамақтану үшін қолданбадағы Пайдалы рецептер бөліміне назар аударыңыз.'),
  ('15d59560-fd44-4273-9de7-62fd70c1a0dd', '1 айдағы көрсеткіштер! 📏', 'Бойы мен салмағы туралы жаңа деректерді Даму трекеріне қосып, қалыпты өсу графигін тамашалап, мақтаныңыз.'),
  ('22b47ac3-665d-4f67-b497-67efe6238be4', 'Құттықтаймыз, бөпеңіз 1 айлық болды! 🥳', 'Осы ерекше күнді атап өту үшін Бөпе фотосессиясы бөлімінде қызықты суреттер жасаңыз.'),
  ('ed8acfc1-dd31-48da-a8f2-04bd91f60de7', 'Өзіңізге алғыс айтыңыз! 💖', 'Алғашқы әрі ең қиын айды артта қалдырдыңыз. Көңіл күй күнделігіне кіріп, осы айда атқарған ерлігіңізді атап өтіңіз.'),
  ('2037f6e8-905d-4847-8172-fdba3ba09cf5', 'Кешкі әдеттегі тәртіп бұзылып жүр ме? 🌙', 'Уайымдамаңыз. Бөпеңіз өзін ана құрсағындағыдай қауіпсіз сезінуі үшін Ақ шулардан жүрек соғысының дыбысын таңдаңыз.'),
  ('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8', 'Кейде бізге аз ғана үзіліс қажет. ☕', 'Бөпеңіз ұйықтап жатқанда Ұйқы таймерін қосып, өзіңізге тыныш демалатын уақыт бөліңіз.'),
  ('b61a8e62-d1c0-449f-9d5b-6bb72079c512', 'Ояу жүретін уақыты ұзарып келеді. ⏱️', 'Онымен ойнап, дамуына қолдау көрсету үшін Блогтар бөліміндегі ойындарға қатысты кеңестерді оқыңыз.'),
  ('111e6f27-8aef-4cfb-a5ab-60fea52474e0', 'Келесі айға дайындық. 🛒', 'Жаңа айға сай жөргектер мен күтім құралдарын іздесеңіз, Ұсынылатын өнімдер міндетті түрде көмектеседі.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'Етпетінен жататын уақыт! 🐢', 'Күніне бірнеше минут етпетінен жату бөпеңіздің мойын бұлшықеттерін нығайтады.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'Түнгі ұйқыға дайындық. 🌙', 'Ұйықтар алдында бөлме температурасын реттеп, Anacan ұйқы таймерін іске қосыңыз.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'Сүтіңізді көбейтудің құпиялары! 🥛', 'Пайдалы рецепттер бөлімінде емшек сүтін көбейтетін табиғи тағамдар мен смузи рецептері Сізді күтеді.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'Даму секірісі болуы мүмкін. 📈', 'Еш себепсіз шыңғырып жылай ма? 3-аптадағы даму секірісі — іш кебуі шаншуының да шегіне жететін кезеңі. Дүрлікпеңіз.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'Қолдан түспейтін кез 🛋️', 'Бөпеңізді орнына жатқыза салысымен оянып, жылай ма? Бүгін төрт қабырғада бөпеңізді қолдан түсіре алмай жүргендей сезінуіңіз мүмкін. Бірақ бөпеңіз үшін ең қауіпсіз жер — Сіздің құшағыңыз екенін ұмытпаңыз. Сабырлы болыңыз.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'Жұбайыңызды да осы іске қатыстырыңыз. 👨‍👩‍👦', 'Бүгін кешке жөргек ауыстыруды немесе Ақ шумен ұйықтатуды оған тапсырып, өзіңіз демалыңыз.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'Тері күтімінің уақыты. 🛁', 'Бөпеңіздің сезімтал терісіне сай кремдер іздеп жүрсіз бе? Ұсынылатын өнімдер тізімі Сізге көмектеседі.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'Рефлекстері дамып келеді! 🖐️', 'Бөпеңіз саусағыңызды қаншалықты қатты ұстайды? Бұл туралы толығырақ білу үшін Блогтардағы мақалаларымызды оқыңыз.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'Күнделікті ұйқы нормасын сақтау маңызды. 😴', 'Бөпеңіз ұйықтағанда ұйқы таймерін қосып, оның күнделікті нормаға қаншалықты сәйкес келетінін тексеріңіз.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'Басын көтеруге тырысып жүр! 🐢', 'Етпетінен (tummy time) жатқанда жасайтын қимылдарын Бөпе альбомына видео ретінде қосыңыз.'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'Сұрағыңыз бар ма? 🤖', '«Неліктен түнде жиі оянады?» деген сияқты Сізді толғандыратын сұрақтарға жауап беруге Anacan AI әрдайым дайын.'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'Күнделікті жөргек көрсеткіші қандай? 🧷', 'Бөпеңіздің жеткілікті тамақтанып жүргенін білудің ең оңай жолы — жөргек ауыстыру жазбаларын жүргізу. Дәл қазір қолданбаға енгізіңіз!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'Алғашқы жымиысы жақындап қалды! 😊', 'Оның жүзіңізге мұқият қарайтын сәттерін жіберіп алмаңыз. Осы сәттер сыйлаған сезімдерді Көңіл күй күнделігіне жазыңыз.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'Күн тәртібін қалыптастыра бастаймыз! 🌙', 'Күн сайын бір уақытта шомылдырып, емізіңіз, Ақ шуды қосып, ұйқы таймерін іске қосыңыз.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'Ана ретіндегі қажеттіліктеріңізді ұмытпаңыз. 🛍', '️Емізік ұшына арналған крем мен омырауға арналған төсемшелерді қолдану өзіңізді жайлырақ сезінуге және киіміңізді қорғауға көмектеседі.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'Таза ауада серуендейтін уақыт! ☀️', 'Жайлы демалып, баламен бірге баруға болатын орын іздеп жүрсіз бе? «Анаға қолайлы орындар» блогымызды міндетті түрде қарап шығыңыз.'),
  ('5bfad78e-cb6a-405d-8517-a356018909ca', 'Бойы мен салмағы қалай өсіп жатыр? 📏', 'Дамуды бақылау бөлімінде жаңа көрсеткіштерді тіркеп, жеке даму кестесін талдаңыз.'),
  ('d87d1938-6445-47b1-b0eb-19c7a9941726', 'Таза ауаға шығайық! 🌳', 'Бөпеңізбен жайлы серуендеу үшін балалар арбасымен кіруге болатын жақын жерді таңдаңыз.'),
  ('fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1', 'Anacan AI әрдайым жаныңызда! 🤖', 'Ұйқы режимі туралы сұрақтарыңыз бар ма? Жасанды интеллектімізге жазыңыз, ол бірден жауап береді.'),
  ('0ac0ad4d-776b-416d-a345-c0bddd639ff1', 'Зейін қою қабілеті артып келеді! 👀', 'Бөлмедегі заттарды қалай бақылайтынына назар аударыңыз. Дамуы туралы көбірек білу үшін Блогтарға кіріңіз.'),
  ('1a8980b4-ba5e-4179-adce-580423431a55', 'Ұйқы нормаларын білу маңызды. ⏱️', 'Ол ұйықтағанда ұйқы таймерін қосып, күнделікті ұйқы нормасын сақтап жүргенін тексеріңіз.'),
  ('c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f', 'Аналарға да қуат керек! 🍳', 'Пайдалы рецептілер арасынан оңай дайындалатын дәмді смузи жасап, күш-қуатыңызды қалпына келтіріңіз.'),
  ('041b2f2c-3594-4ff1-96a1-f589206d267b', 'Емізу және үзілістер. 🤱', 'Әр емізу ұзақтығын Тамақтануды бақылау құралы арқылы өлшеп, күн тәртібіңізді одан әрі жетілдіріңіз.'),
  ('bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec', 'Көңіл күйіңіз қалай, аяулы ана? 💖', 'Кейде бәрі бір мезетте үйіліп кетуі мүмкін. Көңіл күй күнделігін ашып, ішіңіздегіні еркін жазыңыз.'),
  ('cb8cc6b6-0d64-4498-81ae-bc15f03ad73b', 'Бөпеңіздің терісіне ерекше күтім. 🧴', 'Мақпалдай жұмсақ теріге арналған аналар таңдаған үздік құралдарды Ұсынылатын өнімдер блогымыздан табыңыз.'),
  ('47a30b46-d385-4b3c-979c-5465d481ef29', 'Іштің кебуіне қарсы жаттығу! 🚴', '«Велосипед» жаттығуын жасағанда, бөпеңіз әрі көңілденіп, әрі тынышталуы үшін фонға Ақ шуды қосыңыз.'),
  ('a7868664-8e30-4849-9648-70deec39cf3a', '6-аптадағы даму секірісі жақындап келеді! 📈', 'Бөпеңіз әдеттегіден жиі жылауы мүмкін. Осы даму кезеңі мен оның себептері туралы білу үшін Блогтар бөліміне өтіңіз.'),
  ('ba4d5548-5eb3-44e1-bb68-bbab9deb11ee', 'Әкесімен бірге күтім жасайтын уақыт. 👨‍🍼', 'Кешкі тамақтандырудан кейін бөпеңіздің кекірігін шығару кезегін әкесіне беріп, өзіңіз аздап көз шырымын алыңыз.'),
  ('22e06076-dd91-4e1b-834c-b78c42879a13', 'Үйден тыс жерде де жайлы болсын. ☕', 'Достарыңызбен кездесуді жоспарлап жүрсіз бе? Аналарға қолайлы орындар картасын қарамай, үйден шықпаңыз.'),
  ('367f3154-4760-43d6-b507-b914372b7538', 'Жымиюға дайын болыңыз! 😊', 'Бөпеңіз кез келген сәтте Сізге қарап жымия бастауы мүмкін. Телефоныңызды дайын ұстаңыз.'),
  ('56603835-e00b-48c0-82ab-bbdf1844d6ac', 'Күн тәртібі ұйқы сапасын жақсартады. 🛁', 'Бөпеңізді шомылдырып, емізіңіз де, ұйқы таймерін қосып, қолданбада күнделікті ұйқы талдауын жүргізіңіз.'),
  ('173da4aa-4d6e-4106-ab0c-34773a383b02', 'Етпетінен жататын уақыт ұзаруда! 🐢', 'Бөпеңіз басын тігірек ұстай бастады. Мойын бұлшықеттерін нығайтатын осы жаттығуларды күнделікті әдетке айналдырыңыз.'),
  ('3c5122e2-a92c-4444-baa3-d7b7fdd4786f', 'Жөргек ауыстыру статистикаңызды қарап шығайық па? 📊', 'Anacan қолданбасына кіріп, соңғы күндердегі жөргек туралы деректерді салыстырыңыз. Бәрі дұрыс па?'),
  ('f653426f-c687-4b5c-806e-74f597e75cf2', 'Бәрі дұрыс екеніне көз жеткізу үшін. 🤖', 'Сізді алаңдатқан кез келген нәрсені тіпті түнде де Anacan AI-дан сұрай аласыз.'),
  ('2a04ee0c-770e-425b-8987-e6ab25472f0b', 'Ана сүтін арттырудың табиғи жолдары. 🥛', 'Сүтті көбейту үшін «Пайдалы рецепттер» бөліміндегі құнарлы сорпалар мен сусындардың рецептерін қолданып көріңіз.'),
  ('6a605601-9da6-47e9-8d07-a1f552eb5fc0', 'Күнделікті тамақтану мен ұйқы теңгерімі. ⚖', '️ Бүгінгі статистикаңызды «Тамақтануды бақылау» және ұйқы кестелері арқылы талдап, келесі күнді жоспарлаңыз.'),
  ('756d2914-ecb6-4838-adb6-d312a4bc59a2', 'Қолдарын зерттеп жүр! 👐', 'Ол енді қолдарын аузына апара алады.'),
  ('2dcd9888-3b4b-4cb6-a25a-51c4642e3c54', 'Бүгін қырқынан шығарамыз! 🧿', 'Осы ерекше әрі дәстүрлі күнді есте қаларлықтай ету үшін «Бөпе фотосессиясы» бөлімінен қызықты тақырыптарды таңдап, суреттер жасаңыз.'),
  ('92e4d1aa-c4f4-477c-ab81-176ef4f03a16', 'Жайлы ұйқыға көшу. 🌙', 'Осы ерекше күннің соңында бөлмені қараңғылап, Ақ шуды қосыңыз да, бөпеңіз терең ұйқыға кеткенде өзіңіз де тәтті ұйықтаңыз.'),
  ('ba92608f-780e-4381-a0e7-3f6af86021be', 'Өзіңізді қалай сезініп жүрсіз? ✨', '40 күнге созылған маңызды әрі ерекше кезеңді аяқтадыңыз! Сіз нағыз қаһармансыз!'),
  ('6dd4f975-8504-4871-83c4-a6f7bc24a950', 'Бүгінгі күніңіз қалай өтті? 📝', 'Өзіңізге бір шыны кофе құйып, бүгінгі ішкі сезімдеріңізді Көңіл күй күнделігіне жазып, демалыңыз.'),
  ('c6c2469c-d36e-4ffe-a532-bee6050f4bac', 'Қырқынан кейінгі жаңа кезең! 🌸', 'Бөпеңіз айналасына көбірек қызығушылық таныта бастады. Оның айналасында зияткерлік дамыту карталарының болуы пайдалы.'),
  ('d647162e-98ae-41c0-81b4-cc5ca3e15dff', 'Тамақтану тәртібі қалай жүріп жатыр? 🍼', 'Қолданбадағы Тамақтануды бақылау құралы мен таймер арқылы күнделікті нормаға қаншалықты сай келе жатқаныңызды тексеріңіз.'),
  ('06dbea83-4e3d-4be5-8968-0961033df8d5', 'Түстерді жақсырақ ажыратады! 🔴', 'Бөлмедегі ашық түсті заттарды көзімен қалай қадағалайтынына назар аударыңыз.'),
  ('295afbf2-1104-44c2-abf4-fb0e41a0ff0e', 'Таза ауа екеуіңізге де пайдалы. 🌳', 'Серуендеуге шығу үшін Анаға қолайлы орындар картасынан балалар арбасымен кіруге ыңғайлы орынды таңдаңыз.'),
  ('9f7dfdf1-83be-4fad-a93a-817e105844ce', 'Ұйықтауын жеңілдетіңіз. 🌙', 'Кешкі шомылудан кейін Ақ шу бөлімінен феннің немесе жаңбырдың дыбысын таңдап, бөпеңізді терең ұйқыға дайындаңыз.'),
  ('431cbe5a-0f52-442d-a6e8-ab53cd482a5f', 'Күнделікті статистикаңыз дайын! 📊', 'Бүгін бөпеңіздің қанша ұйықтап, қанша тамақтанғанын көру үшін қолданбадағы графиктерді талдаңыз.'),
  ('c4adf9ce-d711-4011-af60-94f404f59ae5', 'Бойы мен салмағының өсуін қадағалаймыз! 📏', 'Дамуды бақылау бөлімінде соңғы көрсеткіштерді жаңартып, дені сау даму графигіне қарап, мақтаныш сезіміне бөленіңіз.'),
  ('ffb18a7a-0d53-482c-b130-00223f89efd3', 'Аналарға арналған қуат көзі! 🥗', 'Күшіңізді қалпына келтіру үшін қолданбадағы «Әйелдерге арналған пайдалы рецепттер» бөлімінен дәруменге бай әрі дәмді тағам таңдаңыз.'),
  ('40712cc0-bb4b-4d42-9a36-7942cb47a970', 'Дыбыстарға реакциясы артып келеді! 🎶', 'Даусыңызды естігенде оның қалай тынышталатынын байқайсыз ба? Осы бір тәтті сәттерді «Бөпе альбомында» мәңгі сақтаңыз.'),
  ('aa025645-c5cd-4f2b-840e-6fb50bb6398b', 'Сауда жасау керек пе? 🛍', '️Бөпеңіздің жаңа айына сай күтім құралдары немесе ойыншықтар таңдау үшін «Ұсынылатын өнімдер» тізімін қарап шығыңыз.'),
  ('c6ae0bdf-11e6-43d9-a0ab-d021b7461194', 'Жөргектерді санауды жалғастырыңыз! 🧷', 'Күнделікті пайдаланылған жөргектер санын Anacan-да белгілеп, бөпеңіздің жеткілікті тамақтанып жүргеніне көз жеткізіңіз.'),
  ('99125d76-b832-4f75-8c29-6320b71e5e67', '6-аптадағы даму секірісі! 📈', 'Бүгін бөпеңіз сәл мазасыз әрі талапшыл болуы мүмкін. Уайымдамаңыз, қолдау алу үшін Anacan AI-мен кеңесіңіз.'),
  ('9f56ae7d-2431-4cb2-8d79-fa19be16c242', 'Түнгі оянуларды қалыпты тәртіпке келтіреміз. 😴', 'Бөпеңіз оянған сайын жарықты қоспаңыз. Anacan таймерімен тамақтандырып, «Ақ шу» көмегімен қайта ұйықтатыңыз.'),
  ('bef1515a-3c39-4799-b9d9-717742d94d5f', 'Бөпеңіз ұйықтағанда, Сіз де демалыңыз. ⏱️', 'Ұйқы таймерін қосып, бөпеңіз ұйықтап жатқанда Сіз де көзіңізді жұмып демалыңыз немесе кітап оқыңыз.'),
  ('3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c', 'Алғашқы былдырлаған дыбыстары жалғасуда! 🗣️', 'Оның Сізбен сөйлесуге талпынысын жазып алыңыз. «Бөпе фотосессиясы» бөлімінен осы сәтке сай жақтауды таңдаңыз.'),
  ('503a0808-7061-4b7d-ae17-f65b9abb87de', 'Дамуын қадам сайын бақылаңыз. 📚', 'Жаңа туған бөпелердің осы айда қандай дағдыларды меңгеретінін білу үшін Блогтар бөліміндегі ең соңғы мақаламызды оқыңыз.'),
  ('aeea52a4-dd88-4cf1-a812-0c13b4f98004', 'Күнделікті ұйқы мөлшері. 🛌', 'Бөбегіңіз ұйықтағанда ұйқы таймерін қосып, оның тәуліктік 14-17 сағаттық ұйқы мөлшерін орындағанын талдаңыз.'),
  ('c86bd995-9231-4eae-b8e0-8f84d6a46b62', 'Сіз өте мықтысыз! ✨', 'Кейде қиын болса да, Сіз керемет анасыз!'),
  ('8e6d5e26-758c-4169-81b6-bd9cbcc10cc5', 'Тамаша күннің тәтті аяқталуы. 🌙', 'Бөлмедегі жарықты бәсеңдетіп, Ақ шулардан ана құрсағындағы дыбысты қосыңыз да, бөбегіңіздің тәтті ұйқыға кеткенін тамашалаңыз.'),
  ('9d97fdbc-edef-4830-93ad-c388f586d909', 'Бірге болғандарыңызға тура 50 күн! 🎈', 'Осы тамаша мерейтойды Бөпенің фотосессиясы құралы арқылы ерекше сурет жасап атап өтіңіз!'),
  ('cb1a5cad-e167-45a8-b0b1-4e8ebe455866', 'Соңғы 50 күнді талдау. 📈', 'Дамуды бақылау және Тамақтануды бақылау бөлімдерін қарап, бөбегіңіздің осы 50 күнде қалай керемет өскенін көріңіз.'),
  ('10f8db02-014b-4a08-8d7a-e5cbbb260125', 'Терең ұйқыға көшу. 😴', 'Ақ шулардан шаш кептіргіштің дыбысын таңдаңыз, ал бөбегіңіз жайлы ұйықтап жатқанда Көңіл күй күнделігіне сезімдеріңізді жазып, жеңілдеп қалыңыз.'),
  ('2cd12a68-4486-435f-ad24-55a11a2f62a2', 'Күнделікті тамақтануды талдау. 🍼', 'Қолданбадағы таймермен емізу ұзақтығын өлшеп, Тамақтануды бақылау бөлімінде қалыпты мөлшерге сәйкестігін тексеріңіз.'),
  ('48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179', 'Сүттің бөлінуін қолдайтын тағамдар. 🍲', 'Әйелдерге арналған пайдалы рецептілер бөліміндегі сүтті көбейтетін сорпалар мен сусындармен өзіңізді қуантыңыз.'),
  ('bcfe1987-8bea-4b53-a1dc-7ef7e234e755', 'Эмоцияларыңызды басқарыңыз. 💖', 'Ана болу шаршатуы мүмкін. Көңіл күй күнделігіне кіріп, бүгін Сізді не мазалағанын жазыңыз — жеңілдеп қаласыз.'),
  ('4c289cf6-60de-4ba6-9f14-eae4086d8d21', 'Аралықтарды реттейік. 🍼', 'Тамақтану мен үзіліс уақыттарын Тамақтануды бақылау құралы арқылы қадағалап, бөпеңізге қолайлы күн тәртібін қалыптастырыңыз.'),
  ('7f93cf2f-abf0-4b16-9f93-396050a7ddb9', 'Әлі де сұрағыңыз бар ма? 🤖', 'Бөпем бүгін аз ұйықтады, бұл қалыпты ма? – Сізді толғандырған сұрақтарды Қауымдастықтағы басқа аналарға қойыңыз.'),
  ('c505d849-65c8-4ead-80b3-2648f5feaa49', 'Tummy time жаттығулары! 🐢', 'Бөпеңіз енді басын ұзағырақ тік ұстай алады. Мойын бұлшықеттерін дамыту үшін осы жаттығуларды күн сайын қайталаңыз.'),
  ('65d67a55-0ffc-4c5f-8c78-443c16c7f697', 'Әкелерді де осы үдеріске қатыстырайық. 👨‍🍼', 'Кешкі тамақтандырудан кейін бөпенің кекірігін шығарып, ұйықтату кезегін әкесіне беріп, өзіңізге уақыт бөліңіз.'),
  ('c7ab2e50-8e71-4df1-97cc-6432f40c4349', 'Күлкісі көбейіп келеді! 😍', 'Бөпеңіздің Сізге қарап, былдырлаған сол бір ғажайып сәтін жіберіп алмаңыз! Суретке түсіріп, Бөпе альбомының ең әдемі бөлігіне орналастырыңыз.'),
  ('dba00752-8e14-4710-8793-6a828172c915', 'Құрбылармен кофе ішуге үзіліс жасайсыз ба? ☕', 'Бөпеңізбен бірге бара алатын ең жақын әрі жайлы дәмханаларды Анаға қолайлы орындар бөлімінен табыңыз.'),
  ('b67a89c9-d8cf-40c2-97a2-43b27081ed44', 'Көру аясы кеңейіп келеді! 👀', 'Бөпеңіз енді заттарды көзімен жақсырақ қадағалай алады.'),
  ('917836b6-b023-4945-8e64-bc144ba97f42', 'Жаңа дыбыстарды үйреніп жүр! 🗣️', 'Оның сүйкімді былдырын жазып алыңыз. Тілінің дамуы туралы көбірек білу үшін блогтарды оқыңыз.'),
  ('d31b874f-e957-475e-a461-b294c96db59f', 'Түнде оянуы жалғасып жатыр ма? ⏱️', 'Әр оянған уақытын ұйқы таймеріне белгілеп, жалпы ұйқы режимі мен тәуліктік нормасын талдаңыз.'),
  ('d491dc2d-f6b9-49dd-8461-5cbffee476e5', 'Өзіңізді де ұмытпаңыз! 🥗', 'Ананың күш-қуаты өте маңызды. Әйелдерге арналған пайдалы рецептілерден дәруменге бай тағам таңдап, күшіңізді қалпына келтіріңіз.'),
  ('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c', 'Сізді не мазалайды? 🤖', 'Тіпті түнде де кез келген сұрағыңызды Anacan AI көмекшімізге қойып, маманның қолдауын алыңыз.'),
  ('f710f746-b942-4fd7-a8ca-dd9b5a248195', 'Жөргек есебін тексерейік. 🧷', 'Anacan-да күнделікті жөргек санын белгілеп, бөпеңіздің жеткілікті тамақтанып жүргеніне көз жеткізіңіз.'),
  ('fa5fc8d8-4263-4a99-9f46-297b1d6ea219', 'Басын тік ұстай бастады! 🐢', 'Ішімен жату жаттығуларын қызықты ойынға айналдырыңыз.'),
  ('42ca0f3b-8083-4338-bf16-9998a33b15c6', 'Таза ауаға шығатын уақыт! 🌳', '«Анаға қолайлы орындар» картасын ашып, бөпеңізбен бірге баруға ең жайлы орынды табыңыз.'),
  ('7fc52d97-b36d-4c5e-a169-0eadba238b0e', 'Салмағы мен бойын бақылау. 📏', 'Бөпеңіз қалай өсіп келеді? Жаңа деректерді Салмақ трекеріне енгізіп, оның жеке өсу кестесін бақылаңыз.'),
  ('df56b34d-b5f8-476f-a65e-11a244242a2f', 'Ұйықтар алдындағы әдеттер. 🛁', 'Шомылдырып, емізіңіз де, ұйқы таймерін қосыңыз. Бәрі жоспарлы әрі жайлы өтсін!'),
  ('0c1e843a-b2dc-4995-89cf-7af4230d574e', 'Қолдарын зерттеп жүр! 👐', 'Ол енді саусақтарына қарап, оларды аузына апарады.'),
  ('3cf29d40-9703-4e58-8a17-b7e68f86c3fa', 'Күтім құралы немесе ойыншық іздеп жүрсіз бе? 🧸', 'Оның дамуына көмектесетін қауіпсіз өнімдерді Ұсынылатын өнімдер тізімінен оңай табыңыз.'),
  ('e6e49938-5987-45e7-8021-a8d016100be4', 'Өзіңізді қалай сезініп жүрсіз? 💖', 'Күні бойы шаршадыңыз ба, әлде күш-қуатыңыз мол ма? Көңіл күй күнделігін ашып, бүгінгі күніңіздің қалай өткенін белгілеңіз.'),
  ('814305c3-77b7-491e-ae0f-134875923d1a', 'Қай емшекпен еміздіңіз? 🤱', 'Anacan таймері оң немесе сол емшекпен емізгеніңізді Сіздің орныңызға есте сақтайды. Емізуді қазір бастаңыз!'),
  ('910b6936-83b0-441d-abe5-33c85153dffe', 'Таңғы күлкі! 😊', 'Оның айналасындағыларға күлімсіреуі күніңізді көркейте түседі. Бөпеңізді суретке түсіріп, осы қуанышты сәтті мәңгі есте сақтаңыз.'),
  ('fcecf920-146e-4152-abc5-066ce8392fd8', 'Тыныштандыратын дыбыс терапиясы. 🎶', 'Іші кеуіп мазасызданса немесе шаршаса, Ақ шулар ішіндегі жүрек соғысының дыбысы оны ана құрсағындағыдай бірден тыныштандырады.'),
  ('2776b020-9972-4e23-acb7-6a529664582d', 'Сіздің даусыңызды іздейді! 👂', 'Онымен жиі сөйлесіп, көзбен байланыс орнатыңыз. Оның дамуына арналған түрлі жаттығулар туралы Блогтар бөлімінен біліңіз.'),
  ('72abc90e-b301-468a-9629-3f3bb7949709', 'Бөпеге күтім жасауға қатысты күмәніңіз бар ма? 🤖', 'Anacan қауымдастығы Сізді сынамай тыңдап, ең қолайлы кеңес береді.'),
  ('816ef2cf-32b6-4eba-b12b-4e8f7936a78f', 'Сүттің молаюына көмектесіңіз. 🥛', 'Суды көп ішуді ұмытпаңыз! Сонымен қатар Әйелдерге арналған пайдалы рецептерден сүтті көбейтетін сусын дайындаңыз.'),
  ('1501b0ff-9742-40e2-9aae-ff2e8f8e5188', 'Отбасылық серуен жоспары! ☕', 'Бос уақытыңызды тиімді өткізу үшін Аналарға қолайлы орындардан жайлы кафе немесе мейрамхана таңдаңыз.'),
  ('427917df-21f2-46c9-a030-52d511e37ce5', 'Күнделікті есеп. 📊', 'Бүгін бөпеңіз қанша ұйықтап, неше рет тамақтанды? Қолданбадағы графиктерден бүгінгі жалпы статистиканы қарап шығыңыз.'),
  ('c555165e-a5c9-4e8c-9a72-cf4d0a16a367', 'Әкелерді де ұмытпаймыз! 👨‍🍼', 'Бөпеңіздің әкесімен ойнаған сүйкімді әрі көңілді сәттерін бағалаңыз.'),
  ('052bbdef-be6b-4b3f-bf88-905af0d4abc5', 'Кейде демалу қажет. 🛋', '️ Бөпеңіз ұйықтап жатқанда ұйқы таймерін қосып, ештеңе істемей, өзіңізге уақыт бөліңіз.'),
  ('1053981f-f622-407a-ade7-529fc27bb2ff', 'Өсу кезеңін бақылап жүрміз! ⚖️', 'Екінші ай аяқталып келеді. Қолданбадағы Салмақты бақылау бөліміне кіріп, соңғы деректерді жаңартқаныңызға көз жеткізіңіз.'),
  ('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4', 'Таза ауада серуендейтін уақыт. 🌳', 'Таза ауада серуендеу бөпеңіздің дамуы мен тыныштығы үшін өте маңызды.'),
  ('b6825824-6eff-4740-b6c1-dc607b41b996', 'Ойыншықтарға қолын созады! 🧸', 'Осындай кішкентай жаңалықтарды бақылау қандай қызық! Онымен ойнаған кезде түсірген бейнелеріңізді Бөпе альбомына жүктеңіз.'),
  ('1ed5f326-68dd-494e-a31c-2d3466644cd0', 'Аналарға арналған қуат көзі! 🥗', 'Күшіңізді қалпына келтіріп, емшек сүтінің түзілуін қолдау үшін Пайдалы рецепттерден дәруменге бай бір рецепт таңдаңыз.'),
  ('59041ede-10ec-4754-8f5f-31f415db3701', '«А-гу» дыбыстары көбейіп келеді! 🗣️', 'Бөпеңіздің Сізбен қарым-қатынас жасауға талпынысы артып келеді. Тілінің дамуын қолдау үшін Блогтар бөліміндегі мақалаларды оқыңыз.'),
  ('d7b0c908-0d97-40c6-a82a-c5283f30a1d8', 'Ұйқы нормасын бақылаңыз. ⏱️', 'Бөпеңіз ұйықтағанда ұйқы таймерін қосып, оның күнделікті ұйқы нормасын сақтап жүрген-жүрмегенін талдаңыз.'),
  ('5309698d-6050-4993-9a68-ab592375ed60', 'Сілекей бездері жұмыс істей бастайды! 💧', 'Енді оның сілекейі көбірек бөлінуі мүмкін.'),
  ('83d11db6-0443-4d69-8d55-9ea20f0cf905', 'Өсу кезеңін бақылап отырамыз! 📏', 'Келесі аптадағы салмағы мен бойы туралы деректерді Салмақ бақылағышына енгізіп, жеке даму кестесін жаңартыңыз.'),
  ('ca5bc974-1377-4065-9dfa-50549135eb55', 'Сізді бір нәрсе алаңдата ма? 🤖', '«Неге бүгін қысқа ұйықтады?» сияқты сұрақтарыңызды тіпті түнгі уақытта да Anacan AI көмекшімізге қоя аласыз.'),
  ('8f5fde4a-3542-4bb1-be02-6df262d75b50', 'Бәрі дұрыс па? 📝', 'Көңіл күйіңіз қалай? Шаршадыңыз ба, әлде күш-қуатыңыз мол ма? Anacan Көңіл күй күнделігі — Сіздің ең сенімді цифрлық сырласыңыз.'),
  ('292a637a-a0ca-4e58-8523-7b2c8b754743', 'Керемет айдың соңы. ✨', 'Бөлменің жарығын бәсеңдетіп, Ақ шуды қосыңыз да, бөпеңіз ұйықтап жатқанда оны мақтан тұтыңыз. Сіз керемет анасыз!'),
  ('39c9a98b-8f4e-4896-9385-5588121bd72d', 'Құттықтаймыз, тура 2 айлық болдық! 🎈', 'Осы тамаша сәтті атап өту үшін Бөпе фотосессиясында естелік сурет жасаңыз!'),
  ('3c5f5d9f-939f-4c7e-9bc8-1feef640d854', 'Екі айлық даму есебі. 📈', 'Салмақ трекеріндегі, жөргек пен тамақтану статистикасындағы деректерге қарап, бөпеңіздің осы 60 күнде қаншалықты жақсы өскенін көріңіз.'),
  ('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae', 'Күннің шаршауын басыңыз. 🛁', 'Өзіңізге уақыт бөліп, бүгінгі ішкі сезімдеріңізді Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('59aa01c0-7e8d-4375-9fcd-733a242d640c', 'Тамақтану тәртібін сақтаймыз. 🍼', 'Бөпеңіздің тәбеті артуы мүмкін. Anacan таймерін іске қосып, тамақтану мөлшерін Тамақтануды бақылау құралы арқылы тексеріңіз.'),
  ('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a', 'Үшінші айдың алғашқы күні! 🎉', 'Бөпеңіз енді айналасын саналы түрде бақылай бастады.'),
  ('8d26cab1-ebfd-469f-9ae0-aa66e0f36761', 'Ұйықтату қиындап кетті ме? 🌙', 'Бөлмені қараңғылап, Ақ шудан мұхит толқындарының дыбысын таңдаңыз да, бөпеңізді терең ұйқыға дайындаңыз.'),
  ('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc', 'Әкесімен бірге күтім жасау уақыты. 👨‍🍼', 'Кешкі тамақтандырудан кейін бөпенің кекірігін шығарып, ұйықтатуды әкесіне тапсырыңыз, ал өзіңіз демалыңыз.'),
  ('a6843443-e0f6-4ec7-a4ec-03cb5d81d392', 'Етпетінен жату жаттығулары оңайырақ бола бастайды. 🐢', 'Ол енді басын тік әрі ұзағырақ ұстай алады. Бұл жаттығуды күнделікті әдетіңізге айналдырыңыз.'),
  ('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d', 'Күнделікті жөргек санын тексерейік. 🧷', 'Бөпенің жеткілікті тамақтанып жүргеніне көз жеткізу үшін Anacan-да әр жөргек ауыстыруды белгілеп отырыңыз.'),
  ('7764e41d-176a-41d8-8f87-2a21677a36ee', 'Күн тәртібін қалыптастырамыз. 🛁', 'Күн сайын кешке бір уақытта шомылдырып, емізіңіз және ұйқы таймерін қосып, дұрыс ұйқы режимін қалыптастырыңыз.'),
  ('9754280d-c633-46e8-94c9-6f16ff032551', 'Өзіңізді де ұмытпаңыз, аяулы ана! 🍲', 'Anacan қолданбасындағы Пайдалы рецепттер бөлімін қарап, бүгін өзіңізге дәмді бір тағам дайындаңыз.'),
  ('c1c4c9b0-cdd8-4321-a494-3bb43739df94', 'Сізді де, даусыңызды да таниды! 😍', 'Бөлмеге кіргеніңізде оның қалай қуанатынына назар аударыңыз. 😊'),
  ('149e95b1-a682-4369-8b74-5827cc5d31dc', 'Сезімдеріңізбен бөлісуден қысылмаңыз. 📝', 'Шаршадыңыз ба, әлде күш-қуатыңыз мол ма? Қалай болғанда да, бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('79b7fb29-fa37-4176-9ae5-409d73ee982e', 'Үйден тыс жерде де жайлылық. ☕', 'Достарыңызбен кофе ішкіңіз келе ме? Аналарға қолайлы орындар картасын қарап алмай, үйден шықпаңыз.'),
  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'Әлеуметтік жымиюлар! 😊', 'Оның тәтті күлкісі бүкіл шаршауыңызды басады.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'Апталық статистикаңыз дайын! 📊', 'Соңғы күндері ұйқы мен тамақтану режимін қаншалықты сақтағаныңызды талдау үшін қолданбаға кіріңіз.'),
  ('aba537d3-5a0f-4b17-b02b-4754b93f711f', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Таймер арқылы оң немесе сол емшекпен емізгеніңізді белгілеңіз, қалғанының бәрін Anacan Сіз үшін есте сақтасын!'),
  ('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8', 'Күндізгі ұйқы режимі өзгеруде. ⏱️', 'Ояу жүретін уақыт пен аралықтарды Тамақтануды бақылау және ұйқы таймерлері арқылы өлшеп, жаңа режим қалыптастырыңыз.'),
  ('32ff20f3-f1f8-47fd-b3be-c14bea1452a2', 'Мазасыздыққа қарсы дыбыс терапиясы. 🎶', 'Егер бөпеңіз бүгін кешке мазасызданса, көңілін тыныштандыру үшін Ақ шу бөлімінен жүрек соғысының дыбысын қосыңыз.'),
  ('a061022a-6a47-4aae-8590-2f0f328fbf09', 'Ойын уақыты! 🎈', 'Онымен уақытты қалай пайдалы әрі қызықты өткізуге болатынын білу үшін Блогтар бөліміндегі дамыту ойындары туралы кеңестерді оқыңыз.'),
  ('b95ca7be-8491-4bbc-afb0-321f795780ea', 'Сатып алатын заттар бар ма? 🛍', 'Бөпеңіздің осы айдағы жасына сай қауіпсіз ойыншықтар мен құралдарды Ұсынылатын өнімдер тізімінен оңай табыңыз.'),
  ('633e342d-82b1-442c-9da8-5c5326907322', 'Күн қорытындысы. 📈', 'Тамақтануды бақылау және ұйқы кестелерін талдап, режиміңіздің қаншалықты жақсы қалыптасып келе жатқанын көріңіз.'),
  ('8655d498-c5d9-40f8-bd47-346f815d3e75', 'Әдемі күннің тәтті аяқталуы. 🌙', 'Бөлменің жарығын бәсеңдетіп, Ақ шу бөлімінен ана құрсағындағы дыбысты қосыңыз да, бөпеңіздің пырылдап ұйықтап жатқанын тамашалаңыз.'),
  ('97e88a0b-26cf-486d-a17f-2c34cfc6b47d', 'Бірге болғандарыңызға тура 70 күн! ✨', 'Сіз керемет анасыз! Бөпе альбомына алғашқы күн мен бүгінгі күннің айырмашылығын көрсететін коллаж қосыңыз.'),
  ('05925891-b678-4a87-8f54-39f692aa9143', 'Қор таусылып бара ма? 🛒', 'Жөргек немесе ылғалды майлық таусылып бара ма? Бәрін ойда сақтауға міндетті емессіз. Қазір сатып алу тізіміне қосып қойыңыз, жұбайыңыз кешке үйге қайтарда ала келсін.'),
  ('41007feb-f415-4088-b094-428b2275abbf', 'Сиқырлы дыбыстар әлемі 📖', 'Кешкі әдеттеріңізге өзгеріс енгізіңіз. Ақылды ертегілерден бөпеңізге тыныштандыратын хикая құрастырып, екеуіңізге де ұйқыға кетуді жеңілдетіңіз.'),
  ('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03', 'Таңғы концерт 🎶', 'Алғаш рет былдырлай бастады ма? Онымен өз тілінде сөйлесіп, дыбыстарына жауап беріңіз. Бүгін осы тәтті сәттен жай ғана ләззат алып, ешқайда асықпаңыз.'),
  ('62fbb893-6a1c-4847-a99e-981afea8fa87', 'Жылаудың түрлері 😭', 'Аш болғаннан ба, әлде ұйқысы қанбағаннан жылап жатыр ма? Уайымдамаңыз, Жылауды талдау құралымыз арқылы бұл дыбыстардың нені білдіретінін бірнеше секундта бірге анықтайық.'),
  ('83a0ab90-d44d-4758-bd3f-c7126ae6e20f', 'Өзіңізге адал болыңыз 📝', 'Бүгін қатты шаршадыңыз ба? Көңіл күй күнделігіне сезімдеріңізді шынайы жазыңыз. Күн сайын мінсіз болуға міндетті емессіз, Сіз де адамсыз.'),
  ('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c', 'Не кигіземін? ⛅', 'Күн райы құбылмалы болып, бөпеңіз тоңып немесе терлеп қала ма деп алаңдайсыз ба? Дереу Ауа райы және киім құралына кіріп, бүгінгі күнге ең қолайлы киім үйлесімін біліңіз.'),
  ('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a', 'Біз бір командамыз! 💪', 'Кейде өзіңізді жалғыз әрі ешкім түсінбейтіндей сезінесіз бе? Anacan қауымдастығына қосылыңыз. Онда Сіз сияқты сезімдерді бастан кешіріп жүрген мыңдаған ана бар. Бүгін олармен бір тәжірибеңізді бөлісіңіз.'),
  ('60059890-bf5b-4e0b-ba41-fedc82fa6a43', 'Әкенің кезегі 👨‍🍼', 'Күннің шаршауын ұмытыңыз. Бөпені әкесіне беріп, бүгін кешке ұйықтатуды соған тапсырыңыз. Ал өзіңіз бір кесе ыстық шай құйып, осы көріністі сырттай тамашалаңыз.'),
  ('b1778419-cb70-4711-96e0-a612732e8575', 'Сілекейлі күлкі 🤤', 'Бөпеңіздің аузынан сілекейі жиі ағып, қолын үнемі аузына сала ма? Тіс шығуын бақылау бөліміне алғашқы жазбаларыңызды енгізе бастаңыз. Иә, бұл қызықты кезеңге дайындық ерте басталады!'),
  ('0eb4da19-cb98-497a-a36b-a4934f47e071', 'Тыныштықты бақылау 🤫', 'Бөпеңіз жаңа ғана ұйықтады, бірақ үйдегі шу оятып жібере ме деп алаңдайсыз ба? Дыбыс өлшегішті қосып, бөлмедегі децибел деңгейін бақылаңыз және бөпеңіздің ұйқысын қорғаңыз.'),
  ('9cab0c58-8a4f-4869-b607-be3e284373f0', 'Сұрағыңыз бар ма? 🤖', 'Күнделікті тірліктің арасында бір сұрақ маза бермей жүр ме? Тамақтану, ұйқы немесе іштің кебуі... Қандай сұрақ болса да, бірден Anacan AI-дан сұрап, нақты әрі ғылыми негізделген жауап алыңыз.'),
  ('e6d33eab-abbe-4eca-94e9-c05138d06c07', 'Қараңызшы, мен осындамын! 👀', 'Енді ол Сізді бөлменің арғы бұрышынан да мұқият бақылайды. Даму трекеріне көзбен байланыс орнатудағы осы тамаша жетістігін жазып, оның өсіп келе жатқанын мақтан тұтыңыз!'),
  ('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa', 'Жұлдызды армандар 🌌', 'Балалар күнделікті қалыптасқан тәртіпті жақсы көреді. Ақылды ертегілер бөлімінде оған арнап ерекше ертегі дайындаңыз.'),
  ('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9', 'Сіз кереметсіз! 🌸', 'Кейде ештеңеге үлгермей жүргендей сезінесіз бе? Бірақ бөпеңіздің дені сау болып, тыныш дем алып жатқанына қараңызшы... Сіз қолыңыздан келгеннің бәрін жасап жүрсіз!'),
  ('faace99e-5074-497e-b5c0-f25a9880f5b0', 'Ананың энергиясы 🍲', 'Күнделікті қарбаласта өзіңіз тамақтануды ұмытып кеткен жоқсыз ба? Пайдалы рецепттер бөлімінен энергияңызды қалпына келтіріп, сүтіңіздің көбеюіне көмектесетін тез дайындалатын сорпа рецептін таңдаңыз.'),
  ('1cd41578-3422-4bf8-9401-e9a058dcad6f', 'Небәрі 15 минут 🛁', 'Бөпе ұйықтап қалды ма? Енді Серіктес режимінде барлық хабарламаны жұбайыңызға бағыттаңыз. Ал өзіңіз жуынатын бөлмеге кіріп, 15 минут бойы жылы су мен тыныштықтан ләззат алыңыз.'),
  ('73a10da9-aef9-4c21-b8d7-bca1f62e8528', 'Тәжірибе бөлісу 💬', 'Соңғы күндері оның қай қылығы Сізді көбірек күлдіріп жүр? Anacan қауымдастығына кіріп, осы сәтті жазба ретінде бөлісіңіз. Басқа аналардың оқиғаларын оқу Сізге де жақсы әсер етеді.'),
  ('acfd33be-87a0-41a3-858d-d5921f61d9a4', 'Қолдарымен танысу 👋', 'Бөпеңіз өз қолдарын байқап, оларға сағаттап қарап жүр ме? Дамудың осы күлкілі әрі ғажайып сәтін өткізіп алмаңыз — Бөпе фотосессиясы арқылы дереу түсіріп, мәңгілік естелікке айналдырыңыз!'),
  ('36b1e2d3-b43a-467e-b08f-870a612d1bb5', 'Жылау коды 🧩', 'Қарны аш емес, жөргегі таза, бірақ әлі де мазасыз ба? Себебін анықтау қиын болса, Жылауды талдау мүмкіндігін пайдаланып, бұл дыбыстың артында қандай қажеттілік тұрғанын біліңіз.'),
  ('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee', 'Шаршауды жасырмаңыз 💖', 'Үй шашылып жатыр, ал тамаққа онлайн тапсырыс бердіңіз бе? Ештеңе етпейді. Бұл жолда Сіз жалғыз емессіз.'),
  ('8f6c6637-de06-4b9d-8e44-d9e85864f3c8', 'Таңғы жаттығу 🐢', 'Ол басын бұрынғыдан да тік ұстай бастады! Етпетінен жату уақытын қызықты ойынға айналдырыңыз. Оны айнаның алдына жатқызып, өз бейнесіне қалай қарайтынын бақылаңыз.'),
  ('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74', 'Еске салу тізімі 📝', 'Үйге қажет заттар ешқашан таусылмайды. Бәрін есте сақтауға тырысып шаршамаңыз: Сатып алу тізімін ашып, қажет заттарды жазып қойыңыз да, тізімді бір рет түрту арқылы жұбайыңызбен бөлісіңіз.'),
  ('12a076b6-d8dc-4bec-a8af-ddc523182bad', 'Ертегі уақыты 📖', 'Бөпеңіздің болашақта қиялы ұшқыр жан болып өсуі бүгіннен басталады. Ақылды ертегілердің көмегімен сиқырлы хикая құрастырып, оқып беріңіз де, көздерінің біртіндеп жұмылғанын тамашалаңыз.'),
  ('58ce6bd9-90fd-4e98-a133-ddfda6d59177', 'Қалтаңыздағы педиатр 🤖', 'Салмағы дұрыс қосылып жатыр ма? Нәжісінің түсі өзгерді ме? Уайымға салынбас бұрын Anacan AI-ға жазыңыз, мәселенің мәнін түсініп, көңіліңізді тыныштандыратын ақпарат алыңыз.'),
  ('5543e602-8610-44ac-8995-56ec74a0576e', 'Ақылды тыныштық 🤫', 'Кешкі мазасыздықты барынша азайту үшін бөлмедегі тыныштықты бақылау маңызды. Дыбыс өлшегішті қосып, шамадан тыс шулы ортадан аулақ болыңыз және бөпеңізді жайлы ұйқыға дайындаңыз.'),
  ('81600590-d6f0-495d-b852-9afcf35b137a', 'Кішкентай зерттеушінің киімі ⛅', 'Серуенге шыққыңыз келеді, бірақ ауа райы қандай болары белгісіз бе? Ауа райы мен киім жөніндегі көмекшіңіздің көмегімен бүгінгі температураға сай ең қолайлы киім үйлесімін санаулы секундта табыңыз.'),
  ('fbf2b91a-0a2a-4aa9-9404-589ba5628b25', 'Таңғы күлкі ☀️', 'Көзін аша сала Сізге қарап, күлімсіреп қойды ма? Сіз әлемдегі ең қымбат сыйлықты алдыңыз. Бүгін осы сәтті ойлап, көтеріңкі көңіл күйде жүріңіз.'),
  ('1f2c4967-df72-43b6-91d0-25ece4f2331b', 'Мерекеге 10 күн қалды! 🎂', 'Дайындалыңыз, 3 ай толуына небәрі 10 күн қалды! Алғашқы үлкен мерейтойлардың бірі жақындап келеді. Әдемі безендіру тақырыбын ойластырып, тортқа тапсырыс беретін кез келді!'),
  ('488e046f-44fb-4fcc-80e0-064c20288a56', 'Бір-біріңізді құттықтаңыздар 🥂', 'Бүгін кешке жұбайыңызбен бірге 80 күн бойғы еңбектеріңіз үшін бір-біріңізге алғыс айтыңыздар. Қолдарыңыздан келді!'),
  ('720785a0-3423-4036-a26d-bba9419b8cb2', 'Керемет 80-ші күн! 🎉', 'Бірге болғандарыңызға тура 80 күн! Бөпе фотосессиясы бөліміне кіріп, арнайы 80-ші күн стикерлерімен осы күнді мәңгі есте қалдырыңыз және қауымдастықта естелік ретінде бөлісіңіз!'),
  ('7d54b8de-cc42-4891-b97a-5856eefffe9d', 'Сіздің жеке ертегіңіз жасалып жатыр 🪄', 'Бүгін кешке басты кейіпкер бөпеңіз болсын! Ақылды ертегілер құралына кіріп, мына тақырыпты жазыңыз: “Түнде ұйықтағысы келмейтін кішкентай серінің шытырман оқиғасы”. Жасанды интеллект тек Сіз үшін бірегей әрі сүйкімді хикая құрастырсын.'),
  ('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a', 'Диалогке дайынсыз ба? 🗣️', 'Енді бөпеңіз жай ғана дыбыс шығарып қоймай, Сіздің даусыңызға әртүрлі үнмен жауап беруге тырысады! Даму трекерін ашып, қарым-қатынастағы осы тамаша серпілісті белгілеңіз де, онымен өз тілінде сөйлесіп көріңіз.'),
  ('f027a882-3827-4905-9807-216432d88e53', 'Ананың миындағы тұман 🌫️', 'Кеше не жегеніңіз есіңізде жоқ па? Ана ұмытшақтығы (Baby brain) — шынайы құбылыс. Миыңызды шаршатпаңыз, үйге қажет нәрсенің бәрін Сатып алу тізіміне жазып қойыңыз, қалғанын жұбайыңыз реттесін.'),
  ('2e536117-6f18-4388-b1bd-29587c89d3cb', 'Шаш түсуі туралы шындық 💇‍♀️', 'Айнаға қарағанда шашыңыздың түсуі Сізді қорқыта ма? Бұл — босанғаннан кейінгі кезеңнің ең жағымсыз шындықтарының бірі! Сіз жалғыз емессіз: дәл қазір Anacan қауымдастығына кіріп, басқа аналардың бұл қиындықты қалай еңсергенін оқыңыз.'),
  ('41393920-01a7-42fe-a049-e26e1148a375', 'Тыныштық іздеу 🤫', 'Кейде үйдегі шу өзіңіз байқамай-ақ бөпеңіздің ұйықтауына кедергі келтіреді. Дыбыс өлшегішті қосып, бөлменің акустикасын тексеріңіз және оған ұйықтауға қолайлы тыныш орта жасаңыз.'),
  ('acb2ca22-b3e3-4ac0-b344-a63734056dfa', 'Қызыл иегі қышып жүр ме? 🦷', 'Бөпеңіз бәрін, әсіресе өз қолын аузына сала бере ме? Сілекейі көп бөліне бастады ма? Тіс шығу трекеріне алғашқы белгілерді дереу жазып, осы ұзақ үдеріске дайын болыңыз.'),
  ('357bed80-6ac0-481c-9f5b-22bc1c97e3fe', 'Қолдарын зерттеу 🤲', 'Ілулі тұрған ойыншықтарға саналы түрде қол созуға тырыса ма? Қимыл-қозғалыс дағдылары дамып келеді. Ұсынылатын өнімдер бөлімінен оның осы жаңа қызығушылығын қолдайтын қауіпсіз ұстауға арналған ойыншықтарды қарап шығыңыз.'),
  ('3c4bae00-6309-4214-a502-aa8dcb398a77', 'Ауа райының тосынсыйы ⛅', 'Сыртқа шыққыңыз келеді, бірақ терезеден қарап, ауа райын түсіне алмай тұрсыз ба? Бөпеңізді қабат-қабат киіндіріп, терлетіп алмаңыз. Ауа райы және киім құралы бүгінгі температураға ең қолайлы киімді санаулы секундта ұсынсын.'),
  ('55bafaf5-82ef-4f88-880d-836cf89145d0', 'Дыбыстардың күші 🌊', 'Кешке қарай себепсіз басталатын мазасыздық сағаттары әбден қажытады. Бөпені бөлмеге апарып, ақ шу арасынан мұхит толқынының немесе феннің дыбысын таңдаңыз да, ортаны бірден тыныштандырыңыз.'),
  ('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87', 'Ананың энергиясы қайда? 🔋', 'Айнадағы шаршаған көзіңізге қарап, өзіңізді кінәламаңыз. Тамақтануыңызға көңіл бөліп жүрсіз бе? Пайдалы рецептілер арасынан 10 минутта дайындалатын, темірге бай ана смузиін таңдап, күш-қуатыңызды қалпына келтіріңіз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('13035ad4-af08-4b79-ba71-a42ceb60fe5b'::uuid, 'Командалық талқылау 🛋️', 'Бала ұйықтағаннан кейін, Көңіл күй күнделігіндегі апталық статистикаңызды жұбыңызбен бірге қарап шығыңыз. Қай күндері күйзелісіңіз көбірек болды? Нені басқаша істеуге болады? Сіздер — бір командасыздар!'),
  ('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6', 'Төменге қараңыз! 👣', 'Ол енді өз аяқтарын зерттеп жүр! Аяқ башпайларын ұстауға тырысатын сол күлкілі әрі сүйкімді сәтті жіберіп алмаңыз. Бөпе фотосессиясын ашып, стикерлермен безендіріңіз де, дамудың осы маңызды сәтін есте қалдырыңыз.'),
  ('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8', 'Тіс қаситын ойыншық іздеу 🦷', 'Сілекейі тоқтамай ағып, бәрін кеміріп жүр ме? Тіс шығуын бақылау құралы ескерту беріп тұр. Ұсынылатын өнімдер бөлімінен таза силиконнан немесе ағаштан жасалған тіс қаситын ойыншықтарды қарайтын дәл уақыт.'),
  ('0d132ba6-d6e9-44f6-a85d-e139c66b9760', 'Жылдам сұхбат 🤖', 'Бала неліктен кенеттен күндізгі ұйқыдан бас тартып жүр? Ұзақ мақалаларды оқуға уақытыңыз жоқ. Сұрағыңызды тікелей Anacan AI-ға жазып, 3 айлық ұйқы регрессиясы туралы нақты әрі қысқа жауап алыңыз.'),
  ('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198', 'Ертегі философиясы 🪄', 'Ақылды ертегілер қайтадан іске кірісті! Жүйеге: «Күндіз ойнап шаршап, түнде ғажайып түстер көретін пері туралы ертегі» деп жазыңыз. Оқып отырып, өзіңіз де ұйықтап қалуыңыз мүмкін.'),
  ('6c6289cf-6e7c-4e83-a178-d01d67cef488', 'Ауа райына сай емес киімдер 👗', 'Кейде тым жұқа, кейде тым қалың киіндіріп қоясыз ба? Күмәнданбаңыз. Терезеге қараудың орнына бірден Ауа райы мен киім бөлімін тексеріңіз де, жүйе ұсынған бірнеше қабат киім нұсқасының арқасында алаңдамай жүріңіз.'),
  ('42bfdf13-2735-49dc-b527-89506330c670', 'Әкенің иығы 👨‍👧', 'Шыдамыңыз таусылып, қолыңыз талып кетті ме? Бүгін кешке Серіктес режимін қосыңыз. Бөпенің кекірігін шығару және бөлме ішінде көтеріп жүру — толығымен әкесінің міндеті. Ал Сіз диванда жай ғана демалыңыз.'),
  ('3d2a21ef-6e5b-4f36-9011-f9c3474762a4', 'Қарны аш емес, онда неге жылайды? 🧩', 'Не істесеңіз де тынышталмай, жылаған дауысы өзгеше естіле ме? Болжай бермей, дауысын Жылауды талдау функциясына тыңдатыңыз да, мәселе ішінің кебуінде ме, әлде ұйқысының қанбауында ма — бірден біліңіз.'),
  ('b092d275-f2d6-47ce-b8d0-3f8ced210589', 'Құлаққап пен кофе 🎧', 'Бүгін шынымен өте қиын күн болды. Көңіл күй күнделігіне сезімдеріңізді жазып, жеңілдеп алыңыз. Содан кейін құлаққапты киіп, сүйікті музыкаңызды қосыңыз да, 10 минут бойы нағыз тыныштықта ыстық кофе ішіңіз.'),
  ('c6fb2576-7fa6-4e01-b8a4-ec89ac753089', 'Таңғы тасқын 💩', 'Көзіңізді аша сала мойнына дейін былғанған бөпе мен ауыстыруды қажет ететін жайманы көрдіңіз бе? Осы үлкен апатты Жөргек бақылауында күліп отырып белгілеңіз. Иә, ана болудың осындай сәттері де бар!'),
  ('022a6d7a-76fe-47e7-aae6-a35dad3d3555', 'Уақытын өлшеңіз ⏱️', 'Ретсіз тамақтану Сізді шаршатты ма? Емшек емгенде немесе бөтелкемен тамақтанғанда қанша уақыт кететінін Тамақтануды бақылау таймерімен өлшеп, бөпеңіздің енді қалыптасып келе жатқан күн тәртібін танып-біліңіз.'),
  ('62da6149-1edf-4e2a-abc6-d69d21a43fa4', 'Таңғы жаттығуға қарсылық 🐢', 'Етпетінен жатқысы (Tummy time) келмей, жылай ма? Оны мәжбүрлемеңіз. Anacan AI-дан: “3 айлық бөпеге етпетінен жатуды қалай қызықты етуге болады?” деп сұрап, жылдам кеңестер алыңыз.'),
  ('938dd21f-e30f-4b2b-b3e0-d79140f44b59', 'Тағы да ертегі құрайық! 🪄', 'Бұл жолы Ақылды ертегілерге одан да күлкілі тапсырма берейік: “Әкесінің сақалына тығылған ергежейлінің хикаясы”. Жасанды интеллект құрастырған бұл ертегіні жұбайыңыз дауыстап оқысын, ал бөлме күлкіге толсын.'),
  ('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc', 'Төрт қабырғадан қашу 🏃‍♀️', 'Үйде отыра беруден шаршадыңыз, бірақ баламен қайда барарыңызды білмейсіз бе? Анаға жайлы орындардан бала арбасымен оңай кіруге болатын әрі емізу бөлмесі бар ең жақын дәмхананы тауып, біраз сергіп, адамдармен араласыңыз.'),
  ('88a16b76-764f-4acc-b335-0aa3f126d25a', 'Серуендейтін уақыт ⛅', 'Киініп, жиналу қиын болып көрінуі мүмкін, бірақ таза ауада 20 минут серуендеу бөпеңізге де, Сіздің көңіл күйіңізге де өте пайдалы. Ауа райына сай киініп, терезені емес, есікті ашыңыз!'),
  ('bb5697de-df9c-4558-a606-a7acef72c755', 'Түннің қаһарманы — әке 🦸‍♂️', 'Алғашқы айлардың ең жақсы қағидасы: кекірту мен бесік жырын айту кезекпен орындалуы керек! Бүгін кешке бөпе әкесінің құшағында, ал Сіз құлаққабыңызды тағып, музыка тыңдап демалыңыз.'),
  ('4696c250-45bb-4765-b4bf-ee4e94f6361c', 'Ананың бір шыныаяқ демалысы ☕', 'Бүгін өзіңіз үшін не істедіңіз? Ештеңе ме? Бөпеңіз күндізгі ұйқыға кеткен бойда телефонды шетке қойыңыз. Өзіңізге ыстық кофе (немесе шай) құйып, 10 минут ештеңе ойламай отырыңыз.'),
  ('7831318d-6b24-4373-9578-2c2a43ef02bf', 'Шаш жұлу өнері 💇‍♀️', 'Бөпеңіз қолын бірден шашыңызға орап, бар күшімен тарта ма? Оның қармау рефлексі күшейіп келеді! Күлкілі әрі ауырсындыратын осы даму кезеңін міндетті түрде видеоға түсіріп, естелікке сақтап қойыңыз.'),
  ('d66ea07a-276e-489b-bd8f-3ff80abe7258', 'Дене жанасуының кереметі 🫂', 'Еш ұйықтағысы келмей, төсегіне жатқызған бойда жылай ма? Кейде ешқандай құралдың қажеті жоқ. Оны кеудеңізге жатқызып, теріге-тері жанасудың екеуіңізді де қалай тыныштандыратынын сезініңіз.'),
  ('a99309cf-e0e5-4d40-9004-a8b08226861a', 'Жағасы әр 10 минут сайын сулана ма?', 'Тіс шығуын бақылау құралындағы алғашқы белгілер енді шындыққа айналып келеді. Төменгі қызыл иегін жиі тексеріңіз, бәлкім, алғашқы ақ маржаны жарып шығуға жақын қалған болар!'),
  ('b14018ad-b2b5-4374-a785-9d281ebdd7e0', 'Небәрі 15 минут тыныштық 🤫', 'Күні бойы шаршағаннан басыңыз ауырып кетті ме? Бөпеңізді ұйықтатқанда Дыбыс өлшегішін қосып, айналадағы шуды бақылауға алыңыз, үйдегілерден тыныштық сақтауын сұрап, миыңызға демалыс беріңіз.'),
  ('c69510ed-a6e2-4456-a462-211d3917dec3', 'Басқа аналар не істеп жүр? 💬', '«Тек менің балам ғана осылай істей ме?» деп ойлайсыз ба? Сіз жалғыз емессіз! Anacan қауымдастығына кіріп, ондағы аналардың шынайы оқиғаларын оқыңыз да, көңіліңізді бір демде басыңыз.'),
  ('8474a75e-7aaf-420e-b5ab-acd7d55ac51c', 'Күлу уақыты! 😂', 'Енді ол жай ғана жымиып қоймай, дауыстап күледі! Онымен ойнаңыз, ішін қытықтаңыз. Бұл күлкі — ұйқысыз өткен барлық түндеріңіз үшін берілген ең керемет сый.'),
  ('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b', 'Ұйқы белгілері 🥱', 'Көзін уқалап, құлағын тартып немесе бір нүктеге қадалып отыр ма? Кешкі мазасыздық басталғанша күтпеңіз. Осы белгілерді байқаған бойда бөлмені қараңғылап, ұйқыға дайындау рәсімін бастаңыз.'),
  ('1867104a-7fa8-428a-ad5d-dd10e6890f0f', 'Ауызбен зерттеу 🤤', 'Қолын, ойыншықтарын, тапқан нәрсесінің бәрін бірден аузына сала ма? Бұл — оның қоршаған ортаны танып-білу тәсілі. Бәрін қолынан ала бермеңіз, тек айналасындағы заттардың таза екеніне көз жеткізіңіз.'),
  ('4ad3cf84-0aac-46cb-bfdf-5a928764105a', 'Үй неге осынша шашылып жатыр? 🌪️', 'Бөлменің ортасындағы үйіліп жатқан ойыншықтар мен жуылмаған ыдыстарға қарап, өзіңізді кінәлап жүрсіз бе? Бүгін сол ыдыстар орнында тұра берсін. Бала өсірудің өзі — орасан зор еңбек!'),
  ('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b', 'Аунау жаттығулары 🤸‍♂️', 'Ол шалқасынан етпетіне қарай аунауға тырысып жүр! Бұл — кішкентай дененің үлкен талпынысы. Оның осы қызықты әрекеттерін қолдаңыз, бірақ кереуеттің шетінде аса мұқият болыңыз.'),
  ('91aad506-9119-4c1d-9011-ca750f77b2da', 'Сіздің барыңыз жеткілікті! 💖', 'Бүгін таңертең айнаға қарап, өзіңізді шаршаған, бәлкім, жеткіліксіз сезіндіңіз бе? Терең тыныс алыңыз. Сізге жәудіреп қарайтын бөпеңіз үшін Сіз — әлемдегі ең керемет жансыз. Сіздің барыңыз жеткілікті!'),
  ('cc5d4a21-5a6c-4726-9656-04a48085588c', 'Қаншалықты шаршадық? 🛋️', 'Бала ұйықтады, ал Сіз ше? Көңіл күй күнделігін ашып, жұбыңызбен бірге бүгінгі қарбаласты әзілмен жазып қойыңыз. Қиын күндер өтіп кетеді, ал командалық рух сақталып қалады.'),
  ('8557b605-4ddd-4ff9-9e9a-646d4a26ea63', 'Ұйқы регрессиясы жақындап қалды ма? 🤖', 'Балаңыз түнде кенеттен жиі ояна бастады ма? Қорықпаңыз, 4-ші айдағы ұйқы регрессиясы жақындап келеді. Осы биологиялық үдеріс туралы қысқа әрі көңілге тыныштық сыйлайтын ақпаратты Anacan AI-дан бірден алыңыз.'),
  ('132d4620-5085-4072-ac1e-81f46dc4e74c', 'Ұйқысын дыбыс өлшегішпен қорғаңыз 🤫', 'Толқып жүрсіз, үйде дайындық қызу жүріп жатыр, бірақ бөпенің ұйқысы да бұзылмауы керек. Бөлмеде Дыбыс өлшегішті қосып қойыңыз да, шу деңгейінің белгіленген шектен асқанын бірден көріңіз.'),
  ('32bd9b1c-365c-405d-addd-9a30d6295abc', 'Бүгін үй жинамайсыз! 🛑', 'Үйдің бәрін жинауға міндетті емессіз. Серіктес режимін қосыңыз: бүгін үй жинау мен тамаққа тапсырыс беру — жұбайыңыздың міндеті. Ал Сіз ертеңгі 3 айлық фотосессияны жоспарлаңыз.'),
  ('a4183b3c-1979-434f-a71f-64b50e2e618c', 'Дайындалатын уақыт келді! 🎂', 'Назар аударыңыз! Ертең — ерекше күн, тура 3 ай толады! 90-күнге айрықша көңіл күй сыйлау үшін тортқа тапсырыс беруді немесе шағын тақырыптық безендіру дайындауды ұмытпадыңыз ба? Асығыңыз!'),
  ('10a571b7-6bc2-4092-a70f-a265883d71ba', 'ТУРА 3 АЙ! ДӘЛ 90 КҮН! 🎉', 'Сіз мұны еңсердіңіз! Ұйқысыздыққа, қиын кезеңдер мен қорқыныштарға қарамастан, 90 күн бойы керемет командалық жұмыс атқардыңыздар. Бөпенің фотосессиясын ашып, 3 айлық стикерді таңдаңыз да, осы қуанышыңызды Anacan Қауымдастығындағы басқа аналармен бірден бөлісіңіз!'),
  ('9877e456-4a5e-45a3-aee9-e9703be5cf91', 'Құттықтаймыз! 🥂', 'Барлық жазбаларыңыз бен даму кестелеріңізге қайта көз жүгіртіңіз. Бөпеңіздің қаншалықты өскенін, ал өзіңіздің қаншалықты күшейгеніңізді көріңіз. Өзіңізді мақтан тұтатын кез келді!'),
  ('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e', 'Команданың жеңіс сәті 💖', 'Бөпеңізді арнайы ұйқы таймерімен ұйықтаттыңыз. Енді жұбайыңызбен бетпе-бет отырып, осы 90 күннің әрбір сәті үшін бір-біріңізге алғыс айтыңыздар. Бұл — бөпеңіздің ғана емес, Сіздердің ата-ана болғандарыңыздың да 3 айлығы!'),
  ('5c67089a-581e-455d-b113-f87f427babb2', 'Өзіңіздің ерекше ертегіңіз 🪄', 'Бүгін кешке Ақылды ертегілер құралына мынадай сүйкімді тақырып берейік: “Аспаннан түскен ең сүйкімді жұлдыздың хикаясы”. Бөлмеде тек осы ертегінің үні естіліп, айналаны мамыражай тыныштық жайласын.'),
  ('66bd508e-0413-4d01-9ea7-c369b0d8cafa', 'Әкенің кезегі 👨‍👧', 'Шыдам таусылып бара ма? Бүгін аналық кезегіңізді аз уақытқа жұбайыңызға тапсырыңыз. Әкесі мен бөпеңіз біраз уақытты бірге өткізсін, ал Сіз аяғыңызды созып, жай ғана демалыңыз.'),
  ('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'Айнадағы дос 👀', 'Оны айнаның алдына апарыңыз. Өз бейнесіне таңырқап, күлімсірей қарағанын бақылаңыз. Ол айнадағы бейненің өзі екенін әлі білмейді, бірақ бұл ойын оның ой-өрісінің дамуына өте пайдалы.'),
  ('6f416e63-4acf-4dd2-8216-6601a8c26df5', 'Кінә сезімінен арылыңыз 🛑', 'Бүгін шыдамыңыз таусылып, сәл ашуланып қалдыңыз да, енді өзіңізді кінәлі сезініп жүрсіз бе? Тоқтаңыз. Сіз роботсыз ба? Жоқ. Сезімдеріңізді қабылдап, өзіңізді кешіріңіз де, ертең жаңа күнді бастаңыз.'),
  ('d584b1c4-e42a-483d-b585-e83a9ab20c88', 'Анаға арналған қуат көзі 🍲', 'Бөпеңізді тойдырамын деп, өзіңіз аш қалып қойдыңыз ба? Пайдалы рецептер бөлімінен оңай қорытылатын әрі қуат беретін тіскебасар дайындаңыз. Бөпеңізге күш беру үшін өзіңіз де қуатты болуыңыз керек.'),
  ('014e3f07-72e8-47f8-b62e-ff583a9df29e', 'Менімен сөйлесіңіз! 🗣️', 'Сізге қарап, түсініксіз буындарды айтып жүр ме? Оның дыбыстары мен кідірістеріне жауап беріңіз. Ол дәл қазір Сізбен нағыз диалог құрып жатыр! Бұл — тіл дамуының ең негізгі қадамы.'),
  ('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef', 'Көзге көрінбейтін қажеттіліктер 🛒', 'Күнделікті қарбаласта бірдеңе таусылуға жақын ба? Дәретхана қағазы, жөргек, сусабын? Ұмытып кетпей тұрғанда, сатып алу тізіміне қазір қосыңыз — жұбайыңыздың телефонына хабарлама болып барсын.'),
  ('e8ec2cd2-3417-4383-8892-bb623cb07365', 'Уақытты тоқтату 📸', 'Ол сондай тез өсіп келеді... Бүгін кешке ұйықтап жатқанда, бет әлпетіне мұқият қараңыз. Оның кішкентай қолдары мен жүзін Бөпе фотосессиясы арқылы суретке түсіріп, осы сәтті мәңгілікке сақтаңыз.'),
  ('2a23a61b-4ca6-48f6-8845-f47a357eed0f', 'Бұл дыбыс нені білдіреді? 🧩', 'Көзін аша сала бірдеңе айтып, жылай бастай ма? Себебін таба алмасаңыз, Жылауды талдау мүмкіндігін пайдаланып, бірнеше секунд ішінде бұл мазасыздықтың сырын ашыңыз.'),
  ('43fbc1cb-7e93-4983-b59f-f5bc67650d3e', 'Ертегінің соңы жоқ 📖', 'Бүгін кешке Ақылды ертегілерге креативтірек тапсырма беріңіз: “Анасының иісін іздеген кішкентай қонжықтың хикаясы”. Кешті махаббатқа толы әрі тыныш аяқтаңыз.'),
  ('b8cf3d8c-2c7c-497e-8657-18fd989a1928', 'Үйден шығу жоспары! 🌳', 'Бөпеңізбен қайда баруға болатынын білмейсіз бе? Саябақта серуендеу шаршата ма? Анаға қолайлы орындардан бөпеңізбен жайлы отырып, бір шыны кофе іше алатын орынды табыңыз.'),
  ('1c648ce0-799c-41f0-964a-90e59cbddc3d', 'Үлкен жеңіс, ортақ мақтаныш 🥂', '100 түн, 100 күн... Осы үлкен жауапкершілікті Сізбен бірге арқалап келе жатқан серігіңізге қараңыз. Көңіл күй күнделігіне 100-ші күннің мақтанышын жазып, бір-біріңізге тік тұрып қол соғыңыздар. Бұл — командаңыздың жеңісі!'),
  ('52155593-73d7-4bb9-861d-d87a0ca100e9', '100 КҮНДІК ҒАЖАЙЫП! 🎉', 'Иә, бүгін өміріңіздің түбегейлі өзгергеніне тура 100 күн болды! Сіз таңғаларлықтай үлкен іс атқарып жүрсіз.'),
  ('7c63492d-1515-406a-bd31-b41ece7e0412', 'Өзіңізге қол соғыңыз 👏', 'Артқа көз салсаңыз, алғашқы күндердің қаншалықты қорқынышты болғанын, ал қазір олардың Сізге қаншама нәрсе үйреткенін көресіз. Өзіңізді мақтан тұтыңыз. Бөпеңіз ғана 100 күн бойы өскен жоқ, Сіз де онымен бірге 100 күн бойы өстіңіз.'),
  ('724659ec-f59f-4bfe-b20d-efdd3d977217', 'Еркіндік сәті 🛋️', 'Ол өздігінен ойнап отырғанда, бірден үй шаруасына кірісіп кетпеңіз. Отырыңыз да, оны алыстан 5 минут бақылап, кофеңізді ішіңіз.'),
  ('aaed3963-e8dd-47d4-93bd-9b307c2b65fd', 'Таңғы сергектік ⚡', 'Көзін аша сала былдырлай ма? Ол Сізбен сөйлескісі келеді. Күлімсіреп жауап беріңіз, бұл — оның тіл дамуының негізі.'),
  ('d1e64fb7-d149-4fd0-afca-834eed2264d1', 'Ұйқы регрессиясы ма? 🌙', 'Түнде жиі ояна бастады ма? Бұл 4-ші айдағы ұйқы регрессиясының белгілері болуы мүмкін. Сабыр сақтаңыз, бұл да уақытша кезең.'),
  ('13cad6d0-aa0a-426b-9515-1e96e73e716a', 'Жаңа жаңалықтар 🤲', 'Қолына түскеннің бәрін аузына сала ма? Алаңдамаңыз, бұл — оның әлемді тану тәсілі. Тек айналасын таза ұстаңыз.'),
  ('1e555e61-fac2-4756-83d5-5c2a2ceaa400', 'Өзіңізге арналған ерекше ертегі 🪄', 'Ақылды ертегілермен кешкі ұйқыға жатуды жеңілдетіңіз. Бөпеңізге арнап ерекше, сүйкімді хикая құрастырып, оқып беріңіз.'),
  ('a4146327-bb44-44e0-9860-d8e3c1abe5c4', 'Біз бір командамыз! 💪', 'Өзіңізді жалғыз әрі шаршағандай сезінесіз бе? Терең тыныс алыңыз. Сіз — осынау аласапыран күндердің ең мықты қаһарманысыз.'),
  ('e3c0355b-40c6-476a-8c2d-f69c78debdb1', 'Керемет аунап түсу 🤸‍♂️', 'Шалқасынан етпетіне аунауға тырысып жүр ме? Ол барын салып жатыр! Бұл әрекеттерін бақылаңыз, бірақ оны төсекте ешқашан жалғыз қалдырмаңыз.'),
  ('532d58e2-50f3-422a-818a-36c88094bb87', 'Не кигіземін? ⛅', 'Сыртқа шығарда не кигізетініңізді ойлап әуре болмаңыз. Ауа райы мен киім таңдау құралын қарап, мінсіз киім үйлесімін санаулы секундта табыңыз.'),
  ('f37039a0-f7af-487a-827e-622e2d9e4d05', 'Қалжырау — қалыпты жағдай 🔋', 'Шыдам таусылғанда өзіңізді жаман анамын деп ойламаңыз. Мұндай шаршау — табиғи нәрсе. Жұбайыңыздан қолдау сұрауға қысылмаңыз.'),
  ('f94cdd25-2b6b-47df-81dc-6e3cab221652', 'Сіз жеткіліктісіз! 🌸', 'Бүгін бәрі ойдағыдай болмай жатыр ма? Ештеңе етпейді. Бөпеңізге Сізден артық ешкім қажет емес. Сіз оған толықтай жеткіліктісіз.'),
  ('18211145-ceeb-48f3-8053-1e2ff686e384', 'Дыбыстардың сиқыры 🌊', 'Кешкісін бөпеңіз тоқтамай жылай бастаса, абыржымаңыз. Бөпеңізге Ақ шуды қосып, бөлменің атмосферасын әп-сәтте өзгертіңіз.'),
  ('49d00520-8368-4f13-9074-fbe894888b76', 'Жасанды интеллектіден сұраңыз 🤖', 'Ойыңызда мыңдаған сұрақ бар ма? Іздеуге уақыт жоғалтпай, бірден Anacan AI-дан сұрап, нақты әрі ғылыми негізделген жауап алыңыз.'),
  ('e6ea83f7-b8a5-46f7-ba44-81c58175071e', 'Төменге қараңыз! 👣', 'Ол аяқ саусақтарын енді байқап жүр! Осы күлкілі әрі таңғажайып сәтті мұқият бақылап, оның дамуына қуаныңыз.'),
  ('53a91083-d8e0-4baf-9f90-46ce72a9291d', 'Айнадағы дос 👀', 'Оны айнаның алдына апарыңыз. Өз бейнесіне таңырқай қарап, күлімдегенін тамашалау — керемет ермек.'),
  ('96d4756e-270f-426b-9e78-f2a573accdac', 'Серуендейтін уақыт 🌳', 'Төрт қабырғада отыру жалықтырады. Оны арбасына отырғызып, 15 минут болса да таза ауаға шығыңыз. Бұл екеуіңізге де жақсы әсер етеді.'),
  ('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41', 'Түнгі қаһарман 🦸‍♂️', 'Түнде қайта-қайта оянудан шаршадыңыз ба? Әкесін оятудан тартынбаңыз. Бір команда болу — жүктемені тең бөлісу деген сөз.'),
  ('07f48fa2-56fd-416e-adda-88c824f2bd6f', 'Терең ұйқыға дайындық 🛀', 'Жылы ванна, жұмсақ массаж және бөлмені қараңғылау... Ұйқыға дайындық тәртібін сақтау — тыныш түндердің сыры.'),
  ('828415f3-317f-4e76-8caf-753026dcf9f1', 'Өзіңізді кінәламаңыз 💖', 'Бөпеңізге аз уақыт бөліп жүрмін деп ойлайсыз ба? Көңілді әрі сапалы өткізілген 10 минут күйзеліске толы 1 сағаттан әлдеқайда құнды.'),
  ('f4730701-e02f-4cf0-9730-df8b7e034297', 'Өзім ұстаймын! 🧸', 'Ілулі тұрған ойыншықтарға дәл қол соза ма? Оның көз бен қол үйлесімділігі жақсарып келеді. Түрлі түсті заттармен қызығушылығын арттырыңыз.'),
  ('70597740-ab51-4b20-b743-042bccb768a6', 'Таңғы жаттығу 🐢', 'Етпетінен жату мойын бұлшықеттерін нығайтады. Жыласа да, күн сайын аз уақыттан жалғастыра беріңіз.'),
  ('bfab4a59-c162-47a2-9035-51b03b7fe911', 'Үй шаруасы күте тұрады 🛑', 'Шашылып жатқан бөлмеге қарап, күйзеліске түспеңіз. Сіз кішкентай адамды өсіріп жатырсыз, мінсіз үй бикесі болуға міндетті емессіз.'),
  ('ca9affc4-d638-41a2-8dc7-75447d9ea222', 'Әкенің кезегі 👨‍🍼', 'Бүгін кешке бөпенің кекірігін шығарып, бесік жырын айту — әкенің міндеті. Ал Сіз барып демалыңыз.'),
  ('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e', 'Өзіңізді ұмытпаңыз 🍲', 'Ол тойды, ал Сіз ше? Қуатыңызды қалпына келтіру үшін құнарлы тамақтануыңыз керек. Бүгін өзіңізге дәмді әрі тойымды тағамға тапсырыс беріңіз.'),
  ('957a90d0-61dc-45f5-a2da-ef7086521cd5', 'Бөлмеден кенет қатты күлкі естідіңіз бе? 😂', 'Иә, ол енді қарқылдап күледі! Бұл күлкі бүкіл шаршауыңызға тұрарлық.'),
  ('dd50206e-acee-43ac-8f19-c5dd29cf7e62', 'Теріге-тері жанасуы 🫂', 'Бөпе қатты мазасызданып жүр ме? Ештеңе көмектеспесе, оны кеудеңізге жатқызыңыз. Жүрегіңіздің соғысы — ең жақсы тыныштандырғыш.'),
  ('2c73f922-1b22-4eb6-922b-215d8e623242', 'Шаш жұлу ойыны 💇‍♀️', 'Саусақтарын шашыңызға орап алып, қатты тарта ма? Ұстау рефлексі дамып келеді. Аздап ауыртатын осы даму сәтін күлімсіреп қабылдауға тырысыңыз.'),
  ('f32eaadc-b85c-4f36-b182-6f6665e1eaae', 'Толық тыныштық 🤫', 'Ұйықтауы қиындап жүр ме? Бөлмені толық қараңғылап, барлық дыбысты өшіріңіз. Қараңғылық пен тыныштық — оның ұйқыдағы ең жақсы серіктері.'),
  ('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b', 'Алғашқы тістері шығып келе ме? 🦷', 'Сілекейі көбірек аға бастады ма? Тіс шығуын бақылау бөлімінде белгілеп отырыңыз және қолыңызда әрдайым таза тіс қаситын ойыншықтар болсын.'),
  ('81a8fffa-561b-48b8-9be0-ff9b930a7bac', 'Эмоциялық жеңілдеу 📝', 'Бүгін бәрі үсті-үстіне келіп жатқандай ма? Барлық қиындық пен шаршағаныңызды Көңіл күй күнделігіне жазыңыз. Сезімдеріңізді іште тұншықтырмаңыз.'),
  ('87db18be-f6b3-443d-9d07-0e305836d90b', '110-күннің жеңісі! 🥂', 'Жаңа өмірге бағыт-бағдар беріп жүргеніңізге тура 110 күн болды. Жұбыңызбен бір-біріңізге алғыс айтып, бүгін кешке тыныштықтан ләззат алыңыздар.'),
  ('1063f207-152c-4454-9267-2e05e30929d8', 'Ақылды тыныштық 🤫', 'Ұйықтап бара жатқанда кенет шыққан дыбыстар бөпеңізді оята ма? Дыбыс өлшегіш арқылы бөлмедегі децибел деңгейін бақылаңыз.'),
  ('17c1a37e-ab5c-4032-afa2-27e4d0964076', 'Қарны аш па, әлде шаршады ма? 😭', 'Бөпеңіз себепсіз жылап, дауысы өзгеше естіле ме? Бұл аштықтан емес, жай ғана ұйқысының қанбауынан болуы мүмкін. Ұйқы режимін мұқият қадағалаңыз.'),
  ('93512cbe-adab-49c7-8e82-4466bf0e00ad', 'Анаға арналған 10 минут ☕', 'Бөпеңіз ұйықтай салысымен үй шаруасына кірісіп кетпеңіз. Диванға отырып, кофеңізді ішіңіз де, 10 минут бойы ештеңе істемей, жай ғана демалыңыз.'),
  ('8bc219eb-803c-491e-9625-0efec17a7dad', 'Кезекті тапсырыңыз 🛋️', 'Бөпеңіз ұйықтағанда Сіздің де құлай кетіп ұйықтағыңыз келсе, үйдегі басқа шаруаларды жұбыңызға тапсырыңыз. Денсаулығыңыз бәрінен маңызды.'),
  ('924ff591-18ec-4c20-80af-4008cda2fc41', 'Әртүрлі үндер 🗣️', 'Бөпеңіздің шығаратын дыбыстары бұрынғыдан да қатты әрі алуан түрлі бола бастады. Оны тыңдап, дыбыстарына еліктеу арқылы күлдіріңіз.'),
  ('be9ad5fd-195c-40e7-99c6-7f5f91e01526', 'Ұмытпас үшін тізім 🛒', 'Ұйқысыздық есте сақтау қабілетіңізді әлсіретті ме? Үйге қажет заттарды ойда сақтауға тырыспай, Сатып алу тізіміне жазып қойыңыз.'),
  ('2226c745-19bb-4270-8e5c-a438c71816d4', 'Басқа аналар не істейді? 💬', 'Алаңдап жүрсіз бе? Anacan қауымдастығына кіріп, сұрағыңызды қойыңыз. Сеніңіз, барлық ана ұқсас кезеңдерден өтеді.'),
  ('31bb23a0-6713-4c06-9f74-65b7a51a3dd9', 'Жұбатар дауыс 📖', 'Бүгін кешке балаңызға өз даусыңызбен қысқа ғана ертегі оқып беріңіз. Ешқандай құралдың қажеті жоқ, ананың даусы — ең үлкен сиқыр.'),
  ('34253cb9-0e01-47a7-9def-03c3b3e05aba', 'Көңілді ойындар 🎈', 'Жатып алып, аяғымен ауада велосипед теуіп жатқандай қимылдай ма? Бұл — оның жаңа ермегі. Сіз де қосылып, оны қытықтаңыз.'),
  ('4eb27952-4f25-4c0d-8e25-cf21169fe3eb', 'Өзіңізді күтіңіз 🥑', 'Босанғаннан кейінгі кезеңде сүйектер мен тістер осал болуы мүмкін. Тағамыңызға кальций қосуды ұмытпаңыз. Өзіңізге жақсы күтім жасаңыз.'),
  ('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c', 'Бүгін таңертең ештеңеге көңілі толмай ма? ☁️', 'Бөпеңіз қарқынды өсу кезеңінде болуы мүмкін. Оны көбірек құшақтап, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('813f6345-1636-47fd-9a6b-aee16d069800', 'Ұйқы белгілері 🥱', 'Көзін уқалап, есіней бастағанын күтпеңіз. Жанары бір нүктеге қадалған бойда бірден ұйқыға дайындау рәсіміне кірісіңіз.'),
  ('088b061c-e51f-4931-8636-b06152d7eaff', 'Бір нәрсе ойыңызды шатастырды ма? 🤖', 'Форумдарды сағаттап оқығанша, сұрағыңызды Anacan AI-ға қойып, жылдам жауап алыңыз.'),
  ('5e878638-6613-43f0-b734-dd308940758d', 'Тура 4 айға толуына 5 күн! 🎂', 'Егер тортпен суретке түсу дәстүріңіз болса, тортқа тапсырыс беретін дәл уақыт келді.'),
  ('616fd04c-b736-454a-9242-b3c011b0cdc5', 'Сабырыңыз таусылып, қолыңыз талды ма? 👨‍👧', 'Бүгін кешке баланы әкесіне беріп, есікті жабыңыз да, 15 минутты өзіңізге арнаңыз.'),
  ('232de7cd-2ff6-4b62-8cee-002063d545fd', 'Шашылған жұмақ 🌪️', 'Үйдің әр жерінде баланың заттары жатыр ма? Жата берсін. Үйдің шашылып жатқаны Сіздің жаман ана екеніңізді емес, басты басымдығыңыз бөпеңіз екенін көрсетеді.'),
  ('2cbef83d-a5f1-4b69-858b-9d1310e2cac3', 'Үйде отырудан жалықтыңыз ба? ☕', 'Үйде отырудан жалықтыңыз ба? Анаға қолайлы орындардан жақын маңдағы бала арбасымен кіруге ыңғайлы дәмхананы таңдаңыз.'),
  ('ff5950e2-aed4-41ca-bc9a-64a1b039968a', 'Ақылды ертегі уақыты 🪄', 'Ақылды ертегілерде бүгінгі кешке арнап ерекше оқиға құрастырыңыз: бұлттардың үстінде ұйықтайтын батыл бөпе туралы ертегі.'),
  ('37346c6c-3239-4e07-bcc0-24af9be99f3f', 'Сілекей ағатын кезең 🤤', 'Киімінің жағасы санаулы секундта су болып қала ма? Қызыл иегі тіс шығуға біртіндеп дайындалып жатыр. Силикон алжапқыштар — ең жақсы көмекші.'),
  ('86a98c8a-884a-4567-83c1-4d206dccead9', 'Таза ауа — дәрі 🌳', 'Бала қатты мазасызданса, оны бірден таза ауаға алып шығыңыз. Таза ауа — мазасыздықты басудың ең қарапайым әрі тиімді жолы.'),
  ('ae291c04-b5c7-4ff1-937e-2b2b6d502624', 'Біз бір командамыз! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ашық сөйлесіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('5fcfd433-5086-40d6-89d5-0d756fb06e17', 'Музыканың күші 🎶', 'Кешке қарай басталатын себепсіз жылауды баяу ырғақты классикалық музыкамен тоқтатып көріңіз. Көбіне көмектеседі.'),
  ('b4113857-b164-4ab8-b41d-4e516341edad', 'Талпынып жатыр! 🤸‍♂️', 'Етпетінен жатқанда қолдарына сүйеніп, басын көтеруге тырысады. Бұлшықеттері күн сайын нығайып келеді, жарайсың, бөпе!'),
  ('ec61705b-0071-49b5-a6b0-3849dfa461ac', 'Уақытты тоқтату 📸', 'Ол сондай тез өсіп келеді... Әдемі киіндіріп, бөпеңізге фотосессия жасап, осы сәтті мәңгілік естелікке айналдырыңыз.'),
  ('72b166c9-a8f9-4dc5-be7f-5911ccda18ea', 'Күлкісі көбейіп келеді 😂', 'Сіздің әрбір күлкілі қылығыңызға қарқылдап күліп жауап береді. Осы керемет сәтті видеоға түсіруді ұмытпаңыз!'),
  ('968ec1c9-36e5-4127-8374-922149e153dc', 'Ұйқының негізі ⏱️', 'Төртінші айда дұрыс ұйқы режимін қалыптастыру өте маңызды. Түндеріңіз тыныш өтуі үшін күн тәртібін бұзбаңыз.'),
  ('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f', 'Бәрі ойдағыдай ✔️', 'Кейде қолыңыздан ештеңе келмей жатқандай сезінесіз. Бірақ оның таза киіміне, тоқ қарнына қараңызшы. Сіз бәрін керемет атқарып жүрсіз!'),
  ('4f713889-2b51-4db7-8d5d-7ee8676555a4', 'КЕРЕМЕТ 4 АЙ! 🎉', 'Сенесіз бе? Осы ғажайып жолды бірге жүріп келе жатқандарыңызға тура 120 күн болды! Бөпеңізге фотосессия жасап, осы сәтті естелікке айналдырыңыз!'),
  ('8d072236-96cb-4886-b83d-b2d8d6523abb', 'Артыңызға бір көз салыңыз 📈', 'Алғашқы күндердегі қорқыныштарыңызды еске түсіріңіз. Ал енді қаншалықты тәжірибелі ана болғаныңызға қараңыз. Өзіңізді мақтан тұтыңыз!'),
  ('cfb7b283-3b96-44ef-84b8-0eca1ae74852', '4 айдың қуанышын сезініңіз.  🥂', 'Бүгін кешке бөпе ұйықтағаннан кейін жолдасыңызбен бірге ортақ жеңістеріңізді атап өтуді ұмытпаңыз!'),
  ('0fa7eced-c60c-4055-8da1-5df4e54ec1ce', 'Мен сөйлеп жатырмын! 🗣️', '«Ба-ба», «ма-ма» сияқты буындарды айта бастады ма? Даму трекерін ашып, тіл дамуындағы осы үлкен жетістікті белгілеңіз және онымен көбірек сөйлесіңіз.'),
  ('19b9faef-1d59-42d5-bcb0-12290f627a1f', 'Тыныштық сәті ☕', 'Бөлмедегі шашылған заттар ешқайда қашпайды. Бөпе өздігінен ойнап отырғанда, Сіз жай ғана кофеңізді ішіп, бөлменің тыныштығынан ләззат алыңыз.'),
  ('65cb82a7-67e0-48b5-80b8-74e806b2980e', 'Өзіңізге ғана арналған ертегі 🪄', 'Бүгін кешке Ақылды ертегілер бөліміне кіріп, оған арнап ерекше ертегі құрастырыңыз да, оқып беріңіз.'),
  ('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62', 'Етпетінен ұзағырақ жата ма?  🐢', 'Бұлшықеттері күн сайын нығайып келеді. Алдына түрлі түсті ойыншық қойып, бұл үдерісті одан әрі қызықты етіңіз.'),
  ('431c0c7a-2968-4edd-9882-df9a926adf72', 'Сілекей сарқырамасы 🤤', 'Киімінің жағасы жиі сулана бастады ма? Қолыңызда міндетті түрде силикон тіс қасуыш болсын.'),
  ('5817fca0-3cbb-4276-a47d-9383c042597d', 'Децибелді бақылау 🤫', 'Бөпе ұйықтап жатқанда, үйдегі әрбір дыбыстан шошисыз ба? Дыбыс өлшегішті қосып, бөлменің акустикасын тексеріңіз де, оның тыныш ұйқысын сақтаңыз.'),
  ('df219eb3-fe33-48d7-81df-3e2d39df4620', 'Сіздің қолыңыздан көп нәрсе келеді! 💖', 'Айнадағы шаршаған көзіңізге қарап, жымиыңыз. Сіз ешқандай нұсқаулықсыз-ақ бір ғажайыпты өсіріп келесіз!'),
  ('f8c399ff-a31e-4e77-a55d-5aab198bafaa', 'Серуенге шығатын уақыт ⛅', 'Ауа райы мен киім құралын пайдаланып, ауа райына сай ең үйлесімді киім жиынтығын санаулы секундта таңдап, таза ауада серуендеп қайтыңыз.'),
  ('fb3d810e-9135-4194-bb47-9ce9e588d70c', 'Әкенің иығы 👨‍👧', 'Бүгін кешке бөлмеде көтеріп жүру мен газын шығару толығымен әкенің міндетінде.'),
  ('09081d67-84a7-403e-b876-3cc97106eb52', 'Ұстау шебері 🧸', 'Ілулі тұрған ойыншықтарды дәл ұстай бастады ма? Қимыл-қозғалыс дағдылары керемет дамып келеді. Оның бұл талпыныстарын сүйіспеншілікпен бақылап, ынталандырыңыз.'),
  ('15b0ec22-2156-4080-ad64-7a588de85fc5', 'Үй шашылып жатыр деп уайымдамаңыз. 🌪️', 'Сіз үшін ең маңыздысы — мінсіз үй емес, дені сау әрі бақытты бөпе. Өзіңізді еркін сезініңіз.'),
  ('e8181dea-ccff-4ba2-ae33-93fa07ea8c28', 'Сұрағыңыз бар ма? 🤖', 'Ұйқы, тамақтану немесе газ мәселесі ойыңызды шатастырды ма? Форумдарда уақыт жоғалтпай, Anacan AI-ға жазыңыз да, нақты ғылыми жауап алыңыз.'),
  ('0140116f-1e50-4656-93a0-277a1645b1ba', 'Іштегі сезімді шығару 📝', 'Күніңіз ауыр өтті ме? Көңіл күй күнделігіне бойыңыздағы бар шаршауды бүкпесіз жазыңыз.'),
  ('1f632261-0ec6-4f1f-be74-71aaaaf4c706', 'Қорыңыз таусылып бара ма? 🛒', 'Жөргек немесе дымқыл майлық таусылып бара ма? Ұмытып кетпей, Сатып алу тізіміне қосыңыз, сонда жұбайыңыздың телефонына хабарлама барады.'),
  ('f2dc5d57-91a4-45de-b81b-0b2998a8593b', 'Сыңғырлаған күлкі 😂', 'Сіздің еркелеткен қылықтарыңызға дауыстап күліп жауап бере ме? Бұл күлкіні міндетті түрде видеоға түсіріп алыңыз.'),
  ('1c68be5f-505e-4c46-be58-571a7196e98d', 'Тәжірибеңізбен бөлісіңіз 💬', '«Осындай күйде жүрген жалғыз мен бе?» деп ойлайсыз ба? Anacan қауымдастығына қосылып, дәл осындай сезімдерді бастан өткеріп жүрген аналармен сырласыңыз.'),
  ('0ed5ca13-9d93-489b-99e3-a198862dd467', 'Ұйқы регрессиясы ма? 🤖', 'Түнде аяқ астынан жиі ояна бастады ма? Бұл даму секірісі болуы мүмкін. Anacan AI-дан 4-5 айлық кезеңдегі ұйқы регрессиясы туралы ақпарат алыңыз.'),
  ('450e1ee4-0ee2-4568-acc9-22677b87903d', 'Ол маған қарап тұр! 📸', 'Бөлменің қай жерінде болсаңыз да, ол Сізді көзімен қадағалайды.'),
  ('696eaa28-30b3-4a02-87e3-0cd00d185f07', 'Небәрі 10 минут 🛀', 'Бөпеңіз ұйықтап, айнала тып-тыныш болды. Ыдыс жуғыш машинаны босатудың орнына жылы душқа түсіп, 10 минут судың дыбысын тыңдаңыз.'),
  ('27873a53-69de-4c27-a20c-c15256739b9a', 'Біз бір командамыз! 🌟', 'Түнде жиі оянудан шаршадыңыз ба? Әкесін оятуға қысылмаңыз. Бір команда болу — ауыртпалықты сүйіспеншілікпен бөлісу.'),
  ('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, тоңып қалмаңыз. Ауа райы және киім көмекшісі арқылы дала жағдайына ең қолайлы шешімді оңай қабылдаңыз.'),
  ('82b46290-c3d6-4ad5-8d94-600e0311ba33', '«Мені құшақта» деген қылығы 🛋️', 'Қолыңыздан түскісі келмей ме? Бұл еркелік емес, оған Сіздің иісіңіз қажет. Оны бауырыңызға қысып құшақтаңыз, бұл күндер тез өтіп кетеді.'),
  ('132a3a1b-1001-4fec-a775-7883117a6988', 'Күн тәртібі қалай өтіп жатыр? 📈', 'Тамақтануды бақылау және ұйқы таймері арқылы соңғы күндердің статистикасын талдаңыз.'),
  ('61f15500-8617-42e1-b833-c482f6ae935c', 'Ойыншықтарын жерге жиі тастай ма? 🧸', 'Осылайша ол себеп-салдар байланысын үйренеді. Жаңа ойыншықтар үшін Ұсынылатын өнімдерді қарай аласыз.'),
  ('92d9f590-3160-4e15-966d-3ee82f9db1d0', 'Ауызбен зерттеу 🦷', 'Бөпеңіз бәрін, әсіресе өз саусақтарын белсенді түрде тістелей ме? Тіс жаруын бақылау құралы ескерту беріп тұр! Таза тіс қаситын сақиналарды дайындайтын кез келді.'),
  ('02654c5d-e5dc-4168-b20f-e995771e2a24', 'Бірліктің күші 💬', 'Бүгін кешке Anacan қауымдастығына кіріп, бөпелері Сіздікімен бір айда туған аналармен даму үдерісін бөлісіп, талқылаңыз.'),
  ('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3', 'Өзіңізді мақтан тұтыңыз 👏', 'Бөлмеге көз жүгіртіп, осы уақытқа дейін қаншама жолдан өткені­ңізді ойлаңыз. Алғашқы апталардағы қорқыныш енді аналық сенімге ұласты. Сіз кереметсіз!'),
  ('50a6a489-6955-49c4-9f2c-e768f813dd17', 'Аяқ башпайлары аузында 👣', 'Бөпеңіз аяқтарын зерттеп, аузына салуға тырысып жүр! Осы күлкілі әрі керемет даму сәтін міндетті түрде видеоға түсіріп, жақындарыңызға жіберіңіз.'),
  ('4a91e0c3-a4cb-4e5c-b68a-474b7d153369', 'Жөргектерді санауды жалғастырыңыз! 🧷', 'Anacan-да күнделікті жөргек санын белгілеп, бөпеңіздің жеткілікті қоректеніп жүргеніне көз жеткізіңіз.'),
  ('4d4822a8-2d08-4775-b1d8-71202fa22509', 'Анаға арналған қуат 🔋', 'Бөпеңіз емген сайын Сіз де калория жұмсайсыз. Дәл қазір «Пайдалы рецепттер» бөлімінен сүтті көбейтуге көмектесетін жеңіл сорпаның рецептін қолданып көріңіз.'),
  ('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7', 'Бойы мен салмағының өсуін қадағалаймыз! 📏', '«Дамуды бақылау» бөлімінде соңғы көрсеткіштерді жаңартып, бөпеңіздің қалыпты өсу графигіне қарап, мақтаныш сезіміне бөленіңіз.'),
  ('648c9f9b-15f6-49e6-933c-3da395b58c88', 'Табанды талпыныстар 🐢', 'Бөпеңіз етпетінен жатқанда алға жылжуға тырысып, ашулана ма? Ол қазірдің өзінде қозғалғысы келеді! Ойыншықтардың көмегімен оны алға қарай ұмтылуға ынталандырыңыз.'),
  ('4b6ccde7-7cce-4142-8822-fa952592f465', 'Ұйқы белгілері 🥱', 'Көзін уқалап, құлағын тартып жүр ме? Ұйқысы келіп мазасыздануын күтпей, бөлмені бірден қараңғылап, кешкі ұйқы рәсімін бастаңыз.'),
  ('7b3662bc-d715-468b-a32f-326c023ef66e', 'Аударылу чемпионы 🤸‍♂️', 'Шалқасынан етпетіне, етпетінен шалқасына аударылуға тырысып жүр ме? Оны төсекте ешқашан жалғыз қалдырмаңыз және қимыл-қозғалысқа толы осы кезеңнен ләззат алыңыз.'),
  ('0aded6bb-b0fa-4cac-b297-4311bcd7f798', 'Бәріне үлгеруге міндетті емессіз. 🌸', 'Сізге сүйіспеншілікпен қарайтын бөпеңіз үшін Сіз әлемдегі ең мінсіз жансыз.'),
  ('658bd674-cc84-4d51-8a7e-822b9255b9d7', 'Жаңа ертегі әлемі 📖', 'Бүгінгі кешті ерекше өткізейік. Ақылды ертегілерде суасты әлемін зерттеуге аттанған су перісі туралы хикая құрастырып, бөлмені сиқырға бөлеңіз.'),
  ('b8b57297-f4b4-4473-87af-9acfeee74dd3', 'Қарны аш емес, онда неге жылайды? 🧩', 'Не істесеңіз де тынышталмай ма? Болжай бермей, дауысын Жылауды талдау функциясына тыңдатыңыз да, мәселенің неде екенін бірден анықтаңыз.'),
  ('9ce62e84-5124-421b-bdd6-3fa7c590aa1a', 'Жаңа түстер әлемі 👀', 'Енді ол түстерді әлдеқайда қанық әрі анық көреді. Оған қарама-қарсы түстердегі ойыншықтарды көрсетіңіз.'),
  ('b42e7a75-4fab-45bd-89fe-f334b8181757', 'Өзіңізді ұмытпаңыз 🍲', 'Бөпеңіз тойса, енді кезек Сізде. Пайдалы рецептілер арасынан 10 минутта дайын болатын қуатқа толы тіскебасарды таңдап, өзіңізге қамқорлық жасаңыз.'),
  ('cf65b961-f3be-4509-9af3-0b6c17f757e7', 'Әке мен бөпе уақыты 🫂', 'Әкелер де бөпемен дене арқылы жақын байланыс орнатуы керек. Кешке оларды оңаша қалдырыңыз: олар бір-біріне бауыр бассын, ал Сіз демалып алыңыз.'),
  ('903de81c-9443-4b1e-8662-d8cbed1ca54e', 'Тісі қыши бастады! 💧', 'Ол бәрін аузына салғысы келеді. Қауіпсіздік пен даму туралы көбірек білу үшін Блогтарды қарап шығыңыз.'),
  ('9dd94bee-b76e-43ec-94c9-51937e10ad6e', 'Бүгін үй жинамайсыз 🛑', 'Шаршадыңыз ба? Жұбайыңызға айтыңыз. Бүгін үйде тамақ әзірленбейді, үй де жиналмайды. Бүгін — ананың демалыс күні!'),
  ('25015c8c-0ca6-43bc-a465-c8490ee6d808', 'Ол Сізге ғашық! 🥰', 'Емшек еміп немесе тамақ жеп жатып, Сізге көз алмай қарай ма? Ол Сіздің бет-әлпетіңізді зерттеп, Сізге деген сүйіспеншілігін білдіріп жүр!'),
  ('565cbb4c-39dd-4c69-980a-b02d63f6cdb4', 'Бір сәт тынығыңыз 🛋️', 'Қиын күннен кейін сезімдеріңізді Көңіл күй күнделігіне жазып қойыңыз. Ойыңызды қағазға түсіріп, ішіңіздегіні ақтару — ең жақсы тегін психолог екенін ұмытпаңыз.'),
  ('f0338702-1ba5-495b-840d-9ad790085c24', 'Қалтаңыздағы педиатр 🤖', 'Нәжісінің түсі өзгеше ме немесе денесінде ұсақ бөртпе бар ма? Дүрлікпей тұрып Anacan AI-ға жазып, ықтимал негізгі себептерін біліңіз.'),
  ('5996a5e8-c639-4f34-8f02-ccaebf8a96eb', 'Қолдары іске кірісті 👐', 'Екі қолымен бір мезетте үлкен заттарды ұстауға тырыса ма? Бұл әрекетті Даму трекеріне белгілеп, жұмсақ доп беріп тексеріңіз.'),
  ('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee', 'Тоңып тұр ма, әлде ыстықтап кетті ме? ⛅', 'Қалай киіндіру керектігі үнемі қиындық тудыра ма? Ауа райы және киім құралы бөпеге неше қабат киім кигізу керектігін дәл айтып берсін. Басыңызды қатырмаңыз.'),
  ('a1ca42ca-05ed-42dc-af4a-99af31043623', 'Ана дауысының сиқыры 🎶', 'Ешбір қолданба ана әлдиін алмастыра алмайды. Бүгін кешке бөпеңізді бауырыңызға басып, сүйікті әлдиін ақырын айтып беріңіз.'),
  ('1a9e3246-5c48-4c5d-9be8-b35243065267', 'Үйде не таусылды? 🛒', 'Сусабын таусылды ма, әлде балалар майы ма? Ойланып жатудың қажеті жоқ. Сатып алу тізімін толтырыңыз, қалғаны — серігіңіздің міндеті.'),
  ('6e836ffa-475e-446a-bc5a-eddbd0eeeec4', 'Дыбыстарды сүзгіден өткізіңіз 🤫', 'Көшеден келетін дыбыстар терең ұйқыға кедергі келтіреді. Дыбыс өлшегішті тексеріп, қажет болса, фонға ақ шу қосыңыз.'),
  ('e31b222d-5c34-45e3-b291-c3f8c8989d13', 'Әдемі әрі шынайы 💇‍♀️', 'Көйлегіңізде дақ, ал шашыңыз ұйпа-тұйпа болуы мүмкін. Бірақ бөпеңіздің көзінде Сіз — әлемдегі ең сұлу жансыз. Өзіңізді кінәламаңыз.'),
  ('29aebaa9-a1ae-4a00-8854-a771800bf560', 'Аралықтарды реттейміз. 🍼', 'Тамақтану мен сергек жүру уақытын Тамақтануды бақылау құралы арқылы қадағалап, мінсіз күн тәртібін қалыптастырыңыз.'),
  ('3942c763-be60-481b-bb4e-1a53687a8d34', 'Әкенің жанкештілігі 💖', 'Ол да күні бойы жұмыс істеді, бірақ енді әкелік кезек келді. Бөпені қалай абайлап ұйықтатып жатқанын сырттай бақылап, бақытты сәттен ләззат алыңыз.'),
  ('3cd07d9d-076c-4523-8ba1-47b8737d6bbf', 'Мен осындамын! 👀', 'Оны бөлменің бір бұрышынан атымен шақырыңыз. Оның бірден дауыс шыққан жаққа бұрылып, Сізге қарағанын көресіз. Естуі мен зейіні керемет!'),
  ('b0613bc2-510c-4582-8829-fd09f1ed2898', 'Дәмдерге қызыға ма? 🍽️', 'Сіз тамақ ішкен кезде тәрелкеңіз бен аузыңызға мұқият қарай ма? Қатты тағамдарға (қосымша тағамға) қызығушылығы біртіндеп оянып келеді!'),
  ('cd2a678b-9234-4910-9725-95b0b9e3443e', 'Кешкі әдет — ұйқы пойызына билет.🚂', 'Жылы ванна, массаж және бөлмені қараңғылау... Бұл әдетті ешқашан бұзбаңыз.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'Мені көріп тұрсың ба? 🧸', 'Ойыншықтың жартысын көрпенің астына жасырыңыз. Бөпеңіз оны іздеп таба ма? Бұл — зат көзден таса болса да, оның бар екенін түсінуге бағытталған маңызды даму қадамы!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'Серуендеу міндетті ⛅', 'Ауа райы мен киім таңдау құралын тексеріп, бөпеңізді киіндіріңіз де, саябақта кемінде 20 минут серуендеңіз. Бұл Сізге де, оған да өте қажет.'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'Дәрігердей ақылды 🤖', 'Балаңыздың қимыл-қозғалысынан Сізге оғаш көрінетін нәрсе байқадыңыз ба? Интернеттен қорқынышты ақпарат оқығанша, Anacan AI-дан нақты жауап алыңыз.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'Әкеден бесік жыры 👨‍🍼', 'Серіктес режимінде хабарландырулар жұбайыңызға келетіндей етіп баптаңыз. Бүгін бөпеңізді ұйықтату үшін ертегіні ол оқып, бесік жырын да өзі айтсын. Ал Сіз тамашалаңыз.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'Таңғы концерт 🎶', 'Сізге қарап, кеңінен күлімсіреп, түрлі буындарды айтады. Дәл қазір ол бөлмедегі ең керемет таңғы концертін қойып жатыр, мұқият тыңдаңыз!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'Ұйқы режиміне қатысты күмәніңіз бар ма? 🤖', '5-ші айға қарай болатын ұйқы өзгерістері туралы сұрақтарыңызды Anacan қауымдастығына жазып, басқа аналардан қолдау алыңыз.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'Дыбысты бақылау 🤫', 'Төртінші айдың соңында ұйықтап кету кейде қиындайды. Дыбыс өлшегішті қосып, дыбыс деңгейінің шегін тексеріңіз және бөлмені міндетті түрде қараңғылаңыз.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'Сіз ең жақсысыз! 💖', 'Мінсіз адам жоқ, бірақ бөпеңіз үшін ең жақсы ана — дәл Сізсіз.'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'Күнделікті қарбаласта түскі асты жүріп ішпеңіз. 🥑', 'Пайдалы рецептілердің бірін таңдап, оңай салат дайындаңыз да, асықпай отырып, сүйсініп жеңіз.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'Сыңғырлаған күлкі сәті 📸', 'Ол күн сайын жиі күлетін болды! Бөпе фотосессиясын ашып, бүгінгі жағымсыз көңіл күйді сейілтетін көңілді күлкісін суретке түсіріңіз.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'Жұбатарлық ертегі 🪄', 'Ақылды ертегілерде 5-айға қадам басқалы тұрған кішкентай кейіпкер туралы хикая құрып, бөлмені жылы да жайлы атмосфераға бөлеңіз.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', '5-АЙҒА ҚАРАЙ! 🎂', 'Назар аударыңыз! Небәрі 10 күннен кейін үлкен күн – 5-айы толады! Арнайы тортқа тапсырыс беруді немесе мерекенің тұжырымдамасын жоспарлауды ұмытпадыңыз ба? Дайындықты қазірден бастаңыз!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'Балаңыз тынышталмай, ал Сіз қатты шаршадыңыз ба?  🛑', 'Бөпені бесігіне қауіпсіз жатқызып, 5 минутқа басқа бөлмеге шыға тұрыңыз. Сіздің де тынығып, дем алуға құқығыңыз бар.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'Дыбыс анализаторы 😭', 'Бөлмеге оралсаңыз, ол әлі де жылап жатыр. Өзіңізді қажытпаңыз! Дауысын бірден Жылау анализіне тыңдатып, бөпеңіздің қажеттілігін дұрыс анықтаңыз да, оны тыныштандырыңыз.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'Қолын аузынан шығармайды 🦷', 'Бәрін қатты тістелеп жүр ме? Жылы әрі таза маталар оның қызыл иегін тыныштандырады.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'Түнгі қаһармандар 🦸‍♀️', 'Түнде қайта-қайта ояну Сізді әбден қажытатынын білеміз. Көңіл күй күнделігіне шаршағаныңызды жазып, серігіңізден қолдау көрсетуін сұраңыз.'),
  ('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9', 'Қуат жинаңыз 🍲', 'Сіздің деніңіз сау болса, бөпеңіз де сау болады. Пайдалы рецепттердің ішінен күш-қуат беретін дәмді кекс рецептін таңдап, кофемен бірге рақаттанып жеңіз.'),
  ('9ee15fcc-d37a-4d63-9556-1032868e91e8', 'ТОРТҚА ТАПСЫРЫС БЕРДІҢІЗ БЕ? 🎂', 'Небәрі 5 күннен кейін бөпеңіз 5 айға толады! 5 ай тақырыбындағы ерекше тортқа немесе киімге тапсырысыңызды дәл қазір рәсімдеңіз!'),
  ('d25e75e7-0029-43b9-b1e7-c401d6b9ca28', 'Ақылды хикая шебері 🪄', 'Бүгін кешке «Ақылды ертегілерде» бөпеңіздің 5 айға дейін қалай тез өскені туралы ерекше әрі әсерлі хикая құрастырыңыз.'),
  ('6a21d9c4-96ab-4453-9d5f-d8979016e2cc', 'Дербестікке қарай 🤸‍♂️', 'Ол шалқасынан етпетіне еркін аунай ала ма? Бұлшықеттері қарқынды дамып келеді. Еркін қимылдауы үшін оны кілемнің үстіне үнемі жатқызып тұрыңыз.'),
  ('c057830d-8790-40ec-a09d-53a252d3ee15', 'Өзіңізді кінәламаңыз 🛑', 'Бүгін шыдамыңыз таусылып, даусыңызды көтеріп қойдыңыз ба? Өзіңізді жаман сезінбеңіз. Сіз шаршамайтын робот емессіз. Ертең қайтадан байқап көресіз.'),
  ('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a', 'Сіз жалғыз емессіз 💬', 'Anacan қауымдастығындағы 5 айлық бөпесі бар басқа аналардың жазбаларын қарап шығыңыз. Әр үйде дәл сондай қарбалас, ұйқысыздық пен махаббат бар!'),
  ('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5', 'Ұйқы белгілерін өткізіп алмаңыз 🥱', 'Егер бір нүктеге қадалып, бос қарап қалса, істеп жатқаныңызды дереу тоқтатыңыз. Ұйықтайтын қолайлы уақытты өткізіп алмай, оны төсегіне апарыңыз.'),
  ('0ecae509-0e89-4406-80e4-d01161b92754', 'Тіс қышытқыш көмекке келеді 🦷', 'Бәрін тістеуге тырыса ма? Салқындатылған силикон тіс қышытқыштар оның қызыл иегін бірден тыныштандырады.'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'Өзіңізді мақтаңыз 👏', 'Барлық жазбаларыңыз бен даму графиктеріңізге қайта көз жүгіртіңіз. Бөпеңіздің қаншалықты өскенін, ал өзіңіздің қаншалықты тәжірибе жинағаныңызды көріңіз!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'Жеңіс кеші 🪄', 'Бүгін кешке Ақылды ертегілерден махаббатқа толы бір хикаяны қосып, жұбайыңызбен бірге бір команда ретінде жетістігіңізді атап өтіңіз!'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', 'Анаға арналған 10 минут ☕', 'Үйдің шашылғаны ешқайда қашпайды. Бөпеңіз ұйықтағанда бірден іске кіріспеңіз. Өзіңізге ыстық кофе құйып, 10 минут бойы ештеңе істемей, жай ғана тынығыңыз.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'Қолдан қолға ауыстыру 🧸', 'Ойыншықты бір қолынан екінші қолына ауыстыра ала ма? Бұл миының екі жарты шары да тамаша жұмыс істеп тұрғанының белгісі! Даму трекерінде осы маңызды дағдыны белгілеңіз.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'Көңіл күйіңізбен бөлісіңіз 📝', 'Бүгін қатты шаршадыңыз ба, әлде бойыңызда күш-қуат бар ма? Көңіл күй күнделігіне сезімдеріңізді шынайы жазыңыз. Ішіңіздегіні ақтару өзіңізді жақсырақ сезінуге көмектеседі.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'Дыбысталған хикаялар 🪄', 'Бүгін кешке бөлмеге ерекше сиқырлы көңіл күй сыйлайық. Ақылды ертегілерде Айға ұшқан батыл мысық туралы хикая құрып, ұйқыға дайындалу рәсімін қызықты етіңіз.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'Табиғи тыныштандырғыш ⛅', 'Бөпеңіз қатты мазасызданып, үйде отырғысы келмей ме? Ауа райын тексеріп, лайықты киініп, бірден саябаққа шығыңыз. Таза ауа екеуіңіз үшін де ең жақсы ем.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'Қолына түскеннің бәрін аузына сала ма? 🤤', 'Бұл — оның қоршаған әлемді танып-білу тәсілі. Тек айналасындағы заттардың таза әрі қауіпсіз болуына мән беріңіз.'),
  ('60bbb8df-cb46-4930-8422-5f0c6fa7daad', 'Мен Сізді танимын! 🥰', 'Бөлмеге кіргеніңізде, ол Сізге ерекше, қуана әрі өзгеше жымиып қарай ма? Иә, ол Сізді басқалардың бәрінен ажыратады және Сіздің иісіңізді жақсы көреді!'),
  ('adbfecc6-7186-41fe-a870-83cf6809ec00', 'Өзіңізге уақыт бөліңіз 🛋️', 'Бөпе ұйықтағанда үй шаруасына емес, өзіңізге уақыт бөліңіз. Бөлме шашылып жатса да болады, ал Сіздің күш-қуатыңыздың қалпына келуі өте маңызды.'),
  ('ba61a641-e703-4b01-b161-601cf36add7a', 'Табиғаттың сиқыры ⛅', 'Қатты мазасызданып жүр ме? Ешбір ойыншық көмектеспей ме? Ауа райы мен киімін тексеріп, оны дереу таза ауаға алып шығыңыз. Табиғат — ең жақсы тыныштандырушы.'),
  ('e97550d4-794b-4a9e-94da-881338077d81', 'Неге тағы жылап жатыр? 😭', 'Себебін түсіне алмайтын жылау ұстамалары әбден қажытады. Өзіңізді қинамаңыз, Жылауды талдау құралын пайдаланып, оның дауысындағы жасырын хабарды анықтаңыз.'),
  ('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed', 'Аналардың күші 🤖', 'Бөлмеге көз жүгіртіп, осы 5 айға қалай жеткеніңізді мақтан тұтыңыз. Қандай да бір қорқынышыңыз болса, Anacan AI-ға жазып, қолдау алыңыз.'),
  ('792511a4-1d02-4324-a33c-59bacedb4645', 'МЕРЕЙТОЙҒА 1 КҮН ҚАЛДЫ! 🎈', 'Ертең — үлкен күн! 5 ай толуына арналған торт дайын ба, киімдер үтіктелді ме? Бөпе фотосессиясы құралын ашып, сынақ суреттерін қазірден түсіріңіз!'),
  ('af763c83-7a14-4218-b3c2-49cdc7255b18', 'Серігіңізбен сырласыңыз 🥂', 'Бүгін кешке жұбайыңызбен алғашқы күндерді еске алып, бірге күліңіздер. Сіздер үлкен жолдан өттіңіздер!'),
  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', 'ТҰП-ТУРА 5 АЙ! 🎉', 'Неткен ғажап! Сіздер тура 150 күн, толық 5 ай бойы бір команда болып, осы ғажайыпты өсіріп келесіздер. Бөпе фотосессиясы арқылы осы ерекше күнді дәл қазір мәңгілік естелікке айналдырыңыз!'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'Басқа аналар не істеп жүр? 💬', 'Алаңдап жүрсіз бе? Anacan қауымдастығына қосылыңыз. Ондағы аналардың да дәл сондай ұйқысыздық пен қиындықтарды бастан өткеріп жүргенін көру Сізге жұбаныш болады.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'Қор таусылып барады 🛒', 'Жөргек немесе бала майы таусылды ма? Ұсақ-түйекке бас қатырмай, Сатып алу тізіміне жазыңыз — жұбайыңыз келе жатқанда ала келеді.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'Сұрағыңыз бар ма? 🤖', 'Бөпеңіздің дамуына қатысты сансыз сұрағыңыз бар ма? Форумдарды сағаттап оқығанша, Anacan AI-ға жазып, қысқа әрі ғылыми негізделген жауап алыңыз.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'Күнделікті жөргек санын бақылап жүрміз. 🧷', 'Бөпеңіздің жеткілікті тамақтанып жүргеніне көз жеткізу және ас қорыту жүйесінің жұмысын бақылау үшін Anacan-да әр жөргек ауыстыруды белгілеп отырыңыз.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'Бірліктің күші 🛋️', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ашық сөйлесіңіз. Бір-біріңізге қолдау көрсетіп, бір команда екендеріңізді сезіну ауыртпалықты екі есе жеңілдетеді.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'Өзіңізді мақтан тұтыңыз 👏', 'Артқа көз тастап, алғашқы апталарда қаншалықты қорыққаныңызды еске түсіріңіз. Ал қазір бәрін нағыз мамандай басқарып жүрсіз! Сіз кереметсіз!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'Дәмді жаңалықтарға аз қалды! 🥦', 'Қосымша тамаққа көшетін бөпелерге арналған Рецепттер бөліміндегі алғашқы езбе идеяларын оқып, келесі айға дайындалыңыз.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'Қалтаңыздағы педиатр 🤖', 'Ұйқы режимі кенет өзгерді ме? Алаңдамас бұрын Anacan AI-дан 5 айлық кезеңдегі ұйқы регрессиясы туралы ақпарат пен кеңес алыңыз.'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'Жылау коды 😭', 'Таңертеңгі мазасыздық аштықтан ба, әлде тіс жарудан ба? Болжам жасамай-ақ, дыбысын Жылауды талдау функциясына тыңдатып, оған не қажет екенін бірден анықтаңыз.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'Сабырыңыз таусылды ма?  👨‍👧', 'Бүгін кешке баламен толықтай әкесі айналыссын, ал Сіз құлаққабыңызды тағып, демалыңыз.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'Біз бір командамыз! 🌟', 'Өзіңізді жалғыз әрі ешкім түсінбейтіндей сезінесіз бе? Терең тыныс алыңыз. Сіз — осы аласапыран күндердің ең мықты қаһарманысыз және бәрін керемет атқарып жүрсіз.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'Мүлгіген тыныштық 🤫', 'Ұйықтап кету қиындады ма? Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріңіз. Теледидардың дыбысын өшіріп, бөлмені толығымен қараңғылаңыз.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'Қызыл иегі қыши ма? 🦷', 'Саусақтарын үнемі аузына салып, сілекейі көп аға ма? Салқындатылған тіс қаситын ойыншықтарды қолданатын кез келді.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'Өзіңізді ұмытпаңыз 🥑', 'Бөпені тойдырамын деп, өзіңіз аш қалып жүрсіз бе? Пайдалы рецептілер арасынан 10 минутта дайындалатын, қуат беретін тағамды таңдаңыз.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'Түнгі бесік жыры 🎶', 'Ананың дауысындай тыныштандыратын ешбір үн жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, сүйікті бесік жырын ақырын айтып беріңіз.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'Бөлменің іші ойыншыққа толы ма? 🌪️', 'Бөлменің іші ойыншыққа толы ма? Үйіңіз шашылып жатыр деп күйзеліске түспеңіз. Сіз керемет анасыз, Сіз үшін ең маңыздысы — тазалық емес, бөпеңіз.'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'Өздігінен аунау 🤸‍♂️', 'Ол шалқасынан етпетіне еркін аунай ала ма? Бұлшықеттерін еркін қимылдатуы үшін оны кең кілемнің үстіне жатқызыңыз.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'Уақытты тоқтату 📸', 'Ол сондай тез өсіп келеді... Ұйықтап жатқанда бөпеңіздің сүйкімді әрі жайбарақат жүзін фотосессияға түсіріп, естелікке сақтап қойыңыз.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'Түнгі оянуды қалыпты тәртіпке келтіреміз. 😴', 'Ол оянған сайын жарықты жақпаңыз. Anacan таймерімен тамақтандырып, Ақ шу көмегімен қайта ұйықтатыңыз.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'Бүгін үй жинамаймыз 🛑', 'Шаршадыңыз ба? Жұбайыңызға айтыңыз. Бүгін үйде тамақ әзірленбейді, үй де жиналмайды. Бүгін — ананың демалып, кофе ішетін күні!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'Менімен сөйлес! 🗣️', 'Ол Сізді мұқият тыңдап, түрлі дыбыстар шығара ма? Демек, ол Сізбен нағыз диалог құрып жатыр. Дауысына жауап беріп, осы қарым-қатынасты қолдаңыз.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'Отыруға алғашқы талпыныстар 🪑', 'Сүйемелдеп отырғызғанда басы мен арқасын тік ұстай ма? Бұл бұлшықеттерінің нығайып келе жатқанын көрсетеді. Қысқа уақыт сүйемелдеп отырғызу жаттығуларын бастаңыз.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'Төрт қабырғадан бір сәтке қашу ☕', 'Үйде отыра беруден жалықтыңыз ба? Бала арбасымен оңай кіруге болатын жақын жердегі дәмхананы тауып, басқа ортада кофе ішіңіз.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'Ұйқы белгілері 🥱', 'Көзін уқалап, бір нүктеге қадалып отырса, мазасызданып жылағанын күтпеңіз. Дереу бөлмені қараңғылап, ұйқыға дайындау рәсімін бастаңыз.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'Қарны аш па, әлде шаршады ма? 🧩', 'Не істесеңіз де, тынышталмай ма? Бәлкім, ол жай ғана қатты шаршаған болар. Нақты білу үшін Жылауды талдау мүмкіндігін пайдаланып, дауыстың астарындағы себепті анықтаңыз.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'Дыбысты бақылау 🤫', 'Ұйықтап бара жатқанда кенет шыққан дыбыстар оны оятып жібере ме? Дыбыс өлшегіштің көмегімен бөлмедегі шу деңгейін бақылауда ұстаңыз.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'Ананың қуаты 🔋', 'Күн ортасында қуатыңыз таусыла ма? Пайдалы рецептілерден емшек сүтіңіздің молаюына көмектесіп, өзіңізге де сергектік сыйлайтын смузи рецептін қараңыз.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'Музыканың күші 🎶', 'Кешкісін басталатын себепсіз жылауды баяу әуенді классикалық музыкамен немесе ақ шумен басып көріңіз.'),
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, бөпеңізге суық тигізіп алмаңыз. Ауа райы және киім көмекшісі арқылы сырттағы жағдайға сай шешім қабылдаңыз.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'Дәмдерге қызыға ма? 🍽️', 'Сіз тамақ ішкенде, көзі тәрелкеңізден таймай ма? Қатты тағамға дайындық белгілері байқала бастады. Бірақ әзірге асықпаңыз, 6-шы айды күтіңіз.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'Тәжірибе бөлісу 💬', 'Бөпеңіздің жаңа қимылы Сізді таңғалдырды ма? Anacan қауымдастығына кіріп, осы жаңалықты басқа аналармен талқылаңыз.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'Ертегінің шегі жоқ 📖', 'Бүгін кешке Ақылды ертегілерге тамаша тапсырма беріңіз: Кемпірқосақтың үстінде ұйықтап жатқан перінің хикаясы.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'Сіз жеткіліктісіз! 💖', 'Бүгін бәрі ойдағыдай болмады ма? Өзіңізді кінәламаңыз. Сіз робот емессіз ғой. Сезімдеріңізді қабылдап, өзіңізді кешіріңіз де, күлімсіреңіз.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'Жарты жасқа жақындап қалды 📈', 'Сенесіз бе? 6-айдың аяқталуына аз ғана уақыт қалды! Даму күнделігін ашып, осы айға дейін жүріп өткен таңғажайып жолыңызды мақтанышпен шолып шығыңыз.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'Кезекті тапсырыңыз 🛋️', 'Бөпе ұйықтағанда Сіз де жата кетіп, ұйықтағыңыз келсе, үйдегі басқа жұмыстарды серігіңізге тапсырыңыз.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'Ойдың тұмандануын ұмытпаңыз 📝', 'Ұмытшақтық — босанғаннан кейінгі кезеңнің бір бөлігі. Ештеңені ұмытып кетпеу үшін сатып алатын заттар тізімін белсенді қолданыңыз.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'Айнадағы дос 👀', 'Бөпеңізді айнаның алдына апарыңыз. Өз бейнесіне қарап былдырлауы — оның ақыл-ойын дамытуға арналған тамаша әрі қызықты әрекет.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'Командалық әңгіме 🥂', 'Көңіл күй күнделігін ашып, бүгінгі жағымсыз сезімдерді артта қалдырыңыз да, серігіңізбен бір команда болудың рақатын сезініңіз.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'Тіс қышытқыш іздейтін кез 🦷', 'Сілекейі көбейіп, қызыл иегі қыши бастайды. Таза тіс қышытқыш сақиналар енді Сіздің ең жақсы көмекшіңіз болады.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'Мені көріп тұрсың ба? 🧸', 'Ойыншықты көрпенің астына жасырыңыз. Бөпеңіз оны іздеп таба ма? Бұл — зат көзден таса болса да жоғалып кетпейтінін түсінуге көмектесетін керемет даму сәті!'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'Өзіңізді күтіңіз 🛋️', 'Бөпе ұйықтағанда, үй шаруасына емес, өзіңізге уақыт бөліңіз. Бөлме жиналмай қалса да болады, ал Сіздің күш-қуатыңыз қалпына келуі керек.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'Ойыншықтарын жерге тастап, бақылап жүр ме? 🎯', 'Осылайша ол тартылыс күшін және себеп-салдар байланысын зерттейді! Ойыншықты сабырмен қайта беріңіз.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'Сіз жалғыз емессіз 💬', 'Алаңдап жүрсіз бе? Anacan қауымдастығына кіріп, сұрағыңызды қойыңыз. Сеніңіз, барлық аналар осыған ұқсас кезеңдерден өтеді.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'Қосымша тағамға дайындық 🥣', '6-айға да аз қалды. Алғашқы езбелер туралы білгіңіз келе ме? Anacan AI-дан қосымша тағамға көшу туралы негізгі ақпаратты сұраңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776'::uuid, 'Бірліктің күші 🥂', 'Бүгін кешке жұбайыңызбен осы маңызды кезеңге қалай жеткендеріңізді талқылаңыз. Сіздер бір команда болып, керемет жұмыс атқардыңыздар.'),
  ('c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f', 'ЖАРТЫ ЖАСҚА 10 КҮН ҚАЛДЫ! 🎂', 'Дайындалыңыз! Тура 10 күннен кейін бөпеңіз 6 айға, яғни жарты жасқа толады! Жарты жасқа арналған тортқа тапсырыс беріп, ерекше киім таңдайтын дәл уақыт келді!'),
  ('3259939c-e2bd-4126-abc3-d15439051dda', 'Таза ауаның күші 🌳', 'Бөпе қатты мазасызданса, оны бірден таза ауаға алып шығыңыз. Таза ауа — мазасыздықты басудың ең қарапайым әрі тиімді тәсілі.'),
  ('382370f5-d970-4100-b0bc-f8460c0758ae', 'Ұстау шебері 👐', 'Екі қолымен бір уақытта үлкен заттарды ұстауға тырыса ма? Жұмсақ доп беріп, байқап көріңіз.'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'Түннің қаһарманы — әке 🦸‍♂️', 'Алғашқы айлардағы ең жақсы қағида: бесік жырын кезектесіп айту керек! Бүгін кешке бөпе әкесінің құшағында, ал Сіз демаласыз.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'Серуендейтін уақыт 🌳', 'Бөпеңізді арбасына отырғызып, небәрі 15 минутқа болса да таза ауаға шығыңыз. Таза ауа екеуіңізге де қажет.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'Таңғы концерт 🎶', 'Бөпеңіз Сізге қарап, кеңінен күлімсіреп, жаңа дыбыстар шығарып жатыр. Дәл қазір ол бөлмедегі ең керемет концертті қойып жатыр, мұқият тыңдаңыз!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'Ұйқының негізі ⏱️', 'Жылы ванна, массаж және бөлмені қараңғылау... Түндеріңіз тыныш өтуі үшін ұйқыға дайындау тәртібін ешқашан бұзбаңыз.'),
  ('ddef2887-0bec-40c8-91a4-05edb188b86b', 'Дәрігердей ақылды 🤖', 'Интернеттен қорқынышты жаңалықтар оқығанша, қосымша тағамға көшу туралы сұрақтарыңызды Anacan AI-ға қойып, көңіліңізді тыныштандырыңыз.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'Ақылды тыныштық 🤫', 'Бөпеңіз ұйықтап бара жатқанда кенет шыққан дыбыстардан оянып кете ме? Дыбыс өлшегіштің көмегімен бөлмедегі децибел деңгейін бақылаңыз.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'Үйлесімсіз киімдер 👗', 'Бөпеңізді кейде тым жұқа, кейде тым қалың киіндіріп қоясыз ба? Күмәнданбаңыз. Ауа райы мен киімді тексеріп, сенімді түрде киіндіріңіз.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'Анаға арналған ас 🥑', 'Күнделікті қарбаласта түскі асты жүріп жүріп ішпеңіз. Пайдалы рецепттердің бірін таңдап, оңай салат дайындаңыз да, отырып, рақаттанып жеңіз.'),
  ('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df', 'Артық дыбысты азайтыңыз 🤫', 'Көшеден естілетін дыбыстар терең ұйқыға кедергі келтіреді. Дыбыс өлшегішті тексеріп, қажет болса, ақ шуды қолданыңыз.'),
  ('9bb7f096-5daa-4e1c-9f5e-688698945f7a', 'Тістері шығып келе ме? 🦷', 'Астыңғы қызыл иегі ауырып, ісінген бе? Алғашқы тістері 6-айға қарай көріне бастауы мүмкін.'),
  ('2ecd0a8e-2817-4551-98e0-4276739c7da9', 'Біз бір командамыз! 💖', '6 ай бойы ұйқысыз түндерде бір-біріңізге қолдау көрсеттіңіздер. Көңіл күй күнделігін ашып, серігіңізге осы бірлескен еңбегі үшін алғыс айтыңыз.'),
  ('ce877206-0633-48d8-aa8f-9241cfab27c3', 'Қосымша тағамға арналған орындық 🪑', 'Тамақтандыруға арналған орындық сатып алуды ойлап жүрсіз бе? Ұсынылатын өнімдер бөліміндегі эргономикалық әрі оңай тазаланатын орындықтарды қарап шығыңыз.'),
  ('e6e852b1-bfb4-4197-aa7b-70b6b2367f30', 'ЖАРТЫ ЖАСҚА 5 КҮН ҚАЛДЫ! 🎈', 'Жарты жасқа небәрі 5 күн қалды! Тортыңызға тапсырыс беріп қойдыңыз ба? Бөпенің фотосессиясы құралынан 6 айға арналған арнайы жиектемелерді қазірден таңдап, жоспарлаңыз.'),
  ('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd', 'Жаңа ертегі ашайық 📖', 'Бүгінгі кешті ерекше өткізейік. Ақылды ертегілер бөлімінде арнайы хикая құрып, бөлмені сиқырға бөлеңіз.'),
  ('9d58451e-ede3-4a05-ba21-dd4e0b7f4086', 'Күнделікті жөргек көрсеткішін қадағалаймыз. 🧷', 'Қосымша тағамға көшпес бұрын ас қорыту жүйесінің қалыпты жұмыс істеп тұрғанына көз жеткізу үшін Anacan-да жөргекті әр ауыстырғаныңызды белгілеп отырыңыз.'),
  ('edc6faba-a997-408a-a40b-e590a39a3721', 'Мен отыра аламын! 🪑', 'Сүйемелдеп отырғызғанда өзін сенімдірек ұстай ма? Жастықтармен тіреп, отыруға ынталандырыңыз, бірақ қысқа уақытқа ғана.'),
  ('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d', 'Дыбысталған ертегілер 🪄', 'Бүгін кешке Ақылды ертегілерде «Өсіп, 6 айлық болған батыл рыцарь» туралы ертегі құрастырыңыз.'),
  ('0e21a1c5-4a15-41e9-abfe-8342adaebb92', 'Мінсіздік жоқ 🛑', 'Бүгін шыдамыңыз таусылып, ашуланып кеттіңіз бе? Өзіңізді кінәламаңыз. Сезімдеріңізді көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('31e88909-0b90-49e0-8727-857efb6836f3', 'Әкеден бесік жыры 👨‍🍼', 'Серіктес режимінде хабарландырулар жұбыңызға жіберілсін. Бүгін түнде бөпені ұйықтату үшін бесік жырын жұбыңыз айтсын.'),
  ('a24757f2-97fa-405f-9959-e4c715aa8ed8', 'Сізді іздеп жүрмін! 👀', 'Бөлмеден шыққаныңызда, бөпеңіз Сізді көзімен іздеп, жылай ма? Айырылу мазасыздығы біртіндеп басталуы мүмкін. Оған қауіпсіздік сезімін сыйлаңыз.'),
  ('989db48b-e318-47e6-9019-f4f957b60d59', 'Себебін түсіне алмайтын жылау ұстамалары әбден қажытады. 😭', 'Өзіңізді қинамаңыз, Жылауды талдау мүмкіндігін пайдаланып, оның дауысындағы хабарды анықтаңыз.'),
  ('a6d43603-e416-4760-8a3f-176e42bf2dc7', 'Ку-ку — оның сүйікті ойыны! 🙈', 'Бетіңізді қолыңызбен жауып, қайта ашыңыз да, оның қалай қуанатынын тамашалаңыз. Осыған ұқсас басқа ойындар туралы Блогтар бөлімінен біліңіз.'),
  ('a85c19d5-09d8-4302-9d52-6f63acdaebee', 'Түнгі бесік жыры 🎶', 'Ешбір дыбыс ананың дауысындай тыныштандыра алмайды. Бүгін кешке оны кеудеңізге басып, ақырын ән айтыңыз.'),
  ('2fc6e816-81b8-4662-85f5-ea7fd4e748a8', 'Анаға арналған 10 минут ☕', 'Бөлменің шашылып жатқаны ешқайда қашпайды. Бөпеңіз ұйықтағанда бірден үй шаруасына кіріспеңіз. Өзіңізге кофе құйып, 10 минут жай ғана демалыңыз.'),
  ('081951c6-0b7d-4045-b641-a4716f751a3d', 'Әкенің иығы 👨‍👧', 'Шыдам шегіне жеттіңіз бе? Серіктес режимін қосыңыз. Бүгін кешке баламен толықтай әкесі айналыссын.'),
  ('b099b3d8-9148-450c-8795-4ab16ea72b2c', 'Сұрақтарыңыз қалды ма? 🤖', 'Алдымен қай көкөніс езбесінен бастаған дұрыс? – Осы және өзіңізді толғандырған басқа да сұрақтарды Anacan AI-дан сұрап, нақты ақпарат алыңыз.'),
  ('e3aafd70-c5f0-4254-ba79-e24f4dca3567', 'Сілекей сарқырамасы 🤤', 'Киімінің жағасы жиі сулана бастады ма? Силикон тіс қаситын ойыншықтарды дайындап қойыңыз.'),
  ('34eb8ef4-b7a5-4969-916d-abfccb27c775', 'Децибелді бақылау 🤫', 'Бөпе ұйықтап жатқанда үйдегі әрбір дыбыстан қорқасыз ба? Дыбыс өлшегішті қосып, бөлменің акустикасын тексеріңіз.'),
  ('da48ef6d-1a19-4a32-9bdc-d912779edf22', 'Шашылған үй, бақытты бөпе 🌪️', 'Бөлменің іші ойыншыққа толы ма? Тазалықтан гөрі онымен күлімдеп өткізген 10 минутыңыз маңыздырақ.'),
  ('ec6f8334-a2ec-4274-9ce3-07c0a3276622', 'Өздігінен аунау 🤸‍♂️', 'Шалқасынан етпетіне, етпетінен шалқасына аунауды толық меңгерді ме? Бұл жетістікті даму бақылағышына белгілеңіз!'),
  ('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d', 'Ұйқы белгілері 🥱', 'Көзін уқалап жатыр ма? Қатты шаршап, мазасыздануын күтпей, бірден бөлмені қараңғылап, кешкі ұйқы рәсімін бастаңыз.'),
  ('a9165256-d8d7-431e-ac72-e7ef065f4e1f', 'Анаға арналған қуат 🍲', 'Ертеңгі мерейтойға күш-қуат қажет. Пайдалы рецептілер арасынан тойымды тіскебасар таңдап, демалыңыз.'),
  ('febb037e-33e6-4760-bc42-cae9b6c70a8a', 'СОҢҒЫ ДАЙЫНДЫҚТАР! 📸', 'Ертең — үлкен күн! Жарты жасқа арналған торт дайын ба? Бөпенің фотосессиясына ең әдемі киімдерді дайындаңыз, ертең көп суретке түсеміз!'),
  ('1ac47b8c-1167-4ac1-a522-104b832c25b0', 'ТУРА 6 АЙ! ЖАРТЫ ЖАС! 🎉', 'Құттықтаймыз! Осы ғажайып бөпені өсіріп келе жатқаныңызға тура 180 күн болды. Дәл қазір Бөпе фотосессиясында осы ерекше күнге арнап сурет жасап, Anacan қауымдастығында бөлісіңіз!'),
  ('788697fe-7a57-4c4c-a3dc-514298d952ed', 'Өзіңізге қол соғыңыз 👏', 'Барлық жазбаңызды қайта қарап шығыңыз. Бөпеңіздің қаншалықты өскенін, ал өзіңіздің қаншалықты тәжірибелі болғаныңызды көріңіз! Сіздер — тамаша командасыздар.'),
  ('7f7b88ee-089c-4ccc-9849-c2f4117d4833', 'Жеңісті кеш 🥂', 'Бүгін кешке бөпе ұйықтағаннан кейін жұбайыңызбен бетпе-бет отырып әңгімелесіңіз. Осы 180 күнді мақтан тұтып, бір-біріңізді құшақтаңыздар!'),
  ('7d616a8c-c926-4291-9221-42ee50e15fd5', 'Жаңа кезең: Қосымша тағам! 🥣', '6 ай толды! Енді көкөніс езбелерімен танысатын уақыт келді. Аллергияны тексеруге арналған 3 күндік сынақ ережесі туралы Anacan AI-дан ақпарат алыңыз.'),
  ('936424c3-1b30-4fc1-924e-920162d0d5bd', 'Толық тыныштық 🤫', 'Ұйықтау қиындап кетті ме? Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, бөлмені толық қараңғылаңыз.'),
  ('e0613a64-c64f-491d-8c87-72276f72849e', 'Дақ түскен киімдер 👗', 'Қосымша тағам дегеніміз — айналаның бәрі былғанады деген сөз. Бұған ашуланбаңыз, силикон алжапқыштарды қолданыңыз және осы қызықты сәттерден ләззат алыңыз.'),
  ('6dad4f0a-8c98-4797-a95f-50aab81d4662', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, тоңып қалмаңыз. Ауа райы және киім көмекшісі арқылы сырттағы жағдайға сай шешім қабылдаңыз.'),
  ('affd2ecc-89d1-4649-8b63-63dfe9a1ced9', 'Сізді іздеп жүрмін! 👀', 'Сіз бөлмеден шыққан сәтте жылай бастай ма? Айырылу мазасыздығы дәл осы кезеңде қалыптасады. Бөпеңіз Сіз қайтып келмей қоясыз ба деп қорқады. Даусыңызбен оны тыныштандырып, қауіпсіздікте екенін сездіріңіз.'),
  ('c4e8f9e9-c94b-41fc-a23a-61a8c7026386', 'Ас қорыту жүйесіндегі өзгерістер. 🧷', 'Қосымша тағам енгізілгенде бөпеңіздің үлкен дәреті өзгереді. Әр жөргек ауыстыруды Anacan-да белгілеп, жағдайын бақылауда ұстаңыз.'),
  ('3bd59fce-abbd-4e13-ab2d-4379b5c89cac', 'Езбені жемей, аузынан түкіріп тастай ма?', 'Өзіңізді епсіз сезінбеңіз. Бұл бөпеңіз үшін мүлде жаңа тәжірибе, сондықтан сабырлы болыңыз.'),
  ('48005ac4-750b-4fca-b0cd-2711d3eb3c21', 'Дыбысталған ертегілер 🪄', 'Бүгін кешке «Ақылды ертегілерде» ертегі құрастырып, күнді көңілді аяқтаңыз.'),
  ('ae1cbea0-aaaf-49ff-9518-967813809e3b', 'Қызыл иегі қыши ма? 🦷', 'Қосымша тағам беру кезеңінде тіс жаруға байланысты ауырсыну да күшеюі мүмкін. Дәрігердің кеңесімен тіске арналған гель қолданыңыз.'),
  ('4beff801-d69f-40c0-bed1-2e8938edb5f2', 'Басқа аналар не істейді? 💬', 'Бөпеңіз асқабақ езбесін ұнатпай ма? Anacan қауымдастығына қосылып, аналардың тәжірибесімен және түрлі рецептілерімен танысыңыз.'),
  ('7df7f58f-05e6-4afb-aa2c-73438e6504d4', 'Ұйқы белгілері 🥱', 'Көзін уқалап, бір нүктеге қадалып отырса, әбден мазасызданғанын күтпеңіз. Бөлмені бірден қараңғылап, ұйқыға дайындау рәсімін бастаңыз.'),
  ('8afe4995-9e98-44a1-a9cc-5c970d87a396', 'Тірексіз отыру әрекеттері 🪑', 'Жастықтарға бұрынғыдан азырақ сүйене ме? Жақын арада еш тірексіз өздігінен отыратын болады!'),
  ('34c92908-0941-4c15-a946-75240f0ea7f7', 'Көңіл күйіңізбен бөлісіңіз 📝', 'Бүгін қатты шаршадыңыз ба? Көңіл күй күнделігіне сезімдеріңізді шынайы жазыңыз. Ішіңіздегіні ақтарсаңыз, жеңілдеп қаласыз.'),
  ('cd45d0d2-bf31-47be-adf8-84c3b1895339', 'Бір жері ауырып тұр ма, әлде іші кеуіп кетті ме? 😭', 'Қосымша тағамға көшу іш қатуға немесе іштің кебуіне әкелуі мүмкін. Не істесеңіз де тынышталмаса, Жылауды талдау функциясын пайдаланып, дауысының астарындағы себепті анықтаңыз.'),
  ('e67730b8-4981-4bba-b868-fe6cf9b7e3da', 'Азық-түлік таусылып барады 🛒', 'Езбе дайындауға жаңа көкөністер керек пе? Сатып алу тізіміне жазып қойыңыз, жұбайыңыз жұмыстан қайтарда балғын өнімдер ала келсін.'),
  ('1f9cc7dc-a0b4-41a4-983b-794c5917ee08', 'Қолдан қолға ауыстырып зерттеу 🧸', 'Ойыншықты бір қолынан екіншісіне еркін ауыстыра ма? Демек, миының екі жарты шары тамаша үйлесіммен жұмыс істеп жатыр. Оған құрылымы әртүрлі заттар беріңіз.'),
  ('298934a2-9d12-42b8-8c9c-6098d3709ab4', 'Әңгімесі ұзарып келеді! 🗣️', 'Үйдің іші «да-да-да», «ба-ба-ба» деген дыбыстарға толды. Оның тілінің дамуы туралы көбірек білу үшін Блогтар бөліміне кіріңіз.'),
  ('89ff16e6-d11a-4deb-ae4f-1ba03e76271d', 'Түннің қаһарманы — әке 🦸‍♂️', 'Алғашқы айлардағы ең жақсы қағида: бесік жырын кезектесіп айту керек! Бүгін кешке бөпе әкесінің құшағында, ал Сіз демаласыз.'),
  ('6f0575b2-9379-4dca-bf05-d518a93aead1', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Таймер арқылы оң немесе сол емшекпен емізгеніңізді белгілеп қойыңыз, қалғанының бәрін Anacan Сіздің орныңызға есте сақтасын!'),
  ('a134dfa9-2e73-4246-a281-0577e4411534', 'Тағаммен ойнауына рұқсат етіңіз! 🥦', 'Тағамды ұстап, езіп, зерттеуіне мүмкіндік беріңіз. Осы сүйкімді әрі айналаны былғайтын сәттерді Бөпе фотосессиясы арқылы түсіріп, естелікке сақтаңыз!'),
  ('98621899-f977-46d0-ba01-3a49123c5aef', 'Еңбектеуге талпыныс! 🐢', 'Ол етпетінен жатып айнала ма, артқа қарай жылжи ма немесе тізерлеп тұруға тырыса ма? Осындай белсенді даму сәттерін бірден Бөпе альбомына қосыңыз.'),
  ('f5a121b8-a795-4ca6-87d9-f17351b40bec', 'Дамуына қатысты күмәніңіз бар ма? 🤖', 'Бөпем әлі еңбектемейді, бұл қалыпты ма? – осы және басқа да сұрақтарыңызды Anacan AI-ға қойып, маманның жауабын алыңыз.'),
  ('17a57fd8-a4e1-4a40-b13f-cad6191dae2a', 'Жаңа дәмдермен танысу! 🍎', 'Бүгін қандай жеміс немесе көкөніс беріп көресіз? Жаңа идеялар алу үшін қосымша тамақ жей бастаған бөпелерге арналған Рецепттерді міндетті түрде қарап шығыңыз.'),
  ('b98f5eb2-8b81-4c72-8526-61cc728e9e49', 'Ертегі ешқашан аяқталмайды 📖', 'Бүгін кешке Ақылды ертегілерде батыл әрі ақылды бала туралы хикая құрастырыңыз.'),
  ('baf623af-022a-4483-b233-e77e915f194b', 'Нағыз тамақсау 🥣', 'Езбені сүйсініп жей бастады ма? Ол өсіп келеді!'),
  ('0ced9920-5225-4ffc-81ba-de83e31f1bd2', 'Таңғы концерт 🎶', 'Сізге қарап, түрлі буындарды ойдан шығарып айтады. Дәл қазір ол бөлмедегі ең керемет таңғы концертін қойып жатыр, мұқият тыңдаңыз!'),
  ('db243270-0483-44d0-9aef-b63565c06a9e', 'Дәрігердей ақылды 🤖', 'Қатты тағамға көшкеннен кейін нәжісі өзгерді ме? Уайымдай бермей, мұның қалыпты-қалыпты еместігін Anacan AI-дан сұраңыз.'),
  ('f06a8dcb-51df-4b58-a9ac-01e5154e736a', 'Ұйқының негізі ⏱️', 'Жылы ванна, массаж және бөлмені қараңғылау... Түндеріңіз тыныш өтуі үшін ұйқыға дайындық тәртібін ешқашан бұзбаңыз.'),
  ('d9470e5a-6317-45d8-9bd1-419a7827e3e6', 'Түнгі оянуды қалыпты тәртіпке келтіреміз. 😴', 'Бөпе оянған сайын жарықты жақпаңыз. Anacan таймерімен тамақтандырып, Ақ шудың көмегімен қайта ұйықтатыңыз.'),
  ('07efb31a-2639-41f8-b1c7-f3807d010a8f', 'Уақытты тоқтату 📸', 'Ол сондай тез өсіп келеді... Ұйықтап жатқанда оның сондай сүйкімді, тыныш жүзін Бөпе фотосессиясы арқылы суретке түсіріп, естелікке сақтаңыз.'),
  ('7deb7b07-a963-4605-b27c-7714e980157d', 'Сұрағыңыз бар ма? 🤖', 'Қосымша тағам мен су беру туралы ойыңызда мыңдаған сұрақ бар ма? Anacan AI-ға жазып, педиатрдың нақты кеңестерін алыңыз.'),
  ('ab8df92e-4241-44fb-8ac7-10559ea60a6f', 'Мен Сізді танимын! 🥰', 'Үйге бейтаныс адам келгенде Сізге тығыла ма? Алаңдамаңыз, ол жақын адамдарын бөтендерден ажырата алады. Бұл — психикалық дамудың қалыпты белгісі.'),
  ('5378180a-aa43-4728-9384-08bbcf8838ee', 'Менімен сөйлесіңіз! 🗣️', '«Ба-ба», «ма-ма» сияқты буындарды анық айта бастады ма? Оның дауысына жауап беріп, осылай қарым-қатынас жасауын қолдаңыз.'),
  ('a4be80bb-cd06-42ba-b875-78d5a32af3ba', 'Отбасылық әңгіме 🛋️', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ашық сөйлесіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('efa880a4-37d0-4521-93db-df2495a01243', 'Өзіңізді мақтан тұтыңыз 👏', 'Өткенге көз жүгіртіп, алғашқы апталарда қаншалықты қорыққаныңызды еске түсіріңіз. Ал қазір Сіз пюре дайындаудың нағыз шебері атандыңыз!'),
  ('5be2b9be-dabd-44b8-93f3-30aaaab56ccf', 'Түнгі бесік жыры 🎶', 'Ешбір дыбыс ананың даусындай тыныштандыра алмайды. Бүгін кешке оны жай ғана кеудеңізге басып, ақырын ән айтыңыз.'),
  ('c2924eec-8b24-41b0-b28a-f63497f548c2', 'Тәжірибе бөлісу 💬', 'Қосымша тамақ рецептерін іздеп жүрсіз бе? Пайдалы рецепттер бөліміне кіріп, қажетіңізге жаратыңыз.'),
  ('2d910805-1ce0-44fc-88f6-f3f6dfe16cea', 'Еңбектеуге талпынысы артып келеді! 🐢', 'Бөпеңіз етпетінен жатып артқа қарай жылжи ма немесе тізерлеп тұруға тырыса ма? Осы белсенді даму сәттерін Бөпе альбомында мәңгілікке сақтаңыз.'),
  ('8f5769c4-aeb4-4cd1-acf0-052c7e0df753', 'Ақылды ертегі уақыты 🪄', 'Ақылды ертегілер бөлімінде бүгінгі кешке арналған ерекше хикая құрастырыңыз.'),
  ('f175db80-862d-40e7-9aed-5b0a0c4423e3', 'Су ішу әдетін қалыптастырамыз. 💧', 'Қосымша тамақпен бірге су ұсынуды ұмытпаңыз.'),
  ('14f79c92-38f1-4965-a9d0-fbcb8e236840', 'Сілекей ағатын кезең 🤤', 'Киімінің жағасы санаулы секундта су болып қала ма? Қызыл иегі тіс жаруға дайындалып жатыр. Силикон алжапқыштарды қолданыңыз.'),
  ('173f7149-2567-449f-9693-a462d1148849', 'Біз бір командамыз! 💖', 'Қиын күннен кейін жұбыңызбен бетпе-бет отырып, ашық сөйлесіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('1af66eec-0d7d-4dcd-9326-d4155d237a55', 'Бөтен адамдардан қорқу басталды ма? 🙈', 'Сізді көрмегенде немесе бөтен адамды көргенде жыласа, бұл — дамудың бір бөлігі. Осы мәселе бойынша Anacan AI-дан кеңес алыңыз.'),
  ('23068177-6d18-4649-91f5-5ac9ecb37933', 'Жылдам жауаптар 🤖', 'Бір нәрсе Сізді мазалап жүр ме? Форумдарды сағаттап оқығанша, сұрағыңызды Anacan AI-ға қойып, жылдам жауап алыңыз.'),
  ('0e6fe355-3307-4562-8e24-f479625f3ff6', 'Таза ауа екеуіңізге де пайдалы. 🌳', 'Ең жақын саябақты таңдап, күніңізді көңілді өткізіңіз.'),
  ('4085929a-ec71-4c5c-a693-62bb796910ba', 'Киім таңдаудағы қайшылықтар 👗', 'Кейде тым жеңіл, кейде тым жылы киіндіресіз бе? Күмәнданбаңыз. Ауа райы мен киімін тексеріп, бөпеңізді сенімді түрде киіндіріңіз.'),
  ('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba', 'Ақылды тыныштық 🤫', 'Ұйықтап жатқанда кенет шыққан дыбыстар оны оята ма? Дыбыс өлшегіш арқылы бөлмедегі децибел деңгейін бақылаңыз.'),
  ('3e7220fc-a665-4ed2-8b95-f202d84e92a8', 'Өзім ұстаймын! 🧸', 'Ілулі тұрған ойыншықтарға дәл қол соза ма? Көз бен қол үйлесімі жақсарып келеді. Түрлі түсті заттармен оны ынталандырыңыз.'),
  ('747238a1-853b-4e40-a51e-30b2b6d818ac', 'Өзіңізді кінәламаңыз 💖', 'Балаңызға аз уақыт бөлемін деп ойлайсыз ба? Көңілді әрі сапалы өткізілген 10 минут күйзеліске толы 1 сағаттан әлдеқайда құнды.'),
  ('a8ca5021-abaf-413e-abe5-95d715e5127d', 'Терең ұйқыға дайындық 🛀', 'Жылы ванна, жұмсақ массаж және бөлмені қараңғылау... Ұйқы тәртібі — алтын ереже.'),
  ('19aba970-f2bf-4842-9b69-4aed1781aeec', 'Төмен қараңыз! 👣', 'Ол аяқ башпайларын тауып, аузына сала бастады! Осы қызықты сәтті міндетті түрде тамашалап, оның дамуының әр кезеңінен ләззат алыңыз.'),
  ('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d', 'Ана сүті әлі де негізгі тағам! 🍼', 'Қосымша тағам енгізілсе де, тамақтану таймерін қосып, оның күнделікті сүт қажеттілігі өтелетініне көз жеткізіңіз.'),
  ('52b2efdc-0a49-4bfa-8a7e-21a3342254cb', 'Талпынып жүр! 🤸‍♂️', 'Етпетінен жатқанда алға қарай жылжуға тырысады. Бұлшықеттері күн сайын нығайып келеді, алдына ойыншық қойып, ынталандырыңыз.'),
  ('97716c97-1bb3-4784-acfc-a5f0354d1864', 'Музыканың күші 🎶', 'Кешке қарай басталатын себепсіз жылауын баяу ырғақты классикалық музыкамен басып көріңіз.'),
  ('21fef948-0fab-41a2-932d-5efc89cc4b78', 'Ұйқының негізі ⏱️', 'Дұрыс ұйқы режимін қалыптастыру өте маңызды. Түндеріңіз тыныш өтуі үшін күнделікті тәртіпті бұзбаңыз.'),
  ('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352', '200 КҮНГЕ 1 КҮН ҚАЛДЫ! 🎂', 'Ертең бөпеңізге 200 күн толады! Осы үлкен әрі тамаша межені қалай атап өтетініңізді ойладыңыз ба? Дайындықты бастаңыз!'),
  ('76b44761-7bef-4f9c-b984-97e78f4d78cb', 'Бәрі ойдағыдай ✔️', 'Кейде қолыңыздан ештеңе келмей жатқандай сезінесіз. Бірақ оның таза киіміне, тоқ қарнына қараңызшы. Сіз бәрін керемет атқарып жүрсіз!'),
  ('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2', 'Артқа бұрылып қараңыз 📈', 'Алғашқы күндердегі қорқыныштарыңызды еске түсіріңіз. Ал енді қосымша тағам беруді меңгерген тәжірибелі анаға айналғаныңызға қараңыз. Өзіңізді мақтан тұтыңыз!'),
  ('87133947-89a5-414b-a6d4-637285ff301e', 'КЕРЕМЕТ 200 КҮН! 🎉', 'Сене аласыз ба? Осы ғажайып жолды бірге жүріп келе жатқандарыңызға тура 200 күн болды! Бөпеңіздің фотосессиясында арнайы стикермен осы сәтті мерекеге айналдырып, Қауымдастықта бөлісіңіз!'),
  ('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169', '200 күннің мақтанышын сезініңіз. 🥂', 'Бүгін кешке бөпеңіз ұйықтаған соң, жұбайыңызбен бірге осы үлкен командалық жеңістеріңізді атап өтуді ұмытпаңыз!'),
  ('05e938a0-adb4-413b-992b-19bbd78f0925', 'МЕРЕЙТОЙҒА ДАЙЫНДЫҚ! 🎂', 'Небәрі 9 күннен кейін бөпеңіз 7 айға толады! Осы айға ерекше безендіру немесе арнайы торт ойластырдыңыз ба? Соңғы күнге қалдырмас үшін дайындықты қазірден бастаңыз.'),
  ('9c5c6958-af17-4420-aa80-95cd295c8995', 'Қолдары еркін 👐', 'Етпетінен жатқанда бір қолымен ойыншыққа ұмтылып, екінші қолына сүйене ме? Бұлшықеттерінің тепе-теңдігі жетіліп келеді!'),
  ('acd2495b-eae5-4005-8f31-3fdfdc4738aa', 'Әкенің кезегі 👨‍👧', 'Бүгін ана ретіндегі міндетіңізді аз уақытқа жұбайыңызға тапсырыңыз. Олар ойнай берсін, ал Сіз аяғыңызды созып, жай ғана демалыңыз.'),
  ('094a764e-f3f1-4dd1-8a87-04126b16323f', 'Өзіңізді ұмытпаңыз 🍲', 'Бөпеңіз езбесін жеді, ал Сіз ше? Күш-қуатыңызды қалпына келтіру үшін құнарлы тамақтануыңыз керек. Бүгін өзіңізге тойымды асқа тапсырыс беріңіз.'),
  ('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6', 'Мен сені танимын 👀', 'Үйге қонақ келгенде Сізге жабысып, оларға тосырқай қарай ма? Бұл — ажырау мазасыздығының басталуы. Бөпеңіз өзін анасының жанында ғана қауіпсіз сезінеді, мұны түсіністікпен қабылдаңыз.'),
  ('740c028d-4797-4507-a894-816747e5301d', 'Өзіңізге арналған ерекше ертегі 🪄', 'Бүгін кешке Ақылды ертегілер құралына сүйкімді бір тақырып ұсыныңыз: “Аспаннан түскен ең сүйкімді жұлдыздың хикаясы”. Бөлмеде тек осы ертегінің үні естілсін.'),
  ('21f7df85-0fd1-4e90-a27b-52045487116f', 'Түнде ояну 🌙', 'Тісі шығар алдында түнде жиі ояна бастады ма? Сабырлы болыңыз, қызыл иегінің ауырсынуы оны мазалап жүр. Жанында екеніңізді сездіріңіз.'),
  ('3ad2c870-178d-449f-aabd-6c01acacefd8', 'Еңбектеуге талпыныс 🐢', 'Тізерлеп тұрып, алға-артқа тербеле ме? Ол еңбектеуге дайындалып жүр!'),
  ('8ee71700-bb17-4782-940b-c0fc02328f1a', 'Нәжістің түсі өзгерді ме? 💩', 'Қосымша тағамға көшкен кезде нәжістің әртүрлі түсті болуы қалыпты. Бірақ алаңдап жүрсеңіз, оның себебін Anacan AI-дан біліңіз.'),
  ('9240cd01-c58e-42aa-be44-a4d2ac461bc2', 'Қалжырау — қалыпты жағдай 🔋', 'Шыдам таусылғанда өзіңізді жаман ана сезінбеңіз. Бұлай шаршау — табиғи нәрсе.'),
  ('1175cce8-f8b8-4dcc-a8b2-c864d9349ad6', '7 АЙҒА 3 КҮН ҒАНА ҚАЛДЫ! 🎂', 'Тортқа тапсырыс беріп қойдыңыз ба? Киімдер таңдалды ма? 7 ай толуына аз ғана уақыт қалды. Осы тамаша күнді үйде шағын фотосессия өткізіп атап өтуді жоспарлаңыз!'),
  ('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf', 'Айнадағы дос 👀', 'Бөпеңізді айнаның алдына апарыңыз. Оның өз бейнесіне таңдана қарап, күлгенін тамашалау — керемет әрі тыныштандыратын әрекет.'),
  ('f998fac0-0a6b-42d2-b200-7a956f147c9a', 'Әкенің кезегі 👨‍🍼', 'Бүгін кешке баланы шомылдырып, ұйқыға дайындау — әкесінің міндеті.'),
  ('06cfdff1-da31-4945-b562-a0c104f43d15', 'Сізді естіп тұрмын 🗣️', 'Бөпеңіз Сізді мұқият тыңдап, ұқсас буындарды (ма-ма, ба-ба) айтуға тырыса ма? Ол Сізбен сөйлесіп жатыр! Оған күлімсіреп, жиі жауап беріңіз.'),
  ('83caf542-3e86-4833-b9bd-0befb15b04d7', 'Серуендейтін уақыт 🌳', 'Бөпеңізді арбасына отырғызып, 20 минут таза ауада серуендеп қайтыңыз. Бұл екеуіңізге де жақсы әсер етеді.'),
  ('fca627d6-9c72-4d82-999a-3b13347100cd', 'Түн қаһарманы 🦸‍♂️', 'Түнде жиі оянудан шаршадыңыз ба? Әкесін оятудан тартынбаңыз. Бір команда болу — жауапкершілікті тең бөлісу деген сөз.'),
  ('4335b974-a43c-4ba3-b369-2006056301ed', 'Тіреусіз отыру 🪑', 'Жастықтарға сүйенбей-ақ, аз уақыт болса да тік отыра ала ма? Құлап қалмауын қадағалап, бұлшықеттерінің дамуын мұқият бақылаңыз.'),
  ('5bc047d7-1539-47af-a21f-c1df4aa3461d', 'Түскі асты жүріп бара жатып, асығыс ішпеңіз. 🥑', 'Өзіңізге дәмді салат дайындап, 15 минутты тек өзіңізге арнаңыз.'),
  ('8d02cce6-aec5-439c-aadf-52670f1abd08', 'Терең ұйқыға дайындық 🛀', 'Жылы ванна, жұмсақ массаж және бөлмені қараңғылау... Ұйқыға дайындық тәртібін сақтау — түні бойы үздіксіз ұйықтаудың құпиясы.'),
  ('347526cf-7568-4464-ab1e-f2a4e4f4b799', 'ТУРА 7 АЙ! 🎉', 'Неткен ғажап! Сіздер бір команда болып, осы кереметті өсіріп келе жатқандарыңызға тура 7 ай болды. Дәл қазір «Бөпе фотосессиясында» осы күнді мәңгі есте қалдырып, Қауымдастықта бөлісіңіз!'),
  ('a649650d-baa3-4dab-9158-780252d27ef4', 'Тамаша күннің соңы. ✨', 'Сіз өте мықты анасыз! Көңіл күй күнделігіне өзіңізді мақтан тұтатыныңызды жазып, Ақ шулармен тынышталып, жайлы ұйықтаңыз.'),
  ('f5e18de7-aba2-4bda-84e9-b3a568ce950b', 'Өткенге көз жүгіртіңіз 📈', 'Алғашқы күндердегі тәжірибесіз кезіңізді еске түсіріңіз. Ал енді қаншалықты тәжірибелі ана болғаныңызға қараңыз. Өзіңізді мақтан тұтыңыз!'),
  ('4650c8e1-3011-45f0-9997-0c6decd79a65', 'Тізім — таптырмас көмекші 🛒', 'Күнделікті қарбаласта бір нәрсені ұмытып кеттіңіз бе? Ойыңызды шаршатпай, үйге қажет заттардың бәрін Сатып алу тізіміне жазыңыз.'),
  ('8c057f2d-32f2-4561-9ca5-5bc651edddcc', 'Ас қорыту үдерісін бақылаймыз. 🧷', 'Қою тағамдар нәжістің өзгеруіне әсер етеді. Әр жөргек ауыстырған кезді Anacan-да белгілеп, бөпеңіздің жаңа тағамдарға реакциясын талдаңыз.'),
  ('b80481ba-8798-458c-83d8-f359b3802548', 'Тыныштық сәті ☕', 'Бөлменің шашылып жатқаны ешқайда қашпайды. Бөпе өздігінен ойнап отырғанда, бірден үй жинауға асықпаңыз. Диванға отырып, 10 минут ештеңе істемеңіз.'),
  ('104420b5-a415-4abb-81d8-7f7b520d18bd', 'Ауыздағы жаңалықтар 🦷', 'Бөпеңіз бәрін қатты шайнап, сілекейі ағып жүр ме? Тіс шығуын бақылау құралымен үдерісті қадағалаңыз. Салқындатқыш тіс сақиналары осындай күндері нағыз көмекші болады.'),
  ('c9c8946d-7797-4bd6-8476-9f649f770a6e', 'Біз бір командамыз! 💪', 'Өзіңізді жалғыз әрі шаршаңқы сезінесіз бе? Терең тыныс алыңыз. Сіз бен жұбайыңыз — осы аласапыран күндердің ең мықты қаһармандарысыздар.'),
  ('f8790842-2782-419a-aaaa-3c8c1fc497de', 'Ауа райы және киім ⛅', 'Сыртқа шығарда бөпеңізге не кигізетініңізді ойлап қиналмаңыз. Ауа райы және киім құралын қарап, бірнеше секундта үйлесімді киім үлгісін таңдаңыз да, таза ауаға шығыңыз.'),
  ('125f59de-0644-435e-8593-de05b7cc7065', 'Әуезді әлди 🎶', 'Ешбір қолданба ана әлдиінің орнын баса алмайды. Бүгін кешке бөпеңізді бауырыңызға басып, оның ең жақсы көретін әлдиін жай ғана ақырын айтып беріңіз.'),
  ('63093c63-3ea0-4bb2-90bb-318617d51b7e', 'Езбе фестивалі 🥣', 'Беті, мұрны, тіпті шашы да тамаққа былғанып қалды ма? Ашуланудың орнына осы сүйкімді сәтті Бөпе фотосессиясы арқылы мәңгілік естелікке айналдырыңыз.'),
  ('9ff73499-a2bd-41b7-96fa-1ec2d780279f', 'Өзіңізді кінәламаңыз 💖', 'Бөпеңізге аз уақыт бөліп жүрмін немесе үй шаруасына үлгермеймін деп ойлайсыз ба? Өзіңізді жазғыруды доғарыңыз. Сіз бәрін тамаша атқарып жүрсіз.'),
  ('5cafdda5-c60b-4328-9530-450093ed8026', 'Мүлгіген тыныштық 🤫', 'Бөпеңіздің ұйықтауы қиындап жүр ме? Бөлмені толық қараңғылап, дыбысты өшіріңіз. Қараңғылық пен тыныштық — оның тәтті ұйқысының ең жақсы серігі.'),
  ('9fc39323-52a1-4045-aa65-bf5c16fac78f', 'Қарны ашты ма, әлде шаршады ма? 😭', 'Себепсіз жылап, дауысы әдеттегіден өзгеше естіле ме? Алаңдамаңыз. Дауысын бірден Жылауды талдау функциясына тыңдатып, мәселенің себебін анықтаңыз.'),
  ('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6', 'Үйдегі қауіпсіздік шаралары! 🛡', '️ Ол қозғала бастаған сайын қауіп те арта түседі. Балаларға арналған құлыптар мен бұрыш қорғағыштарын Ұсынылатын өнімдер тізімінен қараңыз.'),
  ('a0d08200-8263-43d9-90a3-313dda8dadc9', 'Қолмен ұстап жейтін тағамдарға көшу? 🥦', 'Ол тамақты өзі ұстап жегісі келе ме? Қауіпсіз нұсқаларды таңдау үшін Қосымша тағамды бастаған бөпелерге арналған рецепттерді қараңыз.'),
  ('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96', 'Еңбектеуге арналған жаттығулар! 🐢', 'Ол етпетінен жатып артқа қарай жылжи ма немесе тізерлеп тұруға тырыса ма? Еңбектеу дағдысын дамытуға көмектесетін пайдалы жаттығулар туралы Anacan AI-дан сұраңыз.'),
  ('52134c06-b272-4f5f-93b6-cf014fc0e867', 'Ана сүті әлі де негізгі тағам! 🍼', 'Қосымша тағам берілсе де, тамақтандыру таймерін қосып, бөпеңіздің күнделікті сүт қажеттілігі өтелетініне көз жеткізіңіз.'),
  ('62cb9c93-e0de-4d15-8d33-e81c1723d1db', 'Аналарға арналған қуат көзі! 🥗', 'Сіздің де дұрыс тамақтануыңыз өте маңызды! Пайдалы рецепттердің ішінен күш-қуатыңызды арттыратын дәруменге бай салат немесе смузи дайындаңыз.'),
  ('f25f7637-e945-4232-a1c1-f7594c81a0b3', 'Жұбатар дауыс 📖', 'Бүгін кешке балаңызға өз даусыңызбен қысқа ғана ертегі оқып беріңіз. Анасының даусы — бала үшін ең сүйікті әуен.'),
  ('2a37fc3a-8b98-420a-99ba-c491a8c0f435', 'Ұйқы белгілері 🥱', 'Көзін уқалап, есіней бастағанын күтпеңіз. Көзқарасы бір нүктеге қадала бастаған сәтте бірден ұйқыға дайындау рәсіміне көшіңіз.'),
  ('74e14338-c8e1-4b5c-b426-24332f30b919', 'Анаға арналған 10 минут ☕', 'Бөпе ұйықтай салысымен үй шаруасына асықпаңыз. Диванға отырып, кофеңізді ішіңіз де, 10 минут бойы жай ғана қабырғаға қарап, терең тыныстаңыз.'),
  ('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f', 'Мазасыз таңдар ☁️', 'Бүгін таңертең бөпеңізге ештеңе ұнамай жатыр ма? Бұған тісінің шығуы немесе даму секірісі себеп болуы мүмкін. Оны көбірек құшақтап, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('6ac03f7c-34a8-46f5-96a4-c1aa521476a5', 'Заттың тұрақтылығын түсінуге арналған ойын! 🧸', 'Ойыншығын көрпенің астына жасырып, оны тауып алуына мүмкіндік беріңіз. Осы танымдық ойынды ойнаған кезде, Бөпе фотосессиясы арқылы оның қуанышты сәтін түсіріп алыңыз.'),
  ('746b1115-b7ff-4fd7-b04a-46935d1a6f43', 'Үйдің іші бөпе заттарына толып кетті ме? 🌪️', 'Үйдің іші бөпе заттарына толып кетті ме? Ештеңе етпейді. Үйдің шашылып жатуы Сіздің жаман ана екеніңізді емес, басты назарыңыз бөпеңізде екенін көрсетеді.'),
  ('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292', 'Мазасыздыққа қарсы дыбыс терапиясы. 🎶', 'Егер бүгін кешке бөпеңіз жаңа дағдыларды меңгергендегі толқудан ұйықтай алмаса, Ақ шу бөлімінен ана құрсағындағы дыбысты қосыңыз.'),
  ('5b09b018-664d-4b58-86b9-31b6e1d3baf2', '«Ол менікі!» деген қырсықтық 🛑', 'Қолынан қауіпті затты алған кезде ашулана ма? Тыйым сала берудің орнына, назарын дыбысы қаттырақ әрі түрлі түсті басқа ойыншыққа аударып, осындай шағын дағдарыстарды жеңіл өткізіңіз.'),
  ('698ffa60-da73-4003-9656-db865993d1b5', 'Табақтағы өнер туындысы 🥦', 'Бөпеңіз езбені жемей ме? Кейде мәселе дәмінде емес, сыртқы көрінісінде болады. Пайдалы рецепттерді қолданып, түрлі түсті көкөністерден көңілді бет-бейнелер жасап, тәбетін ашыңыз.'),
  ('eec20c49-b219-4211-8916-1e602a8ceafb', 'Сезімтал ұйқы 🤫', 'Ұйықтай салысымен ең кішкентай тықырдан селк ете ме? Дыбыс өлшегішпен бөлменің акустикасын тексеріп, терезеден келетін дыбыстарды бәсеңдету үшін ақ шуды қосыңыз.'),
  ('a2641bfd-0346-425a-86be-0a5a6822a3d8', 'Әкенің дауыс ырғағы 📖', 'Бүгін кешке бөлмеде өзгеше атмосфера қалыптастырайық. Ақылды ертегілерде батыл орман тұрғыны туралы хикая құрастырып, оны әкесінің қоңыр әрі сенімді дауысымен оқуды тапсырыңыз.'),
  ('ba28583a-a3f1-40f6-9657-b7b38af17c60', 'Төрт қабырғадан тысқа ☕', 'Үйдегі күнделікті күйбең Сізді жалықтыра бастады. Бүгін бір өзгеріс жасаңыз. Жақын маңнан бөпе арбасымен кіруге ыңғайлы дәмхана таңдап, кофеден ләззат алыңыз.'),
  ('ea94213c-026e-4de0-be12-a192e4d22b19', 'Бөпеңіз күн сайын дамып келеді🤏', 'Едендегі ең кішкентай дақты немесе қиқымды бас бармағы мен сұқ саусағымен ұстауға тырыса ма? Ұсақ моторикасы керемет дамып келеді!'),
  ('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911', 'Жиһазға өрмелеу 🧗‍♂️', 'Диваннан немесе орындықтан ұстап, өзін жоғары тартуға тырыса ма? Аяқ бұлшықеттері өз бетінше тұруға дайындалып жатыр. Қауіпсіздігін қадағалаңыз, бірақ кішкентай альпинистің бұл талпыныстарына кедергі жасамаңыз.'),
  ('82e71311-374a-4306-bcfc-4f69bc54da1b', 'Түнгі дауыл 😭', 'Түн ортасында еш себепсіз жылап оянды ма? Жылауды талдау арқылы себебін анықтап, оны тыныштандырыңыз.'),
  ('c7aadd23-e889-42f2-a761-3f955cb9600f', 'Миыңызды шаршатпаңыз 🛒', 'Ұйқының қанбауы есте сақтау қабілетіңізді нашарлатып, дүкеннен не алу керегін ұмытып жүрсіз бе? Бәрін Сатып алу тізіміне жазып қойыңыз, жұбайыңыз келе жатқанда алып келсін.'),
  ('4d7eb303-e249-46ed-8460-db2f0a519240', 'Табиғат — ең жақсы ем ⛅', 'Бөпеңіз қатты мазасызданып, ештеңеге көңілі бөлінбей жүр ме? Ауа райы және киім құралын ашып, ауа райына сай киіндіріңіз де, бірден саябаққа 20 минут серуендеуге алып шығыңыз.'),
  ('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7', 'Үнсіз көз жасы 📝', 'Бүгін бәрі бір мезетте Сіздің мойныңызға түсіп, жылағыңыз келіп тұр ма? Бұл — сондай табиғи сезім... Көңіл күй күнделігіне бар шаршағаныңызды жазып шығыңыз. Ішіңіздегіні шығару жаныңызды жеңілдетеді.'),
  ('e8e53d71-abc7-400d-80a7-8cf91f3339ab', 'Алғашқы буындарды қайталау 🗣️', '«Да-да», «ба-ба» сияқты дыбыстарды жиі қайталай ма? Бөпеңіз сөйлеу мүшелерінің жұмысын сынап жүр. Диалог құруды үйренуі үшін ол айтқан әр буынды жымиып қайталаңыз.'),
  ('27772b37-d653-4081-a4d8-e2d8e3036d19', 'Педиатрияға қатысты сұрақтар 🤖', '8-айға қарай ұйқы режимінің бұзылуы қалыпты ма? Интернеттен сағаттап іздегенше, Anacan ЖИ-інен 8-айдағы ұйқы регрессиясы туралы нақты ғылыми деректерді біліңіз.'),
  ('e5b5ed3f-01d7-4566-8860-0dc049a710b5', 'Кешкі әуен 🎶', 'Бөпеңіз ұйықтағысы келмесе, бөлмеде баяу классикалық музыка қосыңыз. Жайлы әуен оның ширыққан жүйке жүйесін тыныштандыруға көмектеседі.'),
  ('ea452c1a-6484-41b5-9042-60a3abcf409d', 'Қиялға негізделген ойындардың басталуы 🧸', 'Ойыншық қонжығына немесе қуыршағына су ішкізуге тырыса ма? Оның қиялы дамып, символдық ойындары басталып келеді. Осы сүйкімді кішкентай режиссерді сырттай тамашалаңыз.'),
  ('3a7b24a5-41c6-4c5d-a602-8a4582791ae2', 'Күнделікті қарбаласта түскі асты жүріп ішпеңіз. 🥑', 'Оны тойдыру үшін қолыңыздан келгеннің бәрін жасайсыз. Ал өзіңіз ше? Өзіңізге арнап тойымды, темірге бай жеке ас дайындаңыз.'),
  ('61d3770b-ac23-4b61-a0c4-be4c333cc55a', 'Сыр бөлісу 💬', '«Менің балам неге әлі еңбектемейді?» деп алаңдайсыз ба? Бірден Anacan қауымдастығына қосылыңыз. Мыңдаған ананың шынайы оқиғаларын оқып немесе сұрақ қойып, әр баланың бірегей екенін көріңіз.'),
  ('a8ecb50a-232f-401a-97bc-3fbfc63cc92b', 'Ажырасудан қорқу 🥺', 'Сіз бөлмеден шыққанда артыңыздан жылай ма? Бөпеңіз Сіз енді қайтып келмейді деп ойлайды. «Мен әрдайым қасыңдамын» деп айтып, даусыңыз арқылы оған сенімділік сезімін сыйлаңыз.'),
  ('6666dee6-8da7-4982-b6e5-9cdc982b4a75', 'Қызыл иектің қышуы жалғасуда 🦷', 'Кез келген затты қатты шайнап, аузынан сілекейі ағып жүр ме? Мұздатқышта салқындатылған тіс қышытқыштар осындай күндері нағыз көмекші болады.'),
  ('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d', 'Командалық кеңес 🥂', 'Қиын күнді артта қалдырдыңыз. Бөпе ұйықтағаннан кейін серігіңізбен бірге шай ішіп отырып, «біз шынымен керемет командамыз» деп, бір-біріңізге ризашылық білдіруді ұмытпаңыз.'),
  ('579d5966-d49f-4125-a264-8acd785d0a8d', 'Айнадағы дос 👀', 'Оны айнаның алдына апарыңыз. Өз бейнесіне таңырқай қарап, оған қол тигізуге тырысқанын бақылаңыз. Бұл — оның өзін-өзі тануына көмектесетін тамаша жаттығу.'),
  ('9099f274-aa9c-4fe9-8624-5cd611699d2d', 'Жылдам қор жинау 🛒', 'Бөпеге арналған май немесе дымқыл майлық таусылуға жақын ба? Сатып алу тізімі қолданбада Сізді күтіп тұр. Қажетті заттарды сол жерге жазып қойыңыз, серігіңіз жұмыстан қайтарда сатып ала келсін.'),
  ('1d706879-d02b-44cf-bac5-4f53776477d3', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, бөпені тоңдырып алмаңыз. Терезеден қарап қана шешім қабылдамаңыз: «Ауа райы және киім көмекшісі» арқылы даладағы жағдайға ең қолайлы нұсқаны дәл таңдаңыз.'),
  ('acd7fb31-0c36-4f0b-9849-cf983e0b0e95', 'Өзім жеймін! 🥦', 'Ол енді езбені қасықпен емес, көкөністерді өз қолымен ұстап жегісі келе ме? Оның дербестігін қолдаңыз. Иә, айнала былғанады, бірақ дамуы жеделдейді.'),
  ('e1819391-1d2d-450e-ac14-9ecfa65465d4', 'Ертегінің сиқырлы әлемі 🪄', 'Бүгін кешке «Ақылды ертегілерде» мүлде өзгеше тәсілді байқап көріңіз. Дауыс ырғағыңызды ертегінің ырғағына бейімдеңіз.'),
  ('aff9ba8d-8d8a-4d80-9363-09474c73609e', 'Кішкентай зерттеуші 👣', 'Ол аяқ башпайларын тауып алып, енді оларды аузына салуға тырысып жүр!'),
  ('d79d065c-4399-4ac9-8bd9-d4970a686fba', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Күндізгі шаршау да Сізге жетеді. Кешке бөпені ұйқыға дайындап, оған пижама кигізуді әкесіне тапсырып, өзіңіз сырттай ғана бақылаңыз.'),
  ('bedd9e86-f764-4777-9e49-e315e75433fd', 'Әкенің жауапкершілігі 👨‍🍼', 'Түнде бөпеге жалғыз өзіңіз ғана тұра бермеңіз. Жұбайыңызды да оятыңыз, өйткені бір команда болу — бұл жауапкершілікті тең бөлісу.'),
  ('c36dcca2-2b51-424c-b39c-c98f7988d549', 'Таптым сені! 🙈', 'Қолыңызбен бетіңізді жауып, «ку-ку» ойнағанда, бөпеңіз дауыстап күле ме? Оның заттардың көзден таса болса да бар екенін түсіну қабілеті толық қалыптасып келеді. Бұл ойынды күнделікті әдетіңіздің бір бөлігіне айналдырыңыз.'),
  ('3f339310-d600-43dc-81a3-1b609288885e', 'Кетпейтін дақтар 👗', 'Қосымша тамақ беру кезеңінде үй мен киімнің үнемі былғануы қалыпты. Бұған ашуланбаңыз. Силикон алжапқыштарды қолданыңыз да, осы күлкілі әрі бояуы қанық сәттерден жай ғана ләззат алыңыз.'),
  ('60071670-7fa4-4f9f-829f-892d281a9741', 'Өзіңізді кінәлауды доғарыңыз. 🛑', 'Бүгін экран алдында көп уақыт өткізілді ме, әлде үй жиналмай қалды ма? Сіз де шаршайтын адамсыз және қолыңыздан келгеннің бәрін жасап жүрсіз.'),
  ('fe5cb47e-9f22-41f9-a236-1db4b224e518', 'Заттарды жерге тастау ойыны 🥄', 'Бөпеңіз тамақтану орындығынан ойыншығын жерге тастап, оны көтеріп беруіңізді күте ме? Ол тартылыс күшін және себеп-салдар байланысын зерттеп жүр. Сабыр сақтап, жымиыңыз.'),
  ('28d590c8-c8a6-4c89-b78b-e70f2f482c0d', 'Қараңғылыққа үйрену 🌙', 'Бөпеңіздің тезірек ұйықтауы үшін бөлмедегі барлық артық жарық пен экрандарды өшіріңіз. Мелатонин гормонының бөлінуі тыныш әрі қараңғы ортада ғана жылдамдайды.'),
  ('31783568-6230-449d-98c8-e7b1b046a34e', 'Мазасыз таңдар ☁️', 'Бөпеңіз көзін аша салысымен бәріне жылап, ештеңеге көңілі толмай ма? Бәлкім, ол дәл қазір қарқынды өсу кезеңін бастан өткеріп жатқан шығар. Оны көбірек құшақтап, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('38c7f3dd-4cf4-4758-8006-37d59832bac8', 'Бөпе ұйықтай салысымен ыдыс жуғышты босатуға асықпаңыз! 🛋️', 'Диванға жатып, көзіңізді жұмыңыз да, 15 минут бойы үйдегі осындай сирек болатын мүлгіген тыныштыққа бөленіңіз.'),
  ('ea309314-6720-4ddf-9fe1-7a4fb805b43f', 'Сұрағыңыз бар ма? 🤖', '8-айға қарай баланың бойы мен салмағының кестесі Сізді алаңдата ма? Интернеттен қорқынышты мақалалар оқығанша, Anacan AI-дан нақты әрі ғылыми негізделген кесте сұраңыз.'),
  ('1c1e068a-2609-422f-991f-68ad50839ea3', 'Қуатыңызды қалпына келтіріңіз 🍲', 'Шаршау әбден титықтатты ма? Пайдалы рецептілердің ішінен 10 минутта дайындалатын, сүтіңіздің бөлінуін қолдап, өзіңізге сергектік сыйлайтын арнайы смузи таңдаңыз.'),
  ('51badc42-c8bc-4aa3-b0b8-ec576b19fa07', 'Дыбыстарды сүзгіден өткізіңіз 🤫', 'Бөпе ұйықтағаннан кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен бөлмені тексеріп, көрші бөлмеден немесе теледидардан шығатын кенет шудың алдын алыңыз.'),
  ('69f05aef-6a67-462b-8173-638d2cb174d5', 'Мақсатқа қарай еңбектеу 🐢', 'Енді бөпе көздегенін таңдап, соған қарай жылдам еңбектейді. Бөлмедегі жұтып қоюы мүмкін барлық ұсақ әрі қауіпті заттарды еден деңгейінен дереу алып тастаңыз.'),
  ('7405692f-45e1-45fa-9dd9-b527045b5e7d', 'Тәжірибе бөлісу 💬', 'Бөпенің жаңа әрекеті (мысалы, басын қабырғаға соғуы) Сізді қорқытты ма? Anacan қауымдастығына жазыңыз және басқа аналардың да бұл кезеңнен қалай өткенін оқыңыз.'),
  ('cad415e5-9ff2-468b-bfee-aaed538d25a0', 'Батыл қадамдар 🧗‍♂️', 'Диваннан ұстап тұрып, бір қолын жіберуге тырыса ма? Тепе-теңдік сезімі жылдам дамып келеді. Оның осындай батыл талпыныстарын алыстан қауіпсіздігін қадағалап, жымиып бақылаңыз.'),
  ('e2523211-afd7-48c7-8227-2ec7b0b2f0f7', 'Сезімдеріңізге ерік беріңіз 📝', 'Өзіңізді тым жалғыз әрі ешкім түсінбейтіндей сезінесіз бе? Бұл — қалыпты сезім. Көңіл күй күнделігіне сезімдеріңізді еш сүзгісіз, шынайы түрде жазып отырыңыз.'),
  ('16c8c619-fdcd-4a82-a21a-ff965106a15f', 'Үйдегі ретсіздік 🌪️', 'Бөлменің іші ойыншыққа толып кетті ме? Үй жинағаннан гөрі, бөпеңізбен көңілді өткізген 10 минутыңыз маңыздырақ. Ойыншықтар ертең де орнында болады, өзіңізді шаршатпаңыз.'),
  ('4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773', '8 айға дайындық! 🎂', 'Назар аударыңыз! Небәрі 10 күннен кейін бөпеңіз тура 8 айға толады! Даму трекерінен осы уақытқа дейін жүріп өткен жолдарыңызға көз салыңыз. Осы шағын мерейтойға Anacan-нан кішкентай тортқа алдын ала тапсырыс беруді ойластырыңыз.'),
  ('724d9097-f64c-406e-8895-2982258b710d', 'Музыкамен ұйқыға дайындалу 🛀', 'Кешкі дағдылы істер қиындап кетті ме? Жылы суға шомылдырғанда, баяу тыныштандыратын музыка қосыңыз. Су мен әуеннің үйлесімі тіпті ең қырсық баланы да жайландырады.'),
  ('12b2ddaa-17a1-4692-8574-725c962b0e1b', 'Себебін түсіне алмайтын жылау ұстамалары әбден қажытады. 😭', 'Себебін түсіне алмайтын жылау ұстамалары әбден қажытады. Болжай бермей, Жылауды талдау мүмкіндігін пайдаланыңыз да, дауыстың астарындағы жасырын себепті (ауырсыну, шаршау) бірден анықтаңыз.'),
  ('19b095ff-5334-4011-abd1-b8df6c79520c', 'Серуендейтін уақыт 🌳', 'Төрт қабырғада отыру Сізді қажытады. Бөпеңізді арбасына отырғызып, небәрі 20 минут болса да таза ауаға шығыңыз. Табиғаттың тыныштығы бөпеңізге де, Сіздің көңіл күйіңізге де жақсы әсер етеді.'),
  ('b6194099-d4e6-4061-b3f2-d6bc5cce0529', 'Сұқ саусақ ☝️', 'Алыстағы затты саусағымен көрсетіп, Сізге қарай ма? Осылайша ол Сізге «маған қараңыз» немесе «мынаны қалаймын» деп тұр. Бұл — қарым-қатынастағы үлкен қадам! Оған заттың атауын айтып беріңіз.'),
  ('b78498d9-706c-458c-aa0f-d6081c7746c6', 'Түнгі бесік жыры 🎶', 'Ешбір қолданба немесе дыбыс ана әлдиінің орнын баса алмайды. Бүгін кешке оны жай ғана бауырыңызға басып, өзі жақсы көретін әрі бойына сенім ұялататын бесік жырын ақырын айтып беріңіз.'),
  ('d08b308d-00d3-45c9-9840-df7ac1047703', 'Қол соғайық 👏', 'Қуанышын алақанын соғып білдіре ме? Осы керемет қимыл-қозғалыс жетістігін көрген сәтте үйде шағын жеңіс биін билеп, оған қосылыңыз!'),
  ('dd6cc7ba-db6f-403b-93e6-2447dbb967dc', 'Тізім қажет қана емес, міндетті 🛒', '8 айлық мерекеге қажетті әшекейлер ұмыт қалмасын! Ойыңызды шаршатпай, бәрін бірден Сатып алу тізіміне жазып, жұбайыңызбен бірлесе әрекет етіңіз.'),
  ('f72fbb7e-431d-4f4b-9a73-06637ff7bd68', 'Мінсіздік болмайды 🛑', 'Бүгін ештеңе жоспар бойынша болмады ма? Өзіңізді кінәламаңыз. Сіз — әлеуметтік желідегі сүзгіден өткен елес емес, шынайы анасыз. Бөпеңізге тек Сіз қажетсіз.'),
  ('61ffa498-18cc-4858-987c-676f525f467c', 'Іштегі ауыр сезімдерден арылыңыз 📝', 'Күніңіз қиын өтті ме? Көңіл күй күнделігіне бүгінгі барлық жағымсыз сезімдеріңізді жазып, ішіңіздегіні шығарыңыз. Мұндай қиын кезеңдер барлық ананың басынан өтеді, Сіз жалғыз емессіз.'),
  ('856b771b-5997-4eed-bc26-8b35541184c6', 'Ауа райын зерттеу ⛅', 'Сырттағы ауа райы түсініксіз бе? Ауа райы және киім құралы терезеден байқалмайтын желдің жылдамдығын көрсетіп, дұрыс киім үйлесімін бірден ұсынсын. Еш күмәнсіз серуенге шығыңыз.'),
  ('c82d9568-ae94-4492-9789-4621c2dbcabc', 'Ойыншығымды бермеймін! 🧸', 'Қолынан бір нәрсені алсаңыз, қарсылық білдіріп, қатты жылай ма? Оның меншік пен дербестік сезімі дамып келеді. Бұл — табиғи психологиялық кезең, онымен күреспеңіз.'),
  ('bc11c415-3d46-43c3-a8ed-0a204516e9ce', 'Дені сау ана, дені сау бөпе 🥑', 'Ағзаңыздағы темір мен кальций қоры азайған. Пайдалы рецептілердің ішінен тез дайындалатын әрі Сізге күш-қуат беретін тағам әзірлеп, өзіңізді қуантыңыз.'),
  ('e386c8f2-240d-4f0f-adaf-e43ea496b8b2', 'Кітап парақтайтын зерек бөпе 📖', 'Қалың парақты кітаптардың беттерін өзі аударып, суреттерге қызығушылық таныта ма? Көру жады тамаша жұмыс істеп тұр. Онымен бірге кітап оқып, суреттегі жануарлардың аттарын атаңыз.'),
  ('e418c384-8ae3-455b-af14-a223e6595751', 'Уақытты тоқтатқан кадр 📸', 'Бөлмеде тәтті қылықтарымен ойнап отырғанда, бірден Бөпе фотосессиясын ашыңыз. 8 айға жақындаған, өзгеріп, есейе түскен осы жүзін ерекше тақырыппен естелікке сақтап қойыңыз.'),
  ('4068a45c-e5fe-4a82-8c4b-a81d556f97cc', 'Сырласқыңыз келе ме? 💬', '«Оның 8 айлық болып қалғанына сене алмаймын» деген ой Сізді толқыта ма? Осы әдемі әрі нәзік сезіміңізді Anacan қауымдастығындағы аналармен бөлісіңіз.'),
  ('7227b833-2ecd-472c-a074-7273a66732d9', 'Таныс жүздер 🥰', 'Бөлмеге кіргеніңізде оның жүзіндегі ерекше, кең күлкіні байқадыңыз ба? Ол Сіз бен жұбайыңызды өзгелерден бірден ажыратады. Оның шексіз махаббаты — ең үлкен мотивация.'),
  ('90341333-a47d-4dc8-b1bb-8fcf07c769b0', 'Әкенің күлкілі қылықтары 🤡', 'Бөпені күлдірудің ең жылдам жолы — әкесінің түрлі оғаш дыбыстар шығарып, күлкілі бет-әлпет көрсетуі. Бүгін кешке оның шат күлкісін тыңдап, бір сәт тынығып алыңыз.'),
  ('d4f1084b-2a25-422f-954c-038d4cf53bd2', 'Форумдарда адаспаңыз 🤖', 'Қосымша тағамға қатысты «Мұны беруге бола ма?» деген күмәніңіз бар ма? Сағаттап ақпарат іздемеңіз, қалтаңыздағы цифрлық педиатрдай Anacan AI сұрақтарыңызға жауап берсін.'),
  ('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc', 'Анаға арналған орын ☕', 'Үйде отыра беріп шаршадыңыз ба? Аналарға қолайлы орындар арасынан бала арбасымен емін-еркін жайғасуға болатын тыныш дәмхананы таңдап, өзіңізге шағын демалыс ұйымдастырыңыз.'),
  ('66c8660e-b8ca-4046-9e3f-578e25572ec7', 'Қоқыс зерттеушісі 🗑️', 'Еденнен немесе кілемнің шетінен не тапса да, асқан қызығушылықпен зерттейді. Бәрін қолынан жұлып алып, ашулана бермеңіз — ол кішкентай зерттеуші. Тек жұтып қоюы мүмкін заттардан абай болыңыз.'),
  ('8d417480-194b-431c-987a-b0b5216ea151', 'Бүгін ақылды ертегілерде 🪄', 'Ақылды ертегілерде бірнеше күннен кейін 8 айға толатын басты кейіпкердің хикаясын құрастырыңыз. Түнгі тыныштықты осы сиқырлы хикая ғана тербесін.'),
  ('5d8608e7-e1cb-4a71-9c73-7f6dde65adfe', '8 айға дейін соңғы 5 күн! 🎈', 'Толқу артып келеді! Небәрі 5 күннен кейін кішкентайыңыз 8 айға толады! Арнайы тортқа тапсырыс беруді немесе мерекенің тұжырымдамасын жоспарлауды ойласаңыз, соңғы күнге қалдырмаңыз.'),
  ('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05', 'Тыныштық пен кофе 🤫', 'Ол ұйықтап қалды! Енді кір жуғыш машинаны босатудың орнына қараңғы бөлмеде жайғасып отырыңыз. Дыбыс өлшегішті қосып, айналадағы шуды бақылауға алыңыз да, 15 минуттық тыныштықтың қадірін сезініңіз.'),
  ('90c5ba08-9d91-4669-8b26-99e0b48d4cf2', 'Байқап көру және қателесу 🧱', 'Екі ойыншық текшені бірінің үстіне бірін қоюға тырысады, бірақ олар құлап қалады. Бөпе мұқият қайта байқап көреді. Оның осындай шағын инженерлік ізденістері мен талпыныстарын үнсіз әрі мақтанышпен бақылаңыз.'),
  ('ed75b4ae-9703-498c-a857-64016faef6cc', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тыныш әрі күңгірт ортада ғана жылдам бөлінеді.'),
  ('695238eb-b88d-4ffe-800b-82d23636ceb9', 'Үй шаруасын кім атқарады? 🌪️', 'Ертеңгі шағын мерекеге дайындық жұмыстары қалып қойды ма? Қала берсін. Серігіңізден бүгін үй шаруасын өз мойнына алуын сұраңыз. Ал Сіз ертеңге күш жинап, демалыңыз.'),
  ('c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8', 'Массаж уақыты 💆‍♂️', 'Бөпе ұйықтағаннан кейін күндізгі күйзелісті басу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыздар. Ертеңгі тамаша жеңіске міндетті түрде күш-қуатпен жетіңіздер!'),
  ('d3b0f81b-e9b4-4b00-883d-9e8bb86131bc', 'Ертең 8 ай толады! 📸', 'Дайынсыз ба? Ертең — үлкен күн! Тура 8 ай! Телефон жадын босатыңыз, ертеңгі бөпенің фотосессиясына көп орын қажет болады. Киімдерді қазірден үтіктеп қойыңыз.'),
  ('393a7a2a-b162-45e4-9577-0e4f2d088bf3', 'Жеңіс биі 🥂', 'Осы 8 айдағы шаршауды, көз жасы мен қуанышты бүгін кешке серігіңізбен бірге атап өтіңіз. Дастарқанға бір шам қойып, мызғымас командаңыздың жеңісіне қол соғыңыздар!'),
  ('4419f2fd-8e6f-4837-aa0e-9d571aac3895', 'Өткенге көз жүгірту 📈', 'Бөпеңіз қаншама жолдан өтті! Алғашқы күндердегі нәзік қорқыныштың орнын енді зор сенім басты. Сіз осы 8 айлық жолдан үлкен мақтанышпен өттіңіз! Сіз шынымен кереметсіз!'),
  ('b4769acb-82a0-480e-b58f-3017d46b37a4', 'Керемет 8 ай! 🎉🎂', 'ҚҰТТЫҚТАЙМЫЗ! Осы ғажайып жолмен бірге келе жатқандарыңызға тура 240 күн болды! Бөпеңіз енді толық 8 айлық. Осы ерекше күнді дәл қазір атап өтіп, Anacan қауымдастығында мақтанышпен бөлісіңіз!'),
  ('075bea5d-3ab7-4404-af70-89a3de20a0ff', 'Жылдам тізім 🛒', 'Кеше үйдегі азық-түліктің бәрі таусылып қалды ма? Сатып алу тізімін ашып, сүт, жеміс және басқа да қажет заттарды бірнеше секундта белгілеп, жұбайыңыздың телефонына жіберіңіз.'),
  ('3c7f679a-b11a-4f67-a3ae-5f350e93a451', 'Ерекше ертегі 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрастырыңыз.'),
  ('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8', 'Мерекеден кейінгі қарбалас 🌪️', 'Кешегі 8 айлық мерекеден кейін үйдің астан-кестені шықты ма? Үй жинауға асықпаңыз. Бүгінгі күнді 8 айға толған кішкентайыңызбен бірге жай ғана демалуға және жаңа ойыншықтарды зерттеуге арнаңыз.'),
  ('2c9fa500-5618-49b8-a232-965da7b82ef7', 'Дыбысты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Шу өлшегішпен бөлмедегі дыбыс деңгейін тексеріп, кенеттен шығатын шудан, теледидар мен көше дыбысынан аулақ болыңыз.'),
  ('87a20850-e59a-4ee2-81e8-79c4b5808e7b', 'Сізді естіп тұрмын 🗣️', 'Бөпеңіз Сізді мұқият тыңдап, ұқсас буындарды айтуға тырыса ма? Ол Сізбен сөйлесіп жатыр! Оған күлімсіреп жауап беріп, осылай қарым-қатынас жасауға ынталандырыңыз.'),
  ('9c963f32-b147-4e84-aa9a-af699e50681f', 'Бүгін шыдамыңыз таусылып, ашуланып кеттіңіз бе?  🛑', 'Өзіңізді кінәламаңыз. Интернеттегі мінсіз өмір туралы елестерге сенбеңіз. Сіз — шынайы анасыз, сондықтан сезімдеріңізді бастан өткеруге толық құқығыңыз бар.'),
  ('0cf5cff8-d958-4ec0-b6df-6f78457976fd', 'Дәрігердей ақылды 🤖', '8 айдан кейінгі даму нормаларына қатысты күмәніңіз бар ма? Интернеттен жауап іздеп әуре болмаңыз, Anacan AI-дан сенімді, ғылыми негізделген және педиатрлар мақұлдаған жауап алыңыз.'),
  ('77b45217-21e4-402a-b5dd-d0ee28c29f05', 'Қолмен тамақтану 🥦', 'Бөпеңіз енді езбені емес, көкөністерді өз қолымен ұстап жегісі келеді! Өздігінен тамақтануға талпынысын қолдаңыз, айналасы былғанса да, міндетті түрде жанында болып, қадағалаңыз.'),
  ('dd6d5f01-5a48-4f85-953e-c5e21662ae95', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпеге жалғыз өзіңіз ғана қарамаңыз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу. Бүгін бөпені ұйықтату кезегі — жұбайыңызда.'),
  ('918fe7fd-3c85-49ee-b337-c52aba217614', 'Түн ортасында айғайлап оянып, тыныштала алмай жүр ме?  😭', 'Дауысын Жылауды талдау функциясына тыңдатып, мәселе жай ғана түнгі қорқыныш па, әлде денесі ауырып тұр ма — анықтаңыз.'),
  ('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b', 'Музыкаға билеу 🎶', 'Көңілді музыка ойнағанда, ырғағына сай тербеле ме? Бұл есту қабілеті мен қимыл-қозғалыс үйлесімінің тамаша дамып жатқанын көрсетеді! Көңілді ән қосып, онымен бірге бөлмеде билеңіз.'),
  ('deba3d42-726a-4e83-bbbd-900d2aee20ad', 'Ол тойса, енді кезек Сізде.', 'Пайдалы рецептілер арасынан қуат беретін тіскебасар таңдап, кем дегенде 10 минут диванға жатып, күш-қуатыңызды қалпына келтіріңіз.'),
  ('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6', 'Эмоциялар күнделігі 📝', 'Өзіңізді жалғыз әрі шаршаңқы сезінгенде, көңіл күй күнделігіне сезімдеріңізді жазыңыз. Барлық әйелдер осындай дауылды кезеңдерден өтеді. Сіз мықтысыз және мұның бәрін еңсере аласыз!'),
  ('90ae683e-61a6-4dd5-b894-186c95367ff3', 'Қызыл иегі әлі де қышып жүр ме? 🦷', 'Саусақтарын үнемі аузына салып, сілекейі көп бөліне ме? Мұздатқышта салқындатылған тіс қаситын ойыншықтарды қайта қолданатын кез келді.'),
  ('b9bfa71c-cf95-4768-adc9-c82fe1e676ac', 'Таза ауа — ем 🌳', 'Күні бойы жылап, мазасыз болды ма? Шешімі өте қарапайым: ауа райын тексеріп, соған сай киіндіріңіз де, арбасына отырғызып, бірден саябаққа шығыңыз. Табиғат — ең жылдам тыныштандыратын құрал.'),
  ('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d', 'Заттың тұрақтылығын түсінуге арналған ойын! 🧸', 'Ойыншығын жамылғының астына жасырып, оны өзіне тапқызыңыз.'),
  ('2e5279b4-ad3c-4da7-866e-49a5932c0601', 'Қолынан ойыншығын алғанда айқайлай ма?🧸', 'Меншік сезімі күшейіп келеді. Бұл — мінездің қалыптасуындағы маңызды кезең.'),
  ('d2ac515d-c34a-47d7-a082-82f89c2863e8', 'Ана сүті әлі де негізгі тағам! 🍼', 'Қосымша тамақ берілсе де, тамақтандыру таймерін қосып, бөпеңіздің күнделікті сүт қажеттілігі өтеліп жатқанына көз жеткізіңіз.'),
  ('31a887b1-fde3-4a67-a32c-13cc6764d41e', 'Бірге кітап оқыңыздар! 📖', 'Дыбысты әрі түрлі-түсті кітаптар оның назарын ерекше аударады. Бірге кітап оқитын пайдалы сәттеріңізді Блогтардағы кеңестермен одан әрі қызықты етіңіз.'),
  ('a82a604d-9504-4486-86ea-c38998236871', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Anacan таймері оң/сол емшекті Сіздің орныңызға есте сақтайды. Емізуді қазір таймермен бастаңыз!'),
  ('d7cab28d-37d6-4301-8e4d-28dfd96b83ab', 'Су ішу әдетін қалыптастырамыз. 💧', 'Қосымша тамақпен бірге су ұсынуды ұмытпаңыз. Қандай су ішетін ыдыстар қолайлы екенін Ұсынылатын өнімдер бөлімінен біліңіз.'),
  ('6122dba2-692e-45e2-8027-9ab67ba2bf07', 'Кел, кел 👏', 'Алақанын шапалақтай ма немесе Сізге қарай қолын соза ма? Бұл — қарым-қатынастың керемет тәсілі. Оны құшақтаңыз.'),
  ('a73ae95c-98a0-4201-9af1-960893ecd116', 'Уақытты тоқтату 📸', 'Ол сондай тез өсіп келеді... Ұйықтап жатқанда оның сүйкімді, тыныш жүзін суретке түсіріп, естелікке сақтап қойыңыз.'),
  ('b8c9eaea-1257-487d-8647-7c1cb6d70a3a', 'Сұрағыңыз бар ма? 🤖', 'Бөпеңіздің дамуына қатысты ойыңызда мыңдаған сұрақ бар ма? Anacan AI-ға жазыңыз және педиатрдың нақты кеңестерін алыңыз.'),
  ('19dff725-11f8-467a-b784-f2971b302ba0', '250-күнге дайындық! 🌟', 'Ертең — үлкен белес! Тура 250 күн! Үйде шағын мерекелік көңіл күй қалыптастырып, осы санды мақтан тұтуға дайындалыңыз.'),
  ('c304b9f3-2045-4d2f-b423-1096223f0f83', 'Бүгін үй жинамайсыз 🛑', 'Шаршадыңыз ба? Жұбайыңызға айтыңыз. Бүгін үйде тамақ дайындалмайды. Бүгін — ананың демалыс күні!'),
  ('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d', 'Ертегінің соңы жоқ 📖', 'Бүгін кешке Ақылды ертегілерде батыл әрі ақылды бала туралы хикая құрастырып, тыныш әрі жайлы атмосфера орнатыңыз.'),
  ('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2', '250 күнді мақтан тұтыңыз🥂', 'Бүгін кешке бөпе ұйықтағаннан кейін жұбайыңызбен бірге осы үлкен командалық жеңістеріңізді атап өтуді ұмытпаңыз!'),
  ('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218', 'ҒАЖАП 250 КҮН! 🎉', 'Сене аласыз ба? Осы қызығы мен қиындығы қатар өрілген сиқырлы жолмен бірге келе жатқандарыңызға тура 250 күн болды! Бөпеңіздің фотосессиясында арнайы жапсырма қолданып, осы сәтті мерекеге айналдырыңыз!'),
  ('e0e283b4-8f62-4d84-98d9-c186d1f67042', 'Артыңызға бір көз салыңыз 📈', 'Алғашқы күндердегі қорқыныштарыңызды еске түсіріңіз. Ал қазір Сіз орнынан тұруға талпынып жүрген бөпенің анасысыз! Өзіңізді мақтан тұтыңыз!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('01890bf6-ab5a-403c-96d2-696020ff0863'::uuid, 'Едендегі қауіптер 🧸', 'Енді бөлмелер ол үшін зерттеу аймағына айналды. Еңбектеп, кез келген жерге жете алады. Үйдің қауіпсіздігін қайта тексеретін кез келді.'),
  ('64b9a99f-59f6-4495-b5ab-9a4825037afc', 'Тартылыс күшін сынау 🥄', 'Қолындағы затты әдейі жерге тастап, Сізге қарай ма? Ол жай ғана себеп-салдар байланысын зерттеп жүр. Сабыр сақтап, ойынға қосылыңыз.'),
  ('b34bf0e6-4ffb-4b59-90eb-68d99299dee1', 'Суып қалған кофе шындығы ☕', 'Бүгін де кофеңіз суып қалды ма? Ештеңе етпейді, Сіз бір сәтке де тыным таппайтын нағыз қаһармансыз. Бүгінгі қарбаласты көңіл күй күнделігіне әзілмен жазып қойыңыз.'),
  ('026d603e-c612-41a2-9525-f4d00f730669', 'Жалғыз душ қабылдау бақыты 🛀', 'Күні бойы бөпеңіздің соңынан жүгіру қолыңызды талдырды. Кезекті жұбайыңызға тапсырып, өзіңізге 15 минуттық үзіліссіз су терапиясын сыйлаңыз.'),
  ('1c49ef6a-c84a-47c7-a1bc-352a17833a3d', 'Диванды жағалай жүру 🛋️', 'Жиһаздан ұстап орнынан тұрып, жанымен қадамдап жүр ме? Бұл — дербестікке бастайтын ең үлкен қадамдардың бірі. Даму трекерінде осы сәтті міндетті түрде белгілеп қойыңыз.'),
  ('b5c1158f-415c-414a-b3ec-c9879bf6e9d9', 'Өз атын таниды! 🗣️', 'Басқа бөлмеден атын атағанда бұрылып қарай ма? Есту және түсіну қабілеті жетіліп келеді. Онымен сөйлескенде атын жиі атап, диалог құрыңыз.'),
  ('bb4b0ba8-0880-4332-8a97-7715f01a7ba8', 'Шкаф детективтері 🕵️‍♂️', 'Асүй шкафтары оның ең сүйікті нысанасына айналды ма? Қауіпсіз ыдыс-аяқты төменгі шкафқа жинап қойыңыз: өз қазынасын зерттеп, ұзақ уақыт ойнай берсін.'),
  ('bf07c6c2-b84c-44ed-9459-f26c37f0e099', 'Тығылмақ ойынының шебері 🙈', 'Қолымен бетін жауып, «ку-ку» ойнау — оның кешкі уақыттағы ең сүйікті ермегі.'),
  ('c24149f4-cca2-46bd-ba68-2442b259ab90', 'Сіз де әйелсіз 💄', 'Сіз анасыз, қорғаушысыз, бірақ сонымен бірге жеке тұлғасыз. Айнаға қарап, өзіңізге жымиыңыз және бүгін өзіңіз үшін кішкентай бір жақсылық жасаңыз.'),
  ('4283eae1-f0b6-489a-be21-28cec6201152', 'Форумдарда адаспаңыз 🤖', 'Тамақтану тәртібіне қатысты күмәніңіз бар ма? Сағаттап ақпарат іздемеңіз, қалтаңыздағы педиатрдай ойлайтын Anacan AI сұрақтарыңызға жауап берсін.'),
  ('743ea03a-9755-40d4-b4aa-1eb6cf8a7495', 'Әкемен кітап оқу уақыты 📖', 'Бүгін кешке Ақылды ертегілерде тауға өрмелеген батыл ешкі туралы ертегі құрастырыңыз. Әкесі оқысын, ал Сіз осы тыныш сәттен ләззат алыңыз.'),
  ('fc594ad6-91bd-4ee2-a759-0d1e76e468c0', 'Қолмен тамақтану 🥦', 'Ол енді пюре емес, көкөністерді өз қолымен ұстап жегісі келеді! Өз бетінше тамақтануға талпынысын қолдаңыз, бірақ міндетті түрде жанында болыңыз.'),
  ('2e4d0e7a-db8d-4408-9d88-01d37ed8b303', 'Ұйқы аралығы қысқарып барады 🥱', 'Түнде жиі оянуы Сізді әбден шаршатты ма? Бәлкім, бұл 3 мезгіл ұйқыдан 2 мезгіл ұйқыға ауысатын кезең шығар. Күндізгі ұйқылар арасындағы уақытты қайта қарастырыңыз.'),
  ('b19774b6-01ed-4a77-8052-5a03aef4ba22', 'Шашындағы пюре 🤦‍♀️', 'Тамақтану уақыты майдан алаңына айнала ма? Баланың тағамды ұстап, зерттеуі — сенсорлық дамудың бір бөлігі. Дақтарға мән бермеңіз.'),
  ('f1d99477-a71b-4368-b9eb-c5c699e49b39', 'Табиғат көмекке келеді 🌳', 'Бөпеңіз қатты мазасызданып, үйде отырғысы келмей ме? Ауа райы мен киім көмекшісінен кеңес алып, бірден саябаққа 20 минут серуендеуге шығыңыз.'),
  ('2958c07b-39da-4ecb-ac79-c0f1640a7d1a', 'Өзіңізді салыстырмаңыз 🛑', '«Пәленшенің баласы жүріп кетті» деген сөзді ұмытыңыз. Әр баланың даму қарқыны ерекше. Anacan қауымдастығында Сіз сияқты ойлайтын аналармен сырласыңыз.'),
  ('da431940-9d6b-4ed8-a933-fd80b83687d9', '«Ана» сөзін асыға күту 🥰', 'Бөпеңіз әртүрлі буындарды дыбыстап жүр. Алғаш рет саналы түрде «Ана» немесе «Әке» дейтін сәті жақын! Дауысына сүйіспеншілікпен жауап беріп, оны ынталандырыңыз.'),
  ('f40e6c18-873e-481a-ba28-76a5634b977a', 'Музыка — жан азығы 🎶', 'Кешкісін себепсіз басталатын мазасыздықты жеңіл классикалық музыкамен басып көріңіз. Көбіне осы қарапайым тәсіл керемет әсер береді.'),
  ('288682cf-7f40-402e-a594-adaf2cbbed34', 'Жалаңаяқ жаңалықтар 👣', 'Үйде шұлықпен жүргенді ұнатпай ма? Табандағы жүйке ұштарының жерге жанасуы мидың дамуына өте пайдалы. Еркін жүре берсін!'),
  ('2951ca5f-9454-4562-9820-3bfb3531edfd', 'Тізім құтқарады 🛒', 'Ұмытшақтық әлі де мазалап жүр ме? Сабын таусылды, жеміс азайды ма? Ұмытып кетпей, Сатып алу тізіміне жазыңыз, қалғанын жұбайыңыз реттесін.'),
  ('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13', 'Отбасылық кеңес 🥂', 'Бүгін кешке бөпе ұйықтаған соң, жұбайыңызбен бірге Көңіл күй күнделігін ашып, осы аптадағы қарбаласқа бірге күліңіздер.'),
  ('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1', 'Тістер қайтадан шабуылда 🦷', 'Себепсіз жылауы қызыл иектегі жайсыздықтан болуы мүмкін. Тіс шығуын бақылау құралын жаңартып, салқындатылған тіс қаситын сақиналарды дайындаңыз.'),
  ('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af', 'Бөлме акустикасы 🤫', 'Ұйықтап бара жатқанда болмашы дыбыстан оянып кете ме? Дыбыс өлшегішпен бөлмені тексеріп, бірқалыпты ақ шумен тыныш ұйықтауына көмектесіңіз.'),
  ('cefb8b22-0318-4268-adf8-8f7052ad66cc', 'Алыстағы затты саусағымен көрсетіп, дыбыс шығара ма? ☝️', 'Ол Сізге «маған қара» немесе «мынаны қалаймын» деп тұр. Бұл — қарым-қатынас дамуындағы үлкен серпіліс!'),
  ('0c385e87-5c02-4870-85f8-9ab052891af8', 'Анаға арналған дәрумен 🥑', 'Оны тойдыру үшін қолыңыздан келгеннің бәрін жасайсыз. Ал өзіңіз ше? Пайдалы рецептілер бөлімінен темір мен кальцийге бай жеңіл түскі ас таңдаңыз.'),
  ('bda4f100-98ac-4f09-9fa3-a50d4e42eedd', 'Назар аударыңыз! 9 ай толуына небәрі 10 күн қалды!  🎂', 'Осы ерекше күнге арнап шағын торт немесе отбасылық фотосессия тұжырымдамасын қазірден ойластыратын уақыт келді.'),
  ('effeac28-8d9e-4d0e-b754-fb4004990432', 'Экрандардан алыстаңыз 📱', 'Түнгі ұйқыға 1 сағат қалғанда үйдегі барлық теледидар мен экранды өшіріңіз. Мелатонин тек тыныш әрі қараңғы ортада белсенді бөлінеді.'),
  ('47fc8d5e-d99d-4104-9258-c8e18ad15266', 'Бүгінгі кештің тақырыбы қандай?🪄', 'Бүгін кешке ертегіні жасанды интеллект жазсын: Ойыншықтарын іздеген кішкентай тиін. Түнгі тыныштықты тек Сіздің мейірімді даусыңыз бұзсын.'),
  ('856e1374-a46f-4ac4-b093-11e46392180f', 'Еліктегіш тотықұс 🦜', 'Сіздің жөтелгеніңізді, күлгеніңізді немесе қол қимылдарыңызды қайталай ма? Бөлмедегі ең жақсы айна — Сізсіз. Оған ең әдемі мимикаларды үйретіңіз!'),
  ('e263bb82-67f5-4f23-9107-f117b8634a27', 'Сезімдеріңізді еркін жіберіңіз 📝', 'Кейде есікті жауып алып, жылағыңыз келе ме? Бұл — қалыпты жағдай... Ойыңызды қағазға түсіру жеңілдік сыйлайды. Сезімдеріңізді Көңіл күй күнделігіне жазыңыз.'),
  ('73d0b947-9db1-4d57-a222-c8c22a2a895b', 'Мінезі қалыптасып келеді 🌟', 'Нені ұнататынын және нені мүлде қаламайтынын енді анық білдіреді. Қырсықтығы Сізді шаршатқанда, бұл оның тұлға болып қалыптасуының бір бөлігі екенін еске түсіріңіз.'),
  ('9596d063-607c-465f-9e92-b73f9f6f0ece', 'Аналар достығы 💬', 'Қиындықтарды бөлісу жанға түскен жүкті жеңілдетеді. Anacan қауымдастығында Сізбен бірдей сезімдерді бастан өткеріп жүрген мыңдаған әйел бар. Мұң-шеріңізді бөлісу тегін.'),
  ('fb27143e-60bd-4519-b45e-80c5584417a4', 'Әкенің жұбанышы 🫂', 'Түнгі мазасыздықты жалғыз өзіңіз басуға тырыспаңыз. Жұбайыңызды да осы үдеріске қатыстырыңыз. Кейде өзге иіс пен құшақ бөпені бірден тыныштандырады.'),
  ('4e869b86-0b42-4c4a-86f7-22a0999a3387', 'Қол соғу тобы 👏', 'Қуанғанын қол шапалақтап білдіре ме? Қимыл-қозғалыс дамуындағы осы керемет жетістікті Даму трекеріне белгілеп, үйде шағын жеңіс биін билеңіздер.'),
  ('72a32149-c4d7-4a45-b296-5cc7c5b673ad', 'Жылдам тексеру 🤖', '9 айлық бөпенің дамуынан не күтуге болады? Ұзақ мақалаларды қоя тұрыңыз. Сұрағыңызды тікелей Anacan AI-ға қойып, педиатр деңгейіндегі нақты жауап алыңыз.'),
  ('df74b674-d83b-4306-a6c3-1477bd965efe', 'Ұйқыға дайындық 🛀', 'Жылы ванна әрдайым көмектеседі. Кешкі әдетті ешқашан бұзбаңыз, өйткені ол бөпенің миына ұйықтайтын уақыт келгенін білдіреді.'),
  ('3c29a397-ae21-4b66-9ae6-c3001d2f3e36', 'Ол Сізге қарап жүр 👀', 'Бөлменің қай жерінде болсаңыз да, оның көзі Сізде. Сіз — оның қауіпсіздік мекенісіз. Шыдамыңыз таусылғанда, оның осы шексіз махаббатын еске түсіріңіз.'),
  ('b3560b09-ab82-494c-a5e9-d6be5d4cb35a', 'Шашып-төгу өнері 🌪️', 'Ойнаған ойыншықтарының бәрін жан-жаққа шашады. Үйдің жинақы болғанынан гөрі, Сіздің демалғаныңыз маңызды. Ойыншықтар ертең де орнында болады, ал сергек ана дәл қазір қажет.'),
  ('fe563692-e0de-40b2-aa34-9d6335348a54', 'Түнгі тыныштық 🤫', 'Көлік немесе сырттан шығатын дыбыстар оны мазаласа, міндетті түрде фонда үздіксіз ақ шу қосып қойыңыз.'),
  ('268d0edd-f8c9-45fd-af24-4b1bd27e458d', 'Әкенің массаж салоны 💆‍♀️', 'Жұбайыңыз бөпені ұйықтатсын, содан кейін тырысып қалған мойын бұлшықеттеріңізге 5 минут массаж жасап берсін!'),
  ('38581365-03a6-48aa-a7b4-923dde40764d', 'Баспалдаққа қызығушылық 🧗‍♂️', 'Үйде баспалдақ немесе биік жерлер болса, бөпе соларға ұмтылады. Қауіпсіздік қақпаларын орнататын уақыт келді.'),
  ('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf', 'Тамақтану тартысы 🥣', 'Бөпе езбені итеріп тастай ма? Күштеп тамақтандырмаңыз. Оның тағамға деген көзқарасын бұзбау үшін тамақтану үдерісін ойынға айналдырып, қауымдастықтан балама рецепттерді қараңыз.'),
  ('5626563e-1119-4751-a2d2-ad651cb7961b', '9 ай 5 күн! 🎈', 'Бір жасқа толуына аз-ақ қалды! Торт, шағын әшекейлер немесе жай ғана үйдегі ең әдемі киімдер... Бөпеңіздің фотосессиясына дайындықты жеделдетіңіз.'),
  ('5e8f6838-89c2-40a6-940e-2ef8b752a179', 'Ортақ естеліктер 📸', 'Қандай әдемі күлімсірейді! Ұйықтар алдында сол пәк жүзін суретке түсіріп алыңыз, бұл сәттер енді қайтып келмейді.'),
  ('912ca02c-47d0-4e27-8bdb-7afe9ba868be', 'Темір қоры 🥩', 'Қаназдық баланың тәбетін де, қуатын да төмендетуі мүмкін. Тамақтану тәртібін қайта қарап, қажет болса, құрамында темір бар тағамдар туралы Anacan AI-дан сұраңыз.'),
  ('0135df6f-fe6e-4faf-9136-dc65b2b29e33', 'Қош айтысатын уақыт 👋', 'Біреу үйден шыққанда қол бұлғап қоштаса ма? Бұл — әлеуметтік дамудың сондай сүйкімді белгісі! Оны жиі қолдап, жігерлендіріңіз.'),
  ('44260d05-153e-4b6b-b9dd-6f07fb02c462', 'Тыныштық іздеу ⛅', 'Шиеленіс күшейгенде, ең жақсы амал — сыртқа шығу. Ауа райын тексеріп, бөпеңізді арбаға отырғызыңыз да, жай ғана серуендеп, ойыңызды сергітіңіз.'),
  ('67247d93-ddf7-4fcc-adef-5828dde725b4', 'Мінсіздік елесі 🛑', 'Бүгін ештеңе жоспардағыдай болмады ма? Өзіңізді кінәламаңыз. Сіз — әлеуметтік желідегі сүзгіден өткен елес емес, шынайы анасыз.'),
  ('4e8edba3-fd16-4c28-a7ff-08ff9853211e', 'Күнделікті ұсақ-түйек қажеттіліктер ұмыт қалады. 🛒', 'Жөргек бітті ме, әлде ылғал майлық па? Сатып алу тізіміне қосыңыз, жұбайыңыз дүкеннен қайтарда ала келсін.'),
  ('5f49ad4f-107b-4550-adae-e4aab3aa9d5b', 'Күндіз екі рет ұйықтауға көшу 🥱', 'Күндіз 3 рет ұйықтайтын балаңыз енді соңғы ұйқыға жатқысы келмей жүр ме? Ол өсіп келеді! Ұйқы кестесін 2 мезгілдік ұйқыға бейімдейтін уақыт келді.'),
  ('4b865d9a-0f66-4cb0-98d0-deaa6f061766', 'Аздап романтика 💖', '9 айдың шаршауы мен мақтанышын бүгін кешке жұбайыңызбен бірге шам жарығында атап өтіңіз. Сіздер — керемет командасыздар!'),
  ('8be43b5a-b4b9-49ba-b74f-59b204783156', 'Тура 9 ай! 🎂', 'Құттықтаймыз! Босанғаныңызға тура 9 ай болды. Бөпеңіз құрсағыңызда 9 ай, құшағыңызда 9 ай өсті! Осы ғажап сәтті атап өтіп, естелігіңізді қауымдастықта бөлісіңіз!'),
  ('334b387f-4019-4208-b951-95f53c679a8b', 'Қуатқа деген қажеттілік 🍲', 'Шаршау әбден сүйегіңізге батты. Пайдалы рецепттер арасынан 10 минутта дайындалатын, темір мен ақуызға бай түскі асты таңдап, күш жинаңыз.'),
  ('495a74f3-0952-464a-80e0-08b1cc46205c', 'Дыбысты реттеңіз 🤫', 'Үйдегі шу оның терең ұйқысын бұзады. Сіз де жайлы демалу үшін дыбыс өлшегіштің көмегімен фондық дыбыс деңгейін бірқалыпты ұстаңыз.'),
  ('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1', '«Жоқ» сөзінің күші 🛑', 'Ол енді ұнатпаған тамағын шетке ысырып, басын шайқап «жоқ» дей ме? Оның мінезі қалыптасып келеді! Өз қалауына құрметпен қараңыз.'),
  ('5238f2b7-2892-49ff-9220-f07d0cf3221d', 'Күндізгі шаршау Сізге жетеді. 👨‍🍼', 'Кешкісін бөпемен бөлмеде аунап, ойын ойнау — тек әкенің міндеті.'),
  ('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede', 'Қазына іздеу 🧺', 'Киім себетін босату немесе шкафтарды ақтару — ол үшін ең қызықты ойын. Еркін ойнауына мүмкіндік беріңіз, бұл оның қимыл-қозғалыс дағдыларын дамытады.'),
  ('f0057ec1-cc62-4ea5-9364-5327660ddc30', 'Сұрауға қысылмаңыз 🤖', 'Балалар тағамына қандай дәмдеуіштер қосуға болады? Күмән тудырған кез келген сұрақты Anacan AI-дан бірден сұрап, көңіліңізді тыныштандырыңыз.'),
  ('00632cb5-4d20-4f2d-9bf8-82242042667b', 'Ғажайып ертегі уақыты 🪄', 'Бүгін кешке өзгеше ертегі айтып беріңіз: ұйықтағанды жақсы көретін сиқырлы бұлт туралы. Даусыңызды бәсеңдетіп, жайлы атмосфера қалыптастырыңыз.'),
  ('61c9e192-532e-41bc-9ebb-f2c296bb0670', 'Жан дүниеңіздегі жүкті бөлісіңіз 💬', 'Anacan қауымдастығына қосылыңыз. Кейде бейтаныс ананың жазбасын оқу кофеден де артық қуат береді.'),
  ('92c6be75-a837-4908-b755-b4ae97896380', 'Қауіпті аймақтарға қызығушылық ⚡', 'Розеткалар мен сымдар оның назарын аударады. Үйдегі «Болмайды» аймақтарын нақтылап, қауіпсіздікті тағы бір рет тексеріңіз.'),
  ('159ac401-c76f-42ec-b9e1-bb1a6d73130e', 'Пинцеттік ұстау арқылы зерттеу 🤏', 'Едендегі ең кішкентай қоқымды да саусақтарының ұшымен тауып алып жүр! Ұсақ моторикасы керемет дамып келеді.'),
  ('306f7e64-ae54-408a-95b9-ac4f9c3c6684', 'Түнгі тыныштық 🛀', 'Қалыптасқан тәртіпті өзгертпеңіз. Әдеттегідей бір ванна, бір массаж майы және қараңғы бөлме — тәтті ұйқының алтын кілті.'),
  ('f3512bb1-5e87-4250-8249-5c396829b593', 'Төрт қабырға синдромы ☕', 'Үйде отырудан жалықтыңыз ба? Анаға қолайлы орындар арасынан өзіңіз таза ауа жұтып, бөпеңіз де жайлы демалатын ең жақын орынды табыңыз.'),
  ('1835b0bb-3338-4b12-9da9-167cd1643dc6', 'Үй шаруасын кім істейді? 🌪️', 'Шаңсорғыштың даусы бөпеңізді қорқытып, үй шаруасы жиналып қалды ма? Қала берсін. Бүгін үй шаруасын серігіңізден өз мойнына алуын сұраңыз.'),
  ('be2205ed-6711-45b7-b2f3-ab21216eef54', 'Эмоциялар күнделігі 📝', 'Өзіңізді жалғыз сезінгенде, көңіл күй күнделігіне сезімдеріңізді жазыңыз. Барлық әйел осы жолдан өтеді, Сіз мықтысыз.'),
  ('8750f5ee-e089-418c-9d9b-a881ca3441c3', 'Сиқырлы ертегілер әлемі 🪄', 'Ақылды ертегілерде небәрі 5 күннен кейін 9 айға толатын басты кейіпкердің хикаясын құрастырыңыз.'),
  ('7ee44a70-ee6e-4b49-a487-76ff5581f580', 'Батыл қадамдар 🧗‍♂️', 'Жиһаздан ұстап тұрып, бір қолын жіберуге тырыса ма? Бұл тепе-теңдік сезімінің дамып келе жатқанын білдіреді. Қолынан ұстап, оған аздап сенімділік беріңіз.'),
  ('97d44a72-2ca4-4c0f-b997-91c31aeabbef', 'Бірлік жайлы әңгіме 🥂', 'Көңіл күй күнделігін ашып, жұбайыңызбен осы айлардың екеуіңізді қалай өзгерткені туралы сөйлесіңіз. Бір команда болу — ең үлкен күш.'),
  ('ff86bc54-face-4f54-a1de-cc0ec9cccbc2', 'Бәрі дұрыс ✔️', 'Кейде қорқыныш Сізді билеп кете ме? Бөпеңіздің таза киіміне, тоқ қарнына және Сізге күлімдеген жанарына қараңыз. Сіздің қолыңыздан бәрі керемет келіп жүр!'),
  ('55476184-e000-441a-91f6-32b219ce5489', 'Ертең — ерекше күн! 🎉', 'Тура 9 ай! Киімдерін дайындадыңыз ба? Телефон жадын босатыңыз, ертең бөпеңіздің фотосессиясына көп орын қажет болады!'),
  ('801186a2-f617-44a4-bfbe-39fa8b84707d', 'Түнгі бесік жыры 🎶', 'Бүгін кешке бөлмені толық қараңғылаңыз. Ешқандай технологиясыз, тек Сіздің сыбырлаған даусыңыз ғана болсын.'),
  ('bcabe7b8-3e78-42a9-bdf0-3f1883219079', 'Қарны аш па, әлде шаршады ма? 😭', 'Себепсіз жылағанда абдырап қалмаңыз. Жылауды талдау мүмкіндігін пайдаланып, мәселенің себебін тез анықтап, шешіңіз.'),
  ('327e6e73-14c5-44c7-86f9-1b01671cc4cc', 'Өткенге көз жүгірту 📈', 'Бөпеңіз қаншама жолдан өтті? Алғашқы күндердегі толқу енді сенімге ұласты. Сіз бұл жолды үлкен жеңіспен жүріп өттіңіз!'),
  ('cd0245fe-8c0d-4f3e-ad23-05cff2186013', 'Қоқыс зерттеушісі 🗑️', 'Жерден не тапса да, асқан қызығушылықпен зерттейді. Бәрін қолынан жұлып алып, ашуланбаңыз, ол — кішкентай зерттеуші. Тек бақылауда ұстаңыз.'),
  ('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638', 'Әкесінің жұбатуы 🫂', 'Түнде бөпе оянғанда, бірде Сіз, бірде жұбайыңыз тұрыңыз. Кейде бөпені тек әкесінің ырғақты сипауы ғана тыныштандырады.'),
  ('77c04114-1662-45d9-9778-494a99f15f4f', 'Ауа райына алданып қалмаңыз ⛅', 'Серуенге шығарда терезеге қарап қана шешім қабылдамаңыз. Ауа райы және киім құралының көмегімен бөпені қабаттап киіндірудің ең қолайлы жолын табыңыз.'),
  ('b630415b-1d8a-4088-bd37-659e6494cb2c', 'Ойыншығымды бермеймін! 🧸', 'Қолынан бір нәрсені алғанда қарсылық білдіріп, жылай ма? Меншік пен жеке тұлғалық сезімі қалыптасып келеді. Бұл — психологиялық дамудың табиғи кезеңі.'),
  ('5c4470d4-31c9-42e6-98b2-6ebad58cdce5', 'Даусындағы өзгешеліктің себебін түсіне алмай жүрсіз бе?  😭', 'Дереу Жылауды талдау құралына тыңдатып, мазасыздықтың себебі тіс пе, әлде ішіндегі жел ме екенін анықтап, көңіліңізді жайландырыңыз.'),
  ('906becee-91c7-4860-a453-bec23a80f855', 'Тыныштық қажеттілігі 🤫', 'Бөлмедегі тыныштықты Дыбыс өлшегішпен бақылаңыз. Түнде бөлінген ұйқы оның да, Сіздің де таңертеңгі көңіл күйіңізге әсер етеді.'),
  ('93f3b238-cc16-44a9-888c-f9d77043f372', 'Музыкаға билеу 🎶', 'Көңілді музыка ойнағанда, ырғаққа сай тербеле ме? Есту қабілеті мен қимыл-қозғалыс арасында байланыс қалыптасып келеді! Көңілді ән қосып, онымен бірге билеңіз.'),
  ('334464c1-4599-4dd4-83dd-d57c384eb650', 'Кітаптарды парақтайды 📖', 'Қалың беттері бар кітаптарды парақтауға тырыса ма? Оған түрлі-түсті әрі сипап сезуге болатын ертегі кітаптарын көбірек алып беріңіз.'),
  ('57fa0aeb-432f-4b34-915b-98422c100236', 'Тіс жару кезіндегі ауырсыну 🦷', 'Қызыл иегі қайтадан қызарып, сілекейі тоқтамай ағып жүр ме? Салқын тіс қаситын ойыншықтарды дайындап қойыңыз.'),
  ('bda23a3e-0646-4246-a5dc-febd245b2bb1', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Anacan таймері оң немесе сол емшекпен емізгеніңізді Сіздің орныңызға есте сақтайды. Емізуді қазір таймермен бастаңыз!'),
  ('e2296439-aad7-4bdf-a627-05d1e066a3d8', 'Ұйқы нормаларын қадағалаңыз. ⏱️', 'Бөпеңіз ұйықтағанда ұйқы таймерін қосып, 9 айлық бөпеңіздің тәуліктік ұйқы нормасын сақтап жүргенін графиктен тексеріңіз.'),
  ('13322f59-d734-452d-8178-1ffb4e5e9f78', 'Орындыққа өрмелеу 🧗‍♂️', 'Еденде жүру аздық етіп, жиһаздың үстіне шығуға тырысып жүр ме? Қимыл-қозғалысы қарқынды дамып жатыр! Міндетті түрде бақылауда ұстаңыз.'),
  ('b349c13b-d822-42ec-876c-d41ccb790846', 'Таза ауа — дәрі 🌳', 'Күні бойы жылап, мазасыз болды ма? Шешімі өте қарапайым: ауа райына сай киіндіріп, арбаға отырғызыңыз да, бірден саябаққа шығыңыз.'),
  ('e46eb59c-0196-4f8a-b3f3-e86458e1f828', 'Бөлме акустикасы 🤫', 'Ұйықтап жатқанда кішкентай ғана сыбдыр оны оятып жібере ме? Дыбыс өлшегішпен бөлмедегі дыбыс деңгейін талдап, тыныштықтың бұзылмауын қамтамасыз етіңіз.'),
  ('3ab1636f-ed5f-47f5-93d7-4ac521edd386', 'Өзіңізді жеткіліксіз сезінесіз бе? 💬', 'Дәл қазір Anacan қауымдастығына кіріп, басқа аналардың қолдау білдірген пікірлерін оқып, көңіліңізді жайландырыңыз.'),
  ('62964d86-1e07-4c7f-a135-52c48581ffc5', 'Бүгін бәрі астан-кестен болды ма?', 'Ештеңе етпейді, бөпеңіз тоқ әрі таза болса, Сіз әлемдегі ең жақсы анасыз.'),
  ('32607011-b168-4558-b64b-8c8947e8d9a9', 'Жылы ванна, массаж және бөлмені қараңғылау. 🛀', 'Ұйқы тәртібін сақтау — түні бойы үздіксіз ұйықтаудың басты құпиясы.'),
  ('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08', 'Әртүрлі буындар, толық сөйлем құрауға талпыныстар 🗣️', 'Ұзақ сөйлеп, өз тілінде толық сөйлем құрап жатқандай болады. Бөлмедегі ең сүйкімді дикторды мұқият тыңдаңыз!'),
  ('3908e4ee-6364-4b5e-bf19-9883638e23db', 'Бөлмедегі дыбыс 🤫', 'Ұйықтау қиындап кетті ме? Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, теледидардың дауысын бәсеңдетіңіз.'),
  ('ce7b77f8-95b5-4071-bf35-61b06d785d85', 'Біз бір командамыз! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ашық әңгімелесіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('fab0e5e3-a0d0-40d0-843b-ff548b4b816f', '«Бері кел» қимылы 👏', 'Қолымен «бері кел» деген қимылды жасауды үйренді ме? Осы сүйкімді қимылды міндетті түрде видеоға түсіріп, естеліктер альбомыңызға қосыңыз.'),
  ('0b91a5b0-1518-4473-b0bb-59cec89d7f6f', 'Әңгімелері түрлене түсуде! 🗣', '️ «Ма-ма», «ба-ба» буындарымен құратын сүйкімді диалогтарын дамыту үшін Блогтардағы сөйлеуді дамытуға арналған кеңестерді оқыңыз.'),
  ('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5', 'Ана сүтін көбейтуге көмектесетін тағамдар. 🍲', 'Әйелдерге арналған пайдалы рецепттер бөліміндегі сүтті көбейтетін сорпаларды бүгін дайындап көріп, күш-қуатыңызды арттырыңыз.'),
  ('db929314-83ca-4372-8890-03ef676e68e5', 'Себебін түсіне алмайтын жылау ұстамалары әбден қажытады. 😭', 'Өзіңізді қинамаңыз, Жылауды талдау құралын пайдаланып, мәселенің түпкі себебін анықтаңыз.'),
  ('72b7b721-7f37-4054-90fd-05ac29f9ff3c', 'Мазасыздыққа қарсы дыбыс терапиясы. 🎶', 'Егер бүгін кешке бөпеңіз мазасызданса, Ақ шу ішінен ана құрсағындағы дыбысты қосып, оны бірден тыныштандырыңыз.'),
  ('761f9ba9-87d1-4b16-a40a-f1ec2385a5fd', '10 айға дайындық! 🎂', 'Назар аударыңыз! Небәрі 10 күннен кейін бөпеңіз 10 айға толады! Екі таңбалы айларға өту құрметіне арнайы тортқа тапсырыс беруді ұмытпаңыз!'),
  ('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9', 'Ертегімен ұйықтайтын бөпе 🪄', 'Ақылды ертегілерде батыл әрі сүйкімді жануарлар туралы хикая құрып, бөлмені сиқырлы мекенге айналдырыңыз.'),
  ('19eac11a-ecf7-498d-85e1-95d4f484d466', '10 айға 10 күн қалды! 🎈', 'Мерейтойға 10 күн қалды! Бөпе фотосессиясы құралынан арнайы жақтауларды қазірден таңдап, жоспарлап қойыңыз.'),
  ('36d1de0a-5eb5-4e0f-98ce-a583a10b254e', 'Ауа райына алданып қалмаңыз ⛅', 'Серуенге шығарда терезеге қарап қана шешім қабылдамаңыз. Ауа райы және киім құралының көмегімен бөпеңізді қабаттап киіндірудің тиімді жолын табыңыз.'),
  ('ea9b5851-8f4a-4a19-990c-97e725808bb5', 'Әкеден бесік жыры 👨‍🍼', 'Бүгін түнде ұйықтар алдында бесік жырын айтып, ертегі оқу — әкенің міндеті.'),
  ('14c6187e-df8b-47e8-b44f-9bc87c4b9143', 'Түнгі тыныштық 🤫', 'Көлік немесе сырттағы дыбыстар бөпеңізді мазаласа, міндетті түрде фонда үздіксіз ақ шу қосып қойыңыз.'),
  ('36c8e54c-04ef-4b47-9a2f-c0754b0990c9', 'Құлап-тұрып үйрену 🧗‍♂️', 'Диваннан ұстап жүріп, бөксесімен отырып қалып, қайта тұра ма? Ол табандылықты үйреніп жүр. Алаңдамай, оған жігер беріңіз.'),
  ('fa0817a9-00d2-41fc-bdcb-8fdae95932ff', 'Заттардың атауын үйреніп жүр 🧸', '«Доп қайда?» деп сұрағанда, көзімен іздеп таба ма? Түсіну қабілеті жетіліп келеді! Онымен заттардың атауын айтып, ойын ойнаңыз.'),
  ('93f4fd0f-1f45-436c-b46b-7acc69d1b899', 'Екі аяқпен тепе-теңдік сақтау 🤸‍♂️', 'Қолтығынан ұстап тұрғанда, аяғымен бұрынғыдан тік әрі нық тұра ма? Даму бақылағышында осы негізгі қадам басу рефлексін міндетті түрде белгілеңіз!'),
  ('b0bdf4f4-2902-43a5-876f-e99b39aef4f9', 'Сиқырлы ертегі уақыты 🪄', 'Ақылды ертегілердегі «Кішкентай кейіпкердің ұйықтау құпиялары» атты хикаямен кешкі әдеттеріңізге әр беріңіз.'),
  ('c6da7887-a402-4a11-8fbf-8de4d7696325', 'Тізім өмірді жеңілдетеді 🛒', 'Үйдің күнделікті қажеттіліктері таусылмайды. Басыңызды қатырмай, сатып алу тізімін толтырыңыз да, жұмыстан келген әкенің құтқарушы болуын күтіңіз.'),
  ('1b15944e-9198-4fc4-b86d-0b17af6cdd00', 'Дәрігерден не сұраймын? 🤖', 'Ай сайынғы тексеруге бармас бұрын не сұрау керегін білмейсіз бе? Anacan AI-дан 9 айлық тексеру тізімін сұраңыз.'),
  ('1eda7621-0a6a-4ff0-8efe-ec931b28a106', 'Үйдің кішкентай көмекшісі 🧺', 'Сіз киімдерді жинап жатқанда, ол да келіп, шашып «көмектесе» ме? Оны бұл істен шеттетпей, қолына бір сүлгі беріңіз.'),
  ('59e058ca-af20-4537-9c74-8aa7eb175af6', 'Сезімдеріңізге ерік беріңіз 📝', 'Кешкі кофеңізді алып, көңіл күй күнделігіне өткен айлардағы және қазіргі сезімдеріңізді салыстырып, шағын жазба жазыңыз.'),
  ('30a7e68c-862a-436f-a801-8270fce13b90', 'Өзіңізді күтіңіз 🍲', 'Сіздің деніңіз сау болса, бөпеңіз де сау болады. Пайдалы рецептілерден 10 минутта дайындалатын жеңіл ана салатын таңдап, жеп алыңыз.'),
  ('d7009029-eb30-44cd-bedc-77f2ddcbdbe4', 'Пюреден түйіршікті тағамдарға! 🍲', 'Бөпеңіз шайнауды қажет ететін тағамдарды жей ала ма? Қолданбамыздағы әртүрлі құрылымдағы пюре мен сорпа рецептілерін «Қосымша тағамды бастаған бөпелер» бөлімінен байқап көріңіз.'),
  ('f5716668-d412-4d80-9c29-0a69a23f4f4e', 'Сатып алу тізімі 🛒', 'Тамаққа қажет брокколи немесе сұлы таусылып қалды ма? Сатып алу тізімін бірден толтырып, қажет заттарды жұбайыңыздың телефонына жіберіңіз.'),
  ('16369cf1-7620-428e-8c38-c6f5104fb5ab', 'Ойыншықтарын қораптан шығарады! 🧸', 'Ол заттарды қораптан бір-бірлеп шығарып, лақтырғанды ұнатады. Осы көңілді әрі айналаны шашып ойнайтын сәтін «Бөпе фотосессиясы» арқылы суретке түсіріп, кейін күліп еске алыңыз.'),
  ('912a7ba7-5cb9-41f1-9daa-dc1c800036eb', 'Алғашқы қадамдар жақын ба? 🧗‍♂️', 'Бөпеңіз диваннан ұстап тұрумен шектелмей, қабырға бойымен жүре бастады ма? Қауіпсіздік шараларын екі есе күшейтіңіз.'),
  ('ec70551b-eda4-4e87-86a9-151235d2eb3e', 'Ертегі тыңдап ұйықтау 🪄', 'Ақылды ертегілерде батыл әрі сүйкімді жануарлар туралы хикая құрып, бөлмені сиқырлы мекенге айналдырыңыз.'),
  ('39498b75-8a2a-463e-a232-aa6ed7188810', 'Сіздің дауыс ырғағыңызды түсінеді 🗣️', 'Қатаң дауыспен «жоқ» дегеніңізде, кідіріп, Сізге қарай ма? Ол енді эмоциялар мен тыйымдарды түсіне бастады!'),
  ('6d030e22-f99a-4fa8-829a-d62a50ce76e0', 'Дамуын тексеру 🤖', 'Балаңыздың қимыл-қозғалысы кеш дамып жатыр деп ойлайсыз ба? Anacan AI-дан 9 айлық баланың қимыл-қозғалыс дағдылары туралы түсінікті ақпарат алыңыз.'),
  ('e607d1aa-9be0-4388-9790-764a5c1e94da', 'Ас қорытуын қадағалаймыз. 🧷', 'Қатты тағамдар үлкен дәреттің сипатын өзгертеді. Әр жөргек ауыстыруды Anacan-да белгілеп, бөпеңіздің денсаулығын талдаңыз.'),
  ('c0c6e209-b8c8-4325-bc8e-9d4231949abd', 'Тіс жару кезіндегі ауырсыну 🦷', 'Қызыл иегі қайтадан қызарып, сілекейі тоқтамай ағып жүр ме? Салқын тіс қаситын ойыншықтарды дайындап қойыңыз.'),
  ('65f53c0c-e8ea-4257-8798-e79b9ed847be', 'Сіз не жесеңіз, бөпе де соны қалайды 🥣', 'Тәрелкеңіздегі әр нәрсеге қол соза ма? Қазір оның тамаққа қызығушылығы шарықтау шегінде. Оған өзі қолымен ұстап жей алатын шағын тағам бөліктерін беріңіз.'),
  ('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4', 'Сезім күнделігі 📝', 'Өзіңізді жалғыз сезінгенде, сезімдеріңізді Көңіл күй күнделігіне жазыңыз. Ойыңызды қағазға түсіру жаныңызды жеңілдетеді.'),
  ('d2c3bcc6-5492-42b4-857f-d6ad8a442199', 'Дамуын тексеру 🤖', 'Қосымша тағамға қатысты сұрақтарыңыз бар ма? Anacan AI-дан 9 айлық бөпенің мәзірі туралы ақпарат сұраңыз.'),
  ('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6', 'Сиқырлы ертегі уақыты 🪄', 'Бүгін кешке өзгеше ертегі айтып көріңіз: ұйықтағанды жақсы көретін сиқырлы бұлт туралы. Даусыңызды бәсеңдетіп, ертегіге сай көңіл күй қалыптастырыңыз.'),
  ('ae31e811-95f5-438c-9d8f-7b39b14eed84', 'Заттарды орнына салуға талпыныс 🧸', 'Ойыншықты қорапқа салып, қайта шығара ма? Ол «ішінде» және «сыртында» деген ұғымдарды танып-біліп жүр.'),
  ('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981', 'Су ішуді әдетке айналдырамыз. 💧', 'Қосымша тағаммен бірге су ұсынуды ұмытпаңыз. Қандай су ішетін ыдыстар қолайлы екенін Ұсынылатын өнімдер бөлімінен оңай таба аласыз.'),
  ('0b7b3ea8-6539-4606-ac0b-b0428466ace0', 'Еліктегіш тотықұс 🦜', 'Сіздің жөтелгеніңізге немесе күлгеніңізге еліктей ме? Бөлмедегі ең жақсы айна — өзіңіз. Оған ең әдемі мимикаларды үйретіңіз!'),
  ('df82eb33-3f1e-407f-b436-e4b5c122a87e', '300 күндік қуаныш! 🌟', 'Ертең үлкен, қос мерейтой! Бөпеңізге 10 ай әрі 300 күн толады! Үйде шағын мерекелік көңіл күй орнатып, телефоныңыздың жадын босатыңыз.'),
  ('19b97cb2-c4a1-4649-a316-a7b34bb3eed4', 'Бөпеңіз қаншама жолдан өтті!  📈', 'Алғашқы күндердегі толқудың орнын сенімділік басты. Сіз бұл жолдан үлкен жеңіспен өттіңіз, Сіз кереметсіз!'),
  ('1d119442-bc5b-4f46-a607-68533220e425', 'Сұрағыңыз бар ма? 🤖', 'Бөпеңіздің дамуына қатысты Сізді алаңдататын кез келген мәселені тіпті түнде де Anacan AI көмекшісінен сұрап, маман қолдауын алыңыз.'),
  ('dd2f968e-d28b-4ab1-9758-59cda94c35f6', 'Керемет 10 ай және 300 күн! 🎉', 'Құттықтаймыз! Сіз осы ғажайыпты тура 300 күн, толық 10 ай бойы өсіріп келесіз.'),
  ('249e422f-5203-4598-a063-3032744aab4c', 'Суды өзі ішкісі келеді 💧', 'Кесесін өзі ұстап ішкісі келеді, бірақ судың көбі үстіне төгіле ме? Оның өз бетінше әрекет етуге талпынысын қолдаңыз, дымқыл майлықтар дәл осындай сәттер үшін керек.'),
  ('88ed955b-e80f-4226-9234-7112a99a4951', 'Серіктесіңіздің қуат жинайтын уақыты 🔋', 'Күндіз бар күш-қуатыңызды бөпеңізге арнадыңыз. Бүгін кешке жұбайыңыз бөпеңізбен уақыт өткізсін, ал Сіз демалып, офлайн режимге ауысыңыз.'),
  ('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb', 'Алғашқы сүйенішсіз секундтар 🧗‍♂️', 'Диваннан ұстап тұрған кезде кенет қолын жібере ме? Ол тепе-теңдік сақтауды үйреніп жүр! Осы қысқа, бірақ толқынысқа толы сәттерде құлап қалмауын мұқият қадағалаңыз.'),
  ('80ecdccb-340a-49ab-94a9-ff073855c0a0', 'Не пісірсем екен? 🍲', 'Қосымша тамақ мәзіріне арналған идеяларыңыз таусылды ма? Интернеттен іздеп әуре болмаңыз. Anacan AI-дан 10 айлық бөпеге арналған оңай саусақпен жейтін тағамдар тізімін сұраңыз.'),
  ('b8e6e605-baf6-44b6-9e44-842e0b7a0af0', 'Әңгімеге қосылады 🗣️', 'Сіз телефонмен сөйлескенде, ол да өз тілінде бірдеңе айтып, дауысын көтере ме? Қарым-қатынас дағдысы қарқынды дамып келеді — енді бөлмеде екінші спикер бар!'),
  ('c9db13f9-8aff-4b71-a7fa-bdce47336917', 'Кенет айғайлап оянды ма? 😭', 'Түнгі қорқыныш ұстамалары басталуы мүмкін. Дауысын Жылауды талдау құралына тыңдатып, мәселенің физикалық немесе психологиялық екенін анықтаңыз.'),
  ('63090d6e-b5fb-4db8-bce4-2e5749468a34', 'Кітаптарға қызығушылық 📖', 'Кешкі әдеттеріңізге қағаз кітап оқуды қосыңыз. Ол енді кітап беттерін өзі аударуға тырысады. Дауыс ырғағыңызды ертегінің қарқынына сәйкестендіріңіз.'),
  ('64ab60a5-a744-4f7e-a8a1-28b04eede9d6', 'Тамақ мұнарасы құлады 🥣', 'Орындығынан қасықты немесе тамақты әдейі жерге тастап, кейін Сізге қарай ма? Ол шекаралар мен тартылыс күшін сынап жүр. Сабыр сақтаңыз.'),
  ('cd288f90-d6da-4851-9b9a-2a8e15ba81fb', 'Өзгерген денеңіз 👗', 'Айнадағы дене бітіміңізге қарап көңіліңіз түсе ме? Сіз осы денеңізбен дүниеге адам әкелдіңіз. Көңіл күй күнделігіне өзіңізге арналған алғыс сөздерін жазыңыз.'),
  ('0e1a794c-f019-4037-b108-0a10db7b5f9f', 'Үнсіз қаһарман 🤫', 'Бөпе ұйықтаған сәтте үйдегі әр дыбыс бомба жарылғандай естіледі. Дыбыс өлшегішпен бөлмедегі дыбыс деңгейін реттегенде, өзіңіз де ақырын жүруге тырысыңыз.'),
  ('cb2d76e0-4e92-41f1-9153-3b4a29404a17', 'Шкаф детективі 🕵️‍♀️', 'Асүйдегі барлық қазан еденде жатыр ма? Рұқсат етіңіз, қауіпсіз заттармен ойнау оның логикалық ойлау қабілетін дамытады. Тек өткір заттарды алысқа қойыңыз.'),
  ('d194240e-ae66-4f32-83ef-39ade449ccb6', 'Аналардың сырласуы 💬', '«Менің балам неге әлі еңбектемейді?» деген сияқты сұрақтар мазаңызды ала ма? Anacan қауымдастығына жазыңыз. Әр баланың өзіне сай мінсіз даму қарқыны бар екенін көресіз.'),
  ('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2', 'Аналарға арналған энергия көзі! 🥗', 'Қимыл-қозғалысы көп бөпенің соңынан жүгіру үшін күш керек! Әйелдерге арналған пайдалы рецептер бойынша дәруменге бай салат немесе смузи дайындаңыз.'),
  ('a261deac-e213-48df-a6bd-e43793de79c9', 'Әкенің массаж салоны 💆‍♀️', 'Жұбайыңыз бөпені ұйықтатсын, содан кейін тартылып қалған мойын бұлшықеттеріңізді босаңсыту үшін иығыңызға 5 минут массаж жасасын!'),
  ('3995ea79-4422-4b71-b376-6426966b7d85', 'Таза ауа — ем 🌳', 'Күні бойы жылап, мазасыз болды ма? Шешімі өте қарапайым: ауа райын ескеріп, лайықты киіндіріңіз де, арбасына отырғызып, бірден саябаққа шығыңыз.'),
  ('b67edfc6-e141-41a3-866c-78583fe5c77b', '10 айға небәрі 5 күн қалды! 🎂', 'Маңызды күнге аз-ақ қалды! 10 айлығына арналған торт пен киімдерді дайындайтын кез келді. Алғашқы туған күніне қадам-қадаммен жақындап келесіздер!'),
  ('da354848-a7ac-41ba-9616-ccf0b8799a86', 'Ұйқы белгілері 🥱', 'Көзін уқалап, бір нүктеге қарап қалса, қатты мазасыздануын күтпеңіз. Бөлмені бірден қараңғылап, ұйқыға дайындау рәсімін бастаңыз.'),
  ('049b837c-5a26-4c32-95e4-e745b4a3443b', 'Қолынан бір нәрсені алғанда қарсылық білдіріп, жылай ма? 🧸', 'Меншік пен жеке тұлғалық сезімі дамып келеді. Бұл — психологиялық дамудың өте табиғи кезеңі.'),
  ('06a37325-84f4-4012-b4a0-ff317ba78e4c', 'Сау бол дейміз! 👋', 'Кетіп бара жатқан адамдарға қол бұлғауды үйренді ме? Оның осы саналы әрі сүйкімді қимылын бөпе фотосессиясы арқылы бірден естелікке сақтап қойыңыз.'),
  ('69b02f6b-1a0a-4f09-860a-f56dfb370b0a', 'Үйдегі қауіпсіздік шаралары! 🛡', '️ Ол орнынан тұруға талпынған сайын қауіп те арта түседі. Балаларға арналған құлыптар мен бұрыш қорғағыштарын табу үшін Ұсынылатын өнімдер тізімін міндетті түрде қараңыз.'),
  ('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6', 'Өзіңізге уақыт бөліңіз. 🛁', 'Бөпеңіз ұйықтап жатқанда, шашыңыз бен теріңізге күтім жасап, демалыңыз.'),
  ('87dbc3cb-466d-4628-b1df-07cce718a3ab', 'Өзі тамақтанғанды ұнатады! 🥦', 'Қосымша тағам жей бастаған бөпелерге Рецепттер бөлімінен қолға ұстауға ыңғайлы, пайдалы тағамдар дайындаңыз.'),
  ('9b804616-ae80-4d37-b6a9-76004e3e5506', 'Қарапайым нұсқауларды түсінеді! 🧠', '«Мынаны маған бер» дегенде, ойыншығын Сізге ұсына ма? Осы зияткерлік серпілісті қолдау үшін Блогтардағы дамытуға арналған мақалаларды оқыңыз.'),
  ('dffa4555-16c2-4705-a09e-e04f9ae6d25d', 'Үй шаруасы қалып бара ма? Қала берсін.  🌪️', 'Жұбайыңыздан бүгін үй шаруасын өз мойнына алуын өтініңіз. Сіз демалыңыз.'),
  ('f2c9cd05-6f08-42dc-b88f-310abadaba89', 'Түнгі тыныштық 🛀', 'Жылы ванна, массаж және бөлмені қараңғылау. Ұйқы тәртібін сақтау — түні бойы үзіліссіз ұйықтаудың басты құпиясы.'),
  ('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85', 'Еденнен не тапса да, асқан қызығушылықпен зерттейді.  🗑️', 'Бәрін қолынан жұлып алып, ашуланбаңыз — ол кішкентай зерттеуші. Тек бақылауда ұстаңыз.'),
  ('7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'Қарны ашты ма, әлде шаршады ма? 😭', 'Себепсіз жылағанда абдырап қалмаңыз. Жылауды талдау мүмкіндігін пайдаланып, мәселенің себебін тез анықтап, шешіңіз.'),
  ('cc7b8905-a439-46c1-8d92-ea81667052be', 'Әкенің жұбату күші 🫂', 'Түнде бөпе оянғанда, кезекпен тұрыңыздар: бірде Сіз, бірде жұбайыңыз. Жүктемені бір команда ретінде тең бөлісіңіздер.'),
  ('29cc3dd1-d28b-45c9-93d7-58bfda48629c', 'Сұқ саусақ белсенді ☝️', 'Алыстағы мысықты немесе ойыншықты саусағымен көрсетіп, оған назар аударады. Бұл — зейінді бағыттаудың ең жоғары кезеңі.'),
  ('6eab5294-c731-4890-971d-ad01e35f7d7c', 'Саябақ па, әлде үй ме? ⛅', 'Сыртқа шыққыңыз келеді, бірақ жел соғып тұр. Ауа райы және киім көмекшісі температураны ғана емес, жел өткізбейтін қандай киім кигізу керегін де айтып берсін.'),
  ('edfb2fd4-70c3-4b15-b2d1-0fc891b31501', 'Әкесінің күлкілі қылықтары 🤡', 'Бөпені күлдірудің ең жақсы жолы — әкесінің қызық дыбыстар шығаруы. Бүгінгі кештің көңілді сәттерін Бөпе фотосессиясы арқылы естелікке айналдырыңыз.'),
  ('9b064bbe-67b8-4d62-b3a0-30f79dc81515', 'Анасынан қалмау кезеңі 🥰', 'Тіпті дәретханаға кірсеңіз де, есіктің ар жағында Сізді күтіп, жылайды. Ажырасудан қорқу сезімі шегіне жеткен. Оған әр жолы «Мен осындамын» деп, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('e77deeee-d612-4dac-bea4-ec9f16608958', 'Бүгін Ақылды ертегіде 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрастырыңыз: күндіз шаршап, түнде жұлдыздарға ұшатын балақай.'),
  ('f0ba97cb-8dd2-4486-865e-1d22a5e551a6', 'Қалтаңыздағы тізім 🛒', 'Жеміс езбесін дайындауға алма таусылып қалды ма? Тізім жасауды серігіңізге тапсырыңыз. Сатып алу тізіміне жазыңыз, ал дүкенге бару — оның міндеті.'),
  ('26bb2530-b202-43eb-9226-30863365843e', 'Ас қорыту үдерісін бақылаймыз. 🧷', 'Әртүрлі қатты тағамдар үлкен дәреттің сипатын өзгертеді. Жөргек ауыстырған сайын Anacan-да белгілеп, бөпеңіздің денсаулығын бақылаңыз.'),
  ('32966fee-53d4-4975-ad1e-195457a2fa5c', 'Ұйқысыз түндер 🥱', 'Ұйықтамау үшін бар күшімен қарсылық көрсетіп жүр ме? Күндізгі ұйқының бірін қысқартатын уақыт келген болуы мүмкін. Күн тәртібін қайта қарап шығыңыз.'),
  ('b5660557-30c8-45a9-9c75-69616076d9ce', 'Аналарға арналған орын ☕', 'Үйде отыра беріп, күшіңіз таусылды. Анаға жайлы орындардың ішінен балалар мәзірі бар әрі еркін отырып демалуға болатын дәмхананы таңдап, өзіңізге уақыт бөліңіз.'),
  ('221ab24d-c8af-4cca-b9d8-b4eae15499d0', 'Өзіңізді мақтаңыз 👏', 'Бөлменің шашылып жатқанына емес, бөпеңіздің бүгін қаншалықты бақытты болғанына қараңыз. Сіз ешбір кітап үйрете алмайтындай керемет анасыз.'),
  ('cdf44716-8a24-472d-9ff5-449bcc14a7fe', 'Музыкаға билеген дене 🎶', 'Теледидардан немесе телефоннан ырғақты әуен ести салысымен, бөксесін бұлғаңдата бастайды. Музыканы сезіну қабілеті дамып келеді, Сіз де оған қосылып билеңіз!'),
  ('d3e69c0c-c087-4266-8819-3e9aa9fc132a', 'Массаж уақыты 💆‍♂️', 'Бөпеңіз ұйықтағаннан кейін күндізгі күйзелісті басу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыздар. Сіздер бір командасыздар!'),
  ('12c2a250-54bd-4e0d-a366-20c820596148', 'Жедел педиатр 🤖', 'Бөпеңіздің денесінде аздап қызару бар ма? Дәрігерге бармас бұрын Anacan AI-дан тағамдық аллергияның белгілері туралы жедел ақпарат алыңыз.'),
  ('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec', 'Есіміне жауап беруі 🗣️', 'Шақырған кезде Сізге қарап қана қоймай, тіпті істеп жатқанын тастап, Сізге қарай келуге тырысады.'),
  ('c7423d2f-6f9f-452c-9de2-5dea29b29f93', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйықтардан 1 сағат бұрын үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш әрі көмескі жарық ортада бөлінеді.'),
  ('100bd53c-84e3-4c7e-8a31-2a287a02c440', 'Өзіңізді кінәламаңыз 📝', 'Бүгін онымен аз ойнадым деп ойлайсыз ба? Сапалы өткізілген 10 минут шаршаған күйде өткізілген 1 сағаттан құндырақ.'),
  ('fd0252a6-07bf-4750-bd4b-be91888e16f6', 'Үлкендерге еліктеу 🧹', 'Сіз үйді сүртіп жатқанда, ол да қолына шүберек алып, дәл солай істеуге тырыса ма? Ол — айнаңыз! Сіздің әр әрекетіңізді қайталайды.'),
  ('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75', 'Бір-біріңізді қолдау 🥂', 'Күн бойғы шаршауды ұмыту үшін серігіңізбен бірге шай ішіп, бір-біріңізге «Бүгін де бәрін еңсердік» деңіздер.'),
  ('ac527e8b-ca16-4272-b6ba-964f15ba419b', 'Педиатрға қатысты сұрақтар 🤖', '10 айлық баланың порциясы қандай болуы керек? Өзіңізді қинамай, Anacan AI-дан нақты әрі педиатр мақұлдаған кесте сұраңыз.'),
  ('e38208ca-c817-4de4-ba96-5a5ca4752901', 'Қызыл иектің қышуы жалғасуда 🦷', 'Саусақтары үнемі аузында болып, кез келген затты кеміре ме? Артқы тістері шығып келе жатқан болуы мүмкін. Жағдайды тіс шығуын бақылау құралында тіркеңіз.'),
  ('0535564e-f2c8-4264-bd71-a94e3154d928', 'Ауа райын білу ⛅', 'Сырттағы ауа райы түсініксіз бе? Ауа райы мен киім таңдау құралы терезеден байқалмайтын желдің жылдамдығын және лайықты киім үйлесімін бірден айтып береді.'),
  ('51cec612-e243-435d-9b60-1e3269d69cee', 'Музыкалық кештер 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — оның сүйікті әнін қосып, құшақтап бірге билеу.'),
  ('533a4ec1-68c0-4cf3-92cd-723b3f8c0979', 'Аяқ киімін өзі шешеді 👟', 'Киіндіру күреске айналып кетті ме? Ол шұлығы мен аяқ киімін өзі тартып шешеді. Қимыл-қозғалыс дағдысына сүйсініңіз!'),
  ('7bbccad8-a83a-493c-82e1-d823d261e04b', 'Логикалық ойындар 🧩', 'Ойыншықтарды қорапқа салып, кейін бәрін қайта төге ме? Осылайша «ішінде» және «сыртында» ұғымдарын түсіне бастайды. Бұл әрекетіне кедергі жасамаңыз.'),
  ('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777', 'Ертегімен ұйқыға кету 🪄', 'Ақылды ертегілерде тек музыка мен табиғат дыбыстарынан тұратын ерекше фон жасаңыз. Сөз жоқ, тек тыныштық бар.'),
  ('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac', 'Саябақпен достық 🌳', 'Бөпеңізге арбамен серуендеу қызықсыз болып кетті ме? Ауа райы мен киімін тексеріп, саябақта шөп пен жапырақтарды ұстап көруіне мүмкіндік беріңіз.'),
  ('d3bac322-3971-4b22-8636-d789ac7ce8db', 'Қабырғадан ұстап жүр 🧗‍♀️', 'Жиһаздың жиегінен ұстап, жанымен қадам басу — оның сүйікті жаттығуы. Қауіпсіздік қорғаныштары мен өткір бұрыштарды тағы бір рет тексеретін кез келді.'),
  ('6498b35b-aa8e-416f-9da1-2596c74b14d0', 'Сау бол дейміз 👋', 'Біреу есіктен шыққанда, өзі қол бұлғап қоштасады! Бұл — тамаша әлеуметтік рефлекс.'),
  ('b49f5612-c3e4-4568-8a0e-3494499a88d1', 'Түн ортасында себепсіз тоқтаусыз жылап оянды ма? 😭', 'Ақырын құшақтаңыз, оятуға тырыспаңыз. Дыбысын Жылауды талдау құралына тыңдатып, себебін анықтаңыз.'),
  ('fd05df6d-36c8-4c59-9212-7542837f9f4c', 'Ішіңіздегіні бөліскіңіз келе ме? 💬', '«Мен енді ешқашан бұрынғыдай бола алмаймын» деген ой Сізді мазалай ма? Осы өткінші сезімді Anacan қауымдастығындағы аналармен бөлісіңіз, Сіз жалғыз емессіз.'),
  ('188836b2-55a8-4b14-87fe-653f4e05ae3e', 'Бүгін бәріне ашуландыңыз ба?', 'Бөпеңіз ұйықтағанда, көңіл күй күнделігіне сезімдеріңізді жазыңыз. Ертең жаңа әрі жақсырақ күн болады.'),
  ('4d566d24-14b9-45b0-be5d-1940c1563ed9', 'Жылдам сауда 🛒', 'Жұбайыңыз жұмыстан шығып келе ме? Дереу Сатып алу тізімін ашып, сүт, жеміс-жидек және үйге қажет басқа заттарды бірнеше секундта жіберіңіз.'),
  ('16cae145-7589-4ff6-ae2c-368fe115d232', 'Сезімдерді басқару 📝', 'Жүйкеңіз жұқарып, кез келген сәтте жарылып кетуге дайынсыз ба? Барлық күйзелісті көңіл күй күнделігіне жазып, терең тыныс алыңыз.'),
  ('9b99e928-dd9a-40d6-9254-12459dac4a3d', 'Қараңғылықпен достасу 🌙', 'Бөпеңіздің тезірек ұйықтауы үшін кешкі дағдысына қараңғылыққа үйренуді қосыңыз. Бөлмедегі барлық артық жарықты өшіріңіз.'),
  ('ee2e2e79-277e-4a7f-9473-05aa36068880', 'Дене мүшелерін таниды 👀', '«Мұрның қайда?» деп сұрағанда, саусағымен түртіп көрсете ме? Ақыл-ойының дамуы шарықтау шегінде!'),
  ('2cb20f11-aee5-456a-b969-c87733104c72', 'Жеңісті кеш 🥂', 'Бүгін кешке бөпе ұйықтағаннан кейін жұбайыңызбен бірге «Біз керемет командамыз!» деп тост айтыңыз. Сіздер шынымен тамаша жұмыс атқарып жүрсіздер!'),
  ('57b926b9-28cb-4c4e-8863-8ce72241c9fe', 'Аллергияға күмән 🤖', 'Жаңа тағам беріп, бөпеңіздің беті қызарғанын байқадыңыз ба? Абыржымас бұрын, алғашқы қадамдар туралы Anacan AI-дан сұраңыз.'),
  ('9c11d140-acfd-48e4-9fef-141a9e34586d', '«Өзім жеймін» деген қырсықтық 🥦', 'Қасықты қолыңыздан алғысы келеді. Ала берсін. Үсті-басы былғанады, бірақ бұл дербестік сезімі ол үшін өте маңызды.'),
  ('09817e37-4e65-43f6-968c-dd333358e01e', 'Қажетті заттар тізімі таусылмайды 🛒', 'Күнделікті қарбаласта сусабын таусылды ма, әлде жөргек пе? Бәрін есте сақтауға тырыспай, Сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('1f244347-1957-4238-988d-4563adba7bcd', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жетеді. Кешке бөпені ұйқыға дайындау және ертегі оқу — тек әкесінің міндеті.'),
  ('84cdedf9-5de5-49c9-887b-6f8ccc988990', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнгі оянулардың бар ауыртпалығын жалғыз көтермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('a4c45285-b9cc-4763-a80c-d694137bbb6a', 'Анаға жайлы орын табыңыз ☕', 'Осындай шаршаудың арасында Сізге де таза ауа жұтып, сергіп алу қажет. Анаға жайлы орындардан жақын маңдағы тыныш дәмхананы тауып, барып қайтыңыз.'),
  ('37e8bf23-2dc4-4b8c-8c8f-49146922ba57', 'Талпыныс пен қателік 🧱', 'Екі ойыншық текшені бірінің үстіне бірін қоюға тырысады, бірақ олар құлап қалады. Содан кейін мұқият қайтадан байқап көреді. Оның осы кішкентай инженерлік талпыныстарын үнсіз бақылаңыз.'),
  ('732cb07a-0e5f-4dc9-9d15-78470db05396', 'Тағам идеялары 🍲', 'Бір тағамдарды қайта-қайта дайындаудан шаршадыңыз ба? Пайдалы рецептілерден 10 айлық балаларға арналған жаңа әрі дәмді, қолмен жеуге ыңғайлы тағамдарды қарап көріңіз.'),
  ('a387d51e-9e9d-455a-be61-4650ee6ffa63', 'Тыныш бөлме, тыныш ми 🤫', 'Ұйқыға дайындалар кезде бөлмедегі дыбыс деңгейін төмендету қажет. Дыбыс өлшегішпен өз даусыңыз бен айналадағы шудың деңгейін тексеріңіз.'),
  ('439ac8e3-ab5f-434a-bb69-d98dee8208cd', 'Арнайы ертегі 🪄', 'Ақылды ертегілерде небәрі 10 күннен кейін тағы бір айға өсетін кейіпкер туралы хикая құрып, бөлмені сиқырға бөлеңіз.'),
  ('e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769', '11 айға небәрі 10 күн қалды! 🎂', 'Сенгісіз! Тура 10 күннен кейін бөпеңіз 11 айға толады. 1 жасқа толу мерекесінің жоспарын ойластыра бастайтын кез келді!'),
  ('ff800946-b6d3-4e88-8699-fe114e37b692', 'Күлкісін суретке түсіріңіз 📸', 'Ол күн сайын өзгеше мінезі бар сүйкімді жан болып өсіп келеді. Дәл қазір Бөпе фотосессиясын ашып, суретті стикерлермен безендіріңіз де, осы көңілді сәтті мәңгіге сақтап қойыңыз.'),
  ('42ea49cf-0e72-4699-aaf4-7633e9ea6a82', 'Уақытты тоқтатар кадр 📸', 'Ол күн сайын балаға көбірек ұқсап, бөпелік келбеті біртіндеп жоғалып барады. Дереу Бөпе фотосессиясын ашып, оның осы өзгерісін суретке түсіріңіз.'),
  ('a0c5dfe0-02f0-4961-8b06-219cd57dde9d', '11 айға жақындағанының алғашқы белгілері! 🎈', 'Назар аударыңыз! Небәрі 20 күннен кейін бөпеңіз 11 айға толады, ал біз 1 жасқа дейінгі үлкен кері санақты бастаймыз. Күлімдеңіз!'),
  ('6032f94e-69e7-4802-b291-44567c9f71d1', 'Әкенің бесік жыры 👨‍🍼', 'Бүгін кешке бөпені бөлмеде өз бетінше ұйықтатып көру кезегі жұбайыңызда.'),
  ('7b460d4a-b37e-465f-9c70-e137f59bcc07', 'Үй жинау ма, әлде демалу ма? 🛋️', 'Бөпе ұйықтағанда ыдыс жуғыш машинаға қарай жүгірмеңіз. Диванға жатып, көзіңізді жұмыңыз да, 15 минут бойы жай ғана тыныстаңыз. Сіз робот емессіз ғой.'),
  ('a1392cb5-508d-45a8-9d3d-1985c8d19958', '«Жоқ» шайқасы басталады 🛑', 'Енді оған ұнамайтын нәрсені ұсынсаңыз, басын шайқап, итеріп жібереді. Оның ерік-жігері қалыптасып келеді. Кішкентай шешімдеріне құрметпен қарауға тырысыңыз.'),
  ('2cc5ac97-f2b1-4c92-8852-fec32f54b311', 'Дыбысты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен бөлмедегі шу деңгейін тексеріп, кенеттен шығатын қатты дыбыстардан сақ болыңыз.'),
  ('e0b42cd5-f681-4866-a7ec-b0b890444381', 'Дені сау ана, дені сау бөпе 🥑', 'Ағзаңыздағы темір мен кальций қоры азайған. Пайдалы рецептілердің ішінен тез дайындалатын әрі бойыңызға қуат беретін нәрлі салат әзірлеңіз.'),
  ('e83a5069-7214-47ea-9051-6406495d5723', '«Ойыншығымды бер!» деген қырсықтық 🧸', 'Қолынан бір нәрсені алсаңыз, қатты қарсылық білдіріп, жылайды. Меншік сезімі толық қалыптасып келеді. Тыйым салудың орнына назарын басқа нәрсеге аударыңыз.'),
  ('9f618083-9332-44d7-8a8f-8ad3af6c22ac', 'Үйдегі заттың бәрі — ойыншық 🥄', 'Пластик ыдыстар мен ағаш қасықтар оған ең қымбат ойыншықтан да қызығырақ. Асүйдегі заттарды емін-еркін зерттеуіне мүмкіндік беріңіз.'),
  ('354e039c-3978-4aa3-a008-1a3a7bbe85a3', 'Жылауды талдау көмекке келеді 😭', 'Түн ортасында оянып, жылауын тоқтатпай жатыр ма? Болжай бермей, Жылауды талдау арқылы себебін бірден анықтаңыз.'),
  ('8fb53566-815d-4365-b87c-c14288ebb122', 'Таза ауа — нағыз құтқарушы 🌳', 'Үйде мазасыздана бастаса, ауа райы мен киімін тексеріп, арбасына отырғызыңыз да, бірден саябаққа шығыңыз. Табиғат — оны тыныштандырудың ең жылдам жолы.'),
  ('c87df5f1-fbe2-4462-a617-a6649445ce77', 'Қыңырлығы шегіне жетті ☁️', 'Ештеңеге көңілі толмай, бәріне жылай ма? Бұл өсу секірісінен немесе тіс жару кезіндегі мазасыздықтан болуы мүмкін. Оны көбірек құшақтай беріңіз.'),
  ('7fd53d22-26ef-4c4c-83bb-d44647b94560', 'Бірге шешейік 💬', '«Менің балам неге бұлай істейді?» деген сұрақтан шаршадыңыз ба? Anacan қауымдастығына кіріп, мыңдаған үйде дәл осындай жағдай болып жатқанын көріңіз!'),
  ('a6ef3f7c-7550-4712-8fc9-23c742a51744', 'Ұйқыға дайындық 🛀', 'Жылы ванна әрдайым көмектеседі. Кешкі әдеттегі тәртіпті ешқашан бұзбаңыз, өйткені ол бөпенің миына қазір ұйықтайтын уақыт келгенін білдіреді.'),
  ('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb', 'Құлап-тұрып үйрену 🧗‍♂️', 'Тік тұрған кезде бөксесімен құлап, күледі де, қайта тұрады. Мұндай құлаулар бұлшықет жадын қалыптастырады, сондықтан тым көп араласпаңыз.'),
  ('25903ac8-0fd6-44f0-92d8-c3e1bee035e5', 'Тыныштық қажет 🤫', 'Ұйықтап бара жатқанда болмашы сыбдырдан оянып кете ме? Дыбыс өлшегішпен ортаны талдап, үздіксіз тыныштықты қамтамасыз етіңіз.'),
  ('932e2f32-ffee-4b5c-9d10-16c135453b42', 'Ертең — үлкен күн! 🎉', 'Дайынсыз ба? Ертең бөпеңіз тура 11 айға толады! 1 жасқа дейін соңғы 1 ай қалды! Бөпеңіздің фотосессиясына ерекше орын мен киім дайындаңыз.'),
  ('aac354e5-8061-403a-8cf7-d00ce05e4093', 'Бірлік рухы 🥂', 'Көңіл күй күнделігін ашып, жұбайыңызбен алғашқы күндерді еске алып, бірге күліңіздер. Осы 11 айға жету Сіздерге оңай болған жоқ!'),
  ('d24d332c-e00e-4b7f-8dac-28439e172c26', 'Ананың кофе үзілісі ☕', 'Бөлмедегі шашылған заттар ешқайда қашпайды, ал Сіздің күшіңіз таусылуы мүмкін. Балаңыз өздігінен ойнап отырғанда, бірден үй шаруасына кіріспеңіз. Отырып, кофеңізді ішіңіз.'),
  ('6ef8817b-2854-4da4-969a-fe13d344017a', 'Жеңіс биі 💖', 'Осы кеште 11 айдың шаршауы мен мақтанышын жұбайыңызбен бірге атап өтіңіз. 1 жасқа дейінгі соңғы кезеңге аяқ бастыңыздар!'),
  ('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b', 'Ана сүті әлі де маңызды! 🍼', '1 жасқа дейін ана сүті маңызды. Тамақтандыру таймерін қосып, бөпеңіздің сүтке деген күнделікті қажеттілігі өтеліп жатқанына көз жеткізіңіз.'),
  ('ad9c3e79-16bb-44a7-9f37-6f5935a4494c', 'Тура 11 ай! 🎂', 'Құттықтаймыз! Босанғаныңызға тура 11 ай болды! Дәл қазір «Бөпе фотосессиясынан» 11 айлық стикерді таңдап, осы қуанышыңызды Anacan қауымдастығында бөлісіңіз!'),
  ('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f', 'Қауіпті аймақтарға қол жеткізу ⚡', 'Бөпеңіздің бойы өсіп, бұрын қолы жетпеген сөрелерге енді жете алады. Үйдің қауіпсіздігін (өткір бұрыштар, ауыр заттар) қайта тексеріңіз.'),
  ('8a4a7da2-606f-4fbb-8668-101f2d47c03c', 'Музыканың күші 🎶', 'Кешкісін аяқ астынан басталатын мазасыздықты баяу классикалық музыкамен басып көріңіз. Көбіне осы қарапайым тәсіл керемет әсер береді.'),
  ('3a5c700f-e10c-4819-bba1-cddd9f951f4f', 'Тізімдер мен ұмытшақтық 🛒', 'Ойыңыз әлі де тұманданып жүр ме? Үйге керек ұсақ-түйекті есте сақтауға тырыспай-ақ, бірден Сатып алу тізіміне қосыңыз — қалғанын жұбайыңыз реттесін.'),
  ('47b342b1-9525-44b6-b917-2eb642240cb2', '«Сізді жақсы көремін» деген құшақ 🫂', 'Кенеттен келіп мойныңыздан құшақтай ма немесе бетіңізден сипай ма? Ол енді сүйіспеншілігін қимылымен білдіре алады. Осы сәттен ләззат алыңыз.'),
  ('361e96e8-a6ed-4fdf-a7bb-50e07abcec66', 'Түнгі тыныштық 🪄', 'Ақылды ертегілерде батыл әрі сүйкімді жануарлар туралы хикая құрып, бөлмені сиқырлы әлемге айналдырыңыз.'),
  ('a4baaa67-c9fb-4208-aab7-e7515b21f64f', 'Оны тойдыру үшін бәрін жасайсыз. Ал өзіңіз ше?', 'Пайдалы рецептер бөлімінен темір мен ақуызға бай түскі ас таңдап, күш жинаңыз.'),
  ('c58c8b30-4c95-4f60-98d7-d9580eb48a38', 'Кітап беттерін аудару 📖', 'Қалың беттері бар кітаптың парақтарын өзі толық аудара ма? Қимыл-қозғалыс дағдысындағы осы жетістікті Даму трекеріне белгілеңіз.'),
  ('2631ed9f-967a-4f12-9097-1f619f7f1e5f', 'Бүгін ештеңе жоспар бойынша болмады ма?', 'Бөпе ұйықтағанда өзіңізді кінәламаңыз. Сіз — шынайы анасыз, Сіз кереметсіз.'),
  ('34415812-3e31-43f2-99de-a1dd76bb1d9e', 'Нысанаға дәл лақтыру ⚾', 'Қолындағы ойыншықты әдейі белгілі бір нысанаға лақтыруға тырысады. Көз бен қол үйлесімі қарқынды дамып келеді.'),
  ('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4', 'Жедел педиатр 🤖', '11 айлық бөпе күндіз қанша уақыт ұйықтауы керек? Күмән тудырған кез келген сұрақты Anacan AI-дан бірден сұрап, көңіліңізді тыныштандырыңыз.'),
  ('a70ebacf-44d0-4367-babf-09742bda8fa8', 'Бір жасқа дайындық басталды! 🎈', '11 айды артқа тастадық. Небәрі 30 күннен кейін бөпеңіздің алғашқы туған күні! Арнайы тақырып, мерекелік орын әлде үйде ғана атап өту ме? Жоспарлауды асықпай бастай беріңіз.'),
  ('0387bc9b-1c64-4eae-ac49-660cb56552f8', 'Ойыншығымды өзім табамын 🧸', 'Көзінен таса етіп, бір жерге жасырған ойыншықты барып тауып ала ма? Демек, ол заттың көзге көрінбесе де бар екенін толық түсінеді!'),
  ('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпеңіз оянғанда, бар ауыртпалықты жалғыз көтермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('89a2b668-b451-4cfe-a183-3183fc159297', 'Сезімдеріңізге ерік беріңіз 📝', 'Бөпеңіз 1 жасқа жақындаған сайын, көңіліңізді біртүрлі мұң басып, «Қалай тез өсіп кетті!» деген сезім пайда болды ма? Осы сезімдеріңізді Көңіл күй күнделігіне жазыңыз.'),
  ('23c2a94e-cf0d-4f81-9604-79b4dcfb2460', 'Төрт қабырғадан тысқа шығыңыз ⛅', 'Үйде отырудан жалықтыңыз ба? Ауа райын тексеріп, бөпеңізді лайықты киіндіріңіз де, саябақта шөп пен жапырақтарды еркін ұстап көруіне мүмкіндік беріңіз.'),
  ('77a8c135-4a26-4877-9f24-fc51c941fb7a', 'Киінгенде көмектеседі 👕', 'Көйлегін кигізгенде қолдарын өзі соза ма немесе аяғын көтере ме? Ол Сізбен ынтымақтасып жатыр. Осы кішкентай көмегін Даму трекеріне белгілеңіз.'),
  ('9df28291-b590-4e7d-a861-feb0732398b2', 'Қараңғылықпен достасу 🌙', 'Тезірек ұйықтап кетуі үшін кешкі дағдыға қараңғылыққа үйренуді қосыңыз. Бөлмедегі барлық артық жарықты өшіріңіз.'),
  ('72f5aeb4-94f9-40bc-943e-fa87664da32b', 'Форумдардан адаспаңыз 🤖', 'Бөпеңіздің қимылынан біртүрлі нәрсе байқадыңыз ба? Интернеттен сағаттап іздемей, сұрағыңызды бірден Anacan AI-ға қойып, көңіліңізді тыныштандырыңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e'::uuid, 'Дені сау ана, дені сау бөпе 🥑', 'Темір мен кальций қорыңыз сарқылған. Пайдалы рецепттерден тез дайындалатын әрі бойыңызға қуат беретін нәрлі салат жасап көріңіз.'),
  ('7883fd83-494d-41a3-b42d-58d452de13d7', 'Әкенің көңілді қылығы 🤡', 'Бөпені күлдірудің ең жақсы жолы — әкесінің қызық дыбыстар шығаруы. Бүгінгі кештің көңілді сәттерін балаңызбен бірге тамашалаңыз.'),
  ('981d8d60-ab26-4f64-a20b-eee1dc2fed12', 'Ұсақтап туралған тағамдарға толық көшу! 🍲', 'Ол енді шайнауды қажет ететін тағамдарды жей алады. Қолданбамыздағы «Қосымша тағамды бастаған бөпелерге арналған рецепттер» бөлімінен жаңа құрылымды тағамдарды байқап көріңіз.'),
  ('74f02405-1cdd-401e-bb47-01d87997f231', 'Өз бетінше ойнайтын уақыт 🧸', 'Ол енді 10-15 минут бойы ойыншықтарымен өз бетінше ойнай алады. Бұл — зейін қою ұзақтығының артқанының белгісі. Оны сырттай бақылап, тыныштықтан ләззат алыңыз.'),
  ('8d91b32b-a0f2-4a07-a181-da0b746268bc', 'Саябақ па, әлде үй ме? ⛅', 'Сыртқа шыққыңыз келеді, бірақ жел соғып тұр. Ауа райы және киім көмекшісі Сізге температураны ғана емес, жел өткізбейтін қандай киім кигізу керектігін де айтып берсін.'),
  ('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e', 'Қиын түндер 🥱', 'Ұйықтамау үшін бар күшімен қарсылық көрсетіп жүр ме? Күндізгі ұйқысы мен күн тәртібін қайта қарап шығыңыз.'),
  ('2f4fbaac-dfe4-48b5-b844-6636c2bc201a', 'Қалтаңыздағы тізім 🛒', '1 жасқа арналған тортқа тапсырыс беру үшін Anacan-дағы торт нұсқаларын қарап шығыңыз.'),
  ('395ddd9b-9009-4fec-ba6f-816d156ad432', 'Үлкен сезімдер, кішкентай дене 🛑', 'Қалағаны болмағанда өзін жерге тастап немесе жылап жібере ме? Ол әлі сезімдерін басқара алмайды. Көзімен бір деңгейде отырып, сабырмен сөйлесу арқылы мұндай ұстамаларды жеңіл өткізуге көмектесіңіз.'),
  ('c8b05bf8-0ed8-4eec-86f7-4cba168167e1', 'Сөздердің мағынасын біледі 🗣️', '«Допты әкел» десеңіз, шынымен барып допты іздейді. Сөздік қоры (түсінетін сөздері) жылдам артып келеді. Онымен күрделірек сөйлемдер қолданып сөйлесіңіз.'),
  ('f8aae6d9-1b70-4333-a55c-1937c871c533', 'Ақылды ертегі уақыты🪄', 'Ақылды ертегілерде небәрі 1 айдан кейін 1 жасқа толатын кейіпкердің хикаясын құрастырыңыз. Түнгі тыныштықты тек осы ертегі ғана бұзсын.'),
  ('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1', '1 жасқа дайындыққа қажетті безендірулер мен шарлар?  🛒', 'Басыңызды қатырмаңыз, Сатып алу тізімін қазірден бастап дайындаңыз.'),
  ('519cad33-f5e8-4169-8f1d-93f4343568db', 'Табанды талпыныстар 🧗‍♂️', 'Қолында ойыншығы болса да, жиһаздан ұстап орнынан тұруға тырысады. Тепе-теңдікті сақтау қабілеті керемет дамыған. Араласпай, сырттай бақылаңыз.'),
  ('aa2fb7c9-acf7-4050-9102-4f2927091b95', 'Үнсіз қаһарман 🤫', 'Ол ұйықтап кеткен сәтте үйдегі әрбір дыбыс бомба жарылғандай естіледі. Дыбыс өлшегішпен бөлмедегі шекті деңгейді реттегенде, өзіңіз де жай басыңыз.'),
  ('9cba5d69-92c6-472c-bb83-c5522d806018', 'Аналардың сырласуы 💬', '«Туған күнін қалай өткіземін?» деген ой Сізді шаршатты ма? Anacan қауымдастығына жазып, аналардан креативті әрі бюджетке сай идеялар алыңыз.'),
  ('f558e782-e140-4835-8b11-1d5f01a717bf', 'Уақытты тоқтатқан кадр 📸', 'Ол күн сайын бөпеден гөрі балаға көбірек ұқсап келеді. Дереу Бөпе фотосессиясын ашып, оның осы шынайы би сәтін естелікке айналдырыңыз.'),
  ('f56842a9-3a83-4016-8e93-a096810c45d3', 'Би мен ырғақтар 🎶', 'Теледидардан немесе телефоннан ырғақты әуен ести сала билей ме? Музыканы қабылдау қабілеті толық іске қосылған, оған қосылып билеңіз!'),
  ('d824145b-4905-49d1-9f4f-46ade8a730f8', 'Кенет айқайлап оянды ма? 😭', 'Бұл түнгі қорқыныш ұстамасы болуы мүмкін. Дауысын Жылауды талдау қызметіне тыңдатып, мәселенің физикалық па, әлде психологиялық па екенін анықтаңыз.'),
  ('a7923459-9b74-4330-949d-00e94d185768', '«Жоқ» сөзінің мағынасы! 🛑', 'Жасауға болмайтын нәрсені істегенде, енді Сіздің реакцияңызды бақылай ма? Тәртіпке үйретудің алғашқы қадамдары туралы Anacan AI-мен кеңесіңіз.'),
  ('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1', 'Массаж уақыты 💆‍♂️', 'Бөпе ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыз. Сіздер бір командасыздар!'),
  ('ef821341-2506-439d-8346-fbafb2b792ff', 'Бір жасқа небәрі 25 күн қалды! 🎈', 'Кері санақ ресми түрде басталды! 1 жасқа арналған фотосессияның орны мен киімін ойластырдыңыз ба? Дайындықты жеделдетіңіз!'),
  ('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea', 'Үйдегі қауіпсіздік шаралары! 🛡', '️ Бөпе өздігінен жүре бастаған сайын қауіп те артады. Балаларға арналған құлыптар мен баспалдақ қоршауларын Таңдаулы өнімдер тізімінен міндетті түрде қарап шығыңыз.'),
  ('959729c5-8ab6-4053-99ca-82aa5fdabc7e', 'Әкелердің күтімге атсалысатын уақыты. 👨‍🍼', 'Кешкі тамақтандырудан кейін кітап оқу мен ұйықтату кезегін әкесіне беріп, өзіңіз аздап мызғып алыңыз.'),
  ('a478b2eb-eaec-4b54-813a-6f2ba55a5d14', 'Бәрін сұқ саусағымен көрсетеді! ☝', '️ «Ол не?» деудің орнына бәрін саусағымен көрсетеді. Оның осы қызығушылығын Бөпе альбомында мәңгілікке сақтаңыз.'),
  ('97023662-0ba2-4bcd-aff7-bc7adf5883ba', 'Дыбысты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал уақыт. Дыбыс өлшегішпен бөлмені тексеріп, кенеттен шығатын қатты дыбыстардан сақ болыңыз.'),
  ('d02f135b-16bc-4fa9-978f-0e7d992c1ba4', 'Жинау ма, әлде демалу ма? 🛋️', 'Бөпе ұйықтағанда ыдыс жуатын жаққа асықпаңыз. Диванға жатып, көзіңізді жұмыңыз да, 15 минут бойы жай ғана тыныс алыңыз.'),
  ('f12c7751-b89f-4d12-a843-8e331c338393', 'Текшелерден қамал құрады 🧱', 'Екі немесе үш ойыншық текшені бірінің үстіне бірін қоюға тырысады. Оның осы кішкентай инженерлік талпыныстарын үнсіз бақылап, қол соғып қолдаңыз.'),
  ('35ab2e31-1937-4e58-b764-83729c6e330a', 'Дене қимылымен жауап береді 🗣️', '«Барайық па?» дегенде қолдарын көтереді немесе «Жоқ» дегенде басын шайқайды. Оның түсіну қабілеті таңғаларлықтай артты.'),
  ('65a36f4e-0f24-45fe-a038-a2e61c778c81', 'Өзіңізді мақтаңыз 👏', 'Бөлменің шашылып жатқанына емес, бүгін оның қаншалықты бақытты болғанына қараңыз. Сіз ешбір кітап үйрете алмайтындай керемет анасыз.'),
  ('7b75b0ec-d253-4e5a-bfac-9ff801269b5f', 'Бүгін «Ақылды ертегіде» 🪄', '«Ақылды ертегілерде» басты кейіпкері өз бөпеңіз болатын ерекше хикая құрыңыз: «Бір жасқа толуға дайындалып жүрген кішкентай арыстан».'),
  ('01302c3b-60e6-4b0a-8a88-e63349585527', '1 жасқа қатысты алаңдаушылық па? 💬', '«Бөпем әлі жүрмейді, дамуы кешеуілдеп жатқан жоқ па?» деген сұрақтар мазаңызды ала ма? Anacan қауымдастығына жазыңыз. Әр баланың өзіне сай мінсіз даму қарқыны бар екенін және жалғыз емес екеніңізді түсінесіз.'),
  ('51d3f88a-4baa-4ed5-b62c-e84a750f8166', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнгі оянулардың бар ауыртпалығын жалғыз көтермеңіз. Жұбайыңызды да оятыңыз: команда болу — жауапкершілікті тең бөлісу.'),
  ('984d2a76-5fec-4059-86ef-85671516c9b6', 'Ауа райын зерттеу ⛅', 'Сырттағы ауа райы құбылмалы ма? Ауа райы мен киім құралы желдің жылдамдығын және қандай киім үйлесімін таңдаған дұрыс екенін бірден көрсетсін.'),
  ('063ccb8e-7bd6-43e4-9c41-f30c172e10a7', 'Дені сау ана, дені сау бөпе 🥑', 'Ағзаңыздағы темір мен кальций қоры азайған. Пайдалы рецептілерден тез дайындалатын әрі күш-қуат беретін салат жасап көріңіз.'),
  ('1bed0d5c-444a-48fc-8e21-35fd8fff35b5', '1 жасқа небәрі 20 күн қалды! 🎂', 'Уақыт неткен жылдам! Туған күнге шақыру қағаздары, тізімдер мен шағын тосынсыйларға қатысты жазбалар жүргізе бастаңыз.'),
  ('caa0a9a0-1a0d-4362-a446-9f103d33e564', 'Уақытты тоқтатқан кадр 📸', 'Бөлмеде сүйкімді болып ойнап жүрген сәтінде бірден Бөпе фотосессиясын ашып, оның есейіп қалғанын көрсететін мінезін суретке түсіріңіз.'),
  ('3cc5a97d-281f-41bf-8747-fbb71f040e65', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйықтардан 1 сағат бұрын үйдегі барлық жарық шамдар мен экрандарды өшіріңіз. Мелатонин тек тыныш әрі жарығы бәсең ортада бөлінеді.'),
  ('528b02c4-9d93-4cda-add4-eb9a04a4395a', 'Сүттің көбеюіне көмектесетін тағамдар. 🍲', 'Әйелдерге арналған пайдалы рецептілер бөліміндегі сүтті көбейтетін сорпаларды бүгін дайындап көріп, күш жинаңыз.'),
  ('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Anacan таймері оң/сол емшекті Сіздің орныңызға есте сақтайды. Емізуді қазір таймермен бастаңыз!'),
  ('5c42ea20-5a84-467a-b408-412bcaaf8374', 'Күндізгі ұйқысы өзгеріп жүр ме? 🥱', 'Күндізгі екі ұйқының біріне қарсылық білдіре ме? 1 жасқа таяғанда ұйқы кестесін қайта реттейтін уақыт келген болуы мүмкін.'),
  ('b5252c17-b36e-4334-8221-0dc9210bbc77', 'Отбасылық дастарханда оның да өз орны бар! 🍲', 'Ол енді Сізбен бірге бір уақытта тамақтанғанды ұнатады. Қосымша тағам жей бастаған бөпелерге арналған Рецептілерден бүкіл отбасыға ұнайтын дәмдерді табыңыз.'),
  ('b4676fcf-2967-4b49-adbd-12ebe6a54334', 'Ішіңіздегіні бөліскіңіз келе ме? 💬', '«Оның 1 жасқа толғанына сене алар емеспін» деген ой Сізді толқыта ма? Осы тамаша сезімді Anacan қауымдастығындағы аналармен бөлісіңіз.'),
  ('b86239c1-4a1c-48b3-b49a-3fd4a012ebae', '1 жасқа небәрі 15 күн қалды! 🎈', 'Сағыныш сезімі оянады! Перзентханадан шыққан алғашқы күніңіз есіңізде ме? Енді міне, 1 жасқа дайындалып жатырсыз! Бөпеңіздің фотосессиясында алғашқы және қазіргі суретін қатар қойыңыз!'),
  ('152edc3c-3a8c-41ee-81bb-0df222f2c1ea', 'Небәрі 2 апта! 🎈', 'Туған күніне небәрі 14 күн қалды! Сағыныш сезімі оянады... Бөпеңіздің фотосуреттерін ашып, туған күнгі және бүгінгі суретін қатар қойып, оның қаншалықты өскенін тамашалаңыз.'),
  ('87c2d4c6-8130-43a1-8ff7-fa406c018013', 'Әкенің кешкі міндеті 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жетеді. Кешке бөпені ұйқыға дайындап, ертегі оқу — әкесінің міндеті. Ал Сіз жай ғана құлаққабыңызды тағыңыз.'),
  ('d1325a58-5701-4db5-a92f-ca67116c5c21', 'Тірексіз тұрған сәттер 🧗‍♂️', 'Диваннан ұстап тұрып, қолдарын аз уақытқа жібере ме? Ол тепе-теңдік сақтауды үйреніп жүр.'),
  ('3beff563-1e72-4a1f-8490-4e977c8b0b7a', 'Не пісіремін деп бас қатырмаңыз 🍲', '1 жасқа таяғанда мәзірге қатысты идеяларыңыз таусылды ма? Anacan AI-дан балаңыз өзі қолына ұстап жей алатын, дайындауы оңай тағамдар тізімін сұраңыз.'),
  ('eebfea92-7f8e-43d7-a45c-4a10e720b24c', 'Қараңғылықпен достасу 🌙', 'Тезірек ұйықтауы үшін кешкі әдеттерге қараңғылықты қосыңыз. Бөлмедегі барлық артық жарық пен экрандарды өшіріңіз.'),
  ('f8f9e691-e184-414d-9abe-ae0a3969929a', 'Әңгімеге қосылады 🗣️', 'Сіз сөйлегенде ол да өз тілінде бірдеңе айтып, дауысын көтере ме? Қарым-қатынас жасау дағдысы қарқынды дамып келеді, бөлмеде екінші спикер бар — оны міндетті түрде тыңдаңыз!'),
  ('ee88eee3-00d7-4463-b0db-60b939d85d4e', 'Сұрағыңыз бар ма? 🤖', '1 жастан кейін сиыр сүтіне қалай көшу керек? деген сияқты маңызды сұрақтарыңызды тіпті түнгі уақытта да Anacan AI көмекшімізге қойып, қолдау алыңыз.'),
  ('48047d55-0e81-4b9a-976d-56b580b1a7b7', 'Педиатриялық сұрақтар 🤖', '1 жасқа жақындағанда тамақтануда не өзгереді? Өзіңізді қинамай, Anacan AI-дан педиатрлар мақұлдаған нақты тізімді сұраңыз.'),
  ('56284941-dca4-4067-9e31-d61fc4ebeb63', 'Бір-біріңізге қолдау көрсетіңіздер 🥂', 'Күн бойғы шаршауды басу үшін серігіңізбен бірге шай ішіп, бір-біріңізге «Бүгін де қолымыздан келді» деңіздер.'),
  ('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e', 'Қарапайым тапсырмаларды толық орындайды! 🧠', '«Допты маған бер», «бері кел» дегеніңізді түсінеді. Бұл зияткерлік серпілісті Блогтардағы мақалалардың көмегімен одан әрі дамытыңыз.'),
  ('20db1e8e-1980-431d-800c-b7aa4ccf158b', 'Өз қасығымен жеуге талпыныстар! 🥄', 'Ол қасықты ұстап, аузына апаруға тырысып жүр ме? Осы қызықты сәттерді қолдау үшін Қосымша тағамды бастаған бөпелерге арналған лайықты тағамдарды таңдаңыз.'),
  ('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6', 'Ертегімен ұйқыға кету 🪄', 'Ақылды ертегілерде тек музыка мен табиғат дыбыстарынан тұратын ерекше фон жасаңыз. Сөз жоқ, тек тыныштық бар.'),
  ('eca3e78d-00de-4e77-bade-43808f152e4f', 'Махаббатқа толы сүйістер 🥰', 'Сіз сүйгенде, ол да Сізге қарай еңкейіп, ернін соза ма немесе бетіңізді сілекейлеп қоя ма? Оның кішкентай сүйістері бүкіл шаршауыңызды басуға қауқарлы.'),
  ('863a6afb-427b-4143-a527-2e01fe303116', 'Әкенің күлкілі қылықтары 🤡', 'Бөпені күлдірудің ең жақсы жолы — әкесінің түрлі оғаш дыбыс шығаруы. Бүгін кешкі көңілді сәттерді бөпеңізбен бірге тамашалаңыз.'),
  ('222d12a8-4347-4dce-afd7-4a0890721d0b', 'Қыңыр түндер 🥱', 'Ұйықтамау үшін бар күшімен қарсылық көрсетіп жүр ме? Күндізгі ұйқының біреуін қысқартатын уақыт келген шығар. Күн тәртібін қайта қарап көріңіз.'),
  ('5047e51c-64dc-4fe5-bc38-0409a743d0f6', 'Бойы мен салмағының өсуін тексерейік! 📏', '1 жастағы тексерілуге аз уақыт қалды. Дамуды бақылау бөліміндегі соңғы деректерді жаңартып, дені сау өсу кестесіне қарап, мақтаныңыз.'),
  ('873f2996-36df-4d67-a2df-ec60f668be2f', 'Тамақ мұнарасы құлады 🥣', 'Қасықты әдейі жерге тастап, Сізге қарап тұр ма? Ол тартылыс күшін және Сіздің реакцияңызды сынап жүр. Сабыр сақтаңыз, бұл — ойынның бір түрі.'),
  ('8cd57628-b75f-4445-8bc9-6b180e6572dc', 'Бүгін ақылды ертегіде 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрастырыңыз.'),
  ('94b60a89-bc34-41d8-818c-174aa7ed663b', 'Жинау ма, әлде демалу ма? 🛋️', 'Бала ұйықтағанда ыдыс жуғышқа қарай жүгірмеңіз. Диванға жатып, көзіңізді жұмыңыз да, 15 минут жай ғана тыныс алыңыз. Сіз роботсыз ба? Жоқ.'),
  ('c7b84129-89ab-4610-b19f-84959d6194f9', 'Шкаф детективі 🕵️‍♀️', 'Асүйдегі барлық қазан еденде жатыр ма? Қауіпсіз заттармен ойнау оның логикалық ойлауын дамытады. Қазынаны емін-еркін іздей берсін.'),
  ('11e743be-fb20-462f-8c74-07c143992d51', '1 жасқа 10 күн қалды! 🎂', 'Толқу артып келеді! Туған күн торты, киімдер, қонақтар тізімі... Ойларыңызды реттеу үшін бәрін Көңіл күй күнделігінің арнайы жазбалар бөліміне жазыңыз.'),
  ('15436a4e-52bb-4539-9146-377403746da0', 'Аналардың сырласуы 💬', '«Неліктен менің балам әлі жүрмейді?» деген сияқты сұрақтар Сізді шаршата ма? Anacan қауымдастығына қосылыңыз, сонда әр баланың даму қарқыны әртүрлі екенін көресіз.'),
  ('0549edc6-63d2-4caa-a43c-f029f7f39465', 'Тіс жару кезіндегі ауырсыну 🦷', 'Қызыл иегі қайтадан қызарып, сілекейі тоқтамай ағып жүр ме? Мүмкін, алғашқы азу тістері шығып келе жатқан болар.'),
  ('1c81021a-496b-49c0-86bc-4bde92ff779d', 'Дыбысты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал уақыт. Дыбыс өлшегішпен айналадағы шу деңгейін тексеріп, кенеттен шығатын қатты дыбыстардан сақ болыңыз.'),
  ('262cbb13-eb12-4831-9fe5-37ece168bdfa', 'Дене қимылымен жауап беру 🗣️', '«Барамыз ба?» дегенде қолдарын көтереді немесе «Жоқ» дегенде басын шайқайды. Оның түсіну қабілеті таңғаларлықтай артты!'),
  ('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8', 'Таза ауа — нағыз құтқарушы 🌳', 'Үйде мазасыздығы күшейсе, ауа райы мен киімін тексеріп, арбасына отырғызыңыз да, бірден саябаққа шығыңыз. Табиғат — оны тыныштандырудың ең жылдам жолы.'),
  ('39697061-01f6-4b41-8098-183a43f25058', 'Текшелерден қамал тұрғызады 🧱', 'Екі немесе үш ойыншық текшені бірінің үстіне бірін қоюға тырысады. Оның осы кішкентай инженерлік талпыныстарын үнсіз бақылап, қол соғып қолдаңыз.'),
  ('c5294433-a84c-4be9-ad57-5744718366c9', 'Бүгін бәріне ашуландыңыз ба? 📝', 'Бөпе ұйықтағанда, көңіл күй күнделігіне сезімдеріңізді жазып қойыңыз. Ертең жаңа әрі жақсы күн болады.'),
  ('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a', 'Жұбайыңызбен бірге алғашқы күндерді еске алып, күліңіз.', 'Сіздер бұл 1 жасқа оңай жеткен жоқсыздар! Бұл — бір команда ретіндегі жеңістеріңіз.'),
  ('5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf', 'Үлкен күнге 2 күн қалды! 🗣', '️ Сізді «Анашым» немесе «Әкешім» деп атауы — ең керемет сыйлық. Алғашқы сөздерінің дамуына қолдау көрсету үшін Блогтардағы кеңестерді оқыңыз.'),
  ('6b37b92f-5c61-4852-9ace-caab2bda465b', 'Отбасылық серуен мен жоспарлар! ☕', 'Туған күнге аз қалды! Достарыңызбен және отбасыңызбен кездесуге арбамен оңай кіре алатын дәмханаларды Анаға қолайлы орындар бөлімінен табыңыз.'),
  ('fedb8c6b-7722-4e20-9134-1af5ae254e85', 'Массаж уақыты 💆‍♂️', 'Бөпе ұйықтағаннан кейін, күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыз. Сіздер бір командасыздар!'),
  ('51bb1e4c-965f-4d69-b6e7-c79da0dce45c', 'Анаға арналған орын ☕', 'Үйде отыра беріп, күш-қуатыңыз таусылды. Анаға қолайлы орындар бөлімінен балалар мәзірі бар, жайлы отыруға болатын дәмхананы таңдап, өзіңізге уақыт бөліңіз.'),
  ('814176f3-c727-409b-b14a-fa62636170f1', 'Кітаптарға қызығушылық 📖', 'Кешкі дағдыңызға қағаз кітап оқуды қосыңыз. Бөпеңіз енді кітап беттерін өзі аударуға тырысады. Дауыс ырғағыңызды ертегінің қарқынына сай өзгертіңіз.'),
  ('f73c2769-0def-42bc-93e0-9a021c41b271', 'Музыкаға билейтін бөпе 🎶', 'Теледидардан ырғақты әуен ести қалса, бөпеңіз бірден бөксесін бұлғаңдатады. Оның музыканы қабылдау қабілеті дамып келеді. Сіз де қосылып, осы керемет сәтті бірге өткізіңіз.'),
  ('4c628627-3074-421f-9cfc-318df363eaf0', 'Қай емшекпен емізгеніңізді ұмытып қалдыңыз ба? 🤱', 'Anacan таймері оң немесе сол емшекпен емізгеніңізді Сіздің орныңызға есте сақтайды. Емізуді дәл қазір таймермен бастаңыз!'),
  ('99abcc3d-bec9-4537-89f9-92bfe6f4056c', 'Керемет күннің соңы. ✨', 'Сіз ғажап анасыз және бір жылдан бері нағыз ерлік жасап келесіз! Көңіл күй күнделігіне өзіңізді мақтан тұтатыныңызды жазып, жайлы ұйықтаңыз.'),
  ('d58a373d-b464-4fff-9b8e-74a104499618', '1 жасқа небәрі 5 күн қалды! 🎈', 'Кері санақ аяқталуға жақын! Алғашқы туған күн! Безендірулер, кішкентай қонақтар... Anacan қауымдастығына кіріп, аналардан 1 жасқа арналған мерекеге креативті идеялар алыңыз.'),
  ('21394622-dd96-488a-a90a-b8f72d718390', 'Алғашқы аяқкиімді таңдау! 👟', 'Қадамдары жиілеп келеді! Аяғының дұрыс дамуына көмектесетін, ортопедиялық әрі табаны жұмсақ алғашқы аяқкиімді таңдау үшін Ұсынылатын өнімдер тізімін міндетті түрде қарап шығыңыз.'),
  ('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1', 'Үйдегі қауіпсіздік шаралары! 🛡', '️ Ол өздігінен жүре бастаған сайын қауіп те арта түседі. Балаларға арналған қауіпсіздік құлыптары мен баспалдақ қоршауларын Ұсынылатын өнімдер бөлімінен қараңыз.'),
  ('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b', 'Өзгерген денеңіз 👗', 'Айнадағы дене бітіміңізге қарап мұңаясыз ба? Сіз осы денеңізбен жаңа адамды дүниеге әкелдіңіз. Өзіңізді құшақтап, қаншалықты мықты екеніңізді еске түсіріңіз.'),
  ('f38aba52-8d3a-44ad-96bf-7d9de570ef68', 'Анадан бір елі қалмау 🥰', 'Тіпті дәретханаға кірсеңіз де, есіктің ар жағында Сізді күтіп, жылайды. Ажырасу мазасыздығы шегіне жеткен кезең. Оған әрдайым «Мен осындамын» деп, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('03283459-7c0f-4d41-9c06-406552e1c477', 'Мінсіздік елесі 🛑', 'Бүгін ештеңе жоспар бойынша болмады ма? Өзіңізді кінәламаңыз. Сіз — шынайы анасыз, әлеуметтік желідегі сүзгілермен жасалған елес емессіз.'),
  ('3843a02f-a85f-47a9-97ba-0e63677749e2', 'Үнсіз қаһарман 🤫', 'Ол ұйықтап қалған сәтте үйдегі әрбір дыбыс бомба жарылғандай естіледі. Дыбыс өлшегішпен бөлмедегі дыбыс деңгейін реттегенде, өзіңіз де аяғыңызды ақырын басыңыз.'),
  ('fde65599-b651-49fa-a50a-5b78bed58d9f', 'Сұқ саусағы іске қосылды ☝️', 'Ол алыстағы затты саусағымен көрсетіп, реакция білдіреді. Бұл — ортақ назар аудару дағдысының маңызды кезеңі. Сол затқа онымен бірге қараңыз.'),
  ('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6', 'Сиыр сүтін беруге бола ма? 🥛', '1 жасқа қарай ас мәзірі өзгереді. Сиыр сүтіне көшу немесе бал секілді тағамдарға қатысты сұрақтарыңыз болса, бірден Anacan AI-дан сұраңыз.'),
  ('e7879bf6-3dca-4f0b-9981-d7f119d39235', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш әрі күңгірт ортада бөлінеді.'),
  ('14e209af-2489-4eb6-a1f0-be21be617768', 'Ертегімен ұйқыға бөлену 🪄', 'Ақылды ертегілерде тек музыка мен табиғат дыбыстарынан тұратын ерекше фон жасаңыз. Сөз жоқ, тек тыныштық пен жағымды күту сезімі бар.'),
  ('a6e2ed87-38de-413e-9884-cda9afcbb191', 'Соңғы дайындықтар 📸', 'Шамдар, торт пен киімдер дайын ба? Телефон жадын тазалаңыз, ертең Бөпе фотосессиясы үшін көп бос орын қажет болады!'),
  ('c639a352-3f59-4488-9ce0-2ba361a4790c', 'Ертең 1 жасқа толады! 🎉', 'Сағынышқа толы сәттер! Перзентханадан шыққан алғашқы күніңіз есіңізде ме? Көңіл күй күнделігін ашып, осы түні бөпеңізге болашақта оқитын әсерлі хат жазыңыз.'),
  ('0eb89ca2-1605-4f92-8c61-0198a966afb1', 'Жеңіс биі 💖', '1 жылдың шаршауы мен мақтанышын бүгін кешке жарыңызбен бірге шам жарығында атап өтіңіз. Сіздер — тамаша командасыздар!'),
  ('2e46d431-01ee-479e-a146-2b349cd7f234', 'БІР ЖАС! АЛҒАШҚЫ ТУҒАН КҮН! 🎂🎉', 'СІЗ КЕРЕМЕТСІЗ! Тұп-тура 365 күн, ұйқысыз түндер, алғашқы күлкі, алғашқы қадамдар! Бөпеңіз енді 1 жаста! Бөпе фотосессиясын ашып, осы тарихи күнді ең әдемі кадрлармен мәңгі есте қалдырыңыз!'),
  ('3c2fa886-d095-424c-ad68-b439a1ffc0b9', 'Өзіңізге қол соғыңыз 👏', 'Ол Сіздің құрсағыңызда 9 ай, құшағыңызда 1 жыл өсті! Бүгін тек оның ғана емес, Сіздің де Ана атанған күніңіз. Өзіңізді мақтан тұтыңыз!'),
  ('0944c4dc-3e95-4efb-97dc-8b4809d96d45', 'Бүлдіршіндік кезең басталады 🌟', 'Нәрестелік шақ артта қалды! Енді ол өзінің дербестігін ашық көрсетіп, бәрін «өзім» дейтін бүлдіршін. Сабыр мен сүйіспеншілікке толы жаңа шытырман басталады!'),
  ('569602c0-f0cf-4229-b498-984bfdabf097', 'Ақылды ертегі уақыты 🪄', 'Ақылды ертегілерде 1 жасқа толып, әлемді танып жүрген басты кейіпкер туралы оқиға құрып, күнделікті дәстүрді жалғастырыңыз.'),
  ('ae6d1371-ca56-433f-b6db-9c70c59094fb', 'Қырсықтық өзгереді 🛑', 'Жерге жата қалып жылау сияқты жаңа ашу ұстамалары басталды ма? Бөпе әлі сезімдерін басқара алмайды. Оның деңгейіне дейін еңкейіп, сабырмен сөйлесу арқылы бұл сәттерді бірге еңсеріңіз.'),
  ('6e25898e-24d8-4ca6-8cbe-71a271993d6f', 'Дыбысты бақылау 🤫', 'Бөпе ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал уақыт. Дыбыс өлшегішпен айналадағы шу деңгейін тексеріп, кенеттен шығатын қатты дыбыстардан сақ болыңыз.'),
  ('d5e35c42-03ad-4068-b27d-3efca55a35ad', 'Қасықты өзі ұстағысы келеді 🥄', 'Қасықты өзі ұстап, езбені өз бетінше жегісі келеді. Төгеді, үстін былғайды, бірақ бұл қимыл-қозғалыс дағдылары үшін өте маңызды. Оған мүмкіндік беріңіз.'),
  ('f93e7290-30ca-44fe-a1e4-55044619c9a6', 'Қуатқа қажеттілік 🍲', 'Күнделікті қарбалас одан әрі күшейді. Пайдалы рецептілердің ішінен Сізге күш беретін, темір мен ақуызға бай түскі ас таңдап, қуат жинаңыз.'),
  ('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпенің оянуын жалғыз өзіңіз көтермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('50b26349-9946-4708-aec2-e87f1b15952f', 'Алғашқы дербес қадамдар? 🧗‍♂️', 'Мүмкін бүгін, мүмкін ертең... Бөпе енді еш жерден ұстамай, бір-екі қадам жасауға талпынып жүр. Даму бақылағышына белгілеуге дайын болыңыз!'),
  ('9407d96f-ca5a-4378-a7c6-ee00256c457a', 'Ауа райын барлау ⛅', 'Серуенге шығарда терезеге қарап қана шешім қабылдамаңыз. Ауа райы мен киім құралы желдің жылдамдығын және қандай киім үйлесімін таңдаған дұрыс екенін бірден көрсетсін.'),
  ('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2', 'Ішіңіздегіні бөліскіңіз келе ме? 💬', '«1 жастан кейін қиындай түседі» дегендер Сізді қорқыта ма? Anacan қауымдастығына жазып, аналардың шынайы әрі жағымды тәжірибелерімен танысыңыз.'),
  ('4c27d203-23f5-4e87-918e-d40df5e30875', 'Түнгі тыныштық 🛀', 'Жылы ванна, массаж және бөлмені қараңғылау. Ұйқы режимін сақтау — түні бойы үздіксіз ұйықтаудың басты құпиясы.'),
  ('6ad316f8-edd9-4dff-aac4-f3492d4a602a', 'Қарапайым өтініштерді орындайды 🧸', '«Допты маған берші» дегенде, оны шынымен тауып әкеле ме? Сөздерді түсіну қабілеті шарықтау шегінде! Оны ойындарға көбірек қатыстырыңыз.'),
  ('028a5b0d-04de-43dc-984d-eaf6e3427904', 'Алғашқы аяқкиімді таңдау 👟', 'Бөпеңіз жүруге дайындалып жүр, ал үйде аяқкиім киюі керек пе? Алғашқы қадамға арналған аяқкиім және жалаңаяқ жүрудің пайдасы туралы Anacan AI-дан сұраңыз.'),
  ('5d68d6d5-05d2-43b4-bd93-e3f95983e445', 'Тізім көп көмектеседі 🛒', '1 жастан кейін ас мәзірі өзгереді. Үйге сиыр сүті немесе басқа азық-түлік керек пе? Сатып алу тізімін бірден толтырып, жұбайыңызға жіберіңіз.'),
  ('9a073421-3e36-4699-bbbd-50a69e46f431', 'Өзіңізге уақыт бөліңіз. 🛁', 'Күні бойы тынбай жүрген баланың соңынан ілесу оңай емес. Шаршағаныңызды Көңіл күй күнделігіне жазып, жеңілдеп, демалыңыз.'),
  ('2cdeb7df-f4f5-4a75-ae9b-552210a168fe', 'Кітап беттерін парақтайды 📖', 'Қалың беттері бар кітапты өзі парақтап, суреттерге қызығушылық таныта ма? Оған түрлі-түсті ертегі кітаптарын көбірек оқып беріңіз.'),
  ('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd', 'Алғашқы өз бетінше басқан қадамдар! 🧗‍♂', '️ Жиһаздан қолын жіберіп, өзі тік тұрады, тіпті көптен күткен алғашқы қадамын басуы мүмкін! Осы ұмытылмас тарихи сәтті өткізіп алмаңыз да, видеоны бірден Бөпе альбомына жүктеңіз.'),
  ('2eeb1f61-7042-48aa-9ecc-41443c68b4a8', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпеңіз оянғанда, бірде Сіз, бірде жұбайыңыз тұрыңыз. Кейде бөпені тек әкесінің ырғақты сипауы ғана тыныштандырады.'),
  ('d1cf73d9-421b-4ad1-b114-e5025146d5b2', 'Үй шаруасын кім істейді? 🌪️', 'Үй шаруасы жиналып қалды ма? Қала берсін. Бүгін жұбайыңыздан үй шаруасын өз мойнына алуын сұраңыз. Ал Сіз демалыңыз.'),
  ('18cb3df2-de24-43c0-a3d0-160051dc5202', 'Эмоциялар күнделігі 📝', 'Өзіңізді жалғыз сезінгенде, Көңіл күй күнделігіне сезімдеріңізді жазыңыз. Барлық әйел осы кезеңдерден өтеді, Сіз мықтысыз.'),
  ('19c626ef-26a5-49ef-921f-4577f35ab653', 'Емізіктен/бөтелкеден шығару керек пе? 🍼', '1 жастан кейін емізіктен шығару туралы ойланып жүрсіз бе? Anacan қауымдастығындағы аналардан мұны барынша жұмсақ жасаудың жолдарын сұраңыз.'),
  ('c6a284e9-0bba-433f-9823-bcc74708dbd9', 'Таза ауа — ем 🌳', 'Бөпеңіз күні бойы жылап, мазасыз болды ма? Шешімі өте қарапайым: ауа райын ескеріп киіндіріңіз, арбасына отырғызып, бірден саябаққа шығыңыз.'),
  ('5f3d97d0-e211-488f-bb05-dd9ccce213a3', 'Біз — бір командамыз! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ішіңіздегіні бөлісіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('92cb503c-c013-47cb-ab12-416c047b2693', 'Дамуын тексеру 🤖', '12 айлық баланың қимыл-қозғалыс дағдылары туралы ақпарат қажет пе? Anacan AI-дан педиатр мақұлдаған қысқа әрі нақты тізім сұраңыз.'),
  ('f20aef27-fde2-489c-9dd8-fe28386cf1db', 'Геометриялық пішіндер мен зияткерлік ойындар! 🧩', 'Бөпеңіз дөңгелекті немесе шаршыны сәйкес саңылауға салуға тырысып жүр. Осындай танымдық сәттерді Бөпе альбомында мәңгілікке сақтаңыз.'),
  ('beccb06c-7cf4-4f1a-9455-17d5b952ad96', 'Музыкалық кештер 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — бөпеңіздің сүйікті әнін қосып, оны құшақтап билеу.'),
  ('0c97760a-2746-4ddf-ad12-5f44e1960612', 'Тыныштық қажет 🤫', 'Бөлмедегі тыныштықты Дыбыс өлшегіштің көмегімен сақтаңыз. Түнде бөлінген ұйқы бөпеңіздің де, Сіздің де таңертеңгі көңіл күйіңізге әсер етеді.'),
  ('61d67656-ab73-4417-b42d-5e55ecf64b87', '«Жоқ» сөзінің күші 🛑', 'Бірдеңе ұсынғанда, басын шайқап «жоқ» деуді үйренді! Бұл қырсықтық емес, өз ойын білдіру тәсілі. Таңдау ұсынып, оны тыныштандырыңыз.'),
  ('b58ae5cb-ec5b-400f-b490-16ff65c6cead', 'Логикалық ойындар 🧩', 'Ойыншықтарды қорапқа салып, кейін бәрін қайта шығара ма? Осылайша «ішінде» және «сыртында» ұғымдарын түсіне бастайды. Бұл әрекетіне кедергі жасамаңыз.'),
  ('6b997061-a83d-4040-b848-d55a40a87a1a', 'Дені сау ана 🥑', 'Бөпеңіз тойса, енді кезек Сізде. Пайдалы рецептілер арасынан қуат беретін тіскебасар таңдап, диванға кем дегенде 10 минут жатып демалыңыз.'),
  ('8d89c421-922f-4b8a-bc83-525a380ead88', 'Баспалдаққа қызығушылық 🧗‍♂️', 'Еденде жүру аз болып, баспалдаққа және жиһаздың үстіне шығуға тырыса ма? Қимыл-қозғалыс дағдылары қарқынды дамып жатыр! Міндетті түрде бақылауда ұстаңыз.'),
  ('dacf6637-c6dd-4427-9e89-1dc06f453ae5', 'Сиқырлы ертегі уақыты 🪄', 'Ақылды ертегілердегі «Ең кішкентай кейіпкердің ұйықтау құпиялары» атты хикаямен кешкі әдеттеріңізді қызықты ете түсіңіз.'),
  ('2d2e06b1-2d94-4883-a675-93637a17ca98', 'Мазасыздық шегіне жетті ☁️', 'Ештеңеге көңілі толмай, бәріне жылай ма? Артқы азу тістері шығып жатқан болуы мүмкін. Салқын тіс қаситын ойыншықтарды дайындаңыз.'),
  ('0955065c-ecf1-48ed-9f6f-735958386a41', 'Анаға арналған дәрумен 🥑', 'Бөпеңізді тойдыру үшін бәрін жасайсыз. Ал өзіңіз ше? Пайдалы рецептер бөлімінен темір мен кальцийге бай жеңіл түскі ас таңдаңыз.'),
  ('1d781ae8-7800-48ae-b0ee-fe44c7f13291', 'Күндізгі ұйқысы өзгеріп жүр ме? 🥱', 'Күндізгі екі ұйқының біріне мүлде қарсылық таныта ма? 1 жастан кейін бір реттік күндізгі ұйқыға ауысу басталады. Күн тәртібін біртіндеп қайта реттеңіз.'),
  ('61536a43-b97b-4fe8-8f6a-f358141baefc', 'Ертегімен ұйықтау 🪄', 'Ақылды ертегілерде батыл әрі сүйкімді жануарлар туралы хикая құрып, бөлмені сиқырлы мекенге айналдырыңыз.'),
  ('76e3844a-efe7-4daa-855a-4cfd4d92bfc9', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш әрі жарығы бәсең ортада бөлінеді.'),
  ('8b586560-e2d2-46b0-ba82-419bb7b56682', 'Ой тұманы 🛒', 'Ұмытшақтық әлі де мазалай ма? Үйге қажет ұсақ-түйекті есте сақтауға тырыспай-ақ, бірден Сатып алу тізіміне қосыңыз — қалғанын жұбайыңыз реттесін.'),
  ('b87394f8-5f2b-4eb7-a491-26b80560c8a3', 'Нысанаға дәл лақтыру ⚾', 'Қолындағы ойыншықты белгілі бір нысанаға әдейі лақтыруға тырысады. Көз бен қол үйлесімі қарқынды дамып келеді. Бірге доп лақтырып, қағып ойнаңыздар.'),
  ('159279c3-df89-49cf-a71c-bb577a8dd0c3', 'Қауіпті аймақтарға қол жеткізу ⚡', 'Бойы өсіп, бұрын қолы жетпеген сөрелерге енді жете алады. Үйдің қауіпсіздігін шұғыл түрде қайта тексеріңіз.'),
  ('3b6ac273-a759-45de-9492-87af2df8cac9', 'Түнгі тыныштық 🤫', 'Көлік немесе сырттағы дыбыстар бөпеңізге кедергі келтірсе, міндетті түрде Дыбыс өлшегішпен ортаны тексеріп, фонда ақ шу қосып қойыңыз.'),
  ('bc24cbab-3bcd-4b5b-92fb-249b861079c2', 'Ойнағанының бәрін жан-жаққа шашады. 🌪️', 'Үйдің тазалығы емес, Сіздің демалғаныңыз маңызды. Ойыншықтар ертең де орнында болады, ал бөпеңізге сергек ана дәл қазір қажет.'),
  ('0693172d-9675-431e-ae2b-b1d735f8da0f', 'Барлық шаршауды бір сәтке ұмытыңыз.', 'Бүгін кешке балаңыз ұйықтағаннан кейін жұбайыңызбен бірге командалық жеңістеріңізді атап өтуді ұмытпаңыз!'),
  ('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125', 'Өзіңізді өзгелермен салыстырмаңыз 🛑', '«Пәленшенің баласы ертерек сөйледі» деген сөзді ұмытыңыз. Әр баланың даму қарқыны ерекше. Сіз оған тек сүйіспеншілігіңізді сыйлаңыз.'),
  ('b9520b22-b9b3-4ca3-a219-de05702404a8', '1 жас 1,5 айға таяп қалды! 📸', 'Ол қазірдің өзінде 12.5 айлық! Бөпеңізге фотосессия жасап, балалық шақтың осы қимыл-қозғалысқа толы, алай-дүлей кезеңіндегі ең күлкілі сәттерді суретке түсіріп, естелікке сақтаңыз.'),
  ('078c86a9-a3c8-4f20-a27a-3aa00d3961ad', 'Тамақтану уақытын көңілді өткізейік! 🥦', 'Бөпеңіздің тәбеті болмаса, «Қосымша тамақ жей бастаған бөпелерге арналған рецепттер» бөлімінен түрлі-түсті әрі назар аударарлық тағамдар дайындаңыз.'),
  ('3b7df91a-7022-4a50-9438-82f89b2240b8', 'Дене мүшелерін таниды 👀', '«Көзің қайда?» деп сұрағанда, саусағымен түртіп көрсете ме? Оның танымдық қабілеті шарықтау шегінде! Мұны даму бақылағышында мақтанышпен белгілеңіз.'),
  ('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56', 'Сіз қолыңыздан келгеннің бәрін жасап жүрсіз! 💖', 'Бала өсіру марафон секілді. Бүгін кешке өзіңізге біраз уақыт бөліп, сүйікті фильміңізді көріңіз немесе жай ғана демалыңыз.'),
  ('18eaf932-80c3-47ae-a394-f6ce083ef215', '«Өзім жеймін» деген қырсықтығы 🥦', 'Қасықты Сіздің қолыңыздан алғысы келеді. Ала берсін. Үсті-басы былғанады, бірақ бұл дербестік сезімі ол үшін өте маңызды.'),
  ('56403a92-c6d5-492f-b073-20bcd436f218', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпеңіз оянғанда бәрін жалғыз өзіңіз атқармаңыз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('763e2885-6f82-4d6b-8ec4-680155ad7a5f', 'Аналардың сырласуы 💬', 'Балаңыздың ашу ұстамаларын жеңе алмай жүрсіз бе? Дереу Anacan қауымдастығына кіріп, басқа аналардың қолдау білдірген пікірлерін оқып, көңіліңізді тыныштандырыңыз.'),
  ('f47e2fcf-5030-43a8-a77b-79834cb3f95a', 'Үлкен сезімдер, кішкентай дене 🛑', 'Қалағаны болмағанда өзін жерге тастай ма? Оның деңгейіне дейін еңкейіп, сабырмен сөйлесу арқылы ашу ұстамасын жеңуге көмектесіңіз.'),
  ('a0e7f0f6-1438-4f75-acb4-559e4df47974', 'Тыныштыққа деген қажеттілік 🤫', 'Бөлмедегі тыныштықты Дыбыс өлшегіш арқылы сақтаңыз. Түнде бөлінген ұйқы оның да, Сіздің де таңертеңгі көңіл күйіңізге әсер етеді.'),
  ('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95', 'Анаға арналған орын ☕', 'Үйде отыра беріп, әбден шаршадыңыз. Анаға қолайлы орындар арасынан жайлы отыра алатын кафе таңдап, өзіңізге уақыт бөліңіз.'),
  ('f34137b7-333a-47bb-8fab-66dd8be52bfb', 'Би мен ырғақтар 🎶', 'Теледидардан немесе телефоннан ырғақты әуен ести сала билей ме? Оның музыканы қабылдау қабілеті белсенді дамып келеді, Сіз де қосылып билеңіз!'),
  ('9dd82a43-7f3a-4a5e-9d01-a99d7d738015', 'Өз бетінше киінуге талпыныс. 👕', 'Ол шұлығын өзі шешуге немесе киюге тырысып жүр ме? Ұсақ моторикасын дамытатын бұл әрекеттерін шыдамдылықпен қолдаңыз.'),
  ('ccf44d60-2dc0-447f-b1ea-dd06a80f0324', 'Су ішу өте маңызды. 💧', 'Белсенді балалар тез шөлдейді. Күні бойы, әсіресе кешкі астан кейін оған су ұсынуды ұмытпаңыз.'),
  ('b55b3812-173b-489f-a2ae-d2c78611fd35', 'Қараңғылықпен достасу 🌙', 'Тезірек ұйықтап кетуі үшін кешкі рәсімге қараңғылыққа үйренуді қосыңыз. Бөлмедегі барлық қосымша жарықты өшіріңіз.'),
  ('c9fb44a1-ad82-4f16-a316-50d99863130e', 'Аллергияға күмән 🤖', '1 жастан кейін жаңа тағамдар бере бастадыңыз ба? Қандай да бір алаңдаушылық болса, алғашқы қадамдарды дереу Anacan AI-дан біліңіз.'),
  ('0c105765-0e1a-42dd-bd14-0ca4153705c0', 'Ұсақ моторикасы дамып келеді. 🖍', '️ Ол қарындашпен қағазға шимай салғанды ұнатуы мүмкін. Оған лайық жуан қарындаштар беріп, шығармашылығын бақылаңыз.'),
  ('1b77ed52-4cf2-48a6-98fc-53d0a94dc968', 'Ұйқы рәсімі сенімділік береді. 🌙', 'Күн сайын кешке бірдей ретпен орындалатын әрекеттер (шомылу, ертегі оқу, жарықты бәсеңдету) оның жеңіл ұйықтап кетуіне көмектеседі.'),
  ('795996e4-e3e1-4fa7-b442-27c8ffa35bff', 'Тіс жару кезіндегі ауырсыну 🦷', 'Қызыл иегі қайтадан қызарып, сілекейі тоқтамай ағып жүр ме? Тіс жаруын бақылау бөлімінде үдерісті белгілеп, салқын тіс қаситын ойыншықтарды дайындаңыз.'),
  ('452e9fa3-8dba-4774-8bfe-d6afa50d161c', 'Тізім өмірді жеңілдетеді 🛒', 'Бөпенің тамағына арналған жеміс немесе сұлы таусылды ма? Сатып алу тізімін дереу толтырып, қажет заттарды жұбайыңыздың телефонына жіберіңіз.'),
  ('8c12c251-a9b5-45cb-92ff-f145e2484025', 'Қабырғадан ұстап жүр 🧗‍♀️', 'Жиһаздың жиегінен ұстап, жанымен адымдау — оның сүйікті жаттығуы. Өздігінен қадам басуына аз-ақ қалды! Даму көрсеткіштерін бақылау бөліміне кіріңіз.'),
  ('c7e52a2b-46d5-4446-b455-907f7523256e', 'Дыбысты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен ортаны тексеріп, кенеттен шығатын қатты дыбыстардан сақ болыңыз.'),
  ('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d', 'Жаңа ойыншық керек пе? 🛒', 'Бөпеңіздің даму деңгейіне сай, ойлау қабілетін жетілдіретін ойыншықтар іздесеңіз, Ұсынылатын өнімдер тізімін қарап шығыңыз.'),
  ('10934358-ef97-4dab-87ad-73a62aee1231', 'Үй жинау ма, әлде демалу ма? 🛋️', 'Бөпеңіз ұйықтағанда ыдыс жуғышқа қарай асықпаңыз. Диванға жатып, көзіңізді жұмыңыз да, 15 минут бойы жай ғана тыныстаңыз.'),
  ('58866969-75c5-44cd-a308-210945d7a2af', 'Сынап көру және қателесу 🧱', 'Бөпеңіз екі ойыншық текшені бірінің үстіне бірін қоюға тырысады, бірақ олар құлап қалады. Ол мұқият қайтадан байқап көреді. Кішкентай инженердің талпыныстарын үнсіз бақылаңыз.'),
  ('94a9a306-04fb-42bb-9962-95b473b02f89', 'Эмоциялар күнделігі 📝', 'Өзіңізді жалғыз сезінгенде, көңіл күйіңіз бен сезімдеріңізді Көңіл күй күнделігіне жазыңыз. Барлық әйелдер осындай кезеңдерден өтеді, Сіз мықтысыз.'),
  ('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5', 'Ұйықтар алдындағы ертегінің сиқыры бар. 📖', 'Ұйықтар алдында оқылған қысқа әңгіме бөпеңіздің қиялын дамытып қана қоймай, араларыңыздағы эмоциялық байланысты да нығайтады.'),
  ('b28c4699-a204-48ae-80c2-bef5008fdffd', 'Өз бетінше ойнау дағдысы. 🧩', 'Бөпеңіздің аз уақыт болса да өз бетінше ойнай алуы оның зейіні дамып келе жатқанын көрсетеді. Осындай сәттерде оны алыстан сүйіспеншілікпен бақылаңыз.'),
  ('e6b48652-88e0-49d8-b2cc-654a9f8eb626', 'Өсуін бақылап отырамыз. 📏', 'Бөпеңіздің киімдері тар бола бастады ма? Салмақ бақылау бөліміне жаңа көрсеткіштерді қосып, оның дені сау өсіп келе жатқанын белгілеп отырыңыз.'),
  ('05e8d5ea-453b-4a35-a697-81e0b9ca911a', 'Үлкендерге еліктеу 🧹', 'Сіз үй жинап жатқанда, ол да қолына шүберек алып, артыңыздан қайталауға тырыса ма? Ол Сіздің айнаңыз іспетті! Сіз жасағанның бәрін қайталайды.'),
  ('04429520-36d1-489e-8ec7-309a2c08ae92', 'Біз бір командамыз! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ойыңыздағыны ашық бөлісіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('05fff0e7-029c-401c-bfab-497bbc099997', 'Сөздердің мағынасын түсінеді 🗣️', '«Допты әкел» десеңіз, шынымен барып, допты іздейді. Сөздік қоры жылдам көбейіп келеді. Онымен күрделірек сөйлемдермен сөйлесіңіз.'),
  ('ec4b2f26-3631-4fed-9578-c9539a35a5c0', 'Қалтаңыздағы тізім 🛒', 'Күнделікті қарбаласта сусабын таусылды ма, әлде жөргек пе? Бәрін есте сақтауға тырыспай, Сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('663824a2-b8fe-471a-b981-3eb69f3a2c7f', 'Сезімі үлкен, өзі кішкентай. 🌪', '️ Өзін жеткізе алмаған кезде ашуланып, жылауы қалыпты жағдай. Оның деңгейіне дейін еңкейіп, сезімдерін түсінетініңізді сабырлы дауыспен айтыңыз.'),
  ('8be96289-58a8-4a48-89ec-c4ba0488e973', 'Сумен ойнау тыныштандырады. 💧', 'Кішкентай легенге су құйып, ішіне пластик ыдыстар салыңыз. Сумен ойнау балаларға бойындағы энергиясын шығарып, тынышталуға көмектеседі.'),
  ('a70fb0ff-98b0-4735-ac10-846168dd5d60', 'Сұрағыңыз бар ма? 🤖', '«1 жас дағдарысын қалай еңсеруге болады?» деген сияқты маңызды сұрақтарыңызды тіпті түнде де Anacan AI көмекшісіне қойып, маман кеңесін алыңыз.'),
  ('12139491-dd07-42f8-b056-98645d9880be', 'Уақытты тоқтатқан кадр 📸', 'Ол күн сайын аздап өсіп келеді. Дәл қазір Бөпе фотосессиясын ашып, оның осы шынайы сәтін естелікке айналдырыңыз.'),
  ('302d3885-ce15-4277-a0cf-d95f95d7ed63', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш ортада бөлінеді.'),
  ('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0', 'Саябақ па, әлде үй ме? ⛅', 'Сыртқа шыққыңыз келеді, бірақ жел соғып тұр ма? Ауа райы мен киім көмекшісі лайықты киім үйлесімін бірден ұсынсын.'),
  ('ecb2b9d1-a640-4303-b570-f3c7f463e0ab', 'Ұйқыға көнбейтін түндер 🥱', 'Ұйықтамау үшін барынша қарсыласа ма? Күндізгі ұйқысы мен күн тәртібін қайта қарап шығыңыз.'),
  ('8a5f3751-2bcd-4454-bfef-74c90f1c3f85', 'Күн аяқталды, енді өзіңізге уақыт бөліңіз. 🛁', 'Бүгін қатты шаршадыңыз ба? Жылы душ қабылдап, демалыңыз және бүгін атқарған барлық ісіңіз үшін өзіңізге алғыс айтыңыз.'),
  ('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8', 'Дене мүшелерін үйренеміз! 👃', '«Мұрның қайда?» дегенде кішкентай саусағымен көрсете ме? Осы сүйкімді жаңалықтарды айна алдында ойынға айналдырып, бірге көңіл көтеріңіз.'),
  ('e70adad3-3a0b-4d15-ab3c-9f286916a872', 'Пайдалы тіскебасар уақыты. 🍎', 'Қуаты таусылмайтын балалар үшін жеміс тілімдері немесе көкөніс таяқшалары — тамаша таңдау. Өз қолымен ұстап жеуіне мүмкіндік беріңіз.'),
  ('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3', 'Кішкентай суретші іске кірісті! 🖍', '️ Жуан қарындаштар беріп, қағаз бетіне еркін шимайлауына мүмкіндік беріңіз. Бұл ұсақ моторикасы мен шығармашылығын дамытуға өте пайдалы.'),
  ('ccb3a3d0-8dc5-450a-b184-37cf81a39c01', 'Таза ауа екеуіңізге де пайдалы. 🌳', 'Анаға қолайлы орындар картасынан бөпе арбасымен еркін серуендеуге болатын жаңа саябақты тауып, серуенге шығыңыз.'),
  ('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5', 'Ұйқы алдындағы әдеттер сенімділік береді. 🌙', 'Күн сайын кешке бірдей ретпен жасалатын әрекеттер (шомылу, ертегі оқу, жарықты бәсеңдету) оның тезірек ұйықтап кетуіне көмектеседі.'),
  ('78f8f713-17f3-46f4-83f8-9cdbfd0c9894', 'Өздігінен ойнайтын уақыт 🧸', 'Енді ол 10-15 минут бойы ойыншықтарымен өздігінен ойнай алады. Оны сырттай бақылап, тыныштықтан ләззат алыңыз.'),
  ('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd', 'Ауа райын зерттеу ⛅', 'Сырттағы ауа райы түсініксіз бе? Ауа райы мен киім таңдау құралы желдің жылдамдығын көрсетіп, қолайлы киім үйлесімін бірден ұсынсын.'),
  ('bac8ff9b-6338-4b34-a5d6-84b7aefd251c', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнгі оянулардың барлық ауыртпалығын жалғыз көтермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('c1daed2c-e22f-4c5a-8534-4ff90b6b866e', 'Ойыншығымды өзім табамын 🧸', 'Көзінен таса етіп, артына жасырған ойыншықты барып тауып ала ма? Демек, ол заттың көзге көрінбесе де бар екенін түсінеді!'),
  ('2a991705-4255-4931-9ad5-cef8eb9bf0dd', 'Кішкентай көмекшіңіз! 🧹', 'Сізге еліктеп, қолына шүберек алып, шаң сүртуге тырыса ма? Осындай сүйкімді әрі үйретуші сәттерді болашаққа естелік ретінде Бөпе альбомына видео түрінде міндетті түрде қосыңыз.'),
  ('813ebcca-fa4c-42de-926c-6ca1c1526de6', 'Музыкамен тынышталу. 🎶', 'Кешкі уақытта белсенді ойындардың орнына жайлы әуендер тыңдап, бөпеңізді ұйқыға, ал өзіңізді тынығуға дайындаңыз.'),
  ('ce071e13-068a-4c5a-8d4c-437e6f25658d', 'Тамақ талғау. 🍲', 'Кейбір тағамдардан бас тартса, алаңдамаңыз. Оларды басқа күндері әртүрлі түрде (мысалы, езбе емес, қолмен ұстап жейтін тағам ретінде) қайта ұсынып көріңіз.'),
  ('502b8118-151f-47c7-9476-eb53fa55cfd0', 'Мұнаралар бой көтеруде! 🧱', 'Ол енді 3-4 текшені бірінің үстіне бірін қоя алады. Зейін мен көз-қол үйлесімін қажет ететін бұл ойынын мақтап, қолдау көрсетіңіз.'),
  ('af470a51-532a-4658-877a-26e61845210a', 'Әлеуметтену уақыты. 👶', 'Саябақта басқа балаларды мұқият бақылай ма? Әзірге бірге ойнамаса да, қатар ойнау (parallel play) кезеңі — әлеуметтенудің алғашқы үлкен қадамы.'),
  ('ceb1c77d-c486-4755-b204-47ec200fcd34', 'Дауыс ырғағыңызды түсінеді 🗣️', 'Сіз байсалды дауыспен «жоқ» дегенде, кідіріп, Сізге қарай ма? Ол эмоциялар мен тыйымдарды түсіне бастады!'),
  ('53cb1b60-78f0-41c1-a42e-b48a4324533b', '400 күндік қуаныш! 🌟', 'Ертең — айтулы төрт жүзінші күн! 1 жас 1 айдан да асты! Үйде шағын мерекелік көңіл күй орнатып, телефоныңыздың жадын босатыңыз.'),
  ('9e145532-f5a6-48ed-a07c-a3e9fc574858', 'Массаж уақыты 💆‍♂️', 'Бөпе ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыздар. Сіздер — бір командасыздар!'),
  ('fab52013-4ea8-458f-b397-01341fb91dad', 'Өзіңізді кешіру кеші 📝', 'Бүгін бәріне ашуландыңыз ба? Бөпе ұйықтағанда, сезімдеріңізді Көңіл күй күнделігіне жазыңыз. Ертең жаңа әрі тамаша күн болады.'),
  ('165064a6-acf5-4848-b342-4a3782635921', 'Керемет 400 күн! 🎉', 'Құттықтаймыз! Міне, осы қызығы мен қиындығы қатар жүретін жолды бірге өткеріп келе жатқандарыңызға тура 400 күн болды! Бұл ерекше күнді дәл қазір атап өтіңіздер!'),
  ('894151c3-97b8-419f-9602-aa08da619716', 'Өздігінен жей берсін. 🥄', 'Үсті-басы былғанса да, өз қасығымен жеуге талпынсын. Бұл оның өзіне деген сенімін арттырып, бұлшықет қимылдарының үйлесімін дамытады.'),
  ('8c8e0b49-c38c-485a-b336-5facb1258a02', 'Сіз ең жақсысыз! ✨', '400 күн бойы танытқан жанқиярлығыңыз баға жетпес. Енді терең тыныс алып, шалқайып отырып, алаңсыз демалыңыз.'),
  ('05dbf09b-2a49-4886-a4e4-6f85e7cbea42', 'Төрт қабырғадан тыс әлемге ⛅', 'Балаңыз үйде энергиясын шығара алмай, мазасызданып жүр ме? Табиғат — ең жақсы тыныштандырушы. Ауа райына сай киім таңдап, бірден саябаққа барыңыз.'),
  ('3cf4affc-53f5-4c77-84f1-006d5732e36a', 'Әкемен ойнайтын уақыт 👨‍👧', 'Күні бойы соңынан жүгіріп, аяқтан талып қалдыңыз. Енді серіктесіңізді іске қосатын уақыт келді. Еденде аунау, ат болып ойнату сияқты ойындарды әкесіне тапсырыңыз. Өзіңіз демалыңыз.'),
  ('f1269e86-21d6-4d2f-83e1-31926957408a', 'Бөлмелер арасындағы марафон 🏃‍♂️', 'Оған жай жүру аздық етіп, енді бөлмеден бөлмеге жүгіре бастады! Тік тұрғандағы тепе-теңдігі толық қалыптасып келеді. Даму бақылағышында ірі моторикадағы осы үлкен жетістігін белгілеңіз.'),
  ('7df527b0-7bf7-42d6-b9f4-0f231186e70c', 'Ас мәзірінің әміршісі 🥣', 'Кеше сүйіп жеген тамағын бүгін итеріп тастай ма? Бір жастан кейін тамақ талғау қалыпты жағдай. Алаңдамай, Пайдалы рецептерден басқа баламаларды іздеп көріңіз.'),
  ('85bb394b-b9a2-4a30-a34a-98479663ff2d', '«Бұл не?» кезеңі ☝️', 'Ол бәрін саусағымен көрсетіп, ерекше дыбыс шығарады. Осылайша Сізден айналасындағы заттардың атауын айтуды сұрайды. Көрсеткен әр затының атауын оған асықпай айтып беріңіз.'),
  ('f78a5d11-ba9f-41e9-8557-2840d12964be', 'Кінә сезімінен арылыңыз 📝', 'Бүгін оған аз кітап оқыдым, экранға тым көп қарады... Мұндай ойларды тоқтатыңыз! Сіз қолыңыздан келгеннің бәрін жасап жүрсіз. Көңіл күй күнделігіне өзіңізге жанашырлық танытатын жазба қалдырыңыз.'),
  ('1167974e-3206-4f0f-b4e8-4d14f35444b6', 'Бір күндізгі ұйқыға көшу 🥱', 'Таңертең ұйықтағысы келмей, бүкіл кестесі бұзылды ма? Ол өсіп келеді! Бұл күндізгі екі ұйқыдан бір ұйқыға ауысу кезеңі болуы мүмкін. Күн тәртібін біртіндеп қайта реттеңіз.'),
  ('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2', 'Сиқырлы бөлме 🪄', 'Ақылды ертегілерде әлемді зерттейтін батыл кейіпкер туралы ерекше оқиға құрастырыңыз. Осы тәтті ертегімен түнгі ұйқыға көшуді жеңілдетіңіз.'),
  ('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c', 'Аналарға арналған орындарды ашыңыз ☕', 'Үйдегі бірдей қабырғаларға қарай беруден шаршадыңыз ба? Аналарға қолайлы орындардан балаларға арналған ойын бұрышы бар дәмхана тауып көріңіз. Бөпеңіз ойнасын, ал Сіз асықпай кофе ішіңіз.'),
  ('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b', 'Бірге кітап оқыңыз. 📖', 'Ол енді кітаптың беттерін өзі аударғысы келеді. Қалың беттері бар кітаптар мен дыбысталған ертегілер осы кезеңге өте қолайлы.'),
  ('d29d33a4-aed4-4635-9f37-3a7a39a378b0', 'Шекараларды тексеріп жүр. 🛑', '«Жоқ» дегеніңізге қарамастан, көзіңізге қарап тұрып әлгі затқа қайта қол соза ма? Бұл қырсықтық емес, ол жай ғана шекараларды танып-білуге тырысып жүр. Сабырлы әрі сөзіңізге берік болыңыз.'),
  ('f3355fe9-0c3b-41e2-9043-0a5cb8a61740', 'Түнде ояну. 😴', 'Тіс жару немесе өсу секірісі ұйқыны бұзуы мүмкін. Қажет болса, ұйқы таймерін бақылап, күн тәртібіндегі өзгерістерді белгілеп отырыңыз.'),
  ('2e0b0129-5a3d-466c-a35f-ef4707dea065', 'Әкенің жұбатуы 🫂', 'Бөпеңіз түнде оянғанда міндетті түрде кезектесіңіздер. Кейде қараңғыда әкесінің ырғақты сипауы мен иісі ғана оны бірден тыныштандырады.'),
  ('812159bf-a0a9-4bf9-8e7b-97d82abbaa80', 'Үлкендерге еліктейтін кішкентай айна 🧹', 'Сіз үйді сүртіп жүргенде, ол да қолына шүберек алып, дәл солай істеуге тырысады. Ол — Сіздің кішкентай көшірмеңіз! Қолына қауіпсіз бір зат беріп, оны үй шаруасына қатыстырыңыз.'),
  ('9510e83b-c10c-4166-b921-d1cd3c8f203c', 'Ұмытшақтықпен күрес 🛒', 'Жадыңыз тағы да жаңылыстырды ма? Үйде таусылған әрбір ұсақ-түйекті бірден Сатып алу тізіміне қосыңыз, жұбайыңыз жұмыстан қайтарда ала келсін.'),
  ('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c', 'Логикалық ойындар 🧩', 'Ойыншықтарды қорапқа салып, кейін бәрін қайта төге ме? Осылайша ол «ішінде» және «сыртында» ұғымдарын түсіне бастайды. Оның осы қайталанатын әрекеттерін үнсіз бақылаңыз.'),
  ('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec', 'Әкенің көңілді қылығы 🤡', 'Бөпені күлдірудің ең жақсы жолы — әкесінің қызық дыбыстар шығаруы. Бүгін кешке балаңызбен бірге осы көңілді сәттерден ләззат алыңыз.'),
  ('3170ad10-66c6-4ca0-bf72-80b0daf91373', 'Кешкі әдеттер ұйқыға дайындайды. 🌙', 'Күн сайын бір уақытта қайталанатын шағын әдеттер (тіс тазалау, ертегі оқу) оның ұйықтауын едәуір жеңілдетеді.'),
  ('64832db8-28ac-41fb-8d33-21a72b48fa8c', 'Зейінді зерттеуші! 🔍', 'Үйдегі әрбір бұрыш пен әрбір шкаф ол үшін жаңа әлем. Қауіпсіз орта жасап, үйдің ішін еркін зерттеуіне мүмкіндік беріңіз.'),
  ('f283f219-7efa-4926-a360-3fb653057b9b', 'Таза ауа және мол қуат! 🌳', 'Балалардың далада ойнап, бойындағы қуатын жұмсауы күндізгі ұйқыға оңай жатуына көмектеседі. Саябаққа бірге барыңыздар.'),
  ('35a5e175-d9f9-4d9a-9445-a523d64bc595', 'Өзі тамақтанғысы келеді. 🥦', 'Үсті-басы былғанса да, қасықты өзі ұстасын. Бұл оның дербестік сезімі мен көз-қол үйлесімін дамытады.'),
  ('66beeaaa-0b78-4114-b41f-8d7e6f407c55', 'Демалуға құқығыңыз бар. 🛁', 'Күні бойы тыным таппадыңыз. Балаңыз ұйықтағаннан кейін ыстық шайыңызды құйып, тыныштықтан ләззат алыңыз.'),
  ('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6', 'Шапшаң қадамдар! 🏃‍♂', '️ Ол енді бөлмелер арасында еркін жүріп, тіпті жүгіруге талпынып жүр. Оның соңынан ілесу — аналар үшін нағыз жаттығу!'),
  ('1008f62b-ef11-490d-886c-a80a06e64454', 'Көзің қайда? 👀', 'Дене мүшелерін табу ойыны әлі де оның сүйікті ойындарының бірі. Ойынды айна алдында ойнап, одан да қызықты етіңіз.'),
  ('47368a03-c0f0-4e5c-a343-b4577d2ffa64', 'Түнгі тыныштық 🛀', 'Жылы ванна, массаж және бөлмені қараңғылау. Ұйқы режимін сақтау — түні бойы үздіксіз ұйықтаудың ең басты құпиясы.'),
  ('8edf71cc-a90b-4465-947f-070adc35b5f7', 'Музыкаға билеу 🎶', 'Теледидардан ырғақты әуен естісе болды, бөксесін бұлғаңдатады. Музыканы сезіну қабілеті дамып келеді, Сіз де қосылып билеңіз!'),
  ('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8', 'Аналардың сырласуы 💬', 'Өзіңізді жеткіліксіз сезінесіз бе? Дереу Anacan қауымдастығына кіріп, басқа аналардың қолдау білдірген пікірлерін оқып, көңіліңізді жайландырыңыз.'),
  ('4a0eb59e-113c-42ab-af5f-e0f64f837b44', 'Жаңа орындарды зерттеңіз. ☕', 'Күнделікті күйбең тірліктен жалықтыңыз ба? Қолданбамыздан балалар арбасымен кіруге ыңғайлы дәмхана тауып, бір шыны кофе ішіп демалыңыз.'),
  ('4c4da832-707f-472e-a209-374acff11d94', 'Үй шаруасындағы көмекші! 🧹', 'Қолына шүберек алып шаң сүртуге немесе сыпырғышпен ойнауға асыға ма? Сізге еліктеуі — оның жақсы дамып келе жатқанының тамаша белгісі.'),
  ('ca45e311-dc2b-43fe-aa24-08a197d26f0a', 'Баланың дамуы туралы сұрақтарыңыз бар ма? 🤖', '13-14 айлық кезеңге қатысты Сізді толғандыратын мәселе болса, тіпті түнде де Anacan AI көмекшімізге жазыңыз.'),
  ('0ffbde04-3193-4b21-aa17-136db5de3c72', 'Сезім күнделігі 📝', 'Өзіңізді жалғыз сезінгенде, Көңіл күй күнделігіне сезімдеріңізді жазыңыз. Барлық әйелдер осындай кезеңдерден өтеді, Сіз мықтысыз.'),
  ('7cdfa7f4-2c92-497d-9290-43caf53d8a56', 'Тыныштық қажет 🤫', 'Бөлмедегі тыныштықты Дыбыс өлшегіш арқылы сақтаңыз. Түнгі ұйқының бөлінуі бөпеңіздің де, Сіздің де таңертеңгі көңіл күйіңізге әсер етеді.'),
  ('302bafdb-c5ca-4389-a56e-16a2ddd6812b', 'Кешкі рәсімнің күші 🛀', 'Жылы ванна әрдайым көмектеседі. Кешкі рәсімді ешқашан бұзбаңыз, өйткені ол бөпенің миына ұйықтайтын уақыт келгенін анық білдіреді.'),
  ('309b39de-d5f5-4702-93e1-596dca9c9021', 'Күш-қуатыңызды қалпына келтіріңіз 🥑', 'Бөпе тойса, енді кезек Сізде. Күнделікті қарбаласта түскі асты жүріп бара жатып ішпеңіз. Пайдалы рецептілерден қуат беретін тіскебасар таңдап, диванға жатып демалыңыз.'),
  ('66b4bd9b-8226-4190-94c7-9d50f8db6c34', 'Ішіңіздегіні бөліскіңіз келе ме? 💬', '«Неліктен менің балам бұлай істейді?» деген ой мазаңызды алып жүр ме? Anacan қауымдастығына қосылып, басқа аналардың ұқсас оқиғаларын оқыңыз да, көңіліңізді тыныштандырыңыз.'),
  ('80e6be85-6917-46a0-b283-acc653cca6c1', 'Кітап парақтайтын зерек бөпе 📖', 'Қалың беттері бар кітаптарды парақтап, суреттерге көңіл бөле ме? Бұл оның көру арқылы есте сақтау қабілеті дамып жатқанын білдіреді. Оған түрлі-түсті ертегі кітаптарын көбірек оқып беріңіз.'),
  ('df1f7c26-41ff-4081-9b25-dae8d38c75e8', 'Сізбен өткізген уақыт қандай тамаша. ✨', 'Әр күн — жаңа бір шытырман оқиға. Ол ұйықтап жатқанда кішкентай қолдарына қарап, бүгінгі шағын жетістіктеріне жымиыңыз.'),
  ('52e92eba-b885-4c30-891d-aa6e5379acf9', 'Өз бетінше тамақтануға талпыныс 🥄', 'Қасықты қолыңыздан алып, өзі тамақтанғысы келеді. Төгіп, үстін былғайды, бірақ бұл оның қимыл-қозғалыс дағдылары үшін маңызды. Өз бетінше әрекет етуіне мүмкіндік беріңіз.'),
  ('a26c1e0d-7872-4f7e-9268-2fba22c9203a', 'Сұрағыңыз бар ма? 🤖', '13-14 айлық баланың мінез-құлқы немесе дамуы туралы мазалаған сұрақтарыңыз болса, Anacan AI көмекшісінен бірден кеңес ала аласыз.'),
  ('eb8ab523-6225-489f-8a09-0f37ba40956a', 'Энергиясын шығарсын! 🏃‍♂', '️ Күндізгі ұйқыға жатар алдында оны аздап шаршататын қимылды ойындар ойнап (қуаласпақ, доп лақтыру), жайлы ұйықтауына көмектесіңіз.'),
  ('2ca5e024-95be-449a-af7e-ee34228f8bca', 'Жоспарлы болу көңілді тыныштандырады. 📝', 'Ертең істейтін істеріңізді немесе ас мәзірін шағын жазбалар түрінде жоспарлап, көңіліңіз жайланып ұйқыға жатыңыз.'),
  ('efb1280f-e8f0-4ecf-bb77-385f667aff5d', 'Жайлы орын іздеп жүрсіз бе? ☕', 'Кейде үйден шығып, басқа ортада болғыңыз келеді. Анаға қолайлы орындар бөлімінен балаңызбен баруға ыңғайлы жақын маңдағы дәмхананы тауып, кофеден ләззат алыңыз.'),
  ('aa01a859-3ad0-4c64-9ef3-4423ccf76d24', '«Жоқ» дегенді жақсы көре ме? 🛑', 'Сіздің қарсылық білдіргеніңізге еліктеп, ол да бәріне «жоқ» деуі мүмкін. Бұл кезеңде шыдамдылық танытып, оған бірнеше қарапайым таңдау ұсыну маңызды.'),
  ('b8b7257f-64c5-46a3-b958-ded901da8e8d', 'Су ішуді қызықты етіңіз. 💧', 'Белсенді қимыл-қозғалыстан кейін ағзасы сусызданбауы үшін, оған түрлі түсті су құтысымен жүйелі түрде су ұсынып тұрыңыз.'),
  ('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c', 'Әкенің ертегі оқитын уақыты. 👨‍🍼', 'Бүгін кешкі ертегіні оқып, бөпені ұйықтатуды әкесіне тапсырып, өзіңізге аздап демалыс беріңіз.'),
  ('4484d3ee-8677-4454-8e65-371ba851a267', 'Ақ шудың күші. 🎶', 'Егер белсенді өткен күннің әсерінен ұйықтай алмаса, Ақ шу бөлімінен мұхиттың немесе жаңбырдың дыбысын қосып, бөлмеде тыныш орта қалыптастырыңыз.'),
  ('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd', 'Тәтті құшақтар! 🤗', 'Сізді кенеттен құшақтап, сүюге тырысуы — оның сүйіспеншілігін білдіру тәсілі. Осындай қайталанбас мейірім сәттерінен ләззат алыңыз!'),
  ('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21', 'Әңгімеге тартыңыз. 🗣', '️ Бөлмедегі заттардың атауын айтып, оның қайталауын күтіңіз. Сөздік қоры дәл осындай шағын ойындар арқылы молаяды.'),
  ('5d99a4ad-d33f-448d-9f7c-32943cbfa648', 'Азу тістері шығып келе ме? 🦷', 'Қызыл иегі ісініп, бәрін кеміріп жүр ме? Артқы тістері шығып келе жатқан болуы мүмкін. Салқын тіс қаситын ойыншықтарды мұздатқышқа салыңыз.'),
  ('70d7d4ed-5c06-44bc-99e5-3871d07a9510', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі жарықты бәсеңдетіп, барлық экранды өшіріңіз. Мелатонин тек тыныш әрі жарығы аз ортада бөлінеді.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('aa9c9479-f8d5-4149-b7c4-99976958a17c'::uuid, 'Қауіпті аймақтарға қолы жетеді ⚡', 'Бойы өсіп, бұрын қолы жетпеген сөрелерге енді жете алады. Теледидар тұғыры, жиһаз бұрыштары... Үйдің қауіпсіздігін шұғыл түрде қайта тексеріңіз.'),
  ('0872925d-e2d7-471e-ba13-22ee468f0a1f', 'Кенеттен ояну 😭', 'Түн ортасында айғайлап оянып, тынышталмай ма? Дауысын Жылауды талдау құралына тыңдатып, мәселенің себебін анықтаңыз.'),
  ('1fe0720b-91d5-4dc9-ad61-71e5ff522246', 'Өсу қарқыны. 📏', 'Оның тез өсіп келе жатқанын киімдерінен де байқап жүрсіз. Трекерге салмағы мен бойын жазып, дені сау болып өсіп келе жатқанына көз жеткізіңіз.'),
  ('ca5a420a-5b8f-49ce-b884-6a219b8b71aa', 'Сезімі үлкен, денесі кішкентай 🛑', 'Қалағаны болмағанда өзін жерге тастай ма? Бұл — бүлдіршін кезеңіне тән ашу ұстамалары. Сабыр сақтап, көзіне қараңыз және оның жанында екеніңізді білдіріңіз.'),
  ('005096a2-1549-4208-a331-7e39e1da9587', 'Жедел педиатр 🤖', '13.5 айлық даму секірістері туралы ақпарат қажет пе? Өзіңізді қинамаңыз, Anacan AI-дан нақты әрі педиатр мақұлдаған тізімді сұраңыз.'),
  ('7de487db-11d1-4c22-8b8d-e58adb31344a', 'Қарапайым нұсқауларды орындайды 🧸', '«Аяқкиіміңді әкел» дегенде, шынымен барып алып келе ме? Сөздік қоры мен түсіну қабілеті шарықтау шегінде! Оны ойындарға жиірек қатыстырыңыз.'),
  ('f39f5c34-c612-4758-a438-ed52b2d49ba8', 'Сау бол дейміз 👋', 'Біреу есіктен шыққанда, бөпеңіз өздігінен қол бұлғап қоштасады! Бұл — тамаша әлеуметтік дағды. Оны әрдайым қолдап, жігерлендіріп отырыңыз.'),
  ('0dcb1657-4eeb-47c5-a193-84ed106d43bc', 'Сұрауға қысылмаңыз 🤖', 'Ұйқы тәртібінде бір нәрсені дұрыс істемей жүрмін деп ойлайсыз ба? Күмән тудырған кез келген сұрақты Anacan AI-дан бірден сұрап, көңіліңізді тыныштандырыңыз.'),
  ('10d800e4-c6bd-4325-b22e-385edaca8f7f', 'Түнгі оянулар әлі де жалғасып жүр ме? 😴', 'Егер соңғы күндері ұйқысы қайтадан бұзылса, Anacan ұйқы таймері арқылы кестені талдап, күн тәртібіндегі олқылықтарды анықтаңыз.'),
  ('319cae50-0492-468a-98e4-1b38563ab7ea', '14 айға жақындап қалдық! 10 күн қалды! 🎂', 'Сену қиын! Тура 10 күннен кейін бөпеңіз 14 айға толады. Күн өткен сайын ол дербес тұлға болып қалыптасып келеді.'),
  ('2064ec2b-0483-4d3b-9453-106b6b9f32f8', 'Қарындашпен алғашқы тәжірибелер. 🖍', '️ Оған ыңғайлы жуан қарындаштар беріп, қағазға шимайлап сурет салғанын сүйіспеншілікпен бақылаңыз. Бәлкім, болашақ суретші өсіп келе жатқан шығар!'),
  ('7f86b541-f24f-46cc-bf72-a538c8e62fa0', 'Ойыншықтарымен өз бетінше ойнау. 🧩', 'Аз уақыт болса да өз бетінше ойнай алуы — дербестікке бастайтын үлкен қадам. Оны алыстан бақылаңыз.'),
  ('f945146d-2bbb-40d9-95f6-29bdc7f3be6d', 'Өсуін жалғастыруда. 📏', 'Балаңыздың киімдері тар болып барады! «Дамуды бақылау» бөліміне бойы мен салмағының жаңа көрсеткіштерін қосып, өсуін қадағалаңыз.'),
  ('241a81f3-8158-4d3c-a8b2-640a1b060696', 'Тамақ талғауды жеңу. 🍲', 'Кей күндері ол ең сүйікті тағамынан да бас тартуы мүмкін. Мәжбүрлемеңіз, тек әртүрлі балама ұсынып көріңіз.'),
  ('4716a93b-966d-4c69-b174-c2a48e9a09fa', 'Кешкі ванна. 🛁', 'Жылы ванна күні бойы жиналған шаң-тозаңнан арылуға көмектесіп қана қоймай, бөпеңізді тыныштандырып, ұйқыға тамаша дайындайды.'),
  ('dbbcb16c-cf48-47f7-92ab-992ed2fab247', 'Дене мүшелерін таниды. 👃', '«Мұрның қайда?» немесе «Құлағың қайда?» ойынын ойнаңыз. Дұрыс көрсеткенде, қол шапалақтап, жігерлендіріңіз.'),
  ('0cc0cda4-4fef-4e92-9af2-cd065cfee008', 'Сіз ең керемет жансыз! 💖', 'Бала өсіру марафон секілді. Бүгін кешке өзіңізге аздап уақыт бөліп, сүйікті фильміңізді көріңіз немесе жай ғана тыныш демалыңыз.'),
  ('781ac9f7-7fd3-4466-9d70-0b41dd1e954a', 'Ойыншықтарын сүйреп жүр! 🧸', 'Жіппен сүйрейтін ойыншықтар немесе итеріп жүретін шағын арбалар қазір оның сүйікті ермегіне айналады. Бұл тепе-теңдікті сақтауға арналған тамаша жаттығу!'),
  ('7dec83e1-5089-42b4-a2b5-f3d997eb1138', 'Өзіңізді де қуаттандырыңыз. 🥗', 'Қуаты тасыған баладан қалыспау оңай емес. Әйелдерге арналған пайдалы рецепттердің бірін таңдап, күш-қуатыңызды қалпына келтіретін дәмді әрі дәруменге бай ас дайындаңыз.'),
  ('6942d3e7-d39d-4aee-b8a0-ef2313920693', '«Өзім!» деген қырсықтық. 🧦', 'Егер шұлығын өзі киюге немесе тамақты өз бетінше жеуге тырысса, оған кедергі жасамаңыз. Дербестік сезімі дәл осындай шағын талпыныстар арқылы дамиды.'),
  ('c0c8236b-5e7c-45b1-a5c1-d45f005b603c', 'Іштегі сезімді сыртқа шығару. 📝', 'Кейде бәрі тым ауыр болып кетуі мүмкін. Көңіл күй күнделігіне ішіңіздегіні және шаршағаныңызды жазып, күн бойы жиналған күйзелістен арылыңыз.'),
  ('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb', 'Таза ауадағы жаңалықтар. 🌳', 'Саябақта жапырақтарды ұстап көру және тастарды жинау оның сезім мүшелерін дамытады. Серуендеу үшін жаңа саябақ таңдаңыз.'),
  ('9052004a-46e9-4652-8de2-61f2a8f774d7', 'Шаршау мен мақтаныш💖', '14 ай бойғы шаршау мен мақтанышты бүгін кешке жұбайыңызбен бірге атап өтіңіз. Сіздер — керемет командасыздар!'),
  ('dde3a118-6b4b-4b86-b077-744218b7fcd7', 'Балаңыз қандай үлкен жолдан өтті! 📈', 'Алғашқы күндердегі қорқыныштың орнын өзіне сенімді ананың нық сенімі басты. Өзіңізді мақтан тұтыңыз!'),
  ('33a2089a-67cc-4441-bb79-483ad77a1a42', 'Өзіңізге уақыт бөліңіз. 🛁', 'Күні бойы аяғыңыздан тік тұрдыңыз. Шаршағаныңызды Көңіл күй күнделігіне жазып, бойыңызды жеңілдетіңіз де, ыстық шай ішіп демалыңыз.'),
  ('625bdfef-2359-4843-aaac-6c8411b1963b', 'Заттарды лақтыру өнері. 🎾', 'Ойыншықты немесе тамақты жерге лақтырып, артынан бақылауы — тентектік емес, гравитацияны зерттеуі. Сабыр сақтап, сынбайтын заттармен ойнауына мүмкіндік беріңіз.'),
  ('ee0ba9ab-4b88-462e-aae9-f9a207218204', 'Артқа және жанға қадам басу! 🦀', 'Ол енді тек алға емес, артқа және жан-жаққа қадам басып көруге тырысады. Бұл — тепе-теңдік пен қимыл-қозғалыс дағдыларына арналған тамаша жаттығу!'),
  ('21478892-353c-43fd-ba31-59c9aeb8255d', 'Аналарға арналған қуат көзі! 🥗', 'Қимылы көп балалар анадан екі есе күш-қуат талап етеді! Пайдалы рецептілердің ішінен қызықты тағам таңдап, әзірлеу арқылы өзіңізді қуантыңыз.'),
  ('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e', 'Алло, бұл кім? 📱', 'Пультті немесе телефонды құлағына ұстап, Сіз сияқты сөйлесуге тырыса ма? Осындай сүйкімді еліктеу сәттерін жіберіп алмаңыз.'),
  ('ab819835-a2e1-481b-91b5-5391eb6051e8', 'Ұйқы нормаларын бақылаңыз. ⏱️', 'Күндізгі ұйқысы бір ретке дейін қысқарды ма? Бөбеңіз ұйықтағанда ұйқы таймерін қосып, жаңа режимге бейімделуін графиктен бақылаңыз.'),
  ('96b02483-42a2-4868-a751-d817b0144951', 'Су ішуді ұмытпаңыз. 💧', 'Бөпеңіз де, Сіз де! Белсенді ойындардан кейін және тамақтану арасында міндетті түрде су ішіп, ағзадағы су теңгерімін сақтаңыз.'),
  ('d89100dc-a7f8-49dd-8358-e3c63248fa5d', 'Кішкентай көмекші іске кірісті! 🧹', 'Сізге еліктеп, қолына шүберек алып шаң сүрте ме немесе сыпырғышпен ойнай ма? Балалар көбіне көргенін қайталау арқылы үйренеді.'),
  ('eea0806e-a72b-42f1-b1c3-b7a791619a96', 'Ұйқы режимі өзгерді ме? 😴', 'Егер күндізгі ұйқысы бір ретке азая бастаса, өтпелі кезеңде түнгі ұйқысы ұзаруы мүмкін. Ұйқы таймері арқылы соңғы күндердегі кестесін бақылаңыз.'),
  ('15bfc39a-e833-4e38-b7fc-bc13ef473b00', 'Өз бетінше ойнайтын уақыт 🧸', 'Бөпеңіз енді 10-15 минут бойы ойыншықтарымен өз бетінше ойнай алады. Бұл оның зейін қою уақыты ұзарғанын білдіреді. Тыныштықтың рақатын көріңіз.'),
  ('99045f34-6450-4abd-856c-64fd61405e7b', 'Дауыс ырғағыңызды түсінеді 🗣️', 'Сіз байсалды дауыспен «жоқ» дегенде, тоқтап, Сізге қарай ма? Ол эмоциялар мен тыйымдарды түсіне бастады!'),
  ('dc953aca-0624-4e7e-a96b-11f2b35b9a14', 'Музыканың күші 🎶', 'Кешкісін себепсіз мазасыздана бастаса, оны баяу классикалық музыкамен тыныштандырып көріңіз. Көбіне осы қарапайым тәсіл ғажайып нәтиже береді.'),
  ('1eee6b26-c3fa-460c-8e48-030eb1e5a77c', 'Түрлі түсті шимайлар! 🖍', '️ Бөлменің бір бұрышына оған ыңғайлы жуан қарындаштар мен үлкен парақ қойыңыз. Алғашқы өнер туындыларын Бөпе альбомында мәңгілікке сақтауды ұмытпаңыз!'),
  ('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69', 'Сарапшының көмегі қажет пе? 🤖', '«14 айлық баланың сөйлеу қабілетін қалай дамытамын?» деген сияқты сұрақтарыңызды тіпті түнде де Anacan AI көмекшімізге қоя аласыз.'),
  ('44b33bc4-3602-4265-9fe5-30b5609015de', 'Әкелердің бөпеге қарайтын уақыты. 👨‍🍼', 'Кешкі ойындар өте белсенді өтеді. Бүгін кешке әкесі мен бала қуаласпақ ойнасын, ал ұйықтату кезегін әкесіне беріп, өзіңіз демалыңыз.'),
  ('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95', 'Жанашырлық сезімі оянады! 💖', 'Біреу жыласа немесе мұңайса, балаңыз жанына барып, оны жұбатуға тырыса ма? Балаңыздың эмоциялық интеллектісі өте жақсы дамып келеді.'),
  ('e569bdf3-a845-44dc-852b-5318a0cf6a72', 'Таза ауадағы сарқылмас қуат! 🌳', 'Еркін қыдырып жүрген балаңыздың бойындағы энергиясын шығару үшін өзіңізге баруға ыңғайлы, қауіпсіз әрі жаңа саябақтарды Анаға қолайлы орындардан табыңыз.'),
  ('381afc75-3dbd-4716-b5ea-3af987c642dc', 'Күндізгі ұйқыға қарсылық. 😴', 'Ойнау ұйықтаудан әлдеқайда қызық! Ұйықтардан жарты сағат бұрын белсенді ойындарды тоқтатып, тыныш әрекеттерге көшіңіз.'),
  ('3ed2bd45-e711-4e56-bdc9-29b31e605069', 'Сұрағыңыз бар ма? 🤖', '«Неліктен балам кей күндері ештеңе жемейді?» деген сияқты маңызды сұрақтарыңызды тіпті түнде де Anacan ЖИ көмекшісіне қойып, қолдау ала аласыз.'),
  ('718ac202-3ddd-463e-90fd-d1367161e2b5', 'Тамақ талғаумен күресу. 🍲', 'Кей күндері ол тіпті ең сүйікті тағамынан бас тартуы мүмкін. Мәжбүрлемеңіз, жай ғана қолданбамыздағы әртүрлі балама рецептілерді қолданып көріңіз.'),
  ('9693a098-adc4-4d19-ab73-4c5cc195a25e', 'Өзім сүртемін! 🧽', 'Сіз үстелді сүртіп жатқанда, ол да майлық сұрай ма? Кішкентай көмекшіңізге қауіпсіз бір тапсырма беріңіз. Бұл оның өзіне деген сенімін айтарлықтай арттырады.'),
  ('98ba1e51-63c6-4c73-891d-99f1b14f3495', 'Ақ шудың күші. 🎶', 'Белсенді өткен күннің әсерінен немесе тісі шығып жатқандықтан ұйықтай алмаса, Ақ шулардан жаңбыр дыбысын қосып, бөлмеде тыныш орта қалыптастырыңыз.'),
  ('f1854aec-f168-4789-a191-8a1fa96c3cd8', 'Қауіпсіздікті күшейтетін кез келді. 🛡', '️ Ол өздігінен жүріп, шкафтарды аша бастаған сайын қауіп те арта түседі. Балаларға арналған құлыптарды Таңдаулы өнімдер тізімінен қараңыз.'),
  ('02d67440-3e37-4d1c-99f8-cbfa7aadda52', 'Пайдалы тіскебасар уақыты. 🍎', 'Күш-қуаты таусылмайтын балалар үшін туралған жемістер немесе көкөніс таяқшалары — тамаша таңдау. Өзі ұстап жесін.'),
  ('4a197291-3001-4afb-9a70-d4320bd260b2', '«Бұл не?» кезеңі. ☝', '️ Ол бәрін саусағымен көрсетіп, атауын сұрайды. Әр заттың атауын шыдамдылықпен айтыңыз — бұл оның сөздік қорын жылдам молайтады.'),
  ('8938f1b0-220a-48ac-b5f5-33db3613995c', 'Әкемен ертегі оқу уақыты. 👨‍🍼', 'Бүгін кешкі ертегіні оқып, бөпені ұйықтатуды әкесіне тапсырып, өзіңізге аздап демалыс беріңіз.'),
  ('47ea2f2a-adf0-473a-a6a2-47218a354bbd', 'Маймыл сияқты өрмелейді! 🧗‍♂', '️ Ол диванға немесе аласа жиһаздарға өздігінен өрмелеуге тырысады. Айналаны қауіпсіз етіп, қимыл-қозғалыс дағдыларын дамытатын осы батыл қадамдарын бақылауыңызбен байқап көруіне мүмкіндік беріңіз.'),
  ('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d', 'Әуеден сүйіс жолдайды! 👋', 'Ол енді кетіп бара жатқандарға саналы түрде қол бұлғап, әуеден сүйіс жолдай ма? Оның осы сүйкімді әрі қарым-қатынасқа бейімділігін көрсететін әрекетіне сүйсініңіз.'),
  ('ea4bc86f-6869-478f-98a6-52bb8dc4c40f', 'Ұйықтау оңайырақ болады. 🌙', 'Күн сайын кешке бірдей ретпен орындалатын әрекеттер (шомылу, ертегі оқу, жарықты бәсеңдету) оның ұйқыға жайлырақ кетуіне көмектеседі.'),
  ('3d197dae-8e31-468d-8d92-41ba68985a62', 'ТУРА 14 АЙ! 🎉', 'Құттықтаймыз! Босанғаныңызға тура 14 ай болды! Дәл қазір Бөпе фотосессиясында арнайы тақырыптық сурет жасап, осы қуанышыңызды Anacan қауымдастығында бөлісіңіз!'),
  ('6b7d6637-7328-44aa-b6c8-47c73df3a6f3', 'Өсу қарқыны жылдам. 📏', 'Балаңыздың киімдері қайтадан тар бола бастады! Даму трекері бөліміне бойы мен салмағының жаңа көрсеткіштерін қосып, дені сау өсуін бақылаңыз.'),
  ('807127b9-417f-43a0-9bca-9ef33fbdadb8', 'Дене қимылымен жауап береді 🗣️', '«Жүрейік пе?» дегенде қолдарын көтереді немесе «Жоқ» дегенде басын шайқайды. Түсіну қабілеті таңғаларлықтай артты!'),
  ('356f85b5-b941-4e2e-8218-18498e652ff8', 'Текшелерден қамал тұрғызады 🧱', 'Екі немесе үш ойыншық текшені бірінің үстіне бірін қоюға тырысады. Оның осы шағын инженерлік талпыныстарын үнсіз бақылаңыз.'),
  ('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3', 'Ақ шудың күші. 🎶', 'Егер белсенді өткен күннің әсерінен немесе тісінің шығуына байланысты ұйықтай алмаса, Ақ шу бөлімінен жаңбыр дыбысын қосып, бөлмеде тыныш атмосфера қалыптастырыңыз.'),
  ('f73e2678-7057-466b-a01a-218bff7ab963', 'Тіс тазалау қызығы. 🪥', 'Тіс щеткасын өзі ұстағысы келе ме? Оған лайық жұмсақ щеткалармен айна алдында тістеріңізді бірге тазалап, осы әдетті қалыптастырыңыз.'),
  ('58b586ed-1396-42c6-81f5-29f087488332', 'Ұйқыға оңай кету. 🌙', 'Белсенді күннен кейін бөлменің жарығын бәсеңдетіп, даусыңызды ақырындатыңыз да, баяу үнмен ертегі оқып, оны ұйқыға дайындаңыз.'),
  ('82b39d0a-8bac-4430-a17f-2937f0af35e1', 'Сіздің де күшіңіз таусылуы мүмкін. 🥗', 'Қатты шаршадыңыз ба? Әйелдерге арналған пайдалы рецепттердің ішінен күшіңізді тез қалпына келтіретін дәруменді смузи дайындап, өзіңізді қуантыңыз.'),
  ('917ef6a5-ae0d-4133-b145-53d60f762945', 'Допты маған әкел! 🧠', 'Енді ол қарапайым нұсқауларды өте жақсы түсінеді. Сіз бір нәрсе сұрағанда, оны қуана әкеліп беруі зердесінің қарқынды дамып келе жатқанын көрсетеді.'),
  ('f5a87b81-5f64-4d75-abaf-6fd718e53fc5', 'Пайдалы тіскебасарлар. 🍎', 'Жеміс тілімдері немесе йогурт — осы жасқа арналған тамаша тіскебасар. Қосымшамыздағы балаларға арналған рецептілерден ерекше әрі дәмді идеялар табыңыз.'),
  ('0b365564-8d23-4572-9881-7a4b9e2159bf', 'Алғашқы суреттері! 🖍', '️ Ол қағазға жуан қарындаштармен шимайлап сурет салғанды қатты ұнатады. Оның алғашқы өнер туындыларын «Бөпенің фотосессиясы» бөлімінде естелікке сақтап қойыңыз.'),
  ('c0638659-03fe-4ca5-b078-76057498811f', 'Анасының жанынан шыққысы келмейді 🥰', 'Сіз тіпті дәретханаға кіргенде де, есіктің ар жағында күтіп, жылайды. Қазір айырылысу мазасыздығы шегіне жеткен кезең. Әрдайым оның жанында екеніңізді сездіріп, тыныштандырыңыз.'),
  ('f2ba1614-ef41-4060-97ee-0fe66e58b884', 'Су ішу әдеті маңызды. 💧', 'Белсенді қимылдаған сайын шөлдеу де күшейеді. Ойын кезінде және тамақтан кейін оған су ұсынуды ұмытпаңыз.'),
  ('1bf6a974-24ed-47b3-8587-a38235ea120e', 'Асүйді зерттеу! 🍳', 'Кәстрөлдер, қасықтар мен пластик ыдыстар оның сүйікті ойыншықтарына айналды. Қауіпсіз шкафтарды зерттеуіне мүмкіндік беріңіз.'),
  ('88b4c840-5c20-4f9f-8b89-4530da60297b', 'Қауіпсіздік шараларын жаңарту керек! 🛡', '️ Ол еркін жүріп, шкафтарды аша бастаған сайын қауіп те арта түседі. Балаларға арналған құлыптар мен бұрыш қорғағыштарын «Ұсынылатын өнімдер» тізімінен міндетті түрде қарап шығыңыз.'),
  ('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3', 'Тыныштандыратын ванна. 🛁', 'Жылы ванна күн бойы жиналған энергияны шығаруға көмектесіп қана қоймай, бұлшықеттерді босаңсытып, ұйқыға тамаша дайындайды.'),
  ('409e6b49-8ccb-4975-92b1-c12021092540', 'Кешкі ертегінің сиқыры бар. 📖', 'Ұйықтар алдында оқылған қысқа ертегі қиялын дамытып қана қоймай, араларыңыздағы эмоциялық байланысты да нығайтады.'),
  ('2cca6125-c540-4b9b-9a06-6121b60507e5', 'Таза ауадағы шытырман! 🌳', 'Үйде энергиясын шығара алмай жүр ме? Бөпе арбасымен жайлы серуендеуге болатын қауіпсіз саябақты таңдап, бірге таза ауаның рақатын көріңіздер.'),
  ('73b001a8-93ab-4798-bca3-094a519e468a', 'Сезімдеріңізге ерік беріңіз. 📝', 'Әр күн оңай өте бермейді, кейде бәрі тым ауыр сезілуі мүмкін. Ішіңіздегі сезімдерді Көңіл күй күнделігіне жазып, күннің күйзелісінен арылыңыз.'),
  ('d452b163-e134-4c64-90b8-7e561b20c6f9', 'Сөздерге еліктейміз! 🗣', '️ Сіз айтқан сөздерді немесе жануарлардың дыбыстарын қайталауға тырыса ма? Өз ойын жеткізуге деген ынтасы артуы үшін бұл талпыныстарын қуана қолдаңыз.'),
  ('80913e3b-4640-4efe-ae49-ce789db16fd1', 'Керемет күннің соңы. ✨', 'Бүгін де ана ретінде қолыңыздан келгеннің бәрін жасадыңыз. Көзіңізді жұмып, өзіңізді мақтан тұтып, жайлы ұйқыға кетіңіз.'),
  ('8e332da4-937a-4f7f-af67-edbe9e325d0e', 'Қадамдары нық бола түсті! 🏃‍♂', '️ Ол енді үйдің ішінде өз бетімен еркін жүріп, кейде тіпті жүгіруге де талпынады. Оның осындай батыл қимылдары Сізді әрі мақтандырады, әрі үнемі сақ болуға мәжбүр етеді!'),
  ('b5982bde-910f-4d42-bc5f-8e5e9b2e683f', 'Аллергияға күдік 🤖', 'Жаңа тағам беріп, бетінің қызарғанын байқадыңыз ба? Абыржымас бұрын, алғашқы қадамдар туралы Anacan AI-дан біліңіз.'),
  ('0deab7a8-9a3b-4827-969f-f24303c70419', 'Тіс жару кезіндегі мазасыздық 🦷', 'Қызыл иегі қайта қызарып, сілекейі тоқтамай ағып жүр ме? Салқын тіс қаситын ойыншықтарды дайындаңыз.'),
  ('46166e0f-606a-46ff-86d4-07304bc93180', 'Су ішу әдеті маңызды. 💧', 'Белсенді қимылдаған сайын шөлдеу де күшейеді. Ойын кезінде және тамақтан кейін оған су ұсынуды ұмытпаңыз.'),
  ('c0b75b28-86cb-44ea-8bc4-de62c31fae30', 'Жоспар құрсаңыз, көңіліңіз жайланады. 📝', 'Ертең істейтін істеріңізді немесе ас мәзірін қысқаша ой елегінен өткізіп, шағын жазбалар түрінде жоспарлаңыз да, төсекке алаңсыз жатыңыз.'),
  ('e47ea433-71bf-4c11-8e6e-6edbaec03292', 'Барлығын саусағымен көрсетеді. ☝', '️ Бұл — «Мынау не?» деген сұрақтың үнсіз нұсқасы. Оның қызығушылығын қолдау үшін көрсеткен заттарының атауын шыдамдылықпен қайталап айтыңыз.'),
  ('09564db7-642f-496e-b113-4fd15ad5aefe', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпенің оянуын жалғыз өзіңіз көтермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('30d6fd90-986c-491d-9a4a-39c6c9f48f69', 'Дамуды тексеру 🤖', '15 айлық кезеңдегі даму секірістері туралы ақпарат қажет пе? Дағдарыс күнтізбесіне назар салыңыз.'),
  ('661b0ef0-cce8-4702-8d5a-2f90901198ad', 'Кітап оқуға қызығушылық. 📖', 'Суретті кітаптардың беттерін парақтау және Сіздің оқығаныңызды тыңдау — сөздік қорды молайтудың тамаша тәсілі. Күн сайын 10 минут болса да, бірге кітап оқыңыздар.'),
  ('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2', 'Сіздің дауыс ырғағыңызды түсінеді 🗣️', 'Сіз байсалды дауыспен «жоқ» дегенде, тоқтап, Сізге қарай ма? Ол эмоциялар мен тыйымдарды түсіне бастады!'),
  ('553f302d-8ba0-44d9-9d9d-e356d494f003', 'Ұйқы алдындағы әдеттер. 😴', 'Жылы ванна мен таза пижама оны тыныштандырып, ұйқыға тамаша дайындайды.'),
  ('ed9814d4-d919-40b0-833b-d118d90c1727', 'Дербестікке ұмтылыс. 🥣', 'Ыдысын немесе қасығын өзі ұстағысы келсе, оған мүмкіндік беріңіз. Шашылған ас пен ретсіздік — үйренудің ең тамаша бөлігі.'),
  ('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e', 'Сізге де энергия қажет. 🥗', 'Күні бойы аяқтан тік тұрасыз. Әйелдерге арналған пайдалы рецепттердің бірін таңдап, күш-қуатыңызды қалпына келтіретін дәмді тіскебасар дайындаңыз.'),
  ('6df61827-7605-47d2-aeef-a4e811b4d8c8', 'Жылдам зерттеулер! 🏃‍♂', '️ Ол енді бөлмелер арасында сенімді жүріп, бәрін ұстап көргісі келеді. Үйдің қауіпсіз екеніне көз жеткізіп, бөпеңіздің осы белсенді кезеңінен ләззат алыңыз.'),
  ('c9b2a6a2-258b-4f8c-96f9-86282d8d8145', 'Эмоциялық жеңілдік. 📝', 'Шаршатқан күннен кейін сезімдеріңізді Көңіл күй күнделігіне жазып, күн бойғы күйзелістен арылыңыз. Сіз керемет анасыз!'),
  ('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267', 'Сіз нағыз қаһармансыз! ✨', '450 күн бойы көрсеткен сүйіспеншілігіңіз бен қамқорлығыңыз баға жетпес. Енді жайғасып, осы тамаша күннен кейін тыныш ұйқыға кетіңіз.'),
  ('4df5ec18-5365-45c2-a49d-90ce26310b0b', 'Тура 15 ай! 🎉', 'Уақыт неткен жылдам! Бөпеңіздің дүниеге келгеніне тура 1 жыл 3 ай болды. Құттықтаймыз.'),
  ('a50254b7-b2f0-44b3-8ee9-5246bba08038', 'Отбасылық дастарқандағы бақыт. 🍲', 'Ол енді Сізбен бірге бірдей тағамдарды жей алады. Қолданбамыздағы рецепттерден бүкіл отбасыға ұнайтын дәмдерді тауып, осы шағын мерейтойды атап өтіңіз.'),
  ('157a98b7-1825-4699-b38d-85781cd21cf3', 'Бөлмелер арасындағы марафон 🏃‍♂️', 'Ол енді жай жүрмейді, жүгіруге шақ қалды! Тепе-теңдікті сақтау қабілеті күн сайын жақсарып келеді. Даму трекерінде осы белсенді кезеңді мақтанышпен белгілеп қойыңыз.'),
  ('47ea1c98-c71a-45d9-b06c-d95aa3da437b', 'Әкемен ойын алаңы 👨‍👧', 'Күні бойы оның артынан жүгіріп, әбден шаршадыңыз. Кешкі кезек әкеде! Еденде аунап ойнау мен қуаласпақты оған тапсырыңыз.'),
  ('9e232723-1401-4819-8b29-1e4636b3edc3', 'Алғашқы суреттері! 🖍', '️ Қағаз бетіне жуан қарындаштармен шимайлап сурет салғанды қатты ұнатады. Оның алғашқы өнер туындыларын болашаққа естелік ретінде Бөпенің фотосессиясы бөлімінде сақтаңыз.'),
  ('2423bd81-d7d2-4b3e-b97a-32a10186bc3d', 'Рөлдік ойындар басталады. 🧸', 'Ойыншық қонжығын тамақтандыруға немесе оған су беруге тырыса ма? Бұл — оның Сізді қаншалықты мұқият бақылап, қайталайтынының ең сүйкімді дәлелі!'),
  ('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc', 'Сұрағыңыз бар ма? 🤖', '«Баламның тамақ талғауы қалыпты ма?» деген сияқты мазалайтын кез келген сұрақты тіпті түнде де Anacan ЖИ көмекшісінен сұраңыз.'),
  ('d4f6586e-25f9-4dd3-9a6b-1408627d49eb', 'Күндізгі ұйқыға қарсылық. 😴', 'Ойын әрқашан ұйқыдан қызығырақ көрінеді. Ұйықтауы қиындаса, Anacan ұйқы таймері арқылы соңғы күндердегі кестесін бақылап, режимін реттеңіз.'),
  ('13b16a71-31e8-44cf-bbf4-b97f55c8f45e', 'Сырттағы ауа райы түсініксіз бе? ⛅', 'Ауа райы және киім құралы терезеден байқалмайтын желдің жылдамдығын Сізге бірден көрсетсін.'),
  ('807a2e9f-2fb3-4378-94cf-0ad756854f25', 'Арнайы ертегі 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрыңыз: Жұлдыздарға өрмелеген батыл бала.'),
  ('d08fdb3f-542d-478d-95e6-72b2d85a8a9a', '15 айға 5 күн! 🎈', 'Кері санақ аяқталуға жақын! Енді Сіз үй ішінде жүріп, бәрін түсінетін кішкентай тұлғамен бір шаңырақ астында тұрып жатырсыз. Күлімсіреңіз!'),
  ('25f37869-be99-4918-83ae-dd5fecd2f5ce', 'Асүйде бірге. 🥦', 'Тамақ дайындап жатқанда оған сынбайтын пластик ыдыс пен ағаш қасық беріңіз, ол да өз тамағын дайындасын.'),
  ('9b3b08e6-de82-413f-9e4b-6da904b304a3', 'Бүгін үй қатты шашылып жатса да, күйзеліске түспеңіз.', 'Балалар жинақы үйді емес, бақытты анасын есінде сақтайды. Кофеңізді құйып, демалыңыз.'),
  ('67b35eea-eab9-41c5-88b7-f31e283eddd9', 'Балаңыз үйде энергиясын шығара алмай, мазасызданып жүр ме?  ⛅', 'Табиғат — ең жақсы тыныштандырушы. Ауа райына сай киімін таңдап, бірден саябаққа бет алыңыз.'),
  ('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9', '«Бұл не?» кезеңі ☝️', 'Ол бәрін саусағымен көрсетіп, ерекше дыбыс шығарады. Осылайша Сізден айналасындағы заттардың атауын айтуды сұрайды. Көрсеткен әр затының атауын оған сабырмен айтып беріңіз.'),
  ('d4a833e4-9676-4c95-baa2-923b9117c325', 'Тыныштық қажет 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, кенеттен шығатын қатты дыбыстардан сақ болыңыз.'),
  ('088ce5b1-9a8e-4d7d-8f55-017e0cc63605', 'Сұрағыңыз бар ма? 🤖', '15 айлық балаңыздың дамуына қатысты Сізді алаңдататын жайттар бар ма? Интернеттен жауап іздеп әуре болмаңыз, бірден Anacan AI-ға жазып, ғылыми негізделген жауап алыңыз.'),
  ('b6c6ae0a-2aaa-45b3-b8de-d4785923503c', 'Сиқырлы ертегі 🪄', 'Ақылды ертегілерде батыл кейіпкердің әлемді танып-білуі туралы ерекше оқиға құрастырыңыз. Ұйқыға кету сәтін жағымды етіңіз.'),
  ('c4cd946e-4029-4937-a10b-6f87983c2067', 'Бір мезгіл ұйқыға ауысу 🥱', 'Таңғы ұйқыға жатқысы келмей, күн тәртібі бұзылды ма? Ол өсіп келеді! Күндіз екі рет ұйықтаудан бір рет ұйықтауға ауысу басталады. Күн тәртібін біртіндеп реттеңіз.'),
  ('2517046a-f369-483a-b1e2-38f6320720ad', 'Жылы ванна тыныштандырады. 🛁', 'Күн бойғы шаң мен шаршаудан арылу үшін суда ойнау оны әрі көңілдендіреді, әрі ұйқыға тамаша дайындайды.'),
  ('258818a7-034e-4b93-86ea-97e8e01d3126', 'Ашу ұстамалары? 🌪', '️ Өз ойын жеткізе алмаған кезде ашуланып, жылауы мүмкін. Бұл жөнінде қолдау қажет болса, Anacan AI-мен кеңесіп, дұрыс әрекет ету жолын біліңіз.'),
  ('ca5a1958-0c22-4c62-874b-c3b801f70118', 'Сөздерді түсіну қабілеті. 🧠', '«Аяқкиіміңді әкел» дегенде, оны тауып әкеле ме? Бұл оның зердесі қарқынды дамып келе жатқанын көрсетеді. Оны жиі мақтаңыз!'),
  ('63bf2d84-bd96-49e0-9c51-b1f59bd85995', 'Жеміс жейтін уақыт! 🍎', 'Қуатын қалпына келтіру үшін маусымдық жемістерден түрлі-түсті әрі тартымды тәрелке дайындаңыз.'),
  ('72ba71ca-1652-48f5-bc29-c321459f659a', 'Ақ шудың күші. 🎶', 'Белсенді күннен кейін ұйықтай алмай жатса, бөлмеде мұхит немесе жаңбыр дыбысы секілді ақ шуды қосып, тыныш орта қалыптастырыңыз.'),
  ('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea', 'Мәзір әміршісі 🥣', 'Кеше ұнатқан тағамын бүгін ысырып қоя ма? Бұл жаста тағам талғау қалыпты жағдай. Алаңдамай, Пайдалы рецепттерден басқа баламаларды іздеп көріңіз.'),
  ('54788c72-cfe2-4f75-82f0-ba29d942e404', 'Жануарлардың дыбысына еліктеу! 🐱', '«Мысық қалай дыбыстайды?» ойынын ойнаңыз. Осындай қарапайым әрі көңілді еліктеулер оның сөйлей бастауы үшін тамаша негіз болады.'),
  ('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa', 'Қуатыңызды қалпына келтіріңіз 🥑', 'Ол тойса, енді кезек Сізде. Күнделікті қарбаласта түскі асты жүре ішпеңіз. Пайдалы рецепттерден қуат беретін тіскебасар таңдап, диванға жантайыңыз.'),
  ('f3a87482-9f2e-4700-94d8-d413093ea00a', 'Кешкі әдеттердің күші 🛀', 'Жылы ванна әрдайым көмектеседі. Кешкі әдеттерді ешқашан бұзбаңыз, өйткені олар оның миына ұйықтайтын уақыт келгенін білдіреді.'),
  ('e84402f2-45d4-40ce-ae96-610f12a3e06b', 'Кішкентай көмекші іске кірісті! 🧹', 'Қолына шүберек алып, шаң сүртуге немесе сыпырғышпен ойнауға асыға ма? Сізге еліктеуі — оның үйрену үдерісінің ең сүйкімді бөлігі.'),
  ('ed63e2e3-10b5-4bd6-9b06-a81622e913eb', 'Ұйқы тәртібі сенімділік сыйлайды. 🌙', 'Күн сайын кешке бірдей ретпен жасалатын әрекеттер (шомылу, ертегі оқу, жарықты бәсеңдету) оның жеңіл ұйықтап кетуіне көмектеседі.'),
  ('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35', 'Сөздерді түсіну қабілеті. 🧠', '«Аяқкиіміңді әкел» дегенде, оны тауып әкеле ме? Бұл оның ойлау қабілетінің қарқынды дамып жатқанын көрсетеді. Оны жиі мақтап, ынталандырыңыз!'),
  ('ce1fc21a-8f96-4c92-b928-5126f2240b1d', 'Сізге де күш-қуат қажет. 🥗', 'Күні бойы тыным таппайсыз. Өзіңізге дәруменге бай әрі дәмді тіскебасар дайындауды ұмытпаңыз.'),
  ('d8cf1dda-3655-48e8-9316-6481b7ea82ba', 'Ашу ұстамалары ма? 🌪', '️ Өзін жеткізе алмаған кезде ашуланып, жылауы мүмкін. Осы мәселе бойынша қолдау қажет болса, Anacan AI-мен кеңесіп, дұрыс әрекет ету жолын біліңіз.'),
  ('2b9c6af1-1706-4704-b2ce-29e57d4866f4', 'Әкенің кезегі. 👨‍🍼', 'Бүгін кешкі ертегіні оқып, бөпені ұйықтатуды әкесіне тапсырып, өзіңізге аздап демалыс беріңіз.'),
  ('8db205c2-0561-48d8-8b6c-61fc68065e2a', 'Мұнара құрау өнері. 🧱', '3-4 текшені бірінің үстіне бірін қойып, қайта құлату — ең сүйікті ойындардың бірі. Бұл ойын көз бен қол үйлесімін жылдам дамытады.'),
  ('e513a042-7558-4dae-8bc5-5e2b5e5d74fa', 'Үйден тыс жерде де жайлы демалыс. ☕', 'Күнделікті тірліктен жалықтыңыз ба? Бала арбасымен еркін кіре алатын дәмхананы «Анаға жайлы орындар» бөлімінен тауып, кофе ішуге үзіліс жасаңыз.'),
  ('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981', 'Күннің тәтті сәттері. 📸', 'Бүгін оның жасаған кез келген қызық қылығын немесе жаңадан үйренген дағдысын Бөпе фотосессиясы арқылы мәңгілікке сақтап қойыңыз.'),
  ('21100889-9857-4170-a0a6-59c3dec113f8', 'Шекараны тексеріп жүр. 🛑', 'Сіз «жоқ» десеңіз де, сол затқа қайта қол соза ма? Бұл қырсықтық емес, ол жай ғана ережелерді түсіну үшін тексеріп жүр. Сабырлы болыңыз.'),
  ('66da2b8a-fe86-40dc-b027-d36d46f5091a', 'Кітап парақтайтын зерек бөпе 📖', 'Қалың бетті кітаптардың парақтарын аударып, суреттерге назар аудара ма? Оның көру арқылы есте сақтау қабілеті дамып келеді. Оған түрлі-түсті ертегі кітаптарын жиі оқып беріңіз.'),
  ('5991e165-7b36-40d5-be3a-c6729cd8e924', 'Үй жинау ма, әлде демалу ма? 🛋️', 'Бөпе ұйықтағанда ыдыс жуғышқа қарай жүгірмеңіз. Диванға жатып, көзіңізді жұмыңыз да, 15 минут бойы жай ғана тыныс алыңыз. Сіз роботсыз ба? Жоқ.'),
  ('67273a71-3d6d-40e2-b209-34b098335818', 'Ол күн сайын сәл-пәл өсіп келеді.📸', 'Бөпе фотосессиясын бірден ашып, оның осы шынайы сәтін естелікке сақтап қойыңыз.'),
  ('d17f36fc-9cb8-4df2-a29e-60891f565b13', 'Өз бетінше тамақтануға талпыныс 🥄', 'Қасықты Сіздің қолыңыздан алып, өзі тамақтанғысы келеді. Төгеді, үстін былғайды, бірақ бұл оның қимыл-қозғалыс дағдылары үшін маңызды. Өз бетінше әрекет етуіне мүмкіндік беріңіз.'),
  ('145c55e0-770c-4adc-a15b-4bd94389378f', 'Қауіпті аймақтарға қолы жетеді ⚡', 'Бойы өсіп, бұрын қолы жетпеген сөрелерге енді жете алады. Теледидар тұғыры, бұрыштар... Үйдің қауіпсіздігін шұғыл түрде қайта тексеріңіз.'),
  ('b6ac32de-f983-4a93-89fc-cb209586570b', 'Азулары шығып келе ме? 🦷', 'Қызыл иегі ісініп, қолын аузына сала бере ме? Артқы тістері шығып келе жатқан болуы мүмкін. Тіс шығуын бақылау құралын тексеріп, салқын тіс қаситын ойыншықтар беріңіз.'),
  ('6537418f-2c88-443b-b40f-e07f0ccd5801', 'Ақ шудың күші. 🎶', 'Егер белсенді күннен кейін ұйықтай алмай жатса, бөлмеде Ақ шу бөлімінен мұхит немесе жаңбыр дыбысын қосып, тыныш орта қалыптастырыңыз.'),
  ('c45968e1-c58f-48dd-a705-2dc4c22325e0', 'Өсу қарқыны. 📏', 'Киімдері тағы да кішірейіп қалды! Даму трекері бөліміне бойы мен салмағының жаңа көрсеткіштерін қосып, дені сау өсу графигін жаңартыңыз.'),
  ('f13027ff-0446-4962-9c51-398d40234b5a', 'Алғашқы суреттері! 🖍', '️ Қалың борлармен қағазға шимайлап сурет салғанды ұнатады. Оның алғашқы өнер туындыларын зор сүйіспеншілікпен тамашалаңыз.'),
  ('3b86e3a2-b53e-4603-a4b1-a57fc531000c', 'Өзі тамақтанғысы келеді! 🥄', 'Үсті-басы мен айналасы былғанса да, қасықты өзі ұстауына рұқсат беріңіз. Бұл оның бұлшықет үйлесімділігі мен дербестігі үшін өте маңызды.'),
  ('ce4d24a9-fdbd-44df-93c0-058cf5d834aa', 'Тәтті құшақтар! 🤗', 'Сізді кенеттен құшақтап, сүюге талпынуы — оның сүйіспеншілік білдіру тәсілі. Осы қайталанбас сәттерден ләззат алып, Бөпе фотосессиясында мәңгілікке сақтаңыз.'),
  ('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7', 'Кітап оқуға қызығушылығы. 📖', 'Суретті кітаптардың беттерін өзі аударуына рұқсат беріңіз. Сіздің даусыңызбен ертегі тыңдау оның сөздік қорын молайтады.'),
  ('1cb9115d-9cf4-466e-adbe-8fa808d6b45c', 'Ұйқы режимін қадағалаймыз. ⏱️', 'Егер күндіз бір-ақ рет ұйықтайтын болса, кешке ертерек шаршайды. Түнгі ұйқыға жататын уақытын сәл ертерек жылжытуға болады.'),
  ('42c60ff7-6aed-4b88-96d2-512be311f08c', 'Су ішуді ұмытпаңыз. 💧', 'Белсенді қимылдаған сайын шөлдеуі де артады. Ойын кезінде және тамақтанғаннан кейін оған үнемі су ұсынып отырыңыз.'),
  ('d2fd7757-cdd9-4cc6-b45c-347ada81b748', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйықтардан 1 сағат бұрын үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш әрі жарығы аз ортада бөлінеді.'),
  ('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182', 'Кенеттен ояну 😭', 'Түн ортасында айғайлап оянып, тыныштала алмай ма? Дауысын Жылауды талдау бөліміне тыңдатып, бұған түнгі қорқыныш па, әлде ауырсыну ма себеп болғанын анықтаңыз.'),
  ('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1', 'Үлкен сезімдер, кішкентай дене 🛑', 'Қалағаны болмағанда өзін жерге тастай ма? Бұл — бүлдіршін кезеңіне тән қырсық ұстамасы. Сабыр сақтап, көзіне қараңыз да, жанында екеніңізді айтыңыз.'),
  ('d33491b0-9722-4db2-ae48-c019740b7411', 'Командалық рух 🥂', 'Жұбайыңызбен алғашқы күндерді, ұйқысыз түндерді еске алып, бірге күліңіздер. Сіздер осы күндерге оңай жеткен жоқсыздар! Бұл — командалық жеңіс.'),
  ('138aeaf3-e845-4d03-b6db-2a04410076a7', 'Әлі де тамақ таңдай ма? 🥦', 'Егер кейбір тағамдардан бас тартса, алаңдамаңыз. Қосымша тағам жей бастаған бөпелерге арналған Рецепттерден тағамды ұсынудың әртүрлі әрі қызықты тәсілдерін байқап көріңіз.'),
  ('2f302f24-3142-4182-84a0-2782c5ce8394', 'Сезімдерді сыртқа шығару. 📝', 'Күніңіз өте ауыр өтті ме? Бөпе ұйықтағаннан кейін Көңіл күй күнделігіне сезімдеріңізді жазып, күндізгі күйзелістен арылыңыз.'),
  ('8b269aa5-a26e-4c52-b247-14a7194a3d35', 'Үй ішіндегі марафон! 🏃‍♂', 'Ол енді жай жүрумен шектелмей, жүгіруге талпынып жүр. Кішкентай аяқтарының тыпырлаған дыбысынан ләззат алыңыз, бірақ оны көзден таса етпеңіз!'),
  ('8ee97257-b3d6-4144-ad9a-91e2e54c967a', 'Таза ауадағы қуыспақ. 🌳', 'Үйде энергиясын шығара алмай жүр ме? Бірге таза ауаға шығыңыздар, саябақта еркін жүріп, әбден шаршап қайтсын.'),
  ('9a860f2e-97a8-4151-9a68-ed86235ecd75', '«Бұл не?» кезеңі. ☝', '️ Бәрін саусағымен көрсетіп, Сізден оның атауын сұрайды. Әр нәрсенің атауын сабырмен айтып отырыңыз; осылайша ол қоршаған ортаны танып-біледі.'),
  ('09bd2033-24ed-4376-ba68-6795f9e6d0fa', 'Музыкаға билейді! 🎶', 'Ырғақты әуен ести сала екі жаққа теңселіп, билей бастай ма? Осындай көңілді сәттерді Бөпе альбомына видео ретінде жүктеңіз.'),
  ('899ab05b-717c-4e03-b941-aadf4ad85007', 'Өз бетінше ойнау дағдысы. 🧩', 'Аз уақыт болса да өз бетінше ойнай алуы оның зейінінің дамып келе жатқанын көрсетеді. Осындай сәттерде оны алыстан сүйіспеншілікпен бақылаңыз.'),
  ('98938324-49d8-43fc-bdde-202849487b20', 'Жылы ванна тыныштандырады. 🛁', 'Күн бойғы шаң мен шаршаудан арылу үшін сумен ойнау оны әрі көңілдендіреді, әрі ұйқыға тамаша дайындайды.'),
  ('67d07afb-a906-4267-ae07-195da32a67d1', 'Шекараны тексеріп жүр. 🛑', 'Сіз «жоқ» дегеніңізге қарамастан, әлгі затқа қайтадан қол соза ма? Бұл қырсықтық емес, ережелерді түсінуге тырысуы. Бірізді әрі сабырлы болыңыз.'),
  ('71f533be-645b-4990-ac46-86ad77f1a038', 'Жеміс жейтін уақыт! 🍎', 'Қуатын қалпына келтіру үшін маусымдық жемістерден түрлі-түсті әрі тәбетті тәрелке дайындаңыз.'),
  ('cbf7129c-f3df-44ab-928f-9f74910675e9', 'Өзіңізді ұмытпаңыз! 💖', 'Бала ұйықтағаннан кейінгі алғашқы сағат тек Сізге арналсын. Ешқандай жұмыс істемей, өзіңізге ұнайтын іспен айналысып, демалыңыз.'),
  ('569d0003-c871-435a-ae9b-f4e977441a16', '16 айға небәрі 10 күн қалды! 🎂', 'Сену қиын! Тура 10 күннен кейін кішкентайыңыз 16 айға толады. Осы айтулы күнге арнап шағын торт немесе фотосессия жоспарлай бастаңыз.'),
  ('6f0da037-da86-424d-bd6d-1e6d3aefe4db', 'Сұрауға қысылмаңыз 🤖', 'Ұйқы режимінде бір нәрсені дұрыс істемей жүрмін деп ойлайсыз ба? Күмән тудырған кез келген сұрағыңызды Anacan AI-дан бірден сұрап, көңіліңізді тыныштандырыңыз.'),
  ('b0d45a27-101a-4c13-b494-715c8c48dda4', 'Бар шаршауды ұмытыңыз. 🥂', 'Бүгін кешке бала ұйықтағаннан кейін жұбайыңызбен бірге командалық жеңістеріңізді атап өтуді ұмытпаңыз!'),
  ('8bf81bea-dee2-4f82-9f28-f1e6a128a812', 'Шыдам шегіне жеткенде. 📝', 'Кейде баланың энергиясы Сізді әбден қажытуы мүмкін. Көңіл күй күнделігін ашып, бүгін Сізді ең қатты шаршатқан нәрсе туралы еркін жазыңыз.'),
  ('977f5267-192c-40d2-9215-420a5a54d255', 'Шанышқы қолдануға көшу. 🍴', 'Бөпеңіз енді тамағын шанышқымен түйреп жеуге тырысады. Қосымша тамақ жей бастаған бөпелерге арналған рецепттерден шанышқымен оңай алуға болатын тағамдар дайындаңыз.'),
  ('c22aaf03-7bb2-467b-9c9d-ca82637af893', 'Аяқ киімін өзі шешеді 👟', 'Киіндіру нағыз күреске айналды ма? Бөпеңіз шұлығы мен аяқ киімін өзі тартып шешеді. Оның моторикалық дағдысына сүйсініңіз!'),
  ('3f154cd8-81d2-425b-aa71-ec2864247772', 'Ол менікі! 🧸', 'Қолынан бірдеңесін алғанда қарсылық білдіріп, жылай ма? Меншік сезімі күшейіп келеді. Бұл — мінездің қалыптасуындағы маңызды кезең.'),
  ('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27', 'Бүгін шомылдыру кезегі әкеде. 👨‍🍼', 'Бүгін кешкі су ойындарын, көбігі мол ваннаға шомылдыруды және бөпені ұйықтатуды әкесіне тапсырып, демалыңыз.'),
  ('b60defb6-6a44-41ab-8087-7dec23cd3f5c', 'Не пісіремін деген уайым 🍲', 'Қосымша тамақ мәзіріне арналған идеяларыңыз таусылды ма? Интернеттен іздеп әуре болмаңыз, «Пайдалы рецепттер» бөлімінен жаңа дәмдерді табыңыз.'),
  ('24b47242-9a10-48f7-a928-0a19449b984a', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш ортада бөлінеді.'),
  ('2d66c314-cb67-48c8-93d1-be3249bad125', 'Табиғаттағы қазына іздеу. 🍂', 'Саябақта серуендегенде әртүрлі жапырақтар немесе бүрлер жинаңыз. Анаға жайлы орындардан табиғаты әр алуан жаңа саябақтарды табыңыз.'),
  ('98db8b9f-36cd-4968-86c5-ed66999457de', 'Жануарлардың дауыстары 🐶', 'Мысықты көргенде «мияу», итті көргенде «ау-ау» деуге тырыса ма? Сөздік қор жануарлардың дауыстарынан басталады. Онымен бірге осы ойынды ойнаңыз.'),
  ('8e91be33-56a9-43aa-bf49-8aa525510abf', 'Табиғаттағы қазына іздеу. 🍂', 'Саябақта серуендегенде әртүрлі жапырақтар немесе бүрлер жинаңыз. Анаға жайлы орындардан табиғаты әр алуан жаңа саябақтарды табыңыз.'),
  ('a9e6c327-e70b-4cd7-9bed-cb9d250622ba', 'Тыныштандыратын дыбыстар. 🎶', 'Белсенді зерттеулерге толы күннен кейін балаңыз тыныштала алмаса, бөлмеде Ақ шу ішінен жаңбыр дыбысын қосып, жайлы атмосфера жасаңыз.'),
  ('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'Толтырып-босататын кез! 📦', 'Ойыншықтарды үлкен қорапқа жинап, кейін бәрін бірден еденге төгу! Бұл себеп-салдар ойыны оның логикалық ойлауын дамытады.'),
  ('1705b7a5-fb30-4cc3-974a-91a4210ec2a2', 'Бұл уақыт тек Сізге арналған. 🛁', 'Ол ұйықтады, үй іші тынышталды. Енді телефоныңызды бір жаққа қойып, сүйікті фильміңізді қосыңыз да, ештеңе істемеудің рақатын сезініңіз.'),
  ('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb', 'Артқа және жан-жаққа жүру! 🦀', 'Ол енді тек алға емес, артқа немесе жанымен қадам басып, тепе-теңдігін сынап жүр. Осы қызықты сәттерді міндетті түрде суретке түсіріңіз.'),
  ('8878ea41-701a-4729-9437-858b0e0448ae', 'Доп лақтыру ойыны! ⚽', 'Бөпеңіз допты жай ғана домалатпай, қолдарын көтеріп, Сізге қарай лақтыруға тырысады! Оның осы спорттық талпыныстарын Бөпе альбомына бірден видео ретінде қосыңыз.'),
  ('d2eace3f-d381-45ba-bfbb-2db61f670769', 'Отбасылық альбомда кімдер бар? 🖼', '️ Суреттерді қарап отырып, «Әже қайда?» деп сұрағанда, саусағымен дұрыс көрсете ме? Есте сақтау және бет-әлпетті тану қабілеті қарқынды дамып келеді.'),
  ('f2055f25-61d4-4680-83b3-954a3f1a9671', 'Инженерлік талпыныстар 🧱', 'Екі ойыншық текшені бірінің үстіне бірін қоюға тырысады, бірақ олар құлап қалады. Бөпеңіз мұны мұқият қайта байқап көреді. Оның талпыныстарын үнсіз бақылаңыз.'),
  ('458a103b-d07a-4e59-ac24-1d9dafc323f0', 'Анаға арналған орын ☕', 'Үйде отыра беріп, күш-қуатыңыз таусылды. Анаға жайлы орындардың ішінен тыныш отырып демалуға болатын дәмхананы таңдап, өзіңізге уақыт бөліңіз.'),
  ('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e', 'Мазасыздық шегіне жетті ☁️', 'Ештеңеге көңілі толмай, бәріне жылай ма? Мүмкін, артқы азу тістері шығып жатқан болар. Бұл үдерісті тіс шығуын бақылау бөлімінде белгілеңіз.'),
  ('ed11b132-51fc-4e86-99e0-021b6675020e', 'Түнгі бесік жыры 🎶', 'Ешбір дыбыс ана даусындай тыныштандыра алмайды. Бүгін кешке бөпеңізді жай ғана бауырыңызға басып, ақырын әндетіңіз.'),
  ('07f52bf7-1174-455b-9c35-8391687a69fe', 'Дамуын тексеру 🤖', '16 айдағы даму секірістері туралы ақпарат қажет пе? Anacan AI-дан педиатр мақұлдаған қысқа әрі нақты тізім сұраңыз.'),
  ('c016a9a1-5e0d-434a-ba4b-907c1125a45a', '16 айға небәрі 5 күн қалды! 🎈', 'Кері санақ аяқталуға жақын! Тортқа тапсырыс беріп, киімдерді дайындап қойдыңыз ба? Бөпеңіздің фотосессиясына арналған көңілді идеяларды қазірден қарап шығыңыз.'),
  ('d94026ce-ef2a-4e93-b559-9f926c9f245d', 'Тыныштандыратын дыбыстар. 🎶', 'Белсенді зерттеулерге толы күннен кейін балаңыз тыныштала алмаса, бөлмеде Ақ шудың жаңбыр дыбысын қосып, жайлы атмосфера қалыптастырыңыз.'),
  ('523911e7-6ac9-424d-9f11-0729711fb179', 'Сенсорлық ойындар. 🌾', 'Үлкен ыдысқа аздап күріш немесе макарон салып, арасына ойыншықтарды жасырыңыз. Оларды қолымен тауып, сипап сезу қабілетін дамытуына мүмкіндік беріңіз.'),
  ('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533', 'Өз бетінше ойнайтын уақыт 🧸', 'Енді ол 10-15 минут бойы ойыншықтарымен өз бетінше ойнай алады. Бұл — зейін қою уақытының ұзарғанының белгісі. Тыныштықтан ләззат алыңыз.'),
  ('adb7bf26-343c-4ba5-8233-149cdef6b1f2', 'Музыканың күші 🎶', 'Кешкісін себепсіз басталатын мазасыздықты жеңіл классикалық музыкамен басып көріңіз. Көбіне осы қарапайым тәсіл ғажайып әсер береді.'),
  ('35d30a24-8966-43d1-afce-6f79d49ebcec', 'Маманның қолдауы. 🤖', '«Балама мені тістегенде қалай әрекет етуім керек?» деген сияқты мінез-құлыққа қатысты жаңа сұрақтарыңызды Anacan AI көмекшімізге қойыңыз.'),
  ('5c715c5a-b613-43a0-9f22-5f59af3ae1fc', 'Шешіну өнері. 🧦', 'Киіну қиын, ал шешіну өте қызық! Баскиімін, шұлығын немесе аяқкиімін өзі шешіп көруіне мүмкіндік беріңіз.'),
  ('d3844bde-9596-474d-adfe-9c81a7e0ff26', 'Үлкендердің заттары қызық. 👜', 'Сіздің сөмкеңізді ақтару немесе әкесінің аяқкиімін киіп көру — оның ең сүйікті ісі. Қауіпсіз заттарыңызды зерттеуіне рұқсат етіңіз.'),
  ('17b19954-1449-474d-a0b9-d199021947cc', 'Дені сау ана, дені сау бөпе 🥑', 'Ағзаңыздағы темір мен кальций қоры азайған. Пайдалы рецептілердің ішінен тез дайындалатын әрі бойыңызға күш беретін салат әзірлеңіз.'),
  ('68c3e726-41d6-481a-91d7-a89fa5795172', 'Шимайлау өнері 🖍️', 'Қолына қалам бергенде қағазға шимай салуға тырыса ма? Бұл ұсақ моториканы дамытуға арналған тамаша жаттығу. Қаламдардың қауіпсіз екеніне көз жеткізіңіз.'),
  ('ab2f1bd1-caf0-41b5-b8ae-89ec60663539', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпеге оянудың бар ауыртпалығын жалғыз көтермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26', 'Ішіңіздегіні бөліскіңіз келе ме? 💬', '«Мен енді ешқашан бұрынғы қалпыма оралмаймын» деген ой Сізді мазалай ма? Бұл өткінші сезімді Anacan қауымдастығындағы аналармен бөлісіңіз.'),
  ('2980029e-45df-4043-851c-f7839d81a721', 'Ертең 16 ай! 🎉', 'Дайынсыз ба? Ертең тура 16 ай! Телефоныңыздың жадын босатыңыз: ертең Бөпе фотосессиясында ең сүйкімді қылықтарын түсіру үшін орын қажет болады.'),
  ('5d958416-87e8-44f2-8b6e-cde98e63822d', 'Бүгін «Ақылды ертегілерде» 🪄', '«Ақылды ертегілерде» батыл әрі сүйкімді жануарлар туралы хикая құрастырып, бөлмені сиқырлы мекенге айналдырыңыз.'),
  ('679e2936-6a93-4a92-9069-b372c4d3f661', 'Кешкі ертегінің сиқыры ерекше. 📖', 'Енді бөпеңіз де кітаптағы суреттерді Сізге көрсетеді. Ұйықтар алдында бірге оқитын шағын ертегі араларыңыздағы байланысты ерекше нығайтады.'),
  ('86b4bb0f-0f98-485c-9149-10540747f598', 'ТУРА 16 АЙ! 🎂', 'Сену қиын, солай емес пе? Бөпеңізді алғаш рет бауырыңызға басқан толқынысқа толы күннен бері тура 16 ай өтті! Осындай керемет өсуді атап өтетін кез келді. Бөпе фотосессиясынан тақырып таңдап, ең сүйкімді сәтті мәңгілікке сақтаңыз және осы мақтанышыңызды Anacan қауымдастығындағы басқа аналармен міндетті түрде бөлісіңіз!'),
  ('fbb768fe-d41f-4451-8978-b683840f7855', 'Салып-төгу кезеңі! 📦', 'Ойыншықтарды үлкен қорапқа жинап, кейін бәрін бірден еденге төгу! Себеп пен салдарды ұғынуға көмектесетін бұл ойын оның логикалық ойлауын дамытады.'),
  ('f05a8717-d544-48fb-a529-17361118fee2', 'Өсу серпілісі! 📏', 'Балаңыздың бойы өсіп жатқанын байқадыңыз ба? Салмақты бақылау бөліміне жаңа көрсеткіштерін енгізіп, даму графигінің қалай жоғарылағанын көріңіз.'),
  ('75798a4e-e59c-4911-827e-b1622b37ae33', 'Шаш тарау және тіс тазалау. 🪥', 'Сізге қарап, тарақты шашына жүргізеді немесе тіс щеткасын аузына апарады. Өзіне күтім жасау дағдыларын ойын арқылы қалыптастыруға ең қолайлы кезең.'),
  ('784b1d1b-2c53-42bf-a43b-d6b6e3121aba', 'Отбасылық кешкі ас. 🍲', 'Бүгін кешке үйде тамақ дайындағыңыз келмей ме? Балаңызға арналған бөлек мәзірі мен балалар орындығы бар мейрамханаларды қолданбамыздағы картадан табыңыз.'),
  ('b328273f-0602-46a6-a82b-54d47ec1b77d', 'Терең тыныс алыңыз. ✨', 'Әр күн Сіз жоспарлағандай өте бермеуі мүмкін, ал үй кейде жиналмай қалуы қалыпты. Мінсіз болуға міндетті емессіз, Сіз балаңыз үшін ең жақсы жансыз.'),
  ('714f8ced-9ccc-40ff-a807-9428279f86d4', 'Ұйқыға оңай ауысу. 🌙', 'Белсенді өткен күннен кейін бөлменің жарығын бәсеңдетіп, оған баяу әрі жұмсақ дауыспен бесік жырын айтыңыз. Бұл оның терең ұйқыға кетуіне көмектеседі.'),
  ('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4', 'Таңдау мүмкіндігін беріңіз. 👕', 'Қызыл жейдені киесің бе, әлде көгін бе? – Оған осындай шағын таңдаулар ұсыну қырсықтығын азайтып, дербестік сезімін нығайтады.'),
  ('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe', 'Күрделі жасырынбақ! 🙈', 'Ойыншығын екі түрлі жамылғының астына жасырсаңыз да, оны оңай таба ма? Демек, заттың көзден таса болса да бар екенін түсіну қабілеті толық қалыптасқан.'),
  ('373a30b7-4c10-4d16-b029-a2c123ab28b9', 'Жүгіру жаттығулары басталды! 🏃‍♂', '️ Жылдам қадамдары енді қысқа жүгіріске айналып келеді. Тізелерін жарақаттанудан қорғау қиындай түссе де, оның еркіндікке деген қуанышын көру соған тұрарлық!'),
  ('5a23341a-91f5-4bdf-a760-e7b99f610283', 'Әртүрлі текстураларға дайын. 🥦', 'Тағамдарының түсі мен пішінін өзгерту арқылы тәбетін арттырыңыз. Идеялар алу үшін Қосымша тағамды бастаған бөпелерге арналған рецепттер бөлімінен шабыт алыңыз.'),
  ('6581c209-98c5-4f79-adf1-c7b985567899', 'Сіз нағыз қаһармансыз. 🛁', 'Күні бойы тыным таппаған баланы бағып шықтыңыз. Енді өзіңізге ыстық шай құйып, ештеңе ойламай, жай ғана демалыңыз.'),
  ('755229fb-26a0-4a27-af2c-49bb6a367386', 'Тыныштандыратын әдет. 🌙', 'Түнгі ұйқыға жатар алдында бөлменің жарығын бәсеңдетіп, сыбырлап сөйлеу оның да қимылын баяулатып, ұйқыға дайындайды.'),
  ('ae949749-3a87-49dc-a4ae-057b9e3594b1', 'Шимайдан мақсатты сызықтарға дейін! 🖍', '️ Қолына қарындаш алғанда, жай ғана нүктелер емес, ұзын сызықтар салуға тырысады. Осы кішкентай өнер туындысын суретке түсіріп, бірден Бөпе альбомына қосыңыз.'),
  ('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9', 'Табиғат аясында қазына іздеу. 🍂', 'Аулада немесе саябақта жапырақтар мен ұсақ тастарды жинап, зерттеу — оның сенсорлық (сезімдік) дамуына арналған тамаша әрекет.'),
  ('1b65f6b1-f423-43f5-bc48-5ffb574c7c74', 'Сумен ойнап, тынығу. 🛁', 'Жылы ваннада суға салған ойыншықтарымен ойнау күндізгі күйзелісті басып қана қоймай, көп көңіл көтереді.'),
  ('bc0b7dcc-fdc0-4664-bff5-56183ea22258', 'Екі кезеңді нұсқауларды түсінеді! 🧠', '«Аяқкиіміңді алып, маған бер» дегенде, екі әрекетті де ретімен орындай ма? Бұл — оның зияткерлік дамуындағы керемет серпілістің белгісі!'),
  ('c18b2eee-ba78-43cc-89fd-423a464819d2', 'Ананың күш-қуаты өте маңызды. 🥗', 'Балаңыздың соңынан жүгіріп, шаршадыңыз. Әйелдерге арналған пайдалы рецепттерден өзіңізге дәмді әрі дәруменге бай тағам дайындаңыз.'),
  ('bf80d71f-c8bb-4983-b046-1ee91c367f20', 'Маманның қолдауы. 🤖', '«Сөздерді түсінеді, бірақ неге аз сөйлейді?» деген сияқты Сізді толғандыратын сұрақтарды Anacan AI көмекшісіне қойып, көңіліңізді тыныштандырыңыз.'),
  ('cd0e822c-b843-41fa-9a3e-f4b682a848ae', 'Қасықты өз бетінше қолдану. 🥄', 'Қасықты аузына апарғанда тамақты азырақ төгеді. Оның ұсақ моторикасының дамуын қолдап, өз бетінше әрекет етуіне мүмкіндік беріңіз.'),
  ('d6374c1a-94a0-4de3-855d-6a8d4e9a29af', 'Ойыншықтарға жанашырлық таныту. 🧸', 'Ойыншық қонжығын сипап, тамақтандырып немесе үстін жауып жүр ме? Осындай сүйкімді рөлдік ойындар оның эмоциялық интеллектісінің жақсы дамып келе жатқанын көрсетеді.'),
  ('299405ea-50dc-48c1-ba2a-233941bf627c', 'Әкенің ертегі оқу уақыты. 👨‍🍼', 'Бүгін кешкі ертегіні оқып, бөпені ұйықтатуды әкесіне тапсырып, өзіңізге аздап демалыс беріңіз.'),
  ('7ad6ef35-e677-498c-8bc2-cc3e84535415', 'Қауіпсіздік шараларын жаңарту қажет. 🛡️', 'Шкафтар мен жәшіктерді ашу — оның ең сүйікті ермегі. Балаларға арналған құлыптарды Ұсынылатын өнімдер тізімінен міндетті түрде қарап шығыңыз.'),
  ('ec2361c8-31f7-458e-ad6e-506355b447a5', 'Жаңа биіктер бағындырылуда! 🧗‍♂', '️ Ол енді биігірек жерлерге қол жеткізіп, жиһазға оңайырақ өрмелей алады. Үйдегі қауіпсіздік шараларын қайта қарап шығатын уақыт келді.'),
  ('21888245-7cf1-48e4-a08b-53389aa39131', 'Су ішуді қызықты етіңіз. 💧', 'Белсенді жүгіру мен ойындар шөлдетеді. Түрлі түсті су құтысымен оған жиі су ұсынып, ағзасындағы сұйықтықтың жеткілікті болуын қадағалаңыз.'),
  ('4595ac68-2033-4a66-a4d9-1146030382ed', 'Күн қорытындысы. ✨', 'Күн сайын мінсіз болуға міндетті емессіз. Бүгін бір нәрсеге үлгермей қалсаңыз, ештеңе етпейді. Сіз ол үшін ең жақсы жансыз.'),
  ('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85', 'Ырғақты сезінуі жақсарып келеді! 🎶', 'Сүйікті әнінің алғашқы секундтарын ести сала қимылдап, күлімсірей ме? Осы көңілді сәттерді Бөпе фотосессиясы арқылы түсіріп, отбасы тобына жіберіңіз.'),
  ('33b8d80d-5434-483c-b198-c7b20c73321d', 'Дене мүшелерін толығырақ танып келеді. 👂', '«Ішің қайда?», «Құлағың қайда?» деген жаңа сұрақтарға дұрыс жауап беруі оның тез үйреніп жатқанын көрсетеді.'),
  ('87029bf7-0808-4eac-a180-0abfa62f0b48', 'Бірге кітап оқыңыздар. 📖', 'Енді ол кітаптың беттерін аударып қана қоймай, ондағы жануарларды немесе заттарды саусағымен көрсетіп, олардың атауын Сізден күтеді.'),
  ('cc468aff-f9d2-4961-b955-bf2eaa13f7ef', 'Өсу қарқыны қалай? 📏', 'Киімдерінің жеңі мен балағы тағы да қысқарып қалыпты! Салмақ бақылау бөліміне жаңа көрсеткіштерін енгізіп, даму графигінің өсуін қадағалаңыз.'),
  ('308b629a-7190-416d-8240-7f61a2fe4d68', 'Өзін жеткізе алмағанда туындайтын ашу. 🌪', '️ Қалағаны болмағанда немесе ойын жеткізе алмағанда ашуланып, жылауы қалыпты жағдай. Оның бойына дейін еңкейіп, сезімдерін түсінетініңізді айтыңыз.'),
  ('78541e65-2128-40ff-8cb4-1e0d54454519', 'Сезімдеріңізге ерік беріңіз. 📝', 'Күніңіз өте шаршатып жіберді ме? Бала ұйықтағаннан кейін Көңіл күй күнделігіне сезімдеріңізді жазып, күн бойғы күйзелістен арылыңыз.'),
  ('7ea95622-1f8d-4996-8638-aeeafe28a802', 'Жаңа орындарды зерттеңіз. ☕', 'Күнделікті күйбең тірліктен жалықтыңыз ба? Баламен баруға ыңғайлы әрі балалар мәзірі бар дәмханаларды Анаға жайлы орындар бөлімінен табыңыз.'),
  ('58ff14f8-978e-4eec-8b86-a777de1b33ba', 'Жинау және ретке келтіру ойыны. 🧺', 'Ойыншықтарды қораптан төккенді ұнататын балақайыңыз енді олардың бірнешеуін қайта салуды да үйреніп келеді. Бірге «жинайық-жинайық» әнін айтып, бұл істі қызықты ойынға айналдырыңыз.'),
  ('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81', 'Ұйқы тәртібі өзгеріп жатыр ма? ⏱️', 'Күндізгі ұйқысы толығымен бір ретке ауысса, түнгі ұйқыға жату уақыты сәл өзгеруі мүмкін. Anacan ұйқы таймері арқылы бүгінгі кестені бақылап, жаңа режимді реттеңіз.'),
  ('e71126af-730c-4cca-8daa-1682609e21a1', 'Пішіндерді орнына салу (Пазлдар). 🧩', 'Дөңгелекті дөңгелек ұяшыққа, ал шаршыны шаршы ұяшыққа салуға тырысады. Мұндай логикалық ойындар оның шыдамдылығы мен зейінін арттырады.'),
  ('069cc383-0002-41b5-ba19-4172c6d6b10f', 'Ұйықтауы қиындап жүр ме? 😴', 'Белсенді зерттеу кейде баланың ұзақ уақыт бойы сергек әрі елігулі жүруіне себеп болады. Ұйқы таймерін қосып, жатар алдында бөлменің жарығын барынша бәсеңдетіп, ертегі оқып беріңіз.'),
  ('1beeca23-44cf-48f8-9b07-fc08412e7809', 'Рақмет және өтінемін. 🙏', 'Ол бірдеңе бергенде немесе алғанда басын изеп не өз тілінде алғысын білдіреді. Әдептілік ережелерін үйретудің дәл уақыты!'),
  ('eb807359-495c-4338-a628-e4dd3e405226', 'Бойы мен салмағының өсуін бақылаймыз. 📏', 'Киімдері тағы да кішірейіп қалды ма? Салмақ бақылағышы бөліміндегі жаңа көрсеткіштерді жаңартып, 500-ші күнге арналған даму кестесін дайындаңыз.'),
  ('158d01ac-e4e7-4be6-959c-37e93007ee0b', 'Кітаптағы жануарларды таниды. 🐶', '«Ит қайда?» деп сұрағанда, саусағымен көрсете ме? Сөздік қорын молайту үшін кітаптағы заттардың түстерін де атай бастаңыз.'),
  ('9e266e10-1251-4668-af5f-a58fe3b3f537', 'Қауіпсіздік шараларын жаңарту қажет. 🛡️', 'Ол енді биігірек жерлерге қолын жеткізе алады. Дастарқандар мен өткір бұрыштарды тағы бір рет тексеріңіз. Қажет болса, Ұсынылатын өнімдерді қарап шығыңыз.'),
  ('ca40c713-93a7-4e51-9b1b-8465a3151e1f', 'Әкемен бірге ойнайтын уақыт. 👨‍🍼', 'Кештің белсенді бөлігін әкесіне тапсырыңыз. Олардың бірге ойнап, күлуі өзара байланысын нығайтып қана қоймай, Сіздің де тынығуыңызға мүмкіндік береді.'),
  ('17791a06-d7d3-466d-acee-c2689fa82589', 'Сенсорлық ойындар. 🌾', 'Үлкен ыдысқа күріш немесе құм салып, ішіне ойыншықтарды жасырыңыз. Оларды қолымен іздеу саусақтарының ұсақ моторикасын дамытуға өте пайдалы.'),
  ('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3', 'Киімді өзі таңдасын. 👕', 'Көк жейдені кигің келе ме, әлде жасылын ба? Екі нұсқа ұсыну оның дербестік сезімін арттырып, қырсықтығын біршама азайтады.'),
  ('e6632c98-233d-431d-adc3-c5f78c1c7a37', 'Сумен ойнап, демалу. 🛁', 'Жылы ванна мен судың сылдыры күн бойғы шаршауды басады. Суға көлемі әртүрлі ыдыстарды салып, бөпеге көлем ұғымын үйретіңіз.'),
  ('148de716-5fb6-4776-96cc-81e2d00b53b8', 'Сезімдеріңізбен бөлісіңіз. ✨', 'Кейде бәрі бір уақытта болып, ауыр сезілуі мүмкін. Күн соңында жан тыныштығын табу үшін өзіңіз ұнататын іспен айналысыңыз.'),
  ('b3ddea65-cbd9-4fdd-900d-8914e021db1f', 'Допты нысанаға лақтырады! ⚽', 'Ол допты жай ғана домалатпай, белгілі бір бағытқа лақтыруға тырысады. Бұл — көз бен қол үйлесімділігінің дамып келе жатқанының айқын белгісі.'),
  ('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3', 'Су ішуді қызықты етіңіз. 💧 A', 'Белсенді балалар тез шөлдейді. Ағзасы сусыз қалмауы үшін оған түрлі түсті, қызықты құтымен үнемі су ұсынып отырыңыз.'),
  ('2f67b26a-192a-4bd5-87f9-5f376ff164e3', 'Екі кезеңді нұсқаулар. 🧠', 'Ойыншықты ал да, қорапқа сал. Осындай күрделі тапсырмаларды орындауы оның түсіну қабілетінің жоғары екенін көрсетеді.'),
  ('bf0e882a-2f6d-4439-b170-c9adaeed59cd', 'Музыкаға өз ырғағымен билейді. 🎶', 'Енді ол жай ғана тербелмей, музыканың ырғағына сай қол шапалақтайды немесе айналады.'),
  ('c522fcf6-60fc-463a-b943-7933f5ac5c70', 'Кешкі ертегінің сиқыры бөлек. 📖', 'Суреттерге қарап, ертегіні өз сөзімен айтып беруіне мүмкіндік беріңіз. Бұл — болашақта кітап оқу әдетінің негізі.'),
  ('19e05272-ac3b-430f-bbad-b5c770118fd3', 'Мерейтойлық мереке! 🎈', 'Бұл күнді кішкентай тортпен немесе оның сүйікті жемісімен атап өтіңіз. Оның қаншалықты тез өсіп келе жатқанын көру — Сіз үшін ең үлкен сый.'),
  ('52e84dda-8f2e-4dce-9b8e-b095190c1816', 'Өзіңізге алғыс айтыңыз. ✨', '500 күн бойы көрсеткен жанқиярлығыңыз, сүйіспеншілігіңіз бен сабырыңыз үшін өзіңізге алғыс айтыңыз. Енді тынығып ұйықтаңыз, ертең жаңа кезең басталады!'),
  ('7cc24719-4bcf-403b-9178-3f6a80317c26', 'Ғажайып 500 күн.🎉', 'Сенесіз бе?! Босанғаннан бері тура 500 күн өтті!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid, 'Анаға қуат жинау 🔋', 'Күндізгі қарбалас бар күшіңізді сарқып жіберді ме? Өзіңізді ұмытып, бала тәрбиелеу — ерлік емес. Оны қауіпсіз жерге отырғызып, 10 минут кофе ішуге үзіліс жасаңыз.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'Жылдамдық шегінен асты 🏃‍♂️', 'Ол енді жүріп қана қоймай, жүгіруге шақ қалды! Артынан ілесу қиындап барады. Даму күнделігіне осы жаңа жылдамдық рекордын жазып, үйдегі кедергілерді алып тастаңыз.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'Сөзсіз түсінісу 🫂', 'Бүгін қатты шаршадыңыз. Бөпе ұйықтағаннан кейін жұбайыңызбен ештеңе айтпастан, диванда қатар отырып, тыныштықтан ләззат алыңыз.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'Денеңіздің қажеттілігі 🥑', 'Қолыңыз бен беліңіз ауыра ма? Бөпе салмақ қосып келеді. Пайдалы рецепттер арасынан кальций мен ақуызға бай жеңіл түскі ас таңдап, бұлшықеттеріңізді нығайтыңыз.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'Қиялға толы ойындар басталады 🧸', 'Ойыншық қонжығына тамақ беруге немесе оны ұйықтатуға тырыса ма? Оның қиялы оянып келеді! Эмпатия танытуға бағытталған осы керемет талпыныстарын мақтанышпен сырттай бақылаңыз.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'Әкемен ойын уақыты 👨‍👧', 'Шыдамыңыз таусылуға жақын ба? Бүгін кешке еденде аунап, қытықтасып ойнауды әкесіне тапсырыңыз.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'Асүйдегі зерттеу. 🍎', 'Жемістерді жуғанда, оның да көмектесуіне рұқсат етіңіз. Судың сылдыры мен жемістердің түсі оның қызығушылығын оятады.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'Сөздерден сөйлем құрауға талпыныс. 🗣', '️ «Ма-ма, бер» немесе «Ә-ке, қара» сияқты екі сөзді біріктіруге тырыса ма? Бұл — сөйлеу дамуындағы керемет серпіліс!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'Ұйқыға арналған сиқырлы фон 🪄', 'Ұйықтай алмай жүр ме? Ақ шу ретінде тек өзеннің сылдыры естілетін тыныштандыратын дыбысты қосыңыз.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'Кішкентай суретші іске кірісті 🖍️', 'Қолына қарындаш берсеңіз, қағазға (немесе қабырғаға) шимайлай ма? Оның ұсақ моторикасы қарқынды дамып келеді. Жуып кетіруге болатын бояуларды сатып алатын уақыт келді.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'Әкенің ертегі айтатын уақыты. 👨‍🍼', 'Кешкі соңғы белсенді ойындарды әкесіне тапсырыңыз. Олардың бірге күлген дауысы Сіздің демалысыңызға арналған ең жағымды әуен болады.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'Ауа райын зерттеу ⛅', 'Сыртта жел соғып тұр ма, әлде жай ғана салқын ба? Терезеден қарап қателеспеңіз. Ауа райы мен киім құралы Сізге дәл қандай киім үйлесімін таңдау керегін санаулы секундта айтып береді.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'Тәжірибеңізбен бөлісіңіз 💬', '«Менің балам да осындай ма?» деген ой мазаңызды ала ма? Anacan қауымдастығына қосылып, 16 айлық бөпесі бар басқа аналардың оқиғаларын оқыңыз да, терең тыныстаңыз.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'Тыныштандыратын ванна. 🛁', 'Ұйықтар алдында жылы сумен ойнау күн бойғы ширығуды басады. Суға аздап эфир майын қосып, жайлы атмосфера қалыптастырыңыз.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'Баспалдақпен өзі көтерілуге талпыныс. 🪜', 'Енді қолыңыздан ұстап, баспалдақпен сенімдірек көтеріледі. Аяқ бұлшықеттерін нығайтуына кедергі жасамаңыз, тек қауіпсіздігін қадағалаңыз.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'Қалтаңыздағы тізім 🛒', 'Күнделікті қарбаласта сусабын таусылды ма, әлде ылғал майлық па? Бәрін есте сақтауға тырыспай, Сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'Сұрағыңыз бар ма? 🤖', '«Неліктен түнде жиі ояна бастады?» деген сияқты сұрақтарды тіпті түнде де Anacan AI көмекшісіне қойып, бірден жауап алыңыз.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'Таптым сені! 🙈', 'Көзін қолымен жауып, «ку-ку» ойнай ма? Заттың көзден таса болса да бар екенін түсіну қабілеті жетіліп келеді.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'Біз бір командамыз! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ашық сөйлесіңіз. Бір-біріңізге қолдау көрсету физикалық және эмоциялық жүктемені екі есе жеңілдетеді.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'Педиатрияға қатысты күмәніңіз бар ма? 🤖', '16-18 айдағы дамудан не күту керек? Интернеттен үрейлі ақпарат оқығанша, Anacan AI-дан маманның нақты әрі қысқаша түсіндірмесін сұраңыз.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'Кітапқа деген сүйіспеншілік 📖', 'Кітап беттерін өзі еркін аударып, суреттерді саусағымен көрсетіп жүр ме? Оқу әдеті қазірден қалыптасып келеді. Онымен бірге суреттегі заттарды атап шығыңыз.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'Кенет айқайлап оянды ма?', 'Бұл түнгі қорқыныш болуы мүмкін. Дауысын Жылауды талдау құралына тыңдатып, мәселенің физикалық немесе психологиялық екенін анықтаңыз.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'Үй шаруасы күте тұрады 🛑', 'Еден жуылмай қалды ма? Ештеңе етпейді. Үйді кейін де жинауға болады, ал әбден қажыған ананың қалпына келуіне көп уақыт қажет. Диванға жатып, тыныштыққа құлақ түріңіз.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'Логикалық ойындар 🧱', '3-4 текшені бірінің үстіне бірін қойып, мұнара тұрғыза ма? Қимыл-қозғалыс дағдыларындағы осы жетістігін Даму трекеріне белгілеңіз! Оның кішкентай инженерлік талпыныстарын мақтап, қолдау көрсетіңіз.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'Ұйықтауы жеңіл болсын. 🌙', 'Бөлмедегі жарықты барынша бәсеңдетіп, ақырын сыбырлап сөйлеңіз. Бұл оның жүйке жүйесіне демалатын уақыт келгенін білдіреді.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'Қуатты қалпына келтіретін уақыт. 🍎', 'Бөпе ұйықтап жатқанда, Сіз де 20 минутқа көзіңізді жұмыңыз. Үй шаруасы бітпейді, ал Сіздің қуатыңыз таусылуы мүмкін. Өзіңізді күтіңіз.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'Кішкентай көмекші. 🧺', 'Ойыншықтарды қорапқа жинай бастағанда, ол да біреуін әкеліп сала ма? Осындай кішкентай көмегін міндетті түрде мақтап, алғыс айтыңыз.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'Ақылды ертегінің сиқыры 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрастырыңыз: Сиқырлы орманда серуендеген батыл бөпе.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'Ананың өзіне арнайтын уақыты 🎧', 'Бөпе ұйықтай салысымен асүйге жүгірмеңіз. Құлаққабыңызды тағып, сүйікті әніңізді қосыңыз да, 15 минутты тек өзіңізге арнаңыз.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'Өзі тамақтанғысы келеді. 🥄', 'Қасықты қолыңыздан алса, кедергі жасамаңыз. Үсті-басы былғанса да, өз бетінше тамақтануы — оның дербестігінің ең үлкен белгісі.'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'Маған қара! ☝️', 'Назар аударту үшін дыбыс шығарып, саусағымен қызықтырған затын көрсетеді. Оның жаңалықтарына ортақтасып, Иә, бұл доп деп растаңыз.'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'Қасықтан бас тартпайды 🥄', 'Өзі тамақтанғысы келіп, жартысын үстіне төгіп алды ма? Тазалыққа мән бере бермеңіз. Дәл осы күндері оның өз бетінше тамақтану дағдысының негізі қаланады.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'Күн қорытындысы 📝', 'Өзіңізді жеткіліксіз сезінген кезде Көңіл күй күнделігіне бүгінгі шағын жетістіктеріңізді жазыңыз. (Мысалы: Оны күлдірдім, тойдырдым). Сіз кереметсіз.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'Әңгіме қыза түседі 🗣️', 'Түсініксіз сөздермен Сізге бірдеңе айтып, тіпті қолымен қимыл көрсете ме? Онымен дәл сондай байыппен диалог құрыңыз, бұл оның сөйлеуінің дамуы үшін маңызды.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'Таза ауаның күші 🌙', 'Ұйықтағысы келмей ме? Терезені ашып, бөлменің ауасын толық жаңартыңыз. Салқын әрі таза ауа ұйықтап кетуді әрдайым жеңілдетеді.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'Аллергияға күмән бар ма? 🤖', 'Жаңа жеміс беріп едіңіз, терісі қызарып кетті ме? Абыржымас бұрын Anacan AI-дан балалардағы тағамдық аллергия кезінде жасалатын алғашқы қадамдар туралы біліңіз.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'Бүгінгі күн ерекше болсын 🌟', 'Үйдегі күнделікті тіршілік жалықтырды ма? Анаға қолайлы орындар картасын ашып, бөпеңізбен бірге жайлы отыра алатын жаңа кафе табыңыз.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'Кішкентай жұлдыз! 📸', 'Оның сүйкімді күлкісі бәріне де тұрарлық! Бөпеге арналған фотосессия мүмкіндігіндегі әртүрлі жақтауларды қолданып, бүгінгі күнді мәңгілік естелікке айналдырыңыз.'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'Асқазан-ішек жұмысын бақылау ⏱️', 'Күніне қанша жөргек қолданылғанын бақылау тамақтану сапасын бағалауға көмектеседі. Бүгінгі жөргек ауыстыруларды қолданбамызға белгіледіңіз бе?'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'Отбасылық дастарқан 🍲', 'Кешкі асқа оған не бересіз? Қосымша тағам рецептерінің арасында бүкіл отбасы сүйсініп жейтін пайдалы тағам идеялары бар.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'Сіздің ана болу хикаяңыз 📝', 'Әр ананың хикаясы бірегей. Блогтарымыздан басқа аналардың шынайы тәжірибелері мен хикаяларын оқып, шабыт алыңыз.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'Саябақта жүгіру 👟', 'Алғашқы қадамдардан кейін жүгіретін кезең басталады. Алғашқы аяқкиімді таңдау үшін Ұсынылатын өнімдер бөліміндегі денсаулыққа пайдалы үлгілерді қараңыз.'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'Бөлмедегі тыныштық 🌊', 'Бүгін ұйықтау қиын болып тұр ма? Ақ шу бөлімінен мұхит толқындарының дыбысын қосыңыз — ол жүйке жүйесін тыныштандырып, ұйықтап кетуді жеңілдетеді.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'Ақуыз қоры жеткілікті ме? 🍗', 'Баланың өсуі үшін ақуыз міндетті түрде қажет! Тамақтануды бақылау құралы арқылы оның күнделікті ас үлесінің теңгерімін бағалап, жетіспейтін қоректік заттарды толықтырыңыз.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'Тәтті ұйқы 🌙', 'Бүгін қатты шаршадыңыз. Ол ұйықтап жатқанда Ақ шудан мұхит толқындарының дыбысын қосыңыз: бөпеңіз де тыныш ұйықтасын, Сіз де демалыңыз.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'Түскі ас таймері ⏱️', 'Тамақтану уақытын бақылау енді оңайырақ! Тамақтану таймерін қосып, бөпеңіздің күнделікті мөлшерін мұқият қадағалаңыз.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'Жүгіру басталды! 🏃‍♀️', '17 айлық кішкентай зерттеуші үйдің астан-кестенін шығарып жүр ме? Энергиясын жұмсауы үшін Анаға жайлы орындар бөлімінен маңайдағы жаңа саябақты тауып көріңіз.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'Дәмді әрі ерекше! 🥦', 'Бүгін оған қандай ерекше тағам дайындасам екен деп ойланып жүрсіз бе? Қосымша тағам жей бастаған бөпелерге арналған дәмді идеяларды Рецепттер бөлімінен таба аласыз.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'Сезімдеріңізді жазыңыз 📝', 'Ана болу кейде шаршатады, бұл — қалыпты жағдай. Бүгін Сізді ең қатты қажытқан нәрсені Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'Таңғы тосынсый 💩', 'Бүгінгі алғашқы жөргекті ауыстырдыңыз ба? Қосымшадағы жөргек бақылау бөліміне белгілеуді ұмытпаңыз, сонда гигиена тәртібін оңай қадағалай аласыз!'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'Күндізгі ұйқы 😴', 'Ұйқы таймерін қосыңыз! 17 айлық баланың күндізгі ұйқы ұзақтығын талдап, кешкі ұйқыға жатқызу жоспарын дәлірек құрыңыз.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'Ыңғайлы нұсқаны іздеп жүрсіз бе? 🍼', 'Оның өз бетінше ішуіне ыңғайлы, төгілмейтін су бөтелкесін іздеп жүрсіз бе? Аналар ең көп ұнатқан нұсқаларды Ұсынылатын өнімдер бөлімінен қараңыз.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'Ұйқы таймері қосулы ма? ⏳', 'Бөпеңізді ұйықтатуға кірісіп жатырсыз ба? Таймерді қосып, ұйықтап кету уақытын талдаңыз және осы әдетті қалай жақсартуға болатынын біліңіз.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'Ақылды көмекшіңіз 🤖', 'Балаңыз неліктен кенет тәбетін жоғалтты? Осы және басқа да мазалайтын сұрақтарыңызды Anacan AI-ға жазып, ғылыми негізделген жауапты бірден алыңыз.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'Қуат жинаңыз 🔋', 'Қарбалас күнге дайынсыз ба? Әйелдерге арналған пайдалы рецептілерден өзіңізге дәмді әрі витаминге бай таңғы ас таңдаңыз.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'Жайлылық іздеп жүрсіз бе? 🍼', 'Бөпеңіз өз бетінше ішуі үшін ең жақсы төгілмейтін поильникті іздеп жүрсіз бе? Ұсынылатын өнімдер бөлімінен аналар ең көп ұнатқан нұсқаларды қараңыз.'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'Сіздің қолыңыздан келеді! 💪', 'Күніңіз қиын өтті ме? Көңіл күй күнделігінде ішкі даусыңызға құлақ асыңыз. Есіңізде болсын, бұл жаман өмір емес, жай ғана қиын күн.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'Тамақтану есебі 📊', 'Балаңыздың бүгінгі тамақтануын Тамақтануды бақылау құралына енгізіңіз. Бүгін қажетті витаминдердің бәрін толық алды ма, тексеріп көрейік.'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'Күннің кереметі 🖼️', '520-шы күнге ерекше естелік! Ең қымбат әрі күлкілі суреттерді Бөпе альбомына жүктеп, жылдар өткен соң күлімсіреп еске алыңыз.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'Даму секірісі ме? 📈', 'Бөпеңіз көп жылай ма немесе ұйқысы бұзылды ма? Anacan AI-мен кеңесіп, бұл 17-ші айдағы даму секірісі аптасы ма, соны анықтаңыз.'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'Өзіңізді ұмытпаңыз! ☕', 'Сіздің күш-қуатыңыз — бөпеңіз үшін ең маңызды нәрсе. Пайдалы рецептерден өзіңізге дәмді әрі қуат беретін смузи дайындаңыз.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'Блог және кофе 📖', 'Бала ұйықтады, енді уақыт өзіңізге тиесілі! Жаңа блог жазбамызды оқып, белсенді балалардың психологиясы туралы көптеген қызықты дерек біліңіз.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'Жайлы серуен 👟', 'Саябақта оның соңынан жүгіріп жүру үшін екеуіңізге де ыңғайлы аяқ киім керек пе? Ұсынылатын өнімдер бөліміндегі үздік нұсқаларды қарап шығыңыз.'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'Сұрағыңыз бар ма? 🤔', 'Баланың күшейіп келе жатқан қырсықтығымен қалай күресуге болатынын ойлап жүрсіз бе? Anacan AI сарапшылар кеңесіне сүйеніп, сұрағыңызға бірден жауап беруге дайын!'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'Терең тыныс алыңыз ✨', 'Бәрі мінсіз болуы міндетті емес. Сіз онсыз да ең жақсы анасыз! Көңіл күй күнделігінде бір күндік күйзелістен арылып, демалыңыз.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'Бойы өсіп кетті ме? 🦒', 'Киімдерінің тар болып қалғанын байқадыңыз ба? Даму трекеріне жаңа көрсеткіштерді енгізіп, өсу графигіндегі өзгерісті тексеріңіз.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'Тамақтану нормасы 🥣', 'Бүгін жеткілікті мөлшерде ақуыз алды ма? Тамақтануды бақылау құралы арқылы бөпеңіздің күнделікті мәзірін талдап, жетіспейтін қоректік заттарды толықтырыңыз.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'Тыныштандыратын дыбыс 🌧️', 'Күндізгі қарбаластан ұйықтай алмай жүр ме? Ақ шу бөлімінен жаңбыр дыбысын таңдап, оның жүйке жүйесінің табиғи түрде тынышталуына көмектесіңіз.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'Тыныштандыратын кешкі әдет 🌙', 'Тамаша күннің соңы. Ұйқы таймерін қосып, Ақ шудан бесік жырын таңдаңыз да, күннің аяқталған сәтін тыныштықта тамашалаңыз.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'Таза ауа іздеп жүрсіз бе? 🌳', 'Үйде отырудан жалықтыңыз ба? Аналарға қолайлы орындар картасын ашып, бөпеңізбен бірге жайлы серуендейтін жаңа саябақ табыңыз.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'Ұйықтайтын уақыт келді ⏱️', 'Бөпеңізді ұйықтатуға кірістіңіз бе? Ұйқы таймерін қосып, күн тәртібін қалай сақтап жүргеніңізді белгілеңіз және ұйқы мөлшерін талдаңыз.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'Таңғы тәбеті қалай? 🥣', 'Күнді пайдалы тағаммен бастау маңызды! Тамақтануды бақылау құралы арқылы бүгінгі дәрумен қажеттілігін есептеп, мәзірді жоспарлаңыз.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'Таңғы күтім 💩', 'Бүгінгі алғашқы жөргекті ауыстырдыңыз ба? Нәжістің түсі мен қоюлығы ішектің саулығы туралы ақпарат береді. Дереу жөргек трекеріне белгілеңіз!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'Әйелдерге арналған қуат 🥗', 'Күнделікті қарбалас шаршатады. Өзіңізді ұмытпаңыз! Әйелдерге арналған пайдалы рецептілердің бірін таңдап, бірден қуат беретін дәмді салат дайындаңыз.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'Ақ шудың сиқыры 🌧️', 'Бүгін өте белсенді күн болды ма? Бөлмеде Ақ шудан жаңбыр дыбысын қосыңыз: бөпеңіз тез ұйықтап, Сіз де бір тынығып аласыз.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'Күннің ең тәтті сәті 📸', 'Бүгін бөпеңіз ерекше әрі күлкілі қылық көрсетті ме? Бөпеге арналған фотосессиядағы көңілді жиектемелермен сол сәтті түсіріп, өмірлік естелікке айналдырыңыз.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'Өзі жегісі келеді! 🥦', 'Бөпеңіз өз бетінше тамақтануға талпынып жүр ме? Қосымша тамаққа көшкен бөпелерге арналған Рецепттерден қолға ұстауға ыңғайлы, шашылмайтын дәмді тағамдарды таңдаңыз.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'Қырсықтықпен күрес 🤖', 'Бәріне «жоқ» дей ме? Осы кезеңдегі дағдарыстарды қалай еңсеру керегін білмесеңіз, Anacan AI-мен бірден кеңесіңіз.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'Киімдері тар болып қалды ма? 📏', 'Балаңыздың кенет бойы өсіп кеткенін байқадыңыз ба? Салмақ трекеріне жаңа көрсеткіштерді енгізіп, дені сау өсу кестесін қараңыз.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'Тамақтану таймері ⏱️', 'Бөпеңіздің тамақтануына қанша уақыт кетеді? Тамақтану таймерін қосып, астың толық қорытылуына көмектесетін режимді қадағалаңыз.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'Пайдалы оқу 📖', 'Бала ұйықтады, ал Сіз не істейсіз? Ана ретіндегі тәжірибеңізді толықтыру үшін Блогтар бөліміндегі ең жаңа мақалаларды оқыңыз.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'Мінсіз су құтысын іздеу 🥤', 'Төгіліп қалмайтын әрі ыңғайлы су құтысын іздеп жүрсіз бе? Ұсынылатын өнімдер бөлімінен аналар жиі сынап көрген өнімдерді қараңыз.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'Кофе ішуге үзіліс ☕', 'Бүгін үйден шыққыңыз келе ме? Аналарға қолайлы орындардан балалар бұрышы бар кафе тауып, өзіңізге уақыт бөліңіз.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'Эмоциялық жеңілдеу 📝', 'Бүгін бәрі жоспардағыдай болмады ма? Өзіңізді кінәламаңыз. Көңіл күй күнделігіне ішіңіздегіні жазып, ойыңызды сергітіңіз.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'Ұйқы нормасын тексерейік 😴', 'Түнде қалай ұйықтады? Ұйқы таймеріндегі жазбаларды қарап, бөпеңіздің тәуліктік ұйқы нормасын орындаған-орындамағанын талдаңыз.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'Сізді не алаңдатады? 🤖', 'Балаңыздың дамуына қатысты күмәніңіз бар ма? Anacan AI сарапшы көмекшімізге жазып, ғылыми негізделген жауаптар алыңыз да, көңіліңізді тыныштандырыңыз.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'Әр тағамның дәмі ерекше 🍲', '«Бүгін не пісіремін?» деген уайым артта қалды. Қосымша тамақ жей бастаған бөпелерге арналған Рецепттер бөлімінде Сіз үшін алуан түрлі әрі пайдалы мәзірлер бар.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'Күнделікті дәрет есебі 💩', 'Таңертең жөргегін ауыстырғанда белгілеуді ұмытпаңыз! Күні бойы жөргек ауыстыру жиілігін бақылау баланың жеткілікті мөлшерде сұйықтық алып жатқанын көрсетеді.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'Сіздің де қажеттіліктеріңіз бар 🥗', 'Күш-қуатыңыз таусылуға жақын ба? Әйелдерге арналған пайдалы рецепттердің бірін қолданып, дәруменге бай смузи дайындаңыз. Сіз мықты болуыңыз керек!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'Ұмытылмас естеліктер 🖼️', 'Болашақта бүгінгі сүйкімді сәттеріне қарап күлу үшін ең әдемі фотосуреттерін Бөпе альбомына жүктеп, қауіпсіз жерде сақтаңыз.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'Бүгін өзіңізді қалай сезіндіңіз? 💖', 'Қатты шаршасаңыз да, оны иіскегенде бәрі ұмытылып кетеді, солай емес пе? Бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, демалыңыз.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'Таймермен тамақтану ⏱️', 'Дастарқан басында тым ұзақ отыра ма? Тамақтану таймерін қосып, уақыт нормасын сақтаңыз және тәбеттің төмендеуіне жол бермеңіз.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'Таңғы ойындар 🧩', 'Бірге үйренеміз! 17.5 айлық балалардың зияткерлік дамуын қолдайтын ойындар туралы Блогтар бөліміндегі мақаламызды міндетті түрде оқыңыз.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', '«Мен Сені Жақсы Көремін» құшағы 🫂', 'Кенеттен келіп, мойныңыздан құшақтай ма немесе бетіңізді сипай ма? Ол енді сүйіспеншілігін қимылымен білдіре алады. Осы сәттен ләззат алыңыз.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'Әкенің жұбанышы 🫂', 'Түнде бөпе оянғанда бірде Сіз, бірде жұбайыңыз тұрыңыз. Жауапкершілікті команда ретінде тең бөлісіңіздер.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'Аллергияға күмән 🤖', 'Жаңа тағам беріп, бөпеңіздің беті қызарғанын байқадыңыз ба? Алаңдамас бұрын алғашқы қадамдар туралы Anacan AI-дан біліңіз.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'Үйде отырудан жалықтыңыз ба?☕', 'Анаға жайлы орындар арасынан өзіңіз таза ауа жұтып, бөпеңіз көңіл көтеретін ең жақын дәмхананы табыңыз.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'Дауыс ырғағыңызды түсінеді 🗣️', 'Сіз байсалды үнмен «жоқ» дегенде, кідіріп, Сізге қарай ма? Ол енді эмоциялар мен тыйымдарды толық түсінеді. Шекараларды сақтаңыз.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйықтардан 1 сағат бұрын үйдегі барлық жарықты бәсеңдетіп, экрандарды өшіріңіз. Мелатонин тек тыныш ортада бөлінеді.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'Ұйқы нормасы ⏱️', 'Ұйықтайтын уақыт келді! Ұйқы таймерін іске қосыңыз. Бөпеңіздің күнделікті ұйқы нормасын сақтайтынына көз жеткізу үшін кестені талдаңыз.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'Қарапайым тапсырмаларды орындайды 🧸', '«Аяқкиіміңді әкел» дегенде, шынымен барып алып келе ме? Сөздік қоры мен түсіну қабілеті қарқынды дамып жатыр! Оны ойындарға көбірек қатыстырыңыз.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'Өзіңізді мақтаңыз 👏', 'Бөлменің шашылып жатқанына емес, оның бүгін қаншалықты бақытты болғанына қараңыз. Сіз ешбір кітап үйрете алмайтындай керемет анасыз.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'Таймер арқылы ұйқыны талдау ⏱️', 'Күндізгі ұйқысы қысқарып жүр ме? Ұйқы таймерін қосып, осы аптаның кестесін талдау арқылы кешкі ұйқы уақытын қайта реттеңіз.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'Бір-біріңізге қолдау көрсетіңіздер! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ішіңіздегіні бөлісіңіз. Бір-біріңізге қолдау көрсету ауыртпалықты екі есе жеңілдетеді.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'Түскі тәбет 🥣', 'Бүгін ол жеткілікті мөлшерде ақуыз жеді ме? Тағамдарды тамақтануды бақылау құралына енгізіп, күнделікті норманың орындалғанына көз жеткізіңіз.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'Ақыл-ой серпілісі 🧠', 'Бөпеңіздің миында қандай өзгерістер болып жатыр? Блогтар бөлімінен 17-18 айлық балалардың танымдық дамуы туралы ең жаңа мақаланы оқыңыз.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'Ұйқы кестесі ⏱️', 'Ояну уақыты өзгерді ме? Ұйқы таймерінің статистикасына қарап, күндізгі және түнгі ұйқы арасындағы тепе-теңдікті мұқият талдаңыз.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'Таңғы есеп 💩', 'Денсаулықтың алғашқы көрсеткіші — ас қорыту жүйесі. Жөргегін ауыстырған кезде үлкен дәреті туралы мәліметті қолданбаға енгізіп, күн ішіндегі өзгерістерді бақылаңыз.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'Тәтті естеліктер 📸', 'Бүгінгі ең күлкілі қылығын Бөпе альбомына қосыңыз. Жылдар өткен соң бұл кадрларды парақтап, бір күліп аласыз.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'Төгілмейтін су бөтелкесі 🥤', 'Жүгіріп жүріп су ішкенді ұнатады, бірақ үстін су қылып қоя ма? Ұсынылатын өнімдер бөлімінен аналар таңдаған ең ыңғайлы су бөтелкелерін қараңыз.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'Киімдері кішірейіп барады! 📏', 'Балақайдың киімінің жеңі қайтадан қысқарып қалды ма? Салмақ бақылағышына жаңа көрсеткіштерді енгізіп, бойы мен салмағының өсуін даму кестесінен мақтанышпен бақылаңыз.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'Өз бетінше ойнайтын уақыт 🧸', 'Енді ол 10-15 минут бойы ойыншықтарымен өз бетінше ойнай алады. Бұл зейін қою ұзақтығының артқанын білдіреді. Тыныштықтан ләззат алыңыз.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'Сырттағы ауа райы түсініксіз бе? ⛅', 'Ауа райы және киім құралы терезеден байқалмайтын желдің жылдамдығын көрсетіп, қандай киім үйлесімін таңдау керегін бірден айтсын.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'Массаж уақыты 💆‍♂️', 'Бала ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыз. Сіздер — бір командасыздар!'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'Дыбысты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен айналадағы дыбыс деңгейін тексеріп, кенеттен шығатын шудан сақ болыңыз.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'Жедел педиатр 🤖', '18 айлық баланың сөйлеуінің дамуына алаңдайсыз ба? Anacan AI-дан сұрап, осы жаста қандай сөздерді айтуы қалыпты екенін біліңіз.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'Өзіңізге қамқорлық жасаңыз 🥗', 'Баланың соңынан жүгіруден шаршадыңыз ба? Әйелдерге арналған пайдалы рецептілерден бірден қуат беретін дәмді салат тауып көріңіз.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'Таңғы тазалық 🧻', 'Бүгінгі алғашқы жөргек ауыстыру қалай өтті? Дәреті туралы мәліметтерді қолданбаға жазып, асқазан-ішек жүйесінің жұмысын оңай бақылаңыз.'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'Дәрумендер қоймасы 🥦', 'Тамақтануды бақылау құралы арқылы бүгінгі мәзірді тексеріңіз. Жетіспейтін дәрумендердің орнын толықтыруға арналған түрлі-түсті тағамдар Бөпе рецептілерінде Сізді күтіп тұр!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'Тым қырсық па? 🤖', '«Жоқ» дегенді айтудан жалықпай ма? 17.5 айлық баланың қырсығуын басқару үшін Anacan AI көмекшісінен ғылыми негізделген психологиялық кеңестер алыңыз.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'Жайлы кеш 🌊', 'Бөлмеде тыныштық орнататын уақыт келді. Ақ шуылдардан мұхит толқындарының дыбысын қосып, оның жүйке жүйесіне терең ұйқыға кетуге көмектесіңіз.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'Ас ішу сынағы ⏱️', 'Тамақтану тым ұзаққа созыла ма? Тамақтану таймерін қосып, уақыт нормасын сақтаңыз әрі тәбеттің болмау себептерін талдаңыз.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'Күнделікті терапия 📝', 'Ана болу кейде эмоциялық күйге толы сапар секілді. Көңіл күй күнделігін ашып, бүгінгі шаршағаныңызды жазып, жеңілдеп қалыңыз.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'Кофе ішетін уақыт келді ☕', 'Үйдің төрт қабырғасынан жалықтыңыз ба? Анаға жайлы орындардан баламен бірге еркін бара алатын кафе тауып, өзіңізді қуантыңыз.'),
  ('e59af63b-a407-459e-a6f1-a0263d9f74f5', 'Кішкентай жұлдыз 🌟', 'Осы сүйкімді күлкіні жіберіп алмаңыз! Бөпе фотосессиясы құралындағы қызықты тақырыптармен оның бүгінгі көңіл күйін мәңгілік естелікке айналдырыңыз.'),
  ('f71b2bf0-976d-4844-8538-db17781ce999', 'Өзіңізге уақыт бөліңіз 🍵', 'Бала ұйықтады, енді өзіңізді қалпына келтіретін кез келді. Пайдалы рецепттерден тыныштандыратын шөп шайын демдеңіз.'),
  ('4f770f32-235d-4481-acc9-8a3353f11910', 'Сізді не алаңдатады? 🤔', 'Бөпеңіз кенеттен тамақтан бас тарта ма? Ана болуға қатысты кез келген сұрағыңызды Anacan AI-ға қойып, бірден сараптамалық дәлдікпен жауап алыңыз.'),
  ('996b9423-cc50-4ec2-bbf6-02866083bb10', 'Ұйқыға оңай кету 🎶', 'Белсенді жаңалықтарға толы күннен кейін ұйықтай алмай жүр ме? Ақ шу бөлімінен бесік жырын таңдап, бөлмеде сиқырлы тыныштық орнатыңыз.'),
  ('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b', 'Табиғатты танып-білу 🍂', 'Таза ауа екеуіңізге де пайдалы. Анаға қолайлы орындардан жаңа саябақ тауып, бөпеңіздің еркін жүгіріп, бойындағы энергиясын шығаруына мүмкіндік беріңіз.'),
  ('19f1aa58-50a6-4acf-b375-1d03850cfcb6', 'Ішкі даусыңыз 💖', 'Мінсіз ана болуға міндетті емессіз, ол үшін Сіз ең жақсы анасыз. Бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, жеңілдеп қалыңыз.'),
  ('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98', 'Өздігінен тамақтану тәжірибесі ⏱️', 'Өзі тамақтануға тырысып жүр ме? Шашылған тағамға мән бермеңіз! Тамақтану таймерін қосып, оның өздігінен тамақтануына қанша уақыт кететінін талдаңыз.'),
  ('f869363f-52a1-4240-a759-b2b999d347e4', 'Пайдалы тәтті 🍪', 'Дүкендегі тәттілердің қажеті жоқ. Қосымша тамақ жей бастаған бөпелерге арналған Рецепттерден оңай, қантсыз әрі дәмді печенье дайындаңыз.'),
  ('91d67474-6689-4302-b69e-a9b260aedef7', 'Дұрыс ойыншық 🧩', 'Логикасын дамытатын ойыншық іздеп жүрсіз бе? Ұсынылатын өнімдер бөлімінен жасына сай әрі пайдалы пазлдарды табыңыз.'),
  ('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2', 'Кешкі ұйқы рәсімі 🌙', 'Күн сайын бір уақытта ұйықтату тұрақты әдет қалыптастырады. Ұйқы таймерін қосып, ұйқы нормасын тексеріңіз де, оңай ұйықтаудың рақатын көріңіз.'),
  ('e8b020dc-c4fe-4f5b-946a-28ae84382a39', 'Дені сау болып өсіп келеміз 📈', '18 айға толуына аз қалды! Даму қарқынын Салмақ бақылау құралында талдап, бойы мен салмағының нормаға сәйкестігін тексеріңіз.'),
  ('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17', 'Тамаша күннің қорытындысы 🖼️', 'Бірге түскен ең көңілді әрі жылы фотосуретті Бөпе альбомына қосып, осы ерекше күнді (540 күн!) мәңгі есте қалдырыңыз.'),
  ('c1dc4453-41a2-40e6-812c-73fb934ccc70', 'Сіз — қаһармансыз! ✨', 'Ана болу жолының 540-шы күні! Бүгінгі жетістігіңізді Anacan AI-ға жазыңыз, ол күніңізге көрік беретін арнайы мотивация ұсынсын.'),
  ('fa1d5820-5e14-435d-81d1-df116bd7de6f', 'Отбасылық дастарқан 🍲', 'Ол енді Сізбен бірге бірдей тағамдарды жей алады. Тамақтануды бақылау құралы арқылы ортақ тағамдарыңыздың тағамдық құндылығын оңай есептеңіз.'),
  ('ae531928-8e01-4e71-961a-63a517eaee5a', 'Терең ұйқыға көшу 🌙', 'Ұйқы таймерін қосыңыз. Түнде жиі ояна бастаса, Ақ шу бөліміндегі мұхит толқындарының дыбысымен оның жүйке жүйесін тыныштандырыңыз.'),
  ('bacdcc71-8211-4dd5-b3af-c5af34fb468a', 'Таңғы тосынсый 💩', 'Күннің алғашқы жөргегін ауыстырғанда белгілеп қойыңыз! Бұл — өсіп келе жатқан бөпенің ас қорыту жүйесі мен сұйықтық қабылдауын бақылаудың ең тиімді жолы.'),
  ('1bf2c33f-3711-4208-8da6-0a931502b566', 'Мүлде қараңғы бөлме 🌙', 'Ұйықтауға қарсылық білдіре ме? Бөлмедегі кішкентай жарықтың өзі оның назарын аударады. Экрандарды өшіріп, бөлмені толық қараңғылаңыз — бұл мелатониннің бөлінуін тездетеді.'),
  ('5f000b16-6031-438b-92a6-3ea1d69ae68b', 'Тағы да есіңізден шығып кетті ме? 🛒', 'Жөргек пе, әлде айран таусылды ма? Ойыңызды артық жүктемей, бірден Сатып алу тізіміне қосыңыз — жұбайыңыз жұмыстан қайтарда ала келсін.'),
  ('8593e3b3-5794-49a0-a5ef-d04af1bd53a7', 'Кітаптағы ұсақ бөлшектер 📖', 'Кітапты парақтап, суреттегі ең кішкентай бөлшекті (мысалы, кішкентай құсты) саусағымен көрсете ме? Даму трекеріне осы танымдық зейінін белгілеп қойыңыз. Көру жады керемет жұмыс істеп тұр!'),
  ('5df90283-8938-4f2c-bc5d-95fad0d0249f', 'Ұйқы режимін тексерейік ⏱️', 'Кешке ұйықтағысы келмей ме? Ұйқы таймерінің кестесін талдаңыз. Күндізгі ұйқысын сәл қысқарту қажет шығар.'),
  ('eb685812-a20b-4dfa-8dcd-a8c0865f1a25', 'Ананың энергиясы 🔋', 'Өзіңізді ұмытпаңыз! Рецептілерден таңғы асқа тез дайындалатын, ақуызға бай әрі дәмді тағам таңдаңыз.'),
  ('f80fa225-e7f6-4b7d-a7da-b651f5688ba0', '«Жоқ!» дейтін кезең 🛑', 'Бәріне қарсылық білдіре ме? 1.5 жастағы қырсықтық туралы Anacan AI көмекшісінен кеңес алып, психологиялық қолдау мен тиімді шешім табыңыз.'),
  ('bd224607-0812-4b81-8b5d-af59d7d7cc10', 'Дәрумендер бомбасы 🥗', 'Ананың күш-қуаты таусылмауы керек! Әйелдерге арналған пайдалы рецептілердің бірін таңдап, бірден қуат беретін дәмді смузи дайындаңыз.'),
  ('c9435c7a-e56d-449f-9eb8-fae0dc263176', 'Ұйқыға дайындық рәсімі 🌙', 'Ұйқы таймерін қосып, бөлмені қараңғылаңыз. Кестені талдау арқылы бөпеңізді күн сайын бір уақытта ұйықтатуды оңай әдетке айналдырыңыз.'),
  ('ffe1377d-426e-4c3f-a06d-3551b2ee446b', 'Зияткерлік ойыншықтар 🧩', '18 ай — логикалық ойындар үшін таптырмас кезең. Ұсынылатын өнімдерден жасына сай пазлдар мен текшелерді тауып, зеректігін шыңдаңыз.'),
  ('10d89b1a-052c-42d7-9604-a8aa080e3159', 'Отбасылық дастарқанның берекесі 🍲', 'Ол енді Сізбен бірге ортақ тағамды толықтай жей алады! Қосымша тамақ жей бастаған бөпелерге арналған Рецепттерден бүкіл отбасыға ортақ әрі пайдалы кешкі ас таңдаңыз.'),
  ('25077620-39e7-49c9-abd7-7ee3d4c9f4a5', 'Ішек жұмысын бақылау ⏱️', 'Жөргек трекеріне күн ішіндегі өзгерістерді белгілеп, оның жеткілікті мөлшерде сұйықтық пен тағамдық талшық алып жүргенін оңай саралаңыз.'),
  ('94fb4891-ca2e-4e41-b663-ea23a832df89', 'Жаңбыр дыбысының тыныштығы 🌧️', 'Белсенді өткен күн миды шаршатуы мүмкін. Ақ шулардан жаңбыр дыбысын қосып, бөлмеде тыныштандыратын әрі ұйқы шақыратын тамаша фон жасаңыз.'),
  ('02d8aef9-6d63-4748-9f41-c063ee842eb2', 'Сіздің қолыңыздан келеді! 💖', 'Шаршағаныңызды сезінгенде, Көңіл күй күнделігін ашыңыз. Оған жай ғана Мен бәрін еңсере аламын деп жазып, демалыңыз.'),
  ('04fca8dd-97bb-4af2-93b5-030f318cd3da', 'Табиғатты зерттеу 🌳', 'Үйдің іші оған тар болып жүр ме? Анаға жайлы орындардан кең әрі қауіпсіз саябақ тауып, бойындағы энергиясын шығаруға көмектесіңіз.'),
  ('7306940e-101e-4de4-af72-da4ab6736ad8', 'Тамақтану таймері ⏱️', 'Тамақпен тым көп ойнай ма? Тамақтану таймерін қосып, дастарқан басында өткізген уақытының нормаға сәйкестігін және тәбетін саралаңыз.'),
  ('07b5d33a-c674-4dcc-a023-81e3746cb054', 'Логикалық ойындар 🧱', '4-5 текшені бірінің үстіне бірін қойып, мұнара тұрғыза ма? Даму трекеріне моторикадағы осы жетістігін белгілеңіз! Оның осындай кішкентай инженерлік талпыныстарына қолдау көрсетуді ұмытпаңыз.'),
  ('e207d666-c361-4203-8076-7ba835d4f015', 'Қасықты қолынан тастамай ма? 🥄', 'Тамақтану таймерін қосыңыз. Өз бетінше тамақтануға талпынысы қанша уақытқа созылатынын талдап, күнделікті тамақтану нормасын қараңыз.'),
  ('35587de2-b62b-435c-aca4-01e72314423a', 'Ішіңіздегіні ақтарыңыз 📝', 'Әр күн мінсіз бола бермейді, бұл қалыпты жағдай. Бүгінгі сезімдеріңізді Көңіл күй күнделігіне жазып, бойыңыздағы күйзелістен арылып, жайбарақат демалыңыз.'),
  ('6dca6700-52a0-4818-812b-80dcc5c42de9', 'Міне, ресми түрде 1.5 жаста! 🎈', 'Балаңыз осы айларда қарқынды өседі. Даму трекеріне соңғы көрсеткіштерді енгізіп, даму кестесіне мақтанышпен көз жүгіртіңіз.'),
  ('da88924f-9b7a-4cc5-9b9e-429e9d903edd', 'Өзіңізді марапаттаңыз ☕', '18 ай бойы ана болу оңай емес! Аналарға қолайлы орындар картасынан жайлы дәмхана тауып, өзіңізге бір шыны ыстық кофе алып беріңіз.'),
  ('6b77a02d-8882-4aed-be91-5f8ce3841671', 'Жүгіруге дайынсыз ба? 👟', 'Алғашқы нық жүгірістер үшін дұрыс аяқкиім міндетті! Ұсынылатын өнімдерден аналар ең көп ұнатқан ортопедиялық үлгілерді табыңыз.'),
  ('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e', 'Тәтті сәттер 📸', 'Жүгіріп бара жатып құлап, күліп жіберді ме? Осы тәтті сәтті дереу Бөпе альбомына қосып, болашаққа жарқын әрі өмірлік естелік етіп сақтаңыз.'),
  ('e2aefd08-9263-41a3-87d4-c2d0378c7526', 'Темір қоры қалай? 🥩', 'Тамақтануды бақылау құралы арқылы бүгін темірді жеткілікті мөлшерде алғанын тексеріңіз. Жетіспеушілік болса, Бөпеге арналған рецепттерді қараңыз.'),
  ('48983c78-1769-4320-a7cf-ba470eef1415', 'Арнайы ертегі 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше хикая жасаңыз: 1.5 жастағы зерттеушінің шытырман оқиғалары.'),
  ('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0', 'Өсу жалғасуда! 🌟', 'Ол енді 18 айдан асты! Өз бетінше жүретін, эмоцияларын көрсететін, қырсықтау болса да, мейірімі мол бөпемен бірге жаңа кезең басталады!'),
  ('cdca9fee-71e1-4e46-aea7-41734d6fa68a', '18 айдағы ұйқы регрессиясы ма? 🥱', 'Ұйықтауға қарсылық білдіре ме немесе түнде оянып кете ме? Бұл — осы кезеңге тән ұйқы регрессиясы. Осы биологиялық үдеріс туралы ғылыми ақпаратты Anacan AI-дан алыңыз.'),
  ('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03', '«Өзім!» деген қырсықтық 🛑', 'Барлығын, тіпті қауіпті заттарды да өзі алғысы келеді. Қолынан алып қойсаңыз, басталатын дауылға дайын болыңыз. Тыйым салудың орнына, назарын одан да қызықты нәрсеге аударып көріңіз.'),
  ('d6508b29-e914-4995-93c3-58c73e271159', 'Массаж және тыныштық 💆‍♀️', 'Күні бойы жүгіріп, беліңіз ауырып кетті ме? Бала ұйықтағаннан кейін жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз бұған лайықсыз!'),
  ('dd068a2e-5d54-49f1-be6d-02db7c690974', 'Нағыз жүгіру жолағындасыз 🏃‍♂️', 'Бөлмеден бөлмеге жүгіріп, бір сәтке де тоқтамай ма? Осы кезеңде оның тік тұрғандағы тепе-теңдігі толық қалыптасады. Үйдегі ұсақ қауіпті заттарды жинап қойып, осы бір жігерлі сәттерді сырттай бақылаңыз.'),
  ('d14775e1-8a41-4689-87c3-351bcaa01c87', 'Әкенің ойын алаңы 👨‍👧', 'Шыдамыңыз таусылды ма? Бөлменің есігін жауып, баланы әкесімен оңаша қалдырыңыз. Бүгін кешке үйдегі ойын алаңын әкесі басқарсын.'),
  ('e1121d1f-a680-4fb9-9a1f-6792cb16e172', 'Жеміспен жауласты ма? 🍎', 'Кеше жақсы көрген алмасын бүгін жерге лақтырып жатыр ма? Тамақ талғау — осы жастағы ең жиі кездесетін қиындықтардың бірі. Интернеттен ұзақ іздемей-ақ, «Пайдалы рецепттер» бөлімінен жемісті қызықты етіп ұсыну идеяларын қараңыз.'),
  ('ef76ecee-5471-407a-a72c-9593be1406af', 'Әңгімесі таусылмайды 🗣️', 'Таңертең ояна сала өз тілінде ұзақ әңгіме айта ма? Сөйлеу орталығы қарқынды дамып жатыр. Оны бар ықыласыңызбен тыңдап, «Рас па?», «Сосын не болды?» деп жауап беріңіз.'),
  ('be5acfb3-03f0-4bea-9e14-40b38bca8262', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде бөпеге жалғыз өзіңіз ғана тұра бермеңіз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу. Бүгін түнде бөпені тыныштандыру кезегі — әкеде.'),
  ('fa9c7680-afc6-4095-9ec3-d56ad432d989', 'Саябақ па, әлде үй ме? ⛅', 'Сыртқа шыққыңыз келеді, бірақ ауа райы құбылмалы. Ауа райы және киім көмекшісі температураны ғана емес, жел өткізбейтін қандай киім кигізу керегін де айтып берсін.'),
  ('b62665c0-5b12-4c5d-adfa-7b34000204cf', 'Күлкіге толы сәттер 📸', 'Бүгін Сізді ерекше күлдірген сол бір сүйкімді сәтті еске түсіріп, оны Бөпе альбомына шағын видео немесе сурет ретінде міндетті түрде қосыңыз.'),
  ('e16b58bb-af8f-43a3-bf1f-c1d132a221a5', 'Уайымға салынбаңыз 🤖', 'Балаңыздың әдеттен тыс әрекетін байқадыңыз ба? Түнді күтпей-ақ, бірден Anacan AI-ға жазып, алаңдаушылығыңызды сейілтіңіз.'),
  ('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4', 'Кальцийге қажеттілік 🦷', 'Тамақтануды бақылау құралы арқылы балаңыздың бүгін қанша кальций алғанын есептеңіз. Сүйектер мен тістердің саулығы үшін сүт өнімдерінің қажетті мөлшеріне назар аударыңыз.'),
  ('72bb2391-6fc4-4ef8-9352-3ae963d61f5b', 'Енді кезек Сізде 🥗', 'Бала ұйықтаса, асүйге өтіңіз! Әйелдерге арналған пайдалы рецептілерден бірден күш-қуат беретін, ақуызға бай салат тауып көріңіз.'),
  ('7c893844-8335-47b4-baf7-b21329be4554', 'Ішіңіздегіні қағазға түсіріңіз 📝', 'Қарбалас әрі шулы күн болды ма? Көңіл күй күнделігіне сезімдеріңізді жазу ойыңыздағы ауыртпалықты жеңілдетеді.'),
  ('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a', 'Киімдер тағы да кішірейіп қалды ма? 📏', '18 айдан кейін бойдың күрт өсу кезеңі күтіледі. Салмақ бақылау құралына жаңа көрсеткіштерді енгізіп, даму қисығына мақтанышпен қараңыз.'),
  ('1e433a5c-ee68-4089-bf86-5ce74fde7136', 'Логикалық ойыншықтар 🧩', '18.5 айға таяғанда логикалық ойындар ойнауға таптырмас уақыт. Ұсынылатын өнімдер бөлімінен жасына сай пазлдар мен текшелерді табыңыз.'),
  ('9d69d283-cfae-47a2-a874-8fabcc20a7f1', 'Өсу қарқыны 📈', 'Даму қарқынын Дамуды бақылау құралында талдаңыз. Бойы мен салмағының нормаға сәйкестігін график арқылы бақылаңыз.'),
  ('a242b14e-b434-493a-ab87-b2064aedfc9e', 'Нағыз шытырман оқиға іздеуші 📸', 'Өрмелеп немесе жүгіріп ойнап жүргенде түсірген ең көңілді фотосын Бөпе альбомына қосып, естелікке айналдырыңыз.'),
  ('465d0258-9df5-4a0a-9902-79a09218dcc5', 'ТУРА 19 АЙ! 🎂', 'Құттықтаймыз! Босанғаныңызға тура 19 ай болды! Дәл қазір Бөпе фотосессиясынан арнайы стикерді таңдап, осы қуанышты Anacan қауымдастығында бөлісіңіз!'),
  ('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4', 'Күлкіге толы сәттер 📸', 'Өрмелеп немесе жүгіріп ойнап жүргенде түсірген ең көңілді фотосын Бөпе альбомына қосып, күннің шаршауын күлкіге айналдырыңыз.'),
  ('ccbbf1c0-789d-4a84-96bd-cdb04c618d13', 'Өсуін бақылайық 📈', 'Дене белсенділігі артты. Ал салмақ қосуы нормаға сай ма? Даму қарқынын Салмақты бақылау құралында талдап, алаңдаушылықтан арылыңыз.'),
  ('0671a41f-8a24-4dff-87f0-008aa3abfc3d', 'Ас қорыту жүйесі қалай жұмыс істейді? 💩', 'Жөргегін ауыстырған кезде үлкен дәреті туралы мәліметті қолданбаға енгізіңіз. Күні бойы жасұныққа бай тағамдардың ас қорытуға әсерін оңай бақылаңыз.'),
  ('d414aad6-2d3e-4a62-a555-9241874e68b3', 'Ұйқы кестесі ⏱️', 'Ұйықтайтын уақыт келді! Ұйқы таймерін іске қосып, тәуліктік ұйқы нормасын сақтайтынына көз жеткізу үшін режимін талдаңыз.'),
  ('22efa7bf-186e-41c7-b46c-b75ce17b0a09', 'Таңғы тазалық 💧', 'Күннің алғашқы жөргегін ауыстырдыңыз ба? Дәрет туралы мәліметтерді қолданбаға енгізіп, бөпеңіздің сұйықтықты жеткілікті қабылдап жүргенін оңай бақылаңыз.'),
  ('37e7b0b1-141f-488d-99c8-a87bde73955f', 'Ас мәзіріне қарсылық 🥣', 'Тамақтан бас тартып жүр ме? Күштеп тамақтандырудың орнына, тәрелкесіне түрлі түсті көкөністер салып, қызығушылығын оятыңыз. Пайдалы рецептілерден жаңа идеялар алыңыз.'),
  ('5ae1647c-ec81-4db7-838c-66f57619dd06', 'Дыбысты бақылау 🤫', 'Ұйқыға дайындаларда бөлмедегі дыбыс деңгейін Дыбыс өлшегішпен бақылаңыз. Түнде бөлінген ұйқы оның дамуына да, Сіздің таңғы көңіл күйіңізге де кері әсер етеді.'),
  ('2e177a88-e995-4df3-ae19-8a1044979006', 'Музыкалы кештер 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — оның сүйікті әнін қосып, құшақтап бірге билеу.'),
  ('82b5cb21-ea7e-4957-9166-81471c0b098a', 'Неге бұлай істейді? 🤖', 'Себепсіз ашу ұстамалары (тантрум) басталды ма? Anacan AI-мен бірден кеңесіп, мамандар ұсынған психологиялық тәсілдерді үйреніңіз.'),
  ('8aa141ab-420e-4a45-9eba-7dddd2430cb1', 'Қантсыз қуат 🍌', 'Түсте тәтті сұрай ма? Бөпелерге арналған рецептілердегі банан мен сұлыдан жасалған пайдалы тіскебасарлар арқылы дұрыс тамақтану тәртібін сақтаңыз.'),
  ('284e490f-ef18-407e-b320-432395edf56f', 'Қажетті заттар тізімі таусылмайды 🛒', 'Сусабын, жөргек немесе сұлы таусылды ма? Есте сақтауға тырыспай-ақ, Сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd', 'Үйден шығатын уақыт ☕', 'Күнделікті тірліктен жалықтыңыз ба? Аналарға қолайлы орындардан балалар бұрышы бар дәмхана тауып, бір шыны ыстық кофеден ләззат алыңыз.'),
  ('ee049a04-c690-49d6-a1c7-d2c603be49d5', 'Ертегімен ұйқыға кету 🪄', 'Ақылды ертегілер бөлімінде арнайы ертегі құрастырып, балаңызға оқып беріңіз.'),
  ('46fbf80f-0604-494d-b68e-60f85488090d', 'Өзі тамақтанады! 🥣', 'Қасықты қолынан тастамай ма? Тамақтану таймерін қосып, тамақтану ұзақтығын бақылаңыз әрі мөлшерінің нормаға сай екенін тексеріңіз.'),
  ('5174db8a-22d1-41db-af86-5a575522337a', 'Алғашқы суреттер 🖍️', 'Балаңыз шимайлап сурет сала бастады ма? Зиянсыз әрі жуылатын бояуларды табу үшін Ұсынылатын өнімдер бөліміндегі үздік нұсқаларды қарап шығыңыз.'),
  ('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b', 'Кішкентай суретші 📸', 'Үсті-басы бояу болып кетті ме? Ашуланудың орнына осы күлкілі сәтті Бөпе фотосессиясындағы көңілді жақтаулармен мәңгілікке сақтап қойыңыз.'),
  ('2d802010-e9c4-4370-b595-862f19214f3d', 'Кальций қоры 🧀', 'Тіс пен сүйекке кальций қажет. Тамақтануды бақылау құралы арқылы бүгін сүт өнімдерінің қажетті мөлшерін тұтынғаныңызды тексеріңіз.'),
  ('739069ab-a4c7-4cc9-ae84-572e67836bd2', 'Күннің ең сүйкімді сәті 🖼️', 'Бүгін Сізді ең қатты күлдірген сол қылығын есіңізге түсірдіңіз бе? Оны бірден Бөпе альбомына жүктеп, болашаққа сақтап қойыңыз.'),
  ('faac9718-e68e-455d-90e4-e34b7b38a24e', 'Зияткерлік даму 🧠', 'Блогтар бөлімінен 1.5 жастағы балалардың миында жүретін таңғажайып үдерістер туралы жаңа мақаланы міндетті түрде оқыңыз.'),
  ('2155f722-dd8c-49ec-a515-ecee85476474', 'Таңғы бақылау 🧻', 'Бүгінгі алғашқы жөргекті қолданбаға белгіледіңіз бе? Нәжістің түсі мен қоюлығы баланың жеткілікті сұйықтық ішіп жүргенін көрсетеді.'),
  ('fbbb1355-d1ac-4efe-b9c7-1746b97b1656', 'Бөліскісі келмей ме? 🤖', 'Саябақта ойыншығын бөліспей, айқайлап жатыр ма? Мұндай жағдайда не істеу керектігін Anacan AI көмегімен біліп, қолданып көріңіз.'),
  ('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e', 'Таңғы тосынсый 💩', 'Күннің алғашқы жөргегін ауыстырдыңыз ба? Нәжіс туралы мәліметтерді қолданбаға енгізіп, асқазан-ішек жүйесінің жұмысын және сұйықтық ішуін мұқият қадағалаңыз.'),
  ('b32e8863-be99-483a-aff4-94fc82f554bc', 'Ұйқы таймері іске қосылды! ⏱️', 'Кешкі дағдылы әрекеттер басталады. Таймерді қосып, белсенді күннің ұйықтап кету уақытына қалай әсер еткенін оңай талдаңыз.'),
  ('f0fc96ac-776c-4e66-bacf-461eff128cbc', 'Түрлі түсті тәрелкелер 🥦', 'Көкөніс жемей ме? Қосымша тағам жей бастаған бөпелерге арналған Рецепттердегі қызықты безендіру тәсілдерін қолданып, Тамақтануды бақылау құралындағы норманы көңілді түрде толықтырыңыз.'),
  ('4673b81e-675b-4232-a5ca-c06aa26d504d', 'Ананың қуаты 🔋', 'Күнделікті қарбалас күшіңізді сарқып жіберді ме? Өзіңізді ұмытпаңыз! Пайдалы рецепттерден бірден қуат беретін ақуызды смузи дайындаңыз.'),
  ('7a2ab463-526e-46c6-a246-3494b6c46fa9', 'Таң қиын басталды ма? 🌪️', 'Қырсығу ұстамалары қажытады. Терең тыныс алып, мұндай жағдайда не істеу керектігін дереу Anacan AI-дан сұраңыз.'),
  ('c995af30-30f9-4eaf-a66c-3d0d65fc825b', 'Ішкі даусыңызды тыңдаңыз 📝', 'Бала ұйықтады. Енді Көңіл күй күнделігін ашып, ешкім оқымайтын сол жолдарға бүгінгі сезімдеріңізді жазып, жеңілдеп қалыңыз.'),
  ('0aa2cefc-f18c-4c10-98d6-e4dfda22198e', 'Тыныштандыратын дыбыс 🌧️', 'Жаңа әсерлерге толы күннен кейін ұйықтай алмай жатыр ма? Ақ шулардан жаңбыр дыбысын қосып, жүйке жүйесін табиғи жолмен тыныштандырыңыз.'),
  ('a57c041d-751b-4413-a98e-ee1564a86127', 'Таза ауа, мол энергия 🌳', 'Үйдің қабырғалары тар болып кетті ме? Анаға қолайлы орындардан түрлі ойын құрылғылары бар жаңа саябақты тауып, бөпеңіздің энергиясын шығаруына көмектесіңіз.'),
  ('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc', 'Зияткерлік серпіліс 🧠', '18.5 айлық бөпенің миында қандай өзгерістер болып жатыр? Блогтар бөліміндегі ең жаңа мақаланы оқып, оның даму үдерістерімен танысыңыз.'),
  ('108adc32-ab84-4dcd-be8c-e7597e84aa99', 'Үстел басында ұзақ отыра ма? ⏱️', 'Тамақпен ойнайтын кезең басталды. Тамақтану таймерін қосып, тәбетінің төмендеуіне жол бермеу үшін тамақтану ұзақтығын талдаңыз.'),
  ('36ae8436-7cda-46ec-b16d-44295bf2f7bc', 'Киімдері тағы да кішірейіп қалды ма? 📏', 'Бөпеңіздің кенеттен бойы өсіп кеткенін байқадыңыз ба? Даму трекеріне жаңа көрсеткіштерді енгізіп, даму графигінің жоғарылағанын мақтанышпен тамашалаңыз.'),
  ('909b1a9f-36d9-4ba3-a481-ae0e711ea145', 'Сүйкімді кадрлар 📸', 'Секіруге немесе билеуге талпынып жүр ме? Осы сәтті Бөпе фотосессиясындағы көңілді жақтаулармен безендіріп, өмір бойы сақталатын естелік жасаңыз.'),
  ('049ab226-ff27-4f2f-a64f-85d2b588c035', 'Тісі ауырып жүр ме? 🤖', 'Себепсіз тәбеті төмендеп немесе жылай бере ме? Азуларының шығу белгілері туралы Anacan AI-дан сарапшы пікірін сұраңыз.'),
  ('0e73fb38-1702-4d44-8a47-bf821e795ce5', 'Қауіпсіз қадамдар 👟', 'Жүгірісі шапшаңдап келеді! Алғашқы нық қадамдары үшін Ұсынылатын өнімдер бөліміндегі ең жақсы ортопедиялық аяқ киім үлгілерін қарап шығыңыз.'),
  ('2606521b-da76-4e40-8b9b-74eaed8f4900', 'Болашаққа мұра 🖼️', 'Бүгін Сізді ерекше күлдірген қылығын Бөпе альбомына қостыңыз ба? Телефон жады толып қалса да, естеліктер әрдайым қауіпсіз сақталсын.'),
  ('67ef78f2-7b35-47be-a6f4-6368c3a37a84', 'Үстел басындағы сынақ ⏱️', 'Үстел басында ұзақ отырып, тамақпен ойнай ма? Тамақтану таймерін қосып, тәбетінің болмау себептерін талдай бастаңыз.'),
  ('d9b69a33-09da-4d7d-98e9-ac3acd553715', 'Ұйқы регрессиясы ма? 🤖', 'Түнде жиі ояна ма? Бұл өсу секірісі ме, жоқ па — Anacan AI сарапшысына жазып, бірден біліңіз.'),
  ('283507fe-ca12-4764-a828-61d9a9f30424', 'Сіз қаһармансыз 💖', 'Сіз мінсіз болуға міндетті емессіз. Көңіл күй күнделігіне жай ғана Мен бәрін еңсере аламын деп жазып, демалыңыз.'),
  ('290e0f59-3a24-4f74-9a01-c478f55efce5', 'Таза ауадағы серуен 🌳', 'Үйдің іші оған тар болып жүр. Анаға қолайлы орындардан кең әрі қауіпсіз саябақ тауып, энергиясын шығаруға көмектесіңіз.'),
  ('d9528425-30f7-4a4a-ac0d-053206658d00', 'Қуатыңыз таусылмасын 🔋', 'Жүгіріп жүріп әбден шаршадыңыз ба? Әйелдерге арналған пайдалы рецептілерден бірден қуат беретін дәмді таңғы ас таңдаңыз.'),
  ('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b', 'Күндізгі ұйқы ⏱️', 'Ұйқы таймерін қосыңыз. Күндізгі ұйқы уақытын нақтылап, кешкі ұйқыға көшуді оңай реттеңіз.'),
  ('1b9ea296-6f6b-4447-9f45-4c6548d5e543', 'Отбасылық дастарқан 🍲', 'Ол енді Сізбен бірдей тағамдарды жей алады. Тамақтануды бақылау құралы арқылы ортақ тағамдарыңыздың тағамдық құндылығын оңай есептеңіз.'),
  ('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0', 'Тыныштандыратын толқындар 🌊', 'Белсенді жаңалықтарға толы күннен кейін ұйықтай алмай жүр ме? Ақ шулардан мұхит толқынының дыбысын таңдап, бөлмеде сиқырлы тыныштық орнатыңыз.'),
  ('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7', 'Ұйқы регрессиясы ма? ⏱️', 'Түнде жиі ояна ма? Ұйқы таймерінің кестесін қараңыз. Күндізгі ұйқысы тым ұзақ болса, оны сәл қысқартатын уақыт келген болуы мүмкін.'),
  ('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9', 'Кальций қоры 🧀', 'Тістер мен сүйектер үшін кальций өте қажет. Тамақтануды бақылау құралы арқылы бүгін сүт өнімдерінің күнделікті мөлшерін тұтынғаныңызды тексеріңіз.'),
  ('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11', 'Күнделікті тепе-теңдік 💧', 'Түсте жөргегін ауыстырғанда, белгілеуді ұмытпаңыз! Бөлінудің жиілігі баланың белсенділігіне байланысты сұйықтық қажеттілігі мен ас қорыту жағдайын көрсетеді.'),
  ('44008632-a96c-4f5e-a936-9b65273a2264', 'Енді кезек Сізде 🥗', 'Бала күндізгі ұйқыға кетті ме? Асүйге барыңыз! Әйелдерге арналған пайдалы рецептілердің бірін таңдап, өзіңізге дәмді ас дайындаңыз.'),
  ('868f8ace-292a-4cf1-9abe-4b2da08aca3f', 'Кофе-брейк ☕', 'Үй шаруасы мен күнделікті күйбең тірлік Сізді шаршатты ма? Анаға жайлы орындардан балалар бұрышы бар кафе табыңыз. Бір шыны ыстық кофе ішуге толық құқығыңыз бар.'),
  ('f7b08a7d-5067-40df-81d3-421be952c00e', 'Мінсіз ана болмайды 💖', 'Бүгін бәрі жоспар бойынша болмаған болса, өзіңізді кінәламаңыз. Көңіл-күй күнделігіне ішкі толғаныстарыңызды жазып, еркін тыныстаңыз.'),
  ('58a79bee-96dd-429b-a570-14dc6d97d91a', 'Тыныштандыратын толқындар 🌊', 'Шамадан тыс әсер алған мидың белсенділігін бәсеңдету қажет. Бөлмеде Ақ шудан мұхит толқындарының дыбысын қосып, оны тыныштандырыңыз.'),
  ('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1', '«Бұл не?» кезеңі 🤖', 'Баланың толассыз сұрақтары мен айналаны зерттеуге деген қызығушылығы Сізді таңғалдыра ма? Танымдық дамудың осы қарқынды кезеңі туралы Anacan AI көмекшімізден ақпарат алыңыз.'),
  ('f8ad5a51-f4c3-4fc4-8170-0775df79fe84', 'Өзі тамақтанғысы келеді 🥣', 'Қасықты қолынан тастамай ма? Тамақтану таймерін қосып, үдерістің ұзақтығын бақылаңыз және Бөпе рецептерінен ұстауға ыңғайлы тағамдарды таңдаңыз.'),
  ('995604f6-97b2-4fe5-91ea-98f2248c1b28', 'Ақуыз қоры 🥚', 'Қимыл-қозғалысы көп бөпенің бұлшықеттері үшін ақуыз өте қажет! Тамақтануды бақылау құралы арқылы оның күнделікті ас мәзірінің теңгерімін бағалап, жетіспейтінін толықтырыңыз.'),
  ('ec6ff433-9523-4a66-a427-b2548807345b', 'Зейін мен есте сақтау 🧠', 'Бөбеңіз қалай үйренеді? Қолданбамыздың Блогтар бөлімінен 1.5 жастан кейінгі зейін мен есте сақтау қабілетінің дамуы туралы мақаланы оқыңыз.'),
  ('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855', 'Күннің соңы 🌙', 'Ұйықтайтын уақыт келді! Ұйқы таймерін қосып, бөпеңіздің күнделікті ұйқы нормасын сақтайтынына көз жеткізу үшін режимін белгілеп отырыңыз да, өзіңіз де демалыңыз.'),
  ('0bcc42e9-f88e-427d-8d6d-562c3e7e7138', 'Брокколи операциясы! 🥦', 'Көкөністерден бас тарта ма? Уайымдамаңыз. Бөпе рецептерінен брокколиді дәмді құймақтардың ішіне қалай жасыруға болатынын біліңіз.'),
  ('2e502c2f-240e-4506-a102-a80013f7742b', 'Өзіңізге мойындаңыз 🛋️', 'Бүгін қатты шаршап, бәрін тастағыңыз келді ме? Бұл қалыпты жағдай! Көңіл күй күнделігін ашып, Маған демалыс керек деп жазыңыз да, осы кешті тек өзіңізге арнаңыз.'),
  ('530196ff-adb2-4ae9-a06d-67bb4bfd998f', 'Құрғақ жөргектер көбейді ме? 🧻', 'Таңертең жөргегін тексеріңіз. Егер ол 2 сағаттан артық құрғақ болып қалса, бұл дәретке үйретуге дайын екенінің алғашқы белгісі болуы мүмкін! Мәліметтерді жөргек трекеріне енгізіп, статистиканы тексеріңіз.'),
  ('057998e1-6566-4f75-aa40-70a38d334aee', 'Ананың су теңгерімі 💧', 'Балаңыздың соңынан жүгіріп жүріп, су ішуді ұмытып кеттіңіз бе? Бас ауруының себебі осы болуы мүмкін. Пайдалы рецепттер бойынша детокс суларын дайындап, күш-қуатыңызды қалпына келтіріңіз.'),
  ('29452fba-ed37-4bde-8e72-45e1f9c46d4d', 'Ұйқыға дейін 10 минут... ⏱️', 'Ұйқы таймерін қосып, бөлмені қараңғылаңыз. Ақ шу ішінен орманның шуылын қосып, ұйқыға кету сәтін бөпеңіз үшін де, өзіңіз үшін де сиқырлы сәтке айналдырыңыз.'),
  ('fa637a9e-0a58-4301-a5dd-89fb27cdb46b', 'Макарон құбыжығы! 🍝', 'Өз бетінше тамақтанып, үсті-басын, тіпті шашын да былғап алды ма? Бұл күлкілі сәтті жіберіп алмаңыз! Бөпе фотосессиясындағы көңілді жиектемелермен безендіріп, альбомға қосыңыз.'),
  ('44418a3d-932e-44e2-832c-c9fdeea34df1', 'Ұру және тістеу? 🛑', 'Бөпеңіз жеткізе алмай жүрген сезімдер кейде агрессияға ұласуы мүмкін. Осы жастағы тістеу және ұру әрекеттеріне қалай дұрыс жауап беру керектігін Anacan AI-дан сұраңыз.'),
  ('4a287257-0f36-49cd-93f7-28a1154386a6', 'Кітапқа деген сүйіспеншілік қалай қалыптасады? 📖', 'Ұйықтар алдында кітап оқисыз ба? Блогтар бөлімінен балаға кітапты жақсы көруге көмектесудің және оның назарын кітап беттерінде ұстап тұрудың алтын ережелерін оқыңыз.'),
  ('f9f77164-bd35-4d6c-83ca-1991fcf7701a', 'Жаңа жаңалықтар, жаңа қауіптер ⚠️', 'Ол енді кез келген жерге өрмелеп шығады! Үйдің қауіпсіздігін арттыру үшін Ұсынылатын өнімдер бөліміндегі жиһаз жиектеріне арналған жұмсақ қорғаныштарды міндетті түрде қарап шығыңыз.'),
  ('66297752-072e-4e90-afa0-bfdfc587176c', 'Темір қоры жеткілікті ме? 🥩', 'Қимыл-қозғалысы көп балақайда қаназдық болмауы және оның сергек жүруі үшін Тамақтануды бақылау құралынан бүгін қанша темір қабылдағанын тексеріп, жетіспеген мөлшерін толықтырыңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('802d0f46-e525-43d0-8f5c-440b82228035'::uuid, 'Құм және жапырақ терапиясы 🍂', 'Үйдің төрт қабырғасынан шығыңыз! Аналарға қолайлы орындардан құм алаңы немесе жасыл желегі мол саябақ тауып, бөпеңіздің сенсорлық дамуына қолдау көрсетіңіз.'),
  ('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618', 'Мінсіз болуға ұмтылысты доғарыңыз ✨', 'Бүгін балаңызға даусыңызды көтеріп қойдыңыз ба? Өзіңізді кінәламаңыз. Көңіл күй күнделігіне ішкі күйзелісіңізді жазып, өзіңізді кешіріңіз және ертеңгі жаңа күнге дайындалыңыз.'),
  ('fec1f9db-8b95-410a-b753-aded5a7dc606', 'Қараңғыдан қорқа ма? 🌌', 'Бөлменің жарығын өшіргенде жылай ма немесе мазасыздана ма? Ақ шу бөлімінен ана құрсағындағы дыбысты (жүрек соғысын) қосып, оған бұрыннан таныс жылулық пен қауіпсіздік сезімін сыйлаңыз.'),
  ('5c635a69-e5ff-42eb-9277-29e39d9986fa', 'Тіс тазалау — көңілді! 🪥', 'Тіс щеткасын аузына жақындатпай ма? Ұсынылатын өнімдер бөлімінен саусаққа киілетін щеткаларды немесе жарығы мен әуені бар үлгілерді қарап, бұл гигиеналық үдерісті ойынға айналдырыңыз.'),
  ('f2a19104-ece3-4a8f-9966-8cad392a68af', 'Түнгі тыныштық 🍵', 'Бала ұйықтады, таймер тоқтады. Енді асығатын емес, демалатын уақыт. Пайдалы рецепттер бөліміндегі түймедақ шайын демдеп, мамыражай тыныштықтан ләззат алыңыз.'),
  ('f524b282-4173-4386-b8dd-255261b77d1d', 'Өзім киінемін! 👕', 'Таңертең киіну үлкен жанжалға айнала ма? Блогтар бөлімінен балаға таңдау мүмкіндігін беру арқылы киіну кезіндегі дағдарысты шешудің тиімді жолдарын оқыңыз.'),
  ('46919051-4727-4a43-8ba3-d5a1f5451c16', 'Дүкенде айғай-шу шығарды ма? 🛒', 'Қоғамдық жерде қалағанын алып бермегеніңіз үшін жерге жата қалып, жылап-шулай ма? Айналадағы адамдардың көзқарасына мән бермеңіз, сол сәтте сабыр сақтау үшін Anacan AI-ға ішіңіздегіні айтып, қолдау алыңыз.'),
  ('874df706-e26e-4b72-a02c-7f8309fc95d5', 'Екі сөзден тұратын сөйлемдер! 🗣️', 'Бүгін «Анашым, кел» немесе «Допты лақтыр» сияқты жаңа сөз тіркесін айтты ма? Тіл дамуындағы осы керемет сәтті бірден дыбысы бар видеоға түсіріп, Бөпе альбомына сақтаңыз.'),
  ('af368cd3-f751-4611-9e47-9c8fda037ebd', 'Саусақ моторикасы іске қосылды! 🧩', 'Бұршақ, жүгері немесе туралған жемістерді өз бетінше жеуіне мүмкіндік беріңіз. Бұл ұсақ моториканы дамытады. Тамақтануды бақылау арқылы порция мөлшерін қадағалаңыз.'),
  ('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323', 'Иммунитетті қолдайық! 🍊', 'Күн райы құбылып тұр ма? Тамақтануды бақылау құралы арқылы бүгін қабылдаған C дәруменінің мөлшерін есептеп, ас мәзіріне цитрус жемістерін, киви немесе түрлі түсті тәтті бұрыш қосыңыз.'),
  ('031932e3-d91b-494c-9f35-dc03d53026b4', 'Аяқ киімі тар болып қалды ма? 👟', 'Соңғы кезде жүгіргенде жиі сүріне ме? Мүмкін, аяғы өсіп кеткен шығар! Салмақ трекеріне аяқ киімінің жаңа өлшемі мен бойын енгізіп, өсу қарқынын талдаңыз.'),
  ('db0a30ff-e18a-4830-abdc-881dc8827a75', 'Миға пайдалы тағам: Омега-3 🐟', 'Ақыл-ойының дамуы үшін балық өте маңызды. Қосымша тағам жей бастаған бөпелерге Рецепттер бөлімінен сүйексіз, пеште пісірілген дәмді балық котлетін дайындаңыз.'),
  ('eb71840a-d8fc-43f9-897d-715c008b72b7', 'Баяулайтын уақыт келді! 🌙', 'Белсенді күн аяқталды. Ұйқы таймерін қосып, жүгіріп-ойнауды тоқтатыңыз да, тыныштандыратын істерге (мысалы, пазл құрастыруға) ауысыңыз.'),
  ('36d9b82f-d63f-40d9-bafa-df3b3dc844b9', '5 минутта дайын дәмді ас! 🥗', 'Түсте жүріп тамақтана саласыз ба? Әйелдерге арналған пайдалы рецепттерден ұзақ уақыт тоқ ұстап, қуат беретін авокадо мен жұмыртқа қосылған тост дайындаңыз.'),
  ('5db92d40-f36e-4671-8f65-a3cb3f1c91ed', 'Ваннадағы физикалық жаңалықтар 🛁', 'Суды бір пластик стақаннан екіншісіне құйған кездегі байсалды әрі зейінді жүзін Бөпе альбомына қосыңыз. Осындай кішкентай жаңалық ашқан сәттер ұмытылмайды!'),
  ('e18f3a19-4a7e-44e4-9703-5c88f6dda037', 'Экран алдында тым көп отыра ма? 📱', 'Телефонды қолынан алу үлкен ашуға ұласа ма? Экран уақытын күйзеліссіз шектеу және дұрыс шекаралар орнату жолдарын Anacan AI-дан біліңіз.'),
  ('2c1e9be8-ccf0-412a-a942-30cea5075e5b', 'Араласатын уақыт келді! 👶', 'Ол енді басқа балалармен бірге болуға ұмтылады. Аналарға қолайлы орындардан балалар ойын орталығы бар орынды тауып, оны қуантыңыз.'),
  ('cb4b4d68-2b36-4d3f-aa77-92d10314464f', 'Жаңа тағам, жаңа реакция 💩', 'Кеше өзгеше немесе аллергия тудыруы мүмкін тағам жеді ме? Таңертең жөргегін ауыстырғанда нәжісін бақылап, түсі мен қоюлығындағы өзгерістерді қолданбаға белгілеп, жағдайын қадағалаңыз.'),
  ('28cf8172-0a76-4afd-b2de-765879c7939a', 'Өзіңізге алғыс айтыңыз! 💖', 'Сіз сондай жанкешті әрі керемет анасыз! Көңіл күй күнделігін ашып, бүгін балаңыз үшін жасаған ең кішкентай жақсылығыңызды да жазып қойыңыз және өзіңізді мақтан тұтыңыз.'),
  ('f00a5e44-ed12-4c77-9249-e4246b2b108d', 'Түбекпен алғашқы танысу 🚽', 'Әлі ерте болса да, түбекті жуынатын бөлмеде ұстау баланың оған көзбен үйренуіне көмектеседі. Ұсынылатын өнімдерден оның назарын аударатын ыңғайлы әрі қызықты үлгілерді қараңыз.'),
  ('6d72635f-ba12-4c8b-b7ef-f626dd634dce', 'Таңғы сергектіктің жөні бөлек! ⚡', 'Сұлы ботқасын жемей ме? Бөпелерге арналған рецептілерден жеміс пен жержаңғақ пастасы қосылған смузи тауып, Тамақтануды бақылау құралындағы калория мақсатына оңай жетіңіз.'),
  ('9867089b-80a4-4895-985d-1e1d5fa3df95', 'Көзіңіз ілініп бара ма? 😴', 'Бала ұйықтағанда, Сіз де жатып демалыңыз. Ұйықтай алмасаңыз, Әйелдерге арналған пайдалы рецептілерден антиоксиданттарға бай көк шай дайындап, сергіп алыңыз.'),
  ('a5fedf21-2dca-46ed-9476-0b415ced68a5', 'Ұйықтағысы келмей ме? 🛌', '19-ай ұйқыдағы өзгерістерімен белгілі. Ұйқы таймерін қосып, кестені тексеріңіз — бәлкім, күндізгі ұйқыны қысқартатын уақыт келген шығар!'),
  ('39db43fc-07a0-417e-90da-c0bbbd5f14a4', 'Іші ауырып жүр ме? 💩', 'Таңертең жөргегін ауыстырғанда, үлкен дәреті туралы деректерді енгізіңіз. Іш қату қаупі болса, Anacan AI-дан шұғыл көмектесетін табиғи тәсілдер мен массаж әдістерін сұрап, қолданып көріңіз.'),
  ('613cd9e2-958a-41bd-b191-0de3ff8ec07f', '«Жоқ» дегенді қанша рет естідіңіз? 🙉', 'Қырсық кішкентаймен тіл табысу үшін көп шыдам қажет. Ішкі күйзелісіңізді Көңіл күй күнделігіне жазып, өзіңізді кінәламай, сезімдеріңізді сыртқа шығарыңыз.'),
  ('e893b0aa-e3fc-4f78-a970-b681a0ed0450', 'Өрмелеуден чемпион! 🧗', 'Үйдегі жиһаздар аздық ете ме? Анаға қолайлы орындардан жұмсақ кедергілер жолағы бар жабық ойын-сауық орталығын тауып, оның өрмелеуге деген құштарлығын қауіпсіз түрде қанағаттандырыңыз.'),
  ('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee', 'Кішкентай сәнгер іске кірісті! 👗', 'Киімін өзі таңдағысы келіп, үйлеспейтін түстерді киіп жүр ме? Осы күлкілі киім үйлесімін Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, альбомдағы ең қызықты кадрға айналдырыңыз.'),
  ('f830cd97-a8bb-4789-bdc5-7806bcd89cfe', 'Шамадан тыс сергектік 🎇', 'Күндіз өте белсенді болған ми түнде баяулай алмайды. Ақ шу бөлімінен шаш кептіргіштің немесе желдеткіштің дыбысын қосып, бірсарынды дыбыстың бөпеңізді қалай тыныштандыратынын бақылаңыз.'),
  ('f8565841-4602-47d5-af45-99f7dea5b129', 'Солақай ма, әлде оңқай ма? 🤚', 'Қасықты қай қолымен ұстайды? Жетекші қолдың қалай және қашан қалыптасатыны туралы Блогтар бөліміндегі жаңа ғылыми мақаламызды міндетті түрде оқып шығыңыз.'),
  ('1915583e-53f5-46af-8212-835dfd587e22', 'Шашыңыз әлі де түсіп жүр ме? 💇‍♀️', 'Ағзаңыз әлі де қалпына келу кезеңінде. Әйелдерге арналған пайдалы рецептілерден мырыш пен биотинге бай таңғы ас мәзірін таңдап, бүгін өзіңізге қамқорлық жасаңыз.'),
  ('cfbeabf3-def0-4cbe-a106-fd34987dd776', 'Музыкалық аспаптар кезеңі 🥁', 'Ағаш қасықтармен кәстрөлдерді соққылағанды ұната ма? Ұсынылатын өнімдер бөлімінен дыбыс деңгейі баланың құлағына қауіпсіз ксилофондар мен барабандарды қараңыз.'),
  ('daa6a0d6-25d4-401e-ba81-8a8ca5108695', 'Жануарлардың алғашқы дыбыстары 🐮', 'Итті немесе мысықты көргенде олардың дыбысын салуға тырыса ма? Танымдық дамудағы осы тамаша жетістігін қысқа бейне түрінде Бөпе альбомына қосып, естелікке сақтаңыз.'),
  ('2ed7fd17-90ba-451d-9c88-a1f94a180fe0', 'Тәбеті төмендеді, ал салмағы ше? 📉', 'Бұл айларда тамақ талғау жиілейді. Салмақ бақылау бөліміне қазіргі көрсеткіштерді енгізіп, дамуының шын мәнінде қалыпты жүріп жатқанын көріп, бірден көңіліңізді жайландырыңыз.'),
  ('50209dd4-d2d7-4719-bf4e-21df8c72686a', 'Ұйқыға дайындық рәсімдері 🧸', 'Күн сайын кешке бірдей реттілік сақтаңыз! Ұйқы таймерін қосып, сүйікті қонжығына «Қайырлы түн» айтқызыңыз және осы тұрақтылықтың ұйықтап кетуді қалай жеңілдететінін бақылаңыз.'),
  ('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf', 'Бөлісе алмау мәселесі 🧸', 'Саябақта басқа балалардың ойыншығына қарай жүгіріп, ал өзінікін бермей ме? Anacan AI-дан 1.5 жастағы балаларға кезекпен ойнауды қалай үйретуге болатынын біліңіз.'),
  ('ca671510-91c4-4377-9f69-b4bd47b292a2', 'Бір кесе үзіліс ☕', 'Қуатыңыз қалай? Үй шаруасын бір сәтке тоқтатыңыз. Әйелдерге арналған пайдалы рецептілерден қуат беретін жержаңғақ пастасы қосылған кекс дайындап, кофе ішіп отырып тыныштықтан ләззат алыңыз.'),
  ('38141003-a43c-4589-a477-21da541a08db', 'Кинетикалық құмның сиқыры 🏖️', 'Үйде кішкентай жағажай жасайық па? Саусақ бұлшықеттерін нығайтатын әрі оңай тазаланатын кинетикалық құм жиынтықтарын Ұсынылатын өнімдер бөлімінен қараңыз.'),
  ('75f9f2e1-a04a-4711-9125-3d8c610326d9', 'Өз денесін танып жүр! 👃', '«Мұрның қайда?» деп сұрағанда, мақтанышпен көрсете ме? Бөпе фотосессиясы үшін бөлмеде шағын түсірілім ұйымдастырып, сол сүйкімді сәтті бірден альбомға сақтаңыз.'),
  ('ae036003-f237-47e6-8031-7feeb47126cc', 'Тойғанын қалай білеміз? ⏱️', 'Тамақты лақтырып немесе түкіріп бастаса, бұл оның тойғанын білдіреді. Тамақтану таймерін тоқтатып, қажетті мөлшердің желінгенін белгілеңіз де, тәбетін талдаңыз.'),
  ('05bc3cfd-c566-4963-b6b2-87889d369e27', 'Сізге де орта қажет 💬', 'Басқа аналармен араласу Сізге де жақсы әсер етеді! Аналарға қолайлы орындар арасынан ойын топтары бар орталықты таңдап, екеуіңізге де жаңа орта сыйлаңыз.'),
  ('5b6366a9-6eb4-4593-8335-c41fd3447da1', 'Бүгінгі жеңісіңіз қандай? 🏆', 'Бөпеңізді жыламай ұйықтату ма? Әлде бір тостаған тамақты толық жегізу ме? Тіпті ең кішкентай жетістігіңізді де Көңіл күй күнделігіне жазып, өзіңізді тік тұрып қошеметтеңіз.'),
  ('98a39354-24f3-4f3c-9cfb-1e084764a56b', 'Өсу аяқкиімнен басталады 📏', 'Аяқкиімін кигісі келмеуі оның тар болып қалғанынан шығар! Өлшем кестесін Салмақ бақылау құралынан тексеріп, дене дамуын қадағалаңыз.'),
  ('cc01349a-6eef-4c61-aa08-b3f505c2eb5f', '«Өзім жеймін!» шайқасы 🥣', 'Өзіне берсеңіз, тамақты жан-жаққа шашады, бермесеңіз, айқайлайды. Бұл дағдарысты күйзеліссіз қалай еңсеруге болатынын Anacan AI-дың психологиялық кеңестері арқылы дәл қазір біліңіз.'),
  ('3abde512-ebd4-4cf1-986e-fb1953695f78', 'Түрлі түсті иммунитет қалқаны 🛡️', 'Тамақтануды бақылау құралы арқылы бүгін оның С дәруменін жеткілікті мөлшерде алғанын тексеріңіз. Қызғылт сары және қызыл көкөністерден тағам әзірлеу үшін Бөпе рецепттерін қараңыз.'),
  ('56129e04-2f90-42b1-b51e-b835940e284e', 'Ой жүгінен арылыңыз 🧘‍♀️', 'Мынаны да істеуім керек, ананы да пісіруім керек деп миыңыз бір сәтке де тынышталмай жүр ме? Барлық жоспарыңыз бен қорқынышыңызды Көңіл күй күнделігіне жазыңыз. Тізім жасау күйзелісті бірден азайтады.'),
  ('deb6cbd4-3a89-4915-9bdf-626d87829918', 'Су мен балшыққа деген сүйіспеншілік 💦', 'Киімін былғап алады деп алаңдамаңыз! Анаға жайлы орындардан ашық аспан астындағы орынды тауып, оның табиғатпен етене араласып, сенсорлық дамуына барынша серпін алуына мүмкіндік беріңіз.'),
  ('1576f605-27d8-4159-b3bd-3dd9e63c91dd', 'Сұйықтық мол болса, ас қорыту жеңілдейді 💧', 'Қою тағамға толық көшу кейде ас қорытуды қиындатады. Жөргек трекеріне жазба енгізу арқылы су ішу мөлшерін арттыру қажет пе, жоқ па, оңай анықтаңыз.'),
  ('93141c59-a17f-414d-9f6c-c865a0650eeb', 'Көлеңке театры басталады! 🐰', 'Бөлменің жарығын өшіріп, қолшаммен қабырғаға көлеңкелі бейнелер түсіріңіз. Оның бұл сиқырға таңдана қараған сүйкімді жүзін Бөпе альбомы үшін міндетті түрде видеоға түсіріп алыңыз.'),
  ('a14c30d1-ff1f-46da-8b1e-98116e38ee0d', 'Парақтарды жыртқысы келе ме? 📖', 'Кітаптарды оқудың орнына жыртқысы келе ме? Осы жаста қатырма қағаздан жасалған және сипап сезуге арналған кітаптардың маңызы туралы Блогтар бөліміндегі жаңа кеңестерді оқыңыз.'),
  ('8e7d531f-d445-43eb-a4d5-05ffff377c4f', 'Дыбыстан тыныштыққа 🎶', 'Теледидардың немесе ойыншықтардың дыбысынан кенет тыныштыққа ауысу балаларды қорқытуы мүмкін. Бөлмеде Ақ шу бөлімінен пойыз дыбысын қосып, ұйқыға жайлы әрі біртіндеп ауысуға жағдай жасаңыз.'),
  ('69c1e419-f8f2-4b2f-90e3-9b51e78ff197', 'Таймер тоқтады, енді демалыңыз 🍵', 'Ұйқы таймерін тоқтатып, бөлмеден шықтыңыз. Енді үй шаруасына кіріспеңіз! Өзіңізге түймедақ шайын демдеп, күннің шаршауын ыстық бумен бірге шығарып жіберіңіз.'),
  ('934796d5-42af-4c49-9cb9-67f18b657e36', 'Тісі қышып жүр ме? 🦷', 'Соңғы азу тістері шығып келе жатқан болуы мүмкін. Қызыл иектің қышуын басу үшін Бөпе рецептерінен салқын, қантсыз әрі пайдалы жеміс мұздағын (popsicles) дайындаңыз.'),
  ('06d75280-127a-43d4-a7f0-42d2871b24c5', 'Кішкентай аспаз! 👨‍🍳', 'Қасықты Сізге бергісі келмей ме? Бөпе рецептерінен қолмен ұстауға ыңғайлы котлеттер дайындаңыз. Тамақтану таймері арқылы өздігінен қанша уақыт тамақтанатынын талдап, тәбетін бақылаңыз.'),
  ('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb', 'Күлкілі бет-әлпет 🤪', 'Айна алдында бет-аузын қисайтып жүр ме? Осы көңілді сәтті жіберіп алмаңыз! Бөпе фотосессиясындағы күлкілі стикерлермен безендіріп, альбомдағы ең көңілді кадрға айналдырыңыз.'),
  ('739af07d-8466-4c3f-a164-5e408385ca93', 'Кез келген жерге өрмелей ме? 🧗‍♀️', 'Диван, үстел, шкаф... Ол нағыз альпинист! Блогтар бөлімінен қауіпті болғанымен, дамуы үшін маңызды осы қимыл-қозғалыс қажеттілігін үйде қалай қауіпсіз қамтамасыз етуге болатынын оқыңыз.'),
  ('8ac7016a-7613-48aa-a952-59cc5f8a6354', 'Шалбарының балағы қысқарып қалды ма? 👖', 'Бойының күрт өсу кезеңі қызу жүріп жатыр! Салмақ бақылағышына қазіргі бойы мен салмағын енгізіп, даму графигінің қалай жоғарылағанын мақтанышпен тамашалаңыз.'),
  ('db467018-0ec9-41a9-a3a3-3ef1c48cda53', 'Дамытушы ойыншық іздеп жүрсіз бе? 🧩', 'Тек дыбыс шығаратын емес, ойландыратын ойыншықтар қажет. Ұсынылатын өнімдер бөлімінен 1.5 жастан асқан балаларға арналған логикалық және пішіндерді сәйкестендіру басқатырғыштарын (puzzle) міндетті түрде қарап шығыңыз.'),
  ('df8f7402-1277-45bd-a743-5c24bdaf48e1', 'Ашуланғанда тістей ме? 🦖', 'Ашуланғанда ұрып немесе тістеп жібере ме? Бұл — сөзбен жеткізе алмайтын сезімдерінің көрінісі. Anacan AI-дан бұл мінез-құлықты жұмсақ түрде қалай өзгертуге болатынын біліңіз.'),
  ('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1', 'Шаш пен теріге арналған 🥑', 'Күнделікті күйбеңнен шаршаған денеңізге күтім жасаңыз. Әйелдерге арналған пайдалы рецептілердің ішінен антиоксиданттарға бай авокадо мен жаңғақ қосылған жастық салатын дайындаңыз.'),
  ('a832a387-bccf-4a1a-823c-3930e73e4c07', 'Су бер, ана кел 🗣️', 'Бөпеңіз екі сөзді біріктіріп, қысқа сөйлемдер құрауға талпынып жүр ме? Бұл — тіл дамуындағы керемет серпіліс! Оның әрбір талпынысын қолдап, сөйлесуге ынталандырыңыз.'),
  ('d1f9f7f1-6831-4583-9dbd-fab805703b8d', 'Таусылмайтын қуат 🔋', 'Жүгіруден шаршамай ма? Ұйқы таймерін қосып, бөлмедегі жарықты бәсеңдетіңіз. Ақ шудан орманның сыбдырын қосып, оны біртіндеп ұйқыға дайындаңыз.'),
  ('34104368-1e25-46df-8c68-910d16cd40b1', 'Ас қорытуы қалай? 🚽', 'Іш қату мәселесі бар ма? Таңертең жөргегін ауыстырған кезде белгілеп қойыңыз және Тамақтануды бақылау құралы арқылы мәзіріне талшыққа бай тағамдарды (алмұрт, сұлы) міндетті түрде қосыңыз.'),
  ('79b083b6-1c72-4250-a120-ca8846206ce5', 'Өзіңізді қалай сезініп жүрсіз? 🧘‍♀️', 'Бүгін «болмайды!» дегенді тым көп айттыңыз ба? Өзіңізді кінәламаңыз. Көңіл күй күнделігіне ішкі ойларыңызды жазып, ана ретінде қаншалықты жанкешті екеніңізді еске түсіріңіз.'),
  ('bfb35c45-0163-48f3-be24-eff4697cb9e8', 'Табиғат өнерпаздары 🍂', 'Жапырақтар, тастар мен бұтақтар — ең жақсы ойыншықтар! Анаға қолайлы орындардан жасыл желегі мол саябақты тауып, ашық аспан астында нағыз зерттеуге аттаныңыз.'),
  ('01861a89-1cc1-4443-8c58-c79d90402305', 'Дүкендегі дағдарыс 🛒', 'Дүкенде қалағанын алып бермегеніңіз үшін жерге жатып алды ма? Абыржымаңыз. Айналадағылардың көзқарасына мән бермей, сабырмен оның көз деңгейіне дейін еңкейіңіз.'),
  ('32e724db-ca0f-4d6b-9d07-716443a9dcdd', 'Эмоциялық жүкті жеңілдетіңіз 📝', 'Күніңіз қиын өтті ме? Бүгінгі күйзелісті Көңіл күй күнделігіне жазып, ішіңіздегіні шығарыңыз. Барлық ана осындай кезеңдерден өтеді, Сіз жалғыз емессіз.'),
  ('a0570819-b575-49b5-bbf4-bc21cf5fc939', 'Қос аяқпен секіру 🦘', 'Бір орында тұрып, екі аяғымен бір мезетте секіруге тырыса ма? Өте күлкілі көрінеді, солай емес пе? Бұл сәтті міндетті түрде Бөпе фотосессиясы арқылы мәңгі есте қалдырыңыз.'),
  ('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d', 'Ұйықтағысы келмей ме? 🥱', 'Күндіз ұйықтағысы келмей, қарсылық көрсете ме? Anacan AI-дан 20 айлық балалардың сергектік аралықтары туралы нақты ақпарат пен күн тәртібін сұраңыз.'),
  ('2edb626b-eafe-49c0-a743-e6dae9f9eddd', 'Әуен сыйлаған тыныштық 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — оның сүйікті әуенін қосып, құшақтап, бірге баяу билеу.'),
  ('b174df30-8e63-488e-ae9b-4d227f3136f1', 'Анаға арналған ас 🥑', 'Оны тойдыру үшін қолыңыздан келгеннің бәрін жасайсыз. Ал өзіңіз ше? Пайдалы рецепттердің ішінен Сізге күш беретін, темірге бай түскі асты таңдап, асықпай отырып тамақтаныңыз.'),
  ('5d951093-5ada-49f6-9750-d303bcf8d918', 'Үлкен азу тістері ме? 🦷', 'Еш себепсіз бәрін кеміріп, жылай бере ме? Ең артқы азу тістері шығып келе жатқан болуы мүмкін. Тіс шығуын бақылау бөлімінде үдерісті белгілеп, салқын тіс қаситын ойыншықтарды дайындаңыз.'),
  ('9fe66081-4fad-49c8-891d-2ca85484f87d', 'Ертегі кейіпкері 🪄', 'Бүгін кешке Ақылды ертегілерде өз балаңыз басты кейіпкер болатын ерекше хикая құрыңыз: тісін тазалағанды жақсы көретін батыл балақай.'),
  ('c638741f-2af1-4bf3-a4de-09ffcb406144', 'Серуенге батыл шығыңыз ⛅', 'Ауа райы құбылмалы деп үйде қалып қойдыңыз ба? Ауа райы және киім құралы терезеден байқалмайтын желдің жылдамдығын және лайықты киім үйлесімін бірден көрсетсін — саябаққа батыл шығыңыз.'),
  ('3d75b744-8440-4e62-83c6-4a08b865c0f7', 'Йогурт маскасы! 🥣', 'Тамақты беті мен шашына жағып алды ма? Ашуланудың орнына, осы ғажайып өнер туындысын Бөпе альбомына қосып, көңілді стикерлер жапсыру арқылы есте қалдырыңыз.'),
  ('45af46ac-18bf-499b-a5c7-56bbe71e4564', 'Тыныштыққа көшетін уақыт 🎶', 'Күні бойы тыным таппаған кішкентай аяқтардың демалатын уақыты келді. Ақ шу бөлімінен автокөлік салонының дыбысын қосып, бірқалыпты әуенмен ұйқыға қолайлы тамаша орта жасаңыз.'),
  ('47b68bdb-a1fd-4da7-9316-dcca5fdae94f', 'Сізге де достар керек 👯‍♀️', 'Бөпеңіз саябақта ойнап жүргенде, Сіз де басқа аналармен әңгімелескіңіз келе ме? Аналарға қолайлы орындардан ойын топтары бар орталықтарды тауып, жаңа адамдармен танысыңыз.'),
  ('49af58d4-c188-43d7-a0b2-43f4cd255337', 'Таңертең бір кофе аздық етеді! ☕', 'Күнді ашқарынға кофе ішуден бастасаңыз, қуатыңыз тез таусылады. Әйелдерге арналған пайдалы рецептілерден 5 минутта дайын болатын қуат беретін сұлы кексін таңдаңыз.'),
  ('869af623-de96-421f-808b-d64172a8f765', 'Сізге жарайсыз дегіміз келеді! 👏', 'Бүгін үйіңіз жиналмай қалды ма? Оған мүлде алаңдамаңыз! Бөпеңізбен бірге өткізген күлкіге толы сәттер әлдеқайда құнды. Көңіл күй күнделігінде өзіңізді міндетті түрде мақтаңыз.'),
  ('aaf473f6-79bc-44cf-97f4-687dfa4eb293', 'Су ішкенді ұнатпай ма? 💧', 'Таңертең жөргегі тым құрғақ болды ма? Сұйықтықты көбірек беру қажет. Мұны жөргек бақылау құралына белгілеп, қолданбадан жеміс қосылған су рецептілері мен түрлі су ішетін ыдыс үлгілерін қараңыз.'),
  ('ff614b36-4091-473e-b7fa-91411bd4e2a9', 'Сүйектері нығайып келеді! 🦴', 'Тамақтануды бақылау құралы арқылы бүгін жеткілікті мөлшерде кальций мен D дәруменін алғанын есептеңіз. Қарқынды дене дамуы үшін бұл екі элемент бір-бірінен ажырамайды.'),
  ('348430a9-4730-49e1-90ac-91076b5c5d7c', 'Түстерді ажыратайық! 🔴🔵', 'Қызыл ойыншықтарды бір жаққа, көк ойыншықтарды екінші жаққа қойыңыз. Блогтар бөлімінен 19.5 айлық балалардың зейіні мен логикасын дамытатын үй ойындары туралы оқып, оларды бірге ойнаңыз.'),
  ('907f2a4d-a45c-43e1-8024-d6c91a18d072', 'Дүкенде қатты айқайлады ма? 🛒', 'Қоғамдық орында жерге жатып алып жылады ма? Өзгелердің көзқарасына мән бермеңіз. Мұндай ашу ұстамаларын сабырмен басқару үшін Anacan AI-мен ой бөлісіп, тиімді әдістерді үйреніңіз.'),
  ('0bde6683-6d18-4d98-bc39-b122396c0b17', 'Енді демалатын уақыт келді 🍵', 'Қарбалас аяқталды! Пайдалы рецепттердің бірімен сусын дайындап, диванға жайғасып, тыныштықтан ләззат алыңыз.'),
  ('0eecf770-9ba2-463c-9b39-bbe24d01b4e1', '«Менікі!» деген айқайлар 🧸', 'Саябақта басқа баланың ойыншығын тартып ала ма? Осы жасқа тән эгоцентризм дағдарысын басқаруға көмектесетін ең тиімді психологиялық тәсілдерді Anacan AI-дан біліңіз.'),
  ('0a81bd63-014b-4d25-b347-1808455aea49', 'Төрт қабырғадан қашу 🏃‍♀️', 'Үйде жиналған энергияны шығару қиын. Анаға қолайлы орындардан Сіз кофе іше алатын, ал бөпеңіз емін-еркін жүгіретін қауіпсіз ойын орталығын табыңыз.'),
  ('657f4585-c7bb-41c0-9574-51e8f943398b', 'Шашылып жатса да, өзі жесін! 🥣', 'Тамақты өзі жеуге қ insist ете ме? Тамақтану таймерін қосып, үдерістің ұзақтығын бақылаңыз және бұл дербестіктің оның ұсақ моторикасына қалай көмектесетінін жазып қойыңыз.'),
  ('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4', 'Түнде қайта ояна бастады ма? ⏱️', 'Бұл 20 айлық кезеңдегі ұйқы регрессиясы болуы мүмкін. Ұйқы таймерінің кестесін қарап, күндізгі ұйқыны 15 минутқа қысқартатын уақыт келген-келмегенін тексеріңіз.'),
  ('385a8205-8e28-4c23-94fa-a2a8fe32e28c', 'Өзіңізді кінәламаңыз 📝', 'Бүгін даусыңызды сәл көтеріп қойдыңыз ба? Өзіңізді жазғырмаңыз. Ішіңіздегі мазасыз ойларды Көңіл күй күнделігіне жазып, бөпеңіз үшін Сізден артық ана жоқ екенін есіңізге түсіріңіз.'),
  ('49b18c8f-b30b-4368-9445-6af88b1d8115', '2 сөзден тұратын сөйлемдер! 🗣️', '«Анашым, кел», «Допты бер» – сөздік қоры жылдам өсіп келеді. Осындай сүйкімді сөйлеу талпыныстарын дыбысы бар видео түрінде бірден Бөпе альбомына қосып, мәңгілік естелікке айналдырыңыз.'),
  ('5d516faa-7c77-4db9-b201-49bff969e3d8', 'Сүйектерге арналған кальций 🦴', 'Көп жүгіретін балақайдың сүйектері мықты болуы керек. Тамақтануды бақылау құралынан бүгінгі кальцийдің (ірімшік, йогурт) мөлшерін тексеріп, күндік норманы толықтырыңыз.'),
  ('e6ec7f70-00dc-438b-af17-5f764a9d8216', 'Күндізгі ұйқы қысқарып жатыр ма? ⏱️', 'Түскі ұйқыға жатқысы келмей ме? Ұйқы таймерінің статистикасын бақылаңыз. Бәлкім, бір реттік күндізгі ұйқы режиміне толық көшіп, кешкі ұйқы уақытын ертерек белгілеу керек шығар.'),
  ('46ef9700-c667-4312-ac63-98bd03625249', 'Аяқкиімге қатысты қырсықтық 👟', 'Далаға шығарда жаздың күні міндетті түрде қысқы аяқкиімін кигісі келе ме? Кейде өзіне таңдау жасауға мүмкіндік беріңіз — бұл оның ерік-жігерін нығайтады.'),
  ('5541587a-ad73-4e1d-9174-d4fe1c028c3e', 'Ұйықтауға қарсылық білдіре ме? 🛌', 'Ойын ұйқыдан қызығырақ болғандықтан, төсегіне барғысы келмейді! Ұйқы таймерін қосып, «Ақ шу» бөліміндегі мұхит толқындарының дыбысымен миын біртіндеп тыныштандырыңыз.'),
  ('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'Дәретханаға қызығушылық таныта бастады ма? 🚽', 'Сізбен бірге жуынатын бөлмеге барғысы келе ме? Бұл — көзбен көріп үйренуге дайындық белгісі. Блогтар бөлімінен түбекке үйретуді қашан және қалай бастау керектігін оқып, алдын ала дайындалыңыз.'),
  ('3b603489-95c3-4a32-b0e0-5191fc844b75', 'Өздігінен киінуге талпыныс 👕', '«Бұл жейдені кигім келмейді!» деп қырсыға бастады ма? Таңертеңгі киіну кезіндегі қиындықтарды азайту және оған өз бетінше таңдау құқығын беру жолдарын Anacan AI-дан сұраңыз.'),
  ('89933e6a-484e-4f2e-bf20-8262f6a74c72', 'Омега-3 қоры 🐟', 'Мидың дамуы жалғасып жатыр. Тамақтануды бақылау құралынан осы аптада балық немесе жаңғақ жеткілікті мөлшерде жегенін тексеріңіз, ал жеткіліксіз болса, міндетті түрде белгілеп қойыңыз.'),
  ('fa46cf0a-85f0-484c-8aa5-b60eb52b320b', 'Үйде артық энергияны қалай жұмсаймыз? 🏃‍♂️', 'Далаға шыға алмай жүрсіз бе? «Ұсынылатын өнімдер» бөлімінен үй ішінде пайдалануға арналған шағын батут немесе сырғанақтарды қарап, оның энергиясын пайдалы арнаға бағыттаңыз.'),
  ('00691751-d785-4fc6-8036-d313adccdad6', 'Таңғы тексеріс 🧻', 'Құрғақ жөргектер көбейді ме, әлде ас қорытуы баяулады ма? Таңертең жөргекті ауыстырғаныңызды жөргек трекеріне белгілеп, бөпеңіздің сұйықтық пен тағамдық талшыққа қажеттілігін дереу талдаңыз.'),
  ('9a0a29d7-d513-4158-b204-99c831639c23', 'Бірге, бірақ бөлек 👶', 'Саябақта балалармен ойнамай, тек сырттай бақылап жүр ме? Бұл — қатар ойнау кезеңі! Anacan AI-дан әлеуметтенудің осы кезеңі туралы қызықты деректер сұраңыз.'),
  ('f527de5c-afa8-4884-a173-da37070a2826', 'Кішкентай үй көмекшісі 🧹', 'Сіз үйді сыпырып жатқанда, ол да шүберекпен үстелді сүрте ме? Осы сүйкімді жауапкершілік сәтін бірден түсіріп, Бөпе альбомындағы ең мақтанышты кадрлардың біріне айналдырыңыз.'),
  ('18518788-d8e2-4971-93f7-6fbf0592ca33', 'Ұру немесе итеру 🛑', 'Ашуланғанда кенеттен қол көтере ме? 20-айға тән бұл мінез-құлықты ойын арқылы қалай түзетуге болатынын білу үшін Anacan AI-ға жүгініңіз.'),
  ('a6200253-33e2-4142-a4a9-811aa67d4feb', 'Бүгінгі күннің қаһарманы — Сіз 🧘‍♀️', 'Бала ұйықтап қалды. Үй шаруасының бәрін тоқтатыңыз. Көңіл күй күнделігіне сезімдеріңізді жазып, жайлы музыка қосыңыз да, осы кешті тек өзіңізге арнаңыз.'),
  ('eefd67fd-3835-4f65-abf3-9ced6b705e30', 'Ас үстіндегі шыдам сынағы ⏱️', 'Бір қасық тамақты 5 минутта жей ме? Тамақтану таймерін қосып, шыдамды болыңыз және тәбетінің өзгерісін қолданбадағы есеп арқылы нақты талдаңыз.'),
  ('070b2f75-0440-4e85-b828-292900301f9e', 'Қиялға толы ойындар басталды 🧸', 'Қонжығына су беріп немесе Сізді емдеп жүр ме? Эмпатияға толы осы керемет сәттерді дыбысы бар бейне түрінде Бөпе альбомына қосып, болашаққа сақтап қойыңыз.'),
  ('388f83f4-0bb5-4306-abf6-b75f9dc65017', 'Темір қорының жеткіліктілігін тексеру 🥩', 'Бұлшықеттері белсенді қимылдап, дені сау болып дамуы үшін қаназдық болмауы керек. Тамақтануды бақылау құралы арқылы бүгін қанша темір (ет, бұршақ тұқымдастар) қабылдағанын тексеріп, жетіспеген мөлшерін дереу толықтырыңыз.'),
  ('9cb7efe6-c6c0-4032-89de-12eeec5119ee', 'Дыбыстан тыныштыққа ауысу 🎶', 'Теледидар мен ойыншықтардың дыбысынан кейін орнаған кенет тыныштық оны қорқытады. Бөлмеде Ақ шу бөлімінен феннің дыбысын қосып, бірқалыпты дыбыстың ұйқы ортасына қалай оң әсер ететінін байқаңыз.'),
  ('80e71246-05ae-4bc6-857d-5ce3af704b5e', 'Ананың қуат көзі 🥗', 'Жүгіріп жүріп әбден шаршадыңыз ба? Тәттіге емес, ақуызға көңіл бөліңіз! Әйелдерге арналған пайдалы рецептілерден бірден қуат беретін жержаңғақ пастасы қосылған смузи дайындаңыз.'),
  ('145211fa-74d2-4e28-8a64-c14921db5185', 'Өзіңізді мақтаңыз! 🌟', 'Бүгін оны жылатпай тамақтандыра алдыңыз ба? Көңіл күй күнделігіне ең кішкентай жетістігіңізді де жазып, аналық шеберлігіңізге тік тұрып қол соғыңыз.'),
  ('4f60f5e8-df5e-4892-aa2e-dcffda8f877b', 'Су теңгерімі өте маңызды 💧', 'Белсенді жүгіріп-ойнау ағзаны сусыздандырады. Жөргек трекеріне таңғы көрсеткішті енгізіп, Ұсынылатын өнімдерден бөпеңіз өзі оңай аша алатын спорттық су бөтелкелерін қараңыз.'),
  ('edd993f1-ac76-4300-8ed0-6009d7897f2b', 'Басқа аналармен әңгімелесу ☕', 'Тек баламен сөйлесуден шаршадыңыз ба? Анаға қолайлы орындардан аналар жиі жиналатын балалар кафесін тауып, өзіңізге де араласуға мүмкіндік сыйлаңыз.'),
  ('6f516c4d-5db5-4d3e-8fca-8c461e614752', 'Темір қоры жеткілікті ме? 🥩', 'Қимыл-қозғалысы көп балаңызда қаназдық болмауы үшін Тамақтануды бақылау құралынан бүгін қанша темір (ет, бұршақ тұқымдастар) қабылдағанын тексеріп, мәзірін реттеңіз.'),
  ('b003834c-8ce3-4da4-a17e-0b837c04f7f7', 'Кальций қорын тексерейік 🧀', 'Жылдам өсіп жатқан сүйектерге кальций қажет! Тамақтануды бақылау құралы арқылы бүгінгі ірімшік пен йогурт мөлшерін тексеріп, жетіспегенін толықтырыңыз.'),
  ('b5cae897-2c37-4223-8c5a-201bd9d0229a', 'Орманның жұмбақ дыбыстары 🍃', 'Бүгін шу мен мазасыздыққа толы күн болды ма? Ақ шу бөлімінен жапырақ сыбдырын қосып, бөпеңіздің де, өзіңіздің де жүйке жүйеңізді тынықтырыңыз.'),
  ('20cf6725-2fdc-45bb-965b-09069424fe0a', 'Қантсыз тіскебасар 🍪', 'Дүкен печеньесін алудың қажеті жоқ. Бөпелерге арналған рецептілерден үйде 10 минутта дайындалатын құрма мен сұлы қосылған пайдалы тәттілерді табыңыз.'),
  ('ad033330-a436-4b30-84e7-2df370198c16', 'Дамытушы ойыншық іздеп жүрсіз бе? 🧩', 'Пішіндерді сәйкес тесіктерге салғанды ұната ма? Ойлау қабілетін одан әрі дамытатын, жасына сай ағаш пазлдарды Ұсынылатын өнімдер бөлімінен табыңыз.'),
  ('d22a5573-d857-4918-90d2-9def6a084f6f', 'Миды тынықтыру өнері 🎶', 'Күні бойы шамадан тыс әсер алған бала түнде ұйықтай алмайды. Бөлмені қараңғылап, Ақ шу бөлімінен мұхит толқынының дыбысын қосып, оны біртіндеп терең ұйқыға дайындаңыз.'),
  ('fb035079-cf24-4146-9049-8d721e68f53f', 'Бояуға малынған кішкентай суретші! 🎨', 'Сурет салып отырып, үсті-басын бояп тастады ма? Ашуланудың орнына, осы көңілді сәтті Бөпе фотосессиясындағы қызықты стикерлермен безендіріп, альбомға жүктеңіз.'),
  ('0b2c56b1-a7a8-4553-8880-13254eeb155b', 'Киімдері кішірейіп қалды ма? 📏', 'Шалбарының балағы қысқарып қалса, бөпеңіз күрт өсіп жатыр! Салмақ трекеріне қазіргі өлшемдерін енгізіп, даму графигінің жоғарылағанын мақтанышпен бақылаңыз.'),
  ('9f2ceaa6-0d99-46a0-884c-3460db78351b', 'Сізді түсінеді, бірақ айтпай ма? 🧠', 'Пассив сөздік қор белсенді сөздік қорға қарағанда жылдамырақ дамиды. Блогтар бөлімінен 20 айлық баланың сөйлеуін дамытуға көмектесетін үй ойындары туралы мақаланы міндетті түрде оқыңыз.'),
  ('f641f443-9a8d-4060-a2b5-fe5d5562fa9d', 'Дәрумендерді жасыру амалы 🥕', 'Көк шөптер мен көкөністерді шетке ысырып қоя ма? Бөпеге арналған рецепттер бөлімінен саумалдық пен сәбізді дәмді құймақтарға білдірмей қосудың тәсілін үйреніңіз.'),
  ('68ef19de-c144-4be9-8878-9cc1b34a6483', 'Ұйықтап кетуге қанша уақыт кетеді? ⏱️', 'Төсекте ұзақ аунақшып жата ма? Ұйқы таймерін қосып, ұйықтап кетуге кеткен уақытты белгілеңіз. Бәлкім, кешкі ойындарды ертерек аяқтау керек шығар.'),
  ('70a3e410-6335-466b-99bc-28ac0c3d913f', 'Неліктен кенеттен жылайды? 🤖', 'Түнде айқайлап оянып, тыныштала алмай ма? Түнгі қорқынышқа қатысты күмәніңізді бірден Anacan AI сарапшысына жазып, қандай әрекет жасау керектігін біліңіз.'),
  ('847e9a71-981a-4920-b6be-a1986674dd92', 'Дастарқан басындағы бітпейтін шоу ⏱️', 'Тамақпен ойнайды, жерге лақтырады, бірақ жемейді. Тамақтану таймерін қосып, сабыр сақтаңыз және осы еркіндік кезеңіндегі тәбетінің өзгерісін қолданбадағы график арқылы мұқият талдаңыз.'),
  ('890ee8d7-3315-4b7a-994a-c41900d8c960', 'Ақылды ойыншық іздейсіз бе? 🧩', 'Пішіндерді сәйкес саңылауларға салуды меңгеріп алды ма? Ойлау қабілетін одан әрі дамытатын жасына сай пазлдарды Ұсынылатын өнімдер бөлімінен дәл қазір табыңыз.'),
  ('8ad462c4-33b5-4c76-be29-aa192feb14a1', 'Аяқ киімі қысып жүр ме? 📏', 'Соңғы кезде жүгіргенде жиі сүріне ме? Аяғы өсіп кеткен болуы мүмкін! Даму трекеріне қазіргі бойы мен өлшемдерін енгізіп, дене дамуын бақылаңыз.'),
  ('2e662854-2d0b-4e0d-be84-f71f33b1ed5b', 'Неліктен кенеттен жылайды? 🤖', 'Жайбарақат ойнап отырып, кенеттен көңіл күйі өзгеріп, жылай бастады ма? Эмоциялық құбылудың себебін анықтау үшін Anacan AI сарапшы көмекшімізге жазыңыз.'),
  ('b30cbe06-794a-4924-bc78-63ebe289b716', 'Зияткерлік даму тоқтамайды 🧠', 'Ол бәрін сұрыптағанды ұнатады! Блогтар бөліміндегі 20-21 айлық балалардың түс пен пішінді қабылдауын дамытатын үй ойындары туралы мақаланы міндетті түрде оқыңыз.'),
  ('dcfe0150-6b59-46be-be17-cba289272768', '5 минуттық қуат 🔋', 'Ашқарынға кофе ішсеңіз, түске қарай қуатыңыз таусылады. Пайдалы рецептілер ішінен тез дайындалатын, ұзақ уақыт тоқ ұстайтын дәмді сұлы кексін таңдаңыз.'),
  ('41523bc6-ac22-4b48-a7b5-8663ed9c74c3', 'Құм терапиясы 🏖️', 'Кір болып қалудан қорықпаңыз! Аналарға қолайлы орындар бөлімінен құм алаңы бар жерді табыңыз. Құммен ойнау сенсорлық даму үшін қымбат ойыншықтардан да пайдалы.'),
  ('863859ae-c920-41fe-b876-915ee50bba17', 'Бояуға батқан суретші! 📸', 'Өзін де, қабырғаны да бояп тастады ма? Ашуланудың орнына осы күлкілі шимайға толы сәтті Бөпе альбомына жүктеп, үстіне көңілді стикерлер жапсырыңыз.'),
  ('3b1eb831-8b25-40be-89a6-b50384eeb49b', 'Сөйлегісі келеді, бірақ... 🗣️', 'Пассив сөздік қоры белсенді сөздік қорынан көп пе? Сөздерді дұрыс айтпаса да, тіл дамуындағы осы керемет серпілісті қалай қолдау керектігін Блогтар бөлімінен оқыңыз.'),
  ('a4477b67-ebfc-489b-b2e5-165c0ebb273f', 'Дербестікке ұмтылу 🥣', 'Қасықты Сізге бермей ме? Тамақтану таймерін қосып, дербестікке талпынысы қанша уақыт алатынын талдаңыз. Ал шашылған тағамға жай ғана күлімсіреңіз.'),
  ('527e5a17-444d-47c4-8578-4ebb1ee870b1', 'Тәтті ұйқы ма, әлде шайқас па? 🛌', 'Ұйықтауға жату үлкен дағдарысқа айналса, Anacan AI-дан 21 айлық балаларға арналған ұйқыға дайындау рәсімдері мен психологиялық тәсілдерді дереу сұраңыз.'),
  ('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6', 'Түн қалай өтті? 🌙', 'Таңертең жөргегі тым ауыр болса, түнгі сұйықтық мөлшерін реттеу қажет болуы мүмкін. Жөргек трекеріне белгілеп, күні бойғы су теңгерімін тексеріңіз.'),
  ('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4', 'Саусақ моторикасы 🧩', 'Пішіндерді тиісті орнына салуды жақсы меңгерді. Зердесін одан әрі дамытатын жасына сай пазлдарды Ұсынылатын өнімдер бөлімінен қазір-ақ табыңыз.'),
  ('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60', 'Баяулайтын уақыт 🎶', 'Белсенді өткен күн миды шаршатуы мүмкін. Ақ шу бөлімінен орман сыбдырын қосып, бөлмеде тыныштандыратын әрі ұйқы шақыратын тамаша фон жасаңыз.'),
  ('d93eedfc-78de-4d26-810d-89c2b8c71690', 'Өзіңізді кофемен қуантыңыз ☕', 'Күні бойы жүгіріп, әбден шаршадыңыз! Аналарға жайлы орындар картасынан балалар ойын алаңы бар дәмхана тауып, өзіңізге кішкентай қуаныш сыйлаңыз.'),
  ('fcfa5044-061e-4832-8787-ddd94f46ab93', 'Жаңа сөзді үйренуі 🗣️', 'Бүгін қандай жаңа сөз айтты?'),
  ('af623bf2-6a45-452d-a9c0-bd16d67bf74d', 'Құймақ құбыжығы 🥞', 'Таңғы астан бас тарта ма? Бөпеге арналған рецепттерден қантсыз, банан қосылған құймақ рецептін байқап көріңіз. Оны қолына ұстап өзі жейді әрі тәбеті де ашылады.'),
  ('a7786d73-a362-4a32-a77f-3c09e4ab2ffb', 'Сумен өтетін физика сабағы 🛁', 'Ваннада суды бір стақаннан екіншісіне құюдан жалықпай ма? Осындай көңілді әрі тыныштандыратын су ойыншықтарын Ұсынылатын өнімдер бөлімінен қараңыз.'),
  ('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793', 'Кальций қалқаны 🦴', 'Тіс пен сүйекке кальций қажет. Тамақтануды бақылау құралы арқылы бүгінгі йогурт пен ірімшік мөлшерінің нормаға сай екенін тексеріңіз.'),
  ('e8d46282-de1c-4981-9242-f0dff7014b1d', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзарып кетті ме? Ұйқы таймерін қосып, кестені бақылаңыз. Бәлкім, күндізгі ұйқыны 15 минутқа қысқартатын уақыт келген шығар.'),
  ('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f', 'Асқазан-ішек жолының белгілері 💩', 'Қатты тағамға толық көшу ас қорытуды қиындатуы мүмкін. Жөргек бақылағышына таңғы мәліметті енгізіп, сұйықтық пен талшық теңгерімін реттеу қажет пе, соны оңай тексеріңіз.'),
  ('c4d895de-4842-4a9b-ae46-1557c6e3d2cc', 'Табиғи тыныштандырғыш 🍃', 'Бүгін мазасыз әрі шулы күн болды ма? Ақ шулардан жапырақ сыбдырын қосып, бөпеңіздің де, өзіңіздің де жүйке жүйеңізді тынықтырыңыз.'),
  ('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3', 'Киіну тартысы 👗', '«Бұл жейдені кимеймін!» деген қырсықтығы бітпей жүр ме? Таңертеңгі киіну кезіндегі қарсылықты азайту үшін «Бөпе фотосессиясында суретке түсеміз» деп, киінуді ойынға айналдырыңыз.'),
  ('0daafb47-5c27-4a37-935b-b3612abf5506', 'Күннің қаһарманы 🌟', 'Оның күн сайын меңгерген әрбір жаңа дағдысында Сіздің еңбегіңіз бар. Көңіл күй күнделігін ашып, бүгін ол үшін жасаған ең кішкентай жақсылығыңызды да жазып, өзіңізді мақтан тұтыңыз!'),
  ('205f33e0-59b6-4cce-bdf2-72feb1805167', 'Пайдалы тәтті іздейсіз бе? 🍪', 'Қантсыз, бірақ дәмді тіскебасар керек пе? Бөпеге арналған рецептерден 10 минутта дайындалатын банан мен құрма қосылған печеньелерді табыңыз.'),
  ('db60a4c8-3ab7-4727-9545-2ff3fea13946', 'Қырсық «Жоқ!» 🛑', 'Бәріне қарсылық білдіріп, айқайлай ма? 21 айлық кезеңдегі қырсықтық туралы Anacan AI көмекшісінен кеңес алып, ашу ұстамаларын басқаруды үйреніңіз.'),
  ('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36', 'Ұйқы режимін тексерейік ⏱️', 'Түнде жиі ояна ма? Ұйқы таймерінің кестесін талдаңыз. Бәлкім, күндізгі ұйқысын сәл қысқартып, кешке қарай көбірек шаршауына мүмкіндік беру керек шығар.'),
  ('87662f03-ab51-47a9-bb0d-dc1172cdf859', 'Дәрумендер қоры 🥗', 'Тамақтануды бақылау құралы арқылы бүгінгі дәрумен қажеттілігін есептеп, мәзірді жоспарлаңыз. Омега-3 пен D дәруменінің теңгерімін міндетті түрде тексеріңіз.'),
  ('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7', 'Логикалық ойыншықтар 🧩', 'Бұл жас — логикалық ойындарға таптырмас кезең. Ұсынылатын өнімдерден жасына сай пазлдар мен пішіндерді сұрыптауға арналған ойыншықтарды тауып, ойлау қабілетін дамытыңыз.'),
  ('b4b68202-2497-420c-9cf0-d0f43130a249', 'Ішіңіздегіні ақтарыңыз 📝', 'Әр күн мінсіз бола бермейді, бұл — қалыпты жағдай. Бүгінгі ішкі күйзелісіңізді Көңіл күй күнделігіне жазып, стрестен арылып, жайлы демалыңыз.'),
  ('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94', 'Бойы күрт өсті! 📏', 'Балаңыздың бойы кенет өскенін байқадыңыз ба? Жаңа көрсеткіштерді Даму трекеріне енгізіп, дені сау өсу кестесіне мақтанышпен қараңыз.'),
  ('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677', 'Қуат жинайтын уақыт 🔋', 'Өзіңізді де ұмытпаңыз! Пайдалы рецептерден таңғы асқа тез дайындалатын, ақуызға бай дәмді смузи жасап, сергіп алыңыз.'),
  ('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce', 'Ақуыз мөлшері жеткілікті ме? 🍗', 'Баланың өсуі үшін ақуыз өте маңызды! Тамақтануды бақылау құралы арқылы оның күнделікті ас мәзірінің теңгерімін бағалап, жетіспейтін қоректік заттарды толықтырыңыз.'),
  ('e90a6ec1-ff62-4f86-8635-bb93512c7c35', 'Таймермен ұйқыны талдау ⏱️', 'Ұйықтайтын уақыт келді! Ұйқы таймерін қосып, күнделікті ұйқы нормасын сақтайтынына көз жеткізу үшін оның режимін талдаңыз да, өзіңіз де демалыңыз.'),
  ('0ac93f21-93e2-449d-b93b-ae00befc33f7', 'Қараңғыдан қорқа ма? 🌌', 'Бөлменің жарығын өшіргенде мазасыздана ма? Ақ шу ішінен ана құрсағындағы дыбысты (жүрек соғысын) қосып, оған жылулық пен қауіпсіздік сезімін сыйлаңыз.'),
  ('5831d6e0-9735-485f-be90-56915bc7047f', 'Енді өзіңізге көңіл бөліңіз 🥗', 'Бала ұйықтаса, асүйге барыңыз! Әйелдерге арналған пайдалы рецепттерден бірден қуат беретін ақуызға бай салат немесе детокс суын таңдаңыз.'),
  ('5c1e8139-b38e-4666-8558-f6706af826d7', 'Кішкентай суретші іске кірісті 🖍️', 'Шимайлап сурет салғанды ұната ма? Киімін бояп алса да, ашуланбаңыз! Осы шығармашылық сәтті бірден Бөпе альбомына қосып, өмірлік естелікке айналдырыңыз.'),
  ('04f3e5a5-25b9-471b-9c8e-e6c96050313b', 'Иммунитеттің түрлі-түсті қалқаны 🛡️', 'Тамақтануды бақылау құралы арқылы бүгін оның С дәруменін жеткілікті мөлшерде қабылдағанын тексеріңіз. Түрлі-түсті көкөніс тағамдарын дайындау үшін Бөпеге арналған рецепттерді қараңыз.'),
  ('41231bd2-e2dd-4432-bc31-3952982f012e', 'Тісін тазалап жүр ме? 🪥', 'Тіс щеткасын көре сала қаша ма? Ұсынылатын өнімдер бөлімінен музыкалық немесе саусаққа киілетін щеткаларды қарап, осы маңызды гигиеналық үдерісті көңілді ойынға айналдырыңыз.'),
  ('9603c325-693c-472c-b02b-2c75bd255571', 'Бүгінгі күннің қаһарманы — Сіз! 🌟', 'Барлық қырсықтық пен шаршауға қарамастан, Сіз кереметсіз! Көңіл күй күнделігін ашып, бүгін өзіңізді тік тұрып қол соғуға лайық сезіндіретін жазба қалдырыңыз.'),
  ('e61cda6e-e7ca-46f3-a40c-42185a9f8216', '5 минуттық қуат ⚡', 'Түсте бөпеңіз ұйықтағанда, үй шаруасына асықпаңыз. Пайдалы рецептілерден антиоксиданттарға бай смузи дайындап, бойыңызға қуат жинаңыз.'),
  ('733a062a-9528-4b89-8399-8894cdcd37ab', 'Бірге кітап оқу 📖', 'Кітаптың беттерін өзі аударғысы келе ме? Блогтар бөлімінен осы жаста кітап оқуға деген сүйіспеншілікті ойын арқылы қалай қалыптастыруға болатыны туралы тамаша мақаланы оқыңыз.'),
  ('840a48c0-60b0-4169-a7a4-bfd97c049d9d', 'Табиғатты зерттеу 🌳', 'Үйдің іші оған тар болып жүр ме? Анаға қолайлы орындар арасынан кең әрі қауіпсіз саябақ тауып, табиғат аясында бойындағы энергиясын шығаруға көмектесіңіз.'),
  ('fc70b034-70d7-48ac-b093-b541c3d08e54', 'Таңғы тазалық және талдау 💧', 'Күннің алғашқы жөргегін ауыстырдыңыз ба? Зәрі мен үлкен дәреті туралы мәліметтерді қолданбаға енгізіп, сұйықтықты жеткілікті қабылдап жүргенін және ас қорытуының қалыпты екенін оңай бақылаңыз.'),
  ('8139b24d-f8c3-4b60-b4f1-38bd25e609a6', 'Қасықты қолынан тастамай ма? 🥄', 'Тамақтану таймерін қосыңыз. Өз бетінше тамақтану әрекеттерінің қанша уақытқа созылатынын талдап, қолданбадан күнделікті тамақтану нормасын тексеріңіз.'),
  ('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91', 'Құм терапиясы 🏖️', 'Кірлеуден қорықпаңыз! Кинетикалық құмға немесе сенсорлық ойындарға арналған ең жақсы құралдарды Ұсынылатын өнімдер бөлімінен бірден табыңыз.'),
  ('f71cc78c-d1eb-4694-b94a-1843f80e2db1', 'Тыныштандыратын толқындар 🌊', 'Белсенді зерттеулерге толы күннен кейін ұйықтай алмай жүр ме? Ақ шу бөлімінен мұхит толқынының дыбысын таңдап, бөлмеде сиқырлы тыныштық орнату арқылы оны ұйқыға дайындаңыз.'),
  ('3787f491-d618-4351-acd6-86ff87689c17', 'Ұру және итеру 🛑', 'Ашуланғанда кенеттен қол көтере ме немесе тістеп ала ма? 21 айға тән бұл мінез-құлықты мейіріммен қалай түзетуге болатынын Anacan AI-дан сұраңыз.'),
  ('a3eb6f02-e9da-422e-a243-1f395cf4661e', 'Ұйқы уақыты жылжып кетті ме? ⏱️', 'Кешкі сергек жүру уақыты ұзарып кетті ме? Ұйқы таймерін қосып, кестені талдау арқылы ұйқы аралықтарын қайта есептеңіз.'),
  ('aac102d8-edd5-4708-bab2-8cf3fcc9802c', 'Ас қорыту баяулады ма? 🚽', 'Таңертең жөргегін ауыстырғанда үлкен дәретін бақылаңыз. Іші қатып жүрсе, оны қолданбаға тіркеп, мәзіріне талшыққа бай тағамдарды (алмұрт, сұлы) қосуды ұмытпаңыз.'),
  ('5bf406ee-d6c9-4691-8b5e-2df617ed2939', 'Табиғатты зерттеу 🌳', 'Үйдің іші оған тар болып жүр ме? Анаға жайлы орындардан кең құм алаңы мен әткеншектері бар қауіпсіз саябақты тауып, таза ауаға шығыңыз.'),
  ('ad873c49-3118-429c-a9cf-3328699e514f', 'Макарон қызығы! 🍝', 'Тамақтану үстелінде отырғысы келмей ме? Бөпелерге арналған рецепттерден түрлі түсті, көкөніс қосылған макарон идеяларын қарап, оның назарын қайтадан тәрелкеге аударыңыз.'),
  ('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42', 'Бірқалыпты дыбыстың күші 🌬️', 'Тыныштық оны қорқыта ма? Бөлмеде «Ақ шу» бөлімінен шаш кептіргіштің немесе желдеткіштің дыбысын қосып, оның ұйықтайтын ортада қауіпсіздік сезімін қалай қалыптастыратынын байқаңыз.'),
  ('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5', 'Өзіңізді мақтаңыз! 🌟', 'Бүгін оны жылатпай киіндіре алдыңыз ба? Көңіл күй күнделігіне ең кішкентай жетістігіңізді де жазып, аналық шеберлігіңіз үшін өзіңізге қошемет көрсетіңіз.'),
  ('5d85dda7-f62e-4490-8b4e-2ca037fd60ac', 'Иммунитет қалқаны 🛡️', 'Маусым ауысуына дайынсыз ба? Тамақтануды бақылау құралы арқылы оның бүгін C дәруменін жеткілікті мөлшерде алғанын тексеріп, мәзірін жаңартыңыз.'),
  ('680f971c-231a-40e8-a772-413975915698', 'Ұру және итеру 🛑', 'Кенет ашуланғанда қол көтере ме немесе итере ме? 21.5 айда кездесетін бұл күрделі мінез-құлықты ойынға айналдырып, қалай реттеуге болатынын Anacan AI-дан сұраңыз.'),
  ('03d03133-0370-4630-9d2e-153f9459d86d', 'Ұйқысынан айғайлап ояна ма?', 'Бөлменің жарығын жақпай-ақ, Ақ шудан ана құрсағындағы дыбысты қосыңыз. Бұл оған өзін қауіпсіз сезініп, қайта ұйықтауына көмектеседі.'),
  ('8ed6f8ef-f210-4aaa-96f8-4667b80d657e', 'Бәріне «Жоқ!» 🛑', 'Барлық ұсынысыңызға қарсылық білдіре ме? Қырсықтығымен күресудің орнына, оған дұрыс таңдау нұсқаларын қалай ұсыну керегін Anacan AI-дан бірден сұраңыз.'),
  ('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c', 'Түнде сұйықтық ішу 🚰', 'Таңертең жөргегі тым ауыр болса, кешкі уақытта су ішуін реттеу қажет болуы мүмкін. Мұны Жөргек трекеріне белгілеп, күнделікті статистиканы қарап шығыңыз.'),
  ('0b3896bc-de1d-4dd2-b68d-bd0aa3890750', 'Күндізгі ұйқысы ұзаққа созыла ма? ⏱️', 'Кешке жатқысы келмей ме? Ұйқы таймерін қосып, кестесін бақылаңыз. Бәлкім, күндізгі ұйқысынан тым кеш оянатын шығар?'),
  ('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d', 'Кальций және сүйектер 🦴', 'Қарқынды дене дамуына кальций қажет. Тамақтануды бақылау құралы арқылы ірімшік пен йогуртқа деген қажеттілікті есептеңіз, ал олар жеткіліксіз болса, Бөпеге арналған рецепттерді қараңыз.'),
  ('c7f42861-81dc-4ed2-b93f-7c30709d92ed', 'Әбден шаршадыңыз ба? 🔋', 'Қуатыңыз таусылды ма? Тәттіге асықпаңыз. Әйелдерге арналған пайдалы рецепттер бойынша қантсыз әрі тез қуат беретін энергетикалық шарлар дайындап, күшіңізді қалпына келтіріңіз.'),
  ('2ecfbac7-2e44-4661-8705-95fe2f59e9a9', 'Мінсіздікке ұмтылуды доғарыңыз 🧘‍♀️', 'Үйіңіз шашылып жатыр ма? Ештеңе етпейді! Сезімдеріңізді Көңіл күй күнделігіне жазыңыз. Бақытты ана мінсіз үйден маңыздырақ екенін ұмытпаңыз.'),
  ('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1', 'Сізге де үзіліс қажет ☕', 'Үйден шығып, аздап сергіп қайтыңыз! Анаға қолайлы орындардан маңайыңыздағы балалар бұрышы бар дәмхананы тауып, ыстық кофеңізден асықпай ләззат алыңыз.'),
  ('f9b61a4f-eba1-4cee-bf4a-958278a9300c', 'Үйдің кішкентай аспазы 👩‍🍳', 'Асүйде Сізге көмектесіп, қазандарды араластыра ма? Үсті-басы ұн болған осы күлкілі сәтті Бөпе фотосессиясындағы аспаз стикерлерімен безендіріңіз.'),
  ('2c0cd78a-df37-49ab-8eae-44063551c7d9', 'Пазл шебері 🧩', 'Пішіндерді сәйкестендіруді шебер меңгеріп жүр ме? Ойлау қабілетін шыңдау үшін Ұсынылатын өнімдер бөлімінен 21 айлық балаларға арналған геометриялық пазлдарды табыңыз.'),
  ('eeefba30-2a67-4d29-87df-2dbd7f03271f', 'Кітап жыртуға құмарлық 📖', 'Оқудың орнына кітап беттерін жырта ма? Блогтар бөлімінен кітап оқу әдетіне зиян келтірмей, бұл мәселені қалай шешуге болатынын қазір оқыңыз.'),
  ('f7f548f7-29ae-4098-8eb1-12f16f94c4b9', 'Тамақпен ойнау кезеңі 🥣', 'Қасықты шетке лақтырып, тамақты қолымен ұстай ма? Тамақтану таймерін қосып, тәбетінің өзгерісін талдаңыз және сенсорлық дамудың бұл кезеңіне сабырмен қараңыз.'),
  ('3512adbc-96b2-42e9-8a54-b673dc404876', 'Кешкі күлкі 📸', 'Ұйықтар алдында жасаған сол күлкілі қылығын жіберіп алмаңыз! Бірден видеоға түсіріп, Бөпе альбомына қосыңыз да, күннің шаршауын күлкіге айналдырыңыз.'),
  ('42cda594-bd4d-4a45-a1f6-1f894ad11fe7', 'Жаңа сөздер келе жатыр! 🗣️', 'Көп дыбыс шығарады, бірақ әлі толық сөз айтпай ма? Anacan AI-дан енжар сөздік қорын белсендіруге арналған ең тиімді үй ойындары мен буын жаттығуларын біліңіз.'),
  ('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54', 'Аяқ киімі тар болып қалды ма? 👟', 'Соңғы кезде жүгіргенде жиі сүріне ме? Аяғы өскен болуы мүмкін! Даму трекеріне қазіргі өлшемдерін енгізіп, өсуін бақылаңыз.'),
  ('8ae66558-ee37-4cd1-9102-46bab1a97b21', '5 минутта дайын дәмді ас! 🥗', 'Түскі уақытта жүріп бара жатып жеңіл-желпі тамақтана саласыз ба? Әйелдерге арналған пайдалы рецепттерден ұзақ уақыт тоқ ұстап, бірден қуат беретін авокадо қосылған тост дайындаңыз.'),
  ('4bdcd931-fb36-41ca-9759-7a92226d97f9', 'Тойғанын қалай білуге болады? ⏱️', 'Тамақты лақтырып немесе түкіріп бастаса, бұл оның тойғанын білдіреді. Тамақтану таймерін тоқтатып, мөлшердің толық берілгенін белгілеңіз және тәбетін талдаңыз.'),
  ('be36c558-6f81-4ee5-9a59-f79497bbff2d', 'Тіс тазалау машақаты 🪥', 'Тіс щеткасын көре сала қаша ма? Ұсынылатын өнімдер бөлімінен музыкалық немесе саусаққа киілетін щеткаларды қарап, осы маңызды гигиеналық үдерісті көңілді ойынға айналдырыңыз.'),
  ('cd9296b3-74e7-4229-8871-9f5ee4fe977a', 'Ананың су теңгерімі 💧', 'Басыңыз ауырып тұр ма? Баланың соңынан жүгіріп жүріп, су ішуді ұмытып кеткен боларсыз. Әйелдерге арналған пайдалы рецепттер бойынша детокс суларын дайындап, ағзаңызға сергектік сыйлаңыз.'),
  ('2fbfd933-5095-452a-808e-4209aab75b80', 'Сізге де қарым-қатынас қажет 👯‍♀️', 'Тек баламен сөйлесуден шаршадыңыз ба? Анаға қолайлы орындар бөлімінен ойын топтары бар орталықтарды тауып, басқа аналармен танысыңыз.'),
  ('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc', 'Кішкентай еліктегіш 📱', 'Сіз сияқты телефонмен сөйлесіп, қимылдарыңызды қайталай ма? Балалар — біздің ең үлкен айнамыз!'),
  ('bf157f3f-185f-45b5-aae0-091b2cf00653', 'Бірге, бірақ бөлек 👶', 'Саябақта басқа балалармен ойнамай, тек бақылап жүр ме? Бұл — қатар ойнау кезеңі! Блогтар бөлімінен әлеуметтенудің осы кезеңі туралы қызықты деректерді біліңіз.'),
  ('9faf82e4-78ff-4782-a4bb-0d745a808c97', 'Жасыл түске қарсылық 🥦', 'Көкөністерден бас тарта ма? Қосымша тамақ жей бастаған бөпелерге арналған Рецепттер бөлімінен көкөністерді дәмді құймақтың ішіне қалай жасыруға болатынын біліңіз.'),
  ('c2142ff9-9553-4737-9602-95ee907b4599', 'Шаршауға берілмеңіз 🛋️', 'Бүгін бәрін тастап кеткіңіз келді ме? Бұл қалыпты жағдай! Көңіл күй күнделігін ашып, ішіңіздегі мазасыздықты жазып, бүгінгі кешті тек өзіңізге арнаңыз.'),
  ('cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'Жөргегі құрғақ па? 🧻', 'Таңғы тексеріс! Егер жөргегі ұзақ уақыт құрғақ қалса, түбекке үйрететін уақыт жақындады. Жөргек трекеріне белгілеп, статистиканы тексеріңіз.'),
  ('3e9ffaf8-f631-4e99-946e-651b683eab7f', '«Анашым, кел!» деген сөйлемдер 🗣️', 'Екі сөзді біріктіріп, сөйлем құрауға талпынып жүр ме? Бұл — тіл дамуының үлкен серпілісі! Оның алғашқы қысқа сөйлемдерін естелік ретінде даму трекеріне жазып қойыңыз.'),
  ('473def83-9d3b-4698-becd-a16f81aed11d', 'Дүкендегі қырсықтық 🛒', 'Дүкенде қалағанын алып бермегеніңіз үшін жерге жата қалып, жылап жіберді ме? Абыржымаңыз. Айналадағылардың көзқарасына мән бермей, сабырмен оның көз деңгейіне дейін еңкейіңіз.'),
  ('fdbb311e-3b42-4723-986f-c65a632fb53e', 'Эмоциялық жүктен арылыңыз 📝', 'Күніңіз қиын өтті ме? Көңіл күй күнделігіне бүгінгі күйзелісіңізді жазып, ішіңіздегіні шығарыңыз. Барлық аналар баласының көпшілік ортадағы осындай қырсықтығын бастан өткереді, Сіз жалғыз емессіз.'),
  ('6b045729-7aac-44f1-99aa-a2dbeb7985f2', 'Тізім өмірді жеңілдетеді 🛒', 'Жадыңыз тағы да жаңылтты ма? Үйде таусылған әрбір ұсақ-түйекті есте сақтауға тырыспай-ақ, бірден Сатып алу тізіміне қосыңыз — қалғанын жұбайыңыз реттесін.'),
  ('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba', 'Доп тебу ⚽', 'Жердегі допты аяғымен тебуге талпынып жүр ме? Тепе-теңдігі мен аяқ қимылдарының үйлесімі жетіліп келеді. Онымен допты бір-біріңізге беріп ойнаңыз.'),
  ('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1', 'Сиқырлы түнгі ертегі 🪄', 'Ұйықтай алмай жүр ме? Ақылды ертегілер бөлімінде бірегей ертегі құрастырып, оқып беріңіз.'),
  ('51155148-f9ec-40a7-99a1-3f09cffe59c1', 'Әкенің ойын алаңы 👨‍👧', 'Шыдамыңыз таусылды ма? Бөлменің есігін жауып, баланы әкесімен оңаша қалдырыңыз. Бүгін кешке үйдегі ойын алаңын әкесі басқарсын.'),
  ('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739', 'Киім таңдаудағы қырсықтық 👗', 'Жазда қалың жемпір, ал қыста жазғы көйлек кигісі келе ме? Оның ерік-жігері қалыптасып жатыр. Ауа райына сай екі киімді шығарып, «Қайсысын қалайсың?» деп таңдауды өзіне қалдырыңыз.'),
  ('c6ce4007-ba3b-4772-8fba-7c4797ad17dd', 'Таза ауа — дәрі 🌳', 'Бала қатты мазасызданып, үйде отырғысы келмей ме? Ауа райы мен киімін тексеріп, бірден саябаққа барыңыз. Табиғат — оны тез тыныштандыратын ең жақсы құрал.'),
  ('02902252-366d-405a-a62b-9c6f129b4a84', 'Зияткерлік қабілет қалай дамиды? 🧠', 'Блогтар бөліміндегі 21.5 айлық балалардың түс пен пішінді қабылдауын жақсартып, миын ынталандыратын үй ойындары туралы мақаланы міндетті түрде оқыңыз.'),
  ('08bbbba1-9e53-4379-a09e-82d1079f7df6', 'Темір қорының деңгейін тексеру 🥩', 'Бұлшықеттердің белсенді қимылдауы үшін қаназдық болмауы керек. Тамақтануды бақылау құралы арқылы бүгін қанша темір қабылдағанын тексеріп, жетіспеген мөлшерін дереу толықтырыңыз.'),
  ('cd9b8bec-56d4-42a3-a245-f71b148a61ef', 'Дыбыстан тыныштыққа ауысу 🎶', 'Шулы ойындардан кейін кенет орнаған тыныштық оны қорқытады. Бөлмеде «Ақ шу» бөлімінен феннің дыбысын қосып, бірқалыпты дыбыстың ұйқыға жағымды әсерін байқаңыз.'),
  ('54f26234-4c50-45b3-9088-6a5b0c08fcd2', 'Ананың су теңгерімі 💧', 'Басыңыз ауырып тұр ма? Баланың соңынан жүгіріп жүріп, су ішуді ұмытып кеткенсіз. Пайдалы рецепттерден детокс сусындарын дайындап, ағзаңызға сергектік сыйлаңыз.'),
  ('a27861d3-4efc-4b58-bec5-f3117fe589e3', 'Сұрыптау ойындары 🔴🔵', 'Қызылдарды бір жаққа, көктерді екінші жаққа жинағанды ұната ма? Логиканы дамытуды одан әрі қызықты ету үшін Anacan AI-дан ойын идеяларын сұраңыз.'),
  ('d5617275-bfe2-4829-8f3f-d3b94dc34cfe', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзарып кетті ме? Ұйқы таймерін қосып, кестені қадағалаңыз. Бәлкім, күндізгі ұйқыны 15 минутқа қысқартатын уақыт келген шығар.'),
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031', 'Түнде ояну ⏱️', 'Ұйқы таймерін қосыңыз! Таймердің статистикалық графигі арқылы бөпеңізде түнгі қорқыныш немесе ұйқы регрессиясы бар-жоғын бірден талдаңыз.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'Темірге қажеттілік 🥩', 'Жүгіргенде жұмыс істейтін бұлшықеттерін нәрлендіріңіз! Тамақтануды бақылау құралы арқылы бүгін темірді жеткілікті мөлшерде алған-алмағанын тексеріп, ас мәзірін реттеңіз.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'Күлкі үні 📸', 'Бетін тыржита ма, әлде Сізге қарап қарқылдап күле ме? Осы сүйкімді сәтті «Бөпе фотосессиясындағы» стикерлермен безендіріп, альбомға мәңгілік естелік ретінде қосыңыз.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'Бірқалыпты дыбыстың күші 🎶', 'Шулы күннен кейінгі кенет тыныштық оны қорқытады. «Ақ шулардан» шаш кептіргіштің дыбысын қосып, ұйықтайтын ортасында қауіпсіздік сезімін қалыптастырыңыз.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'Ананың қуаты 🔋', 'Күш-қуатыңыз таусылды ма? Тәттіге асықпаңыз! Әйелдерге арналған пайдалы рецептілерден бірден қуат беретін, ақуызға бай жержаңғақ пастасы қосылған смузи дайындаңыз.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'Киімдері қайтадан тар болып қалды ма? 📏', 'Бұл — физикалық дамудың қарқынды кезеңі! Даму трекеріне қазіргі бойы мен аяқкиім өлшемін енгізіп, өсу қисығының қалай жоғарылағанын мақтанышпен бақылаңыз.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'Логиканы дамыту 🧩', 'Бірдей ойыншықтардан жалықты ма? Ойлау қабілетін шыңдайтын, жасына сай әрі қауіпсіз пазлдарды «Ұсынылатын өнімдер» бөлімінен табыңыз.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'Кенеттен ұру және тістеу 🦖', 'Ашуланғанда агрессия таныта ма? Anacan AI көмегімен бұл мінез-құлықты ойынға айналдырып, оны қалай жұмсақ өзгертуге болатынын біліңіз.'),
  ('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7', 'Киіну айқасы 👗', '«Бұл жейдені кигім келмейді!» деп қырсыға бастады ма? Таңертеңгі киіну кезіндегі дағдарысты азайтып, оған өз бетінше таңдау жасауға мүмкіндік берудің жолдарын Anacan AI-дан біліңіз.'),
  ('2a640acf-5bf6-44d4-b56f-00e902c2ddd2', 'Дербестікке ұмтылу 🥣', 'Қасықты Сізге бермей ме? Тамақтану таймерін қосып, бұл дербестік сынағының қанша уақыт алатынын талдаңыз. Шашылған тамаққа жай ғана жымиып қараңыз.'),
  ('cb94164a-0ea2-471c-9c17-a09778ea707c', 'Ажырасудан қорқу? 🌌', 'Бөлмеден шыға салысымен артыңыздан жылай ма? Ақ шу бөлімінен ана құрсағындағы дыбысты (жүрек соғысын) қосып, оған бұрынғы жылы қауіпсіздік сезімін сыйлаңыз.'),
  ('d3ae908a-552f-4504-a171-436173eaeceb', 'Тіс тазалау тартысы 🪥', 'Тіс щеткасын көре сала аузын ашпай қоя ма? Ұсынылатын өнімдер бөлімінен музыкалық немесе саусаққа киілетін щеткаларды қарап, бұл гигиеналық әдетті көңілді ойынға айналдырыңыз.'),
  ('4932b8a8-d024-498c-ba06-d790b59bc198', 'Өзіңізге мейірімді болыңыз 🧘‍♀️', 'Бүгін бәрі ойдағыдай болмады ма? Көңіл күй күнделігіне ішкі ойыңызды жазып, өзіңізді кешіріңіз, терең тыныс алып, демалыңыз.'),
  ('ed014436-2469-48a6-b579-7bce93de1ae7', 'Сөздік қоры кеңеюде 🗣️', 'Екі сөзден тұратын сөйлемдері көбейді ме? Оның осындай керемет тілдік дамуын қалай қолдап, диалог құру керектігін бірден Anacan AI-дан сұраңыз.'),
  ('ed579060-f78c-4890-b8e4-2bb0c7729792', 'Нәжістің түсі 💩', 'Жөргегін ауыстырған кезде белгілеп отырыңыз! Сұйықтық пен талшық теңгерімін бақылап, іш қатудың алдын алу үшін Тамақтануды бақылау құралын пайдаланыңыз.'),
  ('15f9bb81-a16f-4753-a3f5-a2b604b16a46', 'Таза ауадағы ұйқы 🌳', 'Үйде ұйықтай алмай ма? Анаға жайлы орындар бөлімінен тыныш, ағашы көп саябақ табыңыз. Таза ауа оның тәбетін ашып, ұйқысын жақсартады.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'Көкөністермен жасырын ойын 🥕', 'Сәбіз бен саумалдықты жемей ме? Бөпеге арналған рецепттерден осы дәрумендерді дәмді құймақтарға шебер жасыру жолдарын табыңыз.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'Өзіңізді кінәламаңыз 💖', 'Бүгін даусыңызды көтеріп қойдыңыз ба? Өзіңізді жазғырмаңыз. Көңіл күй күнделігіне сезімдеріңізді жазыңыз, Сіз бәрібір ол үшін ең жақсы анасыз.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'Дастарқан басындағы бітпейтін көрініс ⏱️', 'Тамақпен ойнайды, бірақ жемей ме? Тамақтану таймерін қосып, үдерістің ұзақтығын бақылаңыз және тәбетінің өзгеруін дәл талдаңыз.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'Бүгінгі күннің қаһарманы — Сіз 🌟', 'Оның күн сайын меңгеретін әрбір жаңа дағдысы — Сіздің еңбегіңіздің жемісі. Көңіл күй күнделігін ашып, бүгін өзіңізге тік тұрып қол соғуға лайық бір жазба қалдырыңыз!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'Бірге, бірақ бөлек 👶', 'Саябақта басқа балалармен ойнамай, тек бақылап жүр ме? Бұл — қатар ойнау! Блогтар бөлімінен әлеуметтенудің осы қалыпты кезеңі туралы оқыңыз.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'Қантсыз тіскебасар 🍪', 'Дүкен печеньесін сатып алудың қажеті жоқ. Бөпеге арналған рецепттерден үйде 10 минутта дайындалатын құрма мен алмадан жасалған пайдалы тәттілерді табыңыз.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'Түнде жөргегі толып қала ма? 🧻', 'Таңертең жөргегі тым ауыр болса, түнгі ұйқысы бұзылуы мүмкін. Жөргек трекеріне бөліндіні белгілеп, кешкі сұйықтық мөлшерін реттеу үшін статистиканы талдаңыз.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'Асүйдегі кішкентай зерттеуші 🥦', 'Ол да Сізбен бірге ас дайындағысы келе ме? Қосымша тамақ жей бастаған бөпелерге арналған Рецепттерден бірге дайындауға болатын оңай, көкөністі әрі дәмді кекс рецепттерін табыңыз.'),
  ('53a89401-1ea0-43b5-9469-65a0d422f72c', 'Дастарқан басындағы бітпейтін шоу 🥣', 'Тамақпен ойнап, жерге лақтырады, бірақ жемейді. Тамақтану таймерін қосып, тәбетінің өзгеруін қолданбадағы график арқылы дәл талдаңыз.'),
  ('86da0f7a-f021-4c65-aed2-e8e15433a92d', 'Айналдыруға деген құмарлық 🌀', 'Дөңгелектерді немесе қақпақтарды тоқтаусыз айналдыра ма? Осы ерекше моторлық қажеттілік және оның танымдық дамудағы рөлі туралы Блогтардан оқыңыз.'),
  ('9ea6bc21-5003-4afe-8fca-e2eebb549250', 'Құм терапиясы 🏖️', 'Үстін былғап алудан қорықпаңыз! Аналарға қолайлы орындардан құм алаңы бар жерді табыңыз. Құмды қолмен ұстау сенсорлық даму үшін өте пайдалы.'),
  ('081299bb-b5c9-4af5-8361-9fa39bbdf0bf', 'Іші қатып жүр ме? 🚽', 'Таңертең жөргегін ауыстырғанда нәжісін бақылаңыз. Іші қатса, оны қолданбаға белгілеп, қосымша тамақ жей бастаған бөпелерге арналған Рецепттерден талшыққа бай тағамдарды (алмұрт, сұлы) таңдаңыз.'),
  ('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb', 'Суретші жұмыс үстінде 🎨', 'Шимайлап сурет салғанда өзін де бояп тастай ма? Зиянсыз, жуып кетіруге болатын бояуларды табу үшін Ұсынылатын өнімдер бөліміндегі аналар жиі таңдайтын өнімдерді қараңыз.'),
  ('f9d59314-c8fe-45fa-9d77-efb82ec57626', 'Кешкі күлкі 📸', 'Ұйықтар алдында жасайтын сол бір күлкілі қылығын жіберіп алмаңыз!'),
  ('34d9fbb9-7747-4964-9067-399afa7f0a7c', 'Табиғи тыныштандырғыш 🍃', 'Бала ұйықтап қалды. Үй шаруасын ұмытыңыз! Әйелдерге арналған пайдалы рецепттерден мелисса шайын демдеп, диванға жайғасып, тыныштықтан ләззат алыңыз.'),
  ('e79393de-a250-4c25-b9a8-93a1bc3692aa', 'C дәруменінің қалқаны 🍊', 'Иммунитет мықты болуы керек. Тамақтануды бақылау құралы арқылы бүгін C дәруменін жеткілікті мөлшерде алған-алмағанын есептеп, ас мәзірін түрлендіріңіз.')
) AS v(id, t, b)
WHERE x.id = v.id;
